window.QUESTION_BANK["middle"] = [{"id":"middle_114-2_s1_q01","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":1,"context":null,"stem":"某電商企業希望利用自然語言處理（NLP）技術，分析顧客在社群平台與商品評論中的文字內容，以即時掌握顧客對產品的滿意度變化。若採用情感分析（Sentiment Analysis）模型，其主要目的為何？","options":{"A":"預測顧客使用的語言風格與語氣","B":"判斷文本中所表達的情感傾向","C":"將顧客留言自動翻譯成企業內部指定語言","D":"產生顧客評論的自動化摘要內容"},"answer":"B","figures":[],"explanation":{"approach":"情感分析（Sentiment Analysis）的核心任務是從文字中判斷作者所表達的情感傾向（正面、負面或中性），以量化顧客滿意度變化。題目要求「即時掌握顧客對產品的滿意度變化」，正對應情感傾向的判斷。","options":{"A":"語言風格與語氣預測屬於文體分析（Style Analysis），並非情感分析的主要目的","B":"正確，情感分析的核心目的即是判斷文本中蘊含的情感傾向（正面/負面/中性），以掌握顧客滿意度","C":"自動翻譯是機器翻譯（Machine Translation）任務，與情感傾向判斷無關，張冠李戴","D":"自動摘要是文字摘要（Text Summarization）任務，目的是精簡內容而非判斷情感"}},"origin":"past"},{"id":"middle_114-2_s1_q02","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":2,"context":null,"stem":"某跨國金融科技公司導入Transformer架構開發多語客服系統，以提升長篇金融文件的自動翻譯品質。下列何者為該模型能顯著改善翻譯準確度的主要原因？","options":{"A":"透過自注意力機制（Self-Attention Mechanism）捕捉長距離語境依賴關係","B":"透過卷積運算（Convolution Operation）加速訓練過程","C":"透過強化學習（Reinforcement Learning）自動調整語句生成策略","D":"透過資料增強（Data Augmentation）平衡多語語料比例"},"answer":"A","figures":[],"explanation":{"approach":"Transformer架構相較RNN/CNN在長文件翻譯上表現優異，主因在於自注意力機制能直接計算序列中任意兩個位置間的關聯權重，不受距離限制，因此能有效捕捉長距離語境依賴，提升翻譯準確度。","options":{"A":"正確，自注意力機制可讓模型在計算每個詞的表示時直接參照全句任意位置的詞，有效捕捉長距離語境依賴關係，是翻譯品質提升的關鍵","B":"卷積運算是CNN的核心操作，Transformer並非以卷積運算為基礎，且卷積本身主要影響運算效率而非語境依賴能力","C":"強化學習主要用於根據獎勵訊號優化決策策略，並非Transformer翻譯品質提升的核心機制","D":"資料增強是訓練資料層面的技術，用於平衡語料比例，並非Transformer架構本身改善翻譯準確度的原因"}},"origin":"past"},{"id":"middle_114-2_s1_q03","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":3,"context":null,"stem":"某企業計畫應用BERT（Bidirectional Encoder Representationsfrom Transformers）模型分析大量顧客意見，以強化客服自動回覆系統。在BERT的預訓練過程中，「遮罩語言模型（Masked LanguageModel, MLM）」的主要訓練策略為何？","options":{"A":"依序遮罩句尾詞語，讓模型從左到右逐步生成完整句子","B":"隨機遮罩部分詞語，並讓模型根據雙向上下文（BidirectionalContext）預測被遮罩的詞","C":"透過對抗訓練（Adversarial Training）生成語意相似的擾動樣本以提升泛化性","D":"以未遮罩的詞為條件，使用解碼器（Decoder）結構重建整句內容"},"answer":"B","figures":[],"explanation":{"approach":"BERT的MLM訓練策略是隨機遮罩輸入句子中約15%的詞語，讓模型利用被遮罩詞左右兩側（雙向）的上下文資訊來預測被遮罩的詞，這使BERT能學習到比單向語言模型更豐富的語境表示。","options":{"A":"依序從左到右生成屬於自迴歸（Autoregressive）語言模型（如GPT）的訓練方式，並非MLM的雙向隨機遮罩策略","B":"正確，MLM隨機遮罩部分詞語，並利用雙向上下文（左右兩側資訊）預測被遮罩的詞，這是BERT預訓練的核心策略","C":"對抗訓練生成擾動樣本是提升模型穩健性的另一種技術，並非MLM的訓練策略","D":"BERT是Encoder-only架構，不含Decoder，此描述將BERT與Seq2Seq類模型的解碼器重建方式混淆"}},"origin":"past"},{"id":"middle_114-2_s1_q04","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":4,"context":null,"stem":"在詞向量（Word Embedding）訓練方法中，GloVe（Global Vectorsfor Word Representation）與Word2Vec的主要差異為何？","options":{"A":"Word2Vec以詞頻權重訓練詞向量，而GloVe以隨機初始化向量進行學習","B":"Word2Vec以全局統計矩陣為基礎，而GloVe採用神經網路進行上下文預測","C":"Word2Vec為基於預測的模型，而GloVe為基於共現統計的模型","D":"Word2Vec僅能用於靜態文本語料，而GloVe可應用於即時語料更新"},"answer":"C","figures":[],"explanation":{"approach":"Word2Vec與GloVe皆用於學習詞向量，但訓練原理不同：Word2Vec屬於「預測式（Predictive）」模型，透過神經網路以上下文預測目標詞（或反之）；GloVe則屬於「計數式（Count-based）」模型，基於全語料的詞共現統計矩陣進行分解學習。","options":{"A":"描述錯誤，Word2Vec並非以詞頻權重訓練，GloVe也不是單純隨機初始化學習，兩者的核心差異被誤植","B":"描述完全相反，實際上GloVe才是以全局共現統計矩陣為基礎，而Word2Vec才是採用神經網路進行上下文預測","C":"正確，Word2Vec是基於預測（透過神經網路預測上下文或中心詞）的模型，GloVe是基於全語料共現統計的模型，這是兩者的本質差異","D":"兩者皆可用於靜態語料訓練，此描述中「即時語料更新」並非GloVe與Word2Vec的本質差異，屬於張冠李戴"}},"origin":"past"},{"id":"middle_114-2_s1_q05","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":5,"context":null,"stem":"某企業以詞頻–逆文件頻率（Term Frequency–Inverse DocumentFrequency, TF-IDF）方法分析顧客意見內容，但發現模型在處理篇幅較長的回饋文本時，無法準確反映關鍵詞的重要性。下列何者為造成此現象的主要原因？","options":{"A":"長文本中的詞頻偏高，導致常見詞權重被過度放大","B":"長文本中缺乏明確句子邊界，造成TF-IDF無法計算詞頻","C":"TF-IDF無法同時處理多份文件","D":"長文本會改變IDF（Inverse Document Frequency）的計算，使所有詞權重趨於相近"},"answer":"A","figures":[],"explanation":{"approach":"TF-IDF中的TF（詞頻）會隨文本長度增加而提高，長文本中常見詞（即使非關鍵詞）也會因反覆出現而累積出較高詞頻，導致其權重被過度放大，掩蓋真正重要的關鍵詞，這是TF-IDF對長文本敏感的已知限制。","options":{"A":"正確，長文本中詞頻普遍偏高，使得常見但非關鍵的詞語權重被過度放大，導致無法準確反映真正關鍵詞的重要性","B":"TF-IDF的計算是以詞為單位統計頻率，並不需要明確的句子邊界，此描述的因果關係錯誤","C":"TF-IDF本質上就是設計來處理多份文件（IDF即依賴多文件的逆文件頻率），此描述與事實相反","D":"IDF是以整個語料庫（跨文件）為單位計算，並非取決於單一文件的長度，此描述的因果關係錯誤"}},"origin":"past"},{"id":"middle_114-2_s1_q06","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":6,"context":null,"stem":"某企業嘗試以N-gram語言模型（N-gram Language Model）建立客服自動回覆系統，但發現模型生成的句子雖在片段上合理，卻缺乏整體語意連貫性。此問題最可能源自N-gram模型的哪一項限制？","options":{"A":"N-gram模型在訓練過程中需要龐大計算量，導致長句無法收斂","B":"N-gram模型僅根據固定長度的前序詞建立機率估計，難以捕捉長距離依賴關係（Long-range Dependencies）","C":"N-gram模型缺乏語意嵌入（Semantic Embedding）層，因此無法表徵詞語間的語意相似度","D":"N-gram模型假設詞與詞之間相互獨立，導致無法建構上下文語意關聯"},"answer":"B","figures":[],"explanation":{"approach":"N-gram語言模型僅依據固定長度（N-1個）的前序詞來估計下一詞出現的機率，屬於局部視窗（Local Context Window）建模方式，無法有效捕捉超出視窗範圍的長距離語意依賴，因此生成句子容易片段合理但整體不連貫。","options":{"A":"計算量與長句收斂性並非造成語意不連貫的直接原因，這是誤植的推論","B":"正確，N-gram僅根據固定長度的前序詞建立機率估計，難以捕捉超出該視窗範圍的長距離依賴關係，導致整體語意不連貫","C":"N-gram確實缺乏語意嵌入層，但此非造成「片段合理、整體不連貫」現象的直接根本原因，核心問題在於固定視窗限制","D":"描述錯誤，N-gram模型並非假設詞與詞相互獨立，而是明確以固定窗口內的前序詞作為條件機率的依據，這與獨立假設矛盾"}},"origin":"past"},{"id":"middle_114-2_s1_q07","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":7,"context":null,"stem":"在企業導入的智慧監控系統中，模型以物件偵測（ObjectDetection）方式自動辨識影像中的人物與車輛。若評估指標採用平均精確率（Mean Average Precision, mAP），其中IoU（Intersection over Union）閾值設定較高時，代表下列哪一項意義？","options":{"A":"預測邊界框與真實邊界框的重疊程度越高，模型偵測結果越精準","B":"預測邊界框與真實邊界框的誤差越大，導致mAP數值上升","C":"模型整體精確率（Precision）降低，但召回率（Recall）上升","D":"預測邊界框的評估結果不受真實框大小影響"},"answer":"A","figures":[],"explanation":{"approach":"IoU（Intersection over Union）衡量預測邊界框與真實邊界框的重疊比例，數值越高代表兩者重疊程度越高、定位越精準。mAP計算時設定較高的IoU閾值，代表評估標準更嚴格，要求偵測框需與真實框高度吻合才視為正確偵測。","options":{"A":"正確，IoU閾值代表判定「命中」所需的重疊程度門檻，閾值越高，代表要求預測框與真實框的重疊程度必須越高，偵測結果需更精準才算正確","B":"描述因果relationship相反，誤差越大代表IoU越低，會導致該預測不被視為正確偵測，使mAP下降而非上升","C":"IoU閾值設定與精確率、召回率此消彼長的直接關係並非必然，此描述並非IoU閾值意義的正確詮釋","D":"描述錯誤，IoU本質上就是以真實框大小（及重疊區域）為基準計算比例，評估結果必然受真實框大小影響"}},"origin":"past"},{"id":"middle_114-2_s1_q08","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":8,"context":null,"stem":"關於Softmax與Max-Pooling，下列敘述何者正確？","options":{"A":"Softmax與Max-Pooling都會將特徵張量壓縮為單一最大值","B":"Max-Pooling會對輸入進行機率分佈的轉換","C":"Softmax會保留所有輸入資訊，但以比例表示；Max-Pooling只保留區域最大值","D":"Softmax主要用於特徵降維，而Max-Pooling用於分類輸出"},"answer":"C","figures":[],"explanation":{"approach":"Softmax將輸入向量轉換為總和為1的機率分佈，保留所有類別的相對比例資訊；Max-Pooling則是在特徵圖的局部區域中僅取最大值，捨棄其餘資訊，用於降維與保留顯著特徵。兩者在資訊保留方式上有本質差異。","options":{"A":"錯誤，Softmax並不會將所有輸入壓縮為單一最大值，而是輸出涵蓋所有類別比例的機率分佈","B":"錯誤，機率分佈轉換是Softmax的功能，Max-Pooling僅做局部最大值篩選，不涉及機率轉換","C":"正確，Softmax以比例（機率分佈）保留所有輸入類別的相對資訊，而Max-Pooling僅保留局部區域中的最大值，捨棄其餘資訊","D":"描述錯誤，Softmax主要用於分類輸出（產生機率分佈），而Max-Pooling才是用於特徵降維，兩者角色被對調"}},"origin":"past"},{"id":"middle_114-2_s1_q09","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":9,"context":null,"stem":"某企業在訓練生成式AI模型時，導入資料增強（DataAugmentation）技術以擴充訓練資料，但觀察到模型效能反而下降。下列哪一項最可能的原因與對應改善策略最為正確？","options":{"A":"增強樣本未經隨機初始化，導致模型梯度更新不穩定，應重新設計訓練啟動流程","B":"增強後資料的特徵分佈與原始資料不一致，影響模型的泛化能力，應檢查並調整增強策略以維持語意一致性","C":"增強樣本的比例過高，造成模型對特定資料產生偏好，應適度提高增強比例並調整學習率","D":"增強後資料的標註可信度下降，導致訓練訊號偏差，應以半監督學習方式重新校正資料"},"answer":"B","figures":[],"explanation":{"approach":"資料增強若未妥善設計，增強後樣本的特徵分佈可能偏離原始資料的真實語意分佈，造成訓練資料與實際資料特性不一致，進而損害模型的泛化能力。因此應檢視並調整增強策略，確保增強後樣本仍維持與原始語意一致。","options":{"A":"增強樣本的問題核心並非「隨機初始化」與梯度更新穩定度，此描述並非資料增強導致效能下降的合理原因","B":"正確，增強後資料特徵分佈與原始資料不一致會影響模型泛化能力，應檢查並調整增強策略以維持語意一致性，才能真正解決問題","C":"提高增強比例會讓分佈不一致的問題更嚴重，並非合理的改善策略，此描述與問題本質矛盾","D":"此現象通常並非源自標註可信度下降，且以半監督學習重新校正並非針對特徵分佈偏移的直接對症做法"}},"origin":"past"},{"id":"middle_114-2_s1_q10","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":10,"context":null,"stem":"如果希望同時兼顧「精確率（Precision）」和「召回率（Recall）」，下列哪一個指標可以作為綜合評估的標準？","options":{"A":"準確率（Accuracy）","B":"均方根誤差（RMSE）","C":"均方誤差（MSE）","D":"F1分數（F1 Score）"},"answer":"D","figures":[],"explanation":{"approach":"F1分數是精確率與召回率的調和平均數（Harmonic Mean），能在兩者之間取得平衡，避免僅偏重其中一項指標，因此是兼顧Precision與Recall的常用綜合評估指標。","options":{"A":"準確率僅反映整體預測正確的比例，在類別不平衡情境下容易失真，且未特別兼顧Precision與Recall的平衡","B":"RMSE是迴歸任務中衡量預測值與實際值誤差的指標，不適用於評估分類任務的Precision與Recall","C":"MSE同樣是迴歸任務的誤差指標，與分類任務的Precision、Recall無直接關聯","D":"正確，F1分數是Precision與Recall的調和平均數，能同時兼顧兩者，是常用的綜合評估指標"}},"origin":"past"},{"id":"middle_114-2_s1_q11","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":11,"context":null,"stem":"企業資料分析團隊使用DBSCAN（Density-Based Spatial Clusteringof Applications with Noise）演算法進行顧客行為分群，並希望模型能自動區分主要群集與雜訊資料。在此演算法中，決定聚類結果的兩個主要超參數為下列何者？","options":{"A":"特徵數與學習率","B":"K值與距離閾值","C":"鄰域半徑（Epsilon ε）與最小點數（MinPts）","D":"交叉熵（Cross Entropy）與權重初始化"},"answer":"C","figures":[],"explanation":{"approach":"DBSCAN是基於密度的分群演算法，其分群結果主要由兩個超參數決定：鄰域半徑Epsilon（ε，定義鄰近範圍）與最小點數MinPts（定義該範圍內需達到多少點數才視為核心點），這兩者共同決定群集的密度門檻與雜訊判定。","options":{"A":"特徵數與學習率屬於一般機器學習/深度學習的參數概念，並非DBSCAN分群的核心超參數","B":"K值是K-means等演算法的超參數，DBSCAN無需預先指定群集數量K，此描述張冠李戴","C":"正確，Epsilon（鄰域半徑）與MinPts（最小點數）是DBSCAN決定核心點、邊界點與雜訊點的兩個關鍵超參數","D":"交叉熵與權重初始化是神經網路訓練相關概念，與DBSCAN這類非監督式密度分群演算法無關"}},"origin":"past"},{"id":"middle_114-2_s1_q12","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":12,"context":null,"stem":"某金融科技公司建立房價預測模型，使用多項特徵（如建坪、房齡、樓層、總價等）進行線性迴歸分析（Linear RegressionAnalysis）。資料分析師發現多個特徵之間存在高度相關性，導致模型係數不穩定、預測誤差上升。為解決此問題，下列哪一種方法最適合？","options":{"A":"繼續保留所有特徵，不進行任何處理","B":"使用主成分分析（PCA）將相關特徵轉換為彼此獨立的主成分","C":"新增更多原始變數以提升模型表現","D":"改用分類模型進行預測"},"answer":"B","figures":[],"explanation":{"approach":"特徵間高度相關性（多重共線性）會使線性迴歸的係數估計不穩定。主成分分析（PCA）可將原始相關特徵轉換為彼此正交（線性獨立）的主成分，消除共線性問題，同時降維並保留主要變異資訊，是常用的解決方式。","options":{"A":"保留所有相關特徵且不做任何處理，無法解決多重共線性導致的係數不穩定問題","B":"正確，PCA能將高度相關的特徵轉換為彼此獨立（正交）的主成分，消除共線性對迴歸係數估計的負面影響","C":"新增更多原始變數只會加劇特徵間的相關性，使多重共線性問題更嚴重，並非有效解法","D":"改用分類模型改變了任務類型（迴歸變分類），並未針對特徵共線性問題本身提出解決方案"}},"origin":"past"},{"id":"middle_114-2_s1_q13","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":13,"context":null,"stem":"下列何者為Kubernetes在AI模型部署與運行中的核心功能？","options":{"A":"自動化管理模型的訓練流程與參數調校","B":"管理與協調模型服務的部署、擴展與運行環境","C":"提供AI模型的資料儲存與版本控管功能","D":"負責深度學習推論的GPU加速運算"},"answer":"B","figures":[],"explanation":{"approach":"Kubernetes是容器編排（Container Orchestration）平台，其核心功能是管理容器化服務的部署、水平擴展（Scaling）與執行環境的協調，確保AI模型服務能穩定、彈性地運行於生產環境。","options":{"A":"模型訓練流程與參數調校屬於MLOps訓練管線或AutoML工具的職責，非Kubernetes的核心功能","B":"正確，Kubernetes的核心功能在於管理與協調容器化服務（含模型服務）的部署、擴展與運行環境","C":"資料儲存與版本控管屬於資料/模型版本管理工具（如DVC、Model Registry）的職責，非Kubernetes本身功能","D":"GPU加速運算是底層硬體與驅動（如CUDA）的功能，Kubernetes僅能排程與分配GPU資源，並非負責實際運算加速"}},"origin":"past"},{"id":"middle_114-2_s1_q14","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":14,"context":null,"stem":"在調整模型超參數（Hyperparameters）時，若希望避免因過度調整參數而導致過擬合，下列哪一種做法最有效提升模型的泛化能力？","options":{"A":"採用交叉驗證（Cross-Validation）於多組參數組合間反覆評估，選擇在驗證資料上表現最穩定的設定","B":"使用早期停止機制（Early Stopping）監控訓練誤差並在收斂前停止訓練，以防模型學習過度","C":"對輸入特徵進行標準化以減少特徵值差異帶來的過擬合風險","D":"提高模型複雜度並使用更多超參數搜尋範圍，以確保模型能充分學習資料特徵"},"answer":"A","figures":[],"explanation":{"approach":"避免超參數調整過程本身造成過擬合，最有效的做法是搭配交叉驗證：在多組參數組合間反覆於不同資料切分上評估效能，選出在驗證資料上表現最穩定、泛化能力最佳的參數設定，而非僅依賴單一驗證結果。","options":{"A":"正確，交叉驗證能在多組參數組合間反覆評估，選出在多次驗證中表現穩定的設定，有效降低超參數選擇本身造成的過擬合風險","B":"早期停止機制主要用於防止訓練過程中的過擬合（依訓練/驗證誤差判斷停止時機），並非針對超參數調整過程本身的過擬合問題","C":"特徵標準化解決的是特徵尺度差異問題，與超參數調整過程導致的過擬合風險並非直接對應的解法","D":"提高模型複雜度並擴大超參數搜尋範圍會增加過擬合風險，與題目「避免過擬合」的目標相反"}},"origin":"past"},{"id":"middle_114-2_s1_q15","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":15,"context":null,"stem":"在企業導入的MLOps（Machine Learning Operations）流程中，Model Registry最常用於哪一個階段？","options":{"A":"用於設定運算資源與執行環境以確保訓練穩定","B":"用於建立可重複使用的資料與特徵版本","C":"用於集中管理模型版本、訓練紀錄與部署狀態","D":"用於追蹤模型上線後的表現與漂移情況"},"answer":"C","figures":[],"explanation":{"approach":"Model Registry（模型註冊表）在MLOps流程中的核心用途是集中管理已訓練模型的版本、相關訓練紀錄（如超參數、指標）以及部署狀態，方便團隊追蹤與治理模型生命週期。","options":{"A":"運算資源與執行環境設定屬於訓練基礎設施（Infrastructure）管理範疇，非Model Registry的用途","B":"可重複使用的資料與特徵版本管理是Feature Store（特徵倉儲）的職責，並非Model Registry","C":"正確，Model Registry最常用於集中管理模型版本、訓練紀錄與部署狀態，是模型治理的核心工具","D":"追蹤上線後表現與漂移情況屬於模型監控（Model Monitoring）系統的功能，非Model Registry本身職責"}},"origin":"past"},{"id":"middle_114-2_s1_q16","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":16,"context":null,"stem":"下列哪一種情境中最適合使用「序列到序列（Seq2Seq）」模型？","options":{"A":"預測銷售趨勢曲線，輸出未來數值序列","B":"辨識文本中出現的人名、地名與組織名稱等實體資訊","C":"對輸入文本中的關鍵字進行頻率統計與可視化","D":"將輸入文字轉換成語意等價的另一段文字，如自動翻譯或摘要生成"},"answer":"D","figures":[],"explanation":{"approach":"Seq2Seq（序列到序列）模型的架構特性是將一段輸入序列轉換為另一段輸出序列，且輸入輸出長度可不同，最典型的應用即是機器翻譯、文字摘要等「輸入文字轉換為語意等價的另一段文字」的任務。","options":{"A":"數值序列預測屬於時間序列預測任務，雖然也可用Seq2Seq處理，但並非此技術最典型代表性的應用情境","B":"辨識人名、地名等實體資訊屬於命名實體辨識（NER），是序列標註（Sequence Labeling）任務，非典型Seq2Seq生成應用","C":"關鍵字頻率統計與可視化屬於統計分析範疇，不涉及序列到序列的文字生成轉換","D":"正確，將輸入文字轉換成語意等價的另一段文字（如翻譯、摘要生成）正是Seq2Seq模型最典型的應用情境"}},"origin":"past"},{"id":"middle_114-2_s1_q17","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":17,"context":null,"stem":"在自然語言處理中，檢索增強生成（Retrieval-AugmentedGeneration, RAG）是一種結合語言模型與向量搜尋的技術，可有效減少模型知識過時與產生幻覺的問題。若要建立一套高效能的RAG系統，下列何者為在「檢索階段」最關鍵的挑戰？","options":{"A":"確保檢索到的文件能被完整納入語言模型的上下文視窗（ContextWindow）中進行生成","B":"選擇使用Faiss或ScaNN等近似最近鄰搜尋函式庫","C":"降低嵌入模型（Embedding Model）在高維空間中的計算成本與記憶體占用","D":"避免向量檢索結果僅具語意相似但與查詢意圖無實質關聯的情況"},"answer":"D","figures":[],"explanation":{"approach":"RAG系統的檢索階段目的是找出與查詢意圖真正相關的文件，最關鍵的挑戰在於向量檢索僅依賴語意相似度計算，可能檢索出表面語意相近但實際與查詢意圖無關的文件，進而影響後續生成品質。","options":{"A":"確保檢索文件能完整納入上下文視窗，屬於「生成階段」如何運用檢索結果的挑戰，並非檢索階段本身的關鍵挑戰","B":"選擇何種近似最近鄰搜尋函式庫屬於工程實作選型細節，並非檢索階段最核心的挑戰","C":"降低嵌入模型的計算成本與記憶體占用屬於系統效能優化議題，非檢索品質的核心挑戰","D":"正確，避免向量檢索結果僅語意相似卻與查詢意圖無實質關聯，是檢索階段確保結果真正相關、提升RAG效能的最關鍵挑戰"}},"origin":"past"},{"id":"middle_114-2_s1_q18","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":18,"context":null,"stem":"當Transformer模型發生「注意力分布過於平均（AttentionCollapse）」的情形時，導致模型無法有效聚焦於關鍵資訊，下列哪一項策略可有效改善此問題？","options":{"A":"提高Query-Key點積（Dot Product）的縮放常數","B":"在Softmax前加入高斯雜訊（Gaussian Noise）","C":"使用ReLU函數取代Softmax","D":"對注意力權重施加稀疏化約束（Sparsity Constraint）"},"answer":"D","figures":[],"explanation":{"approach":"注意力分布過於平均（Attention Collapse）代表模型無法有效聚焦關鍵資訊，此時可對注意力權重施加稀疏化約束，迫使模型將注意力集中於少數重要位置，藉此改善聚焦能力。","options":{"A":"提高Query-Key點積的縮放常數會讓Softmax輸出更平滑（分布更平均），反而加劇注意力分布過於平均的問題，方向錯誤","B":"在Softmax前加入高斯雜訊會使注意力分布更加隨機、不穩定，無助於改善聚焦能力","C":"以ReLU取代Softmax會破壞注意力權重應為機率分佈（總和為1）的特性，並非有效或標準的改善方式","D":"正確，對注意力權重施加稀疏化約束，可迫使模型將注意力集中在少數關鍵位置，有效改善注意力分布過於平均的問題"}},"origin":"past"},{"id":"middle_114-2_s1_q19","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":19,"context":null,"stem":"某研究團隊正在訓練一個針對低資源語言（如少數民族語言）的語言模型，但該語言僅有約1萬筆語料可用。在訓練過程中出現明顯的過擬合現象，若希望在不新增真實語料的前提下提升模型的泛化能力，採用下列哪一種方法最為適合？","options":{"A":"將Transformer的隱藏層維度擴增至1024，以提升表徵能力","B":"採用反向翻譯（Back-Translation）技術，以生成額外目標語句的偽平行語料（Pseudo‑Parallel Corpus）","C":"對詞嵌入矩陣（Embedding Matrix），施加L1正則化以壓縮模型參數","D":"將多語言BERT（mBERT）中所有Transformer層全部凍結以保留預訓練知識"},"answer":"B","figures":[],"explanation":{"approach":"在不新增真實語料的前提下提升低資源語言模型泛化能力，常用做法是透過反向翻譯技術，利用既有翻譯模型將目標語言句子翻回來源語言（或反之），生成偽平行語料以擴充訓練資料的多樣性，而非依賴真實標註語料。","options":{"A":"擴增隱藏層維度會提高模型複雜度，在資料量已不足的情況下反而更容易加劇過擬合，方向錯誤","B":"正確，反向翻譯技術可在不新增真實語料的前提下，利用既有資源生成額外的偽平行語料，有效擴充訓練資料多樣性、緩解過擬合","C":"對詞嵌入矩陣施加L1正則化雖有助於壓縮參數、抑制過擬合，但相較於直接擴充有效訓練訊號的反向翻譯，並非此情境下最適合的做法","D":"將所有Transformer層全部凍結會使模型無法針對低資源語言任務進行有效調整，反而限制了泛化能力的提升"}},"origin":"past"},{"id":"middle_114-2_s1_q20","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":20,"context":null,"stem":"在使用生成對抗網路（GAN）進行人臉影像生成時，若出現「模式崩潰」（Mode Collapse）現象，下列哪一種方法最常被用來有效解決此問題？","options":{"A":"在鑑別器中加入梯度懲罰（Gradient Penalty）以穩定訓練過程","B":"採用Wasserstein距離（WGAN損失）替代原始的GAN損失函數","C":"對生成器輸入的潛在向量加入隨機擾動","D":"使用多尺度鑑別器架構以提高對多樣性的判別能力"},"answer":"B","figures":[],"explanation":{"approach":"模式崩潰（Mode Collapse）是GAN訓練中生成器僅能生成有限多樣性樣本的常見問題，其根源常與原始GAN損失函數（基於JS散度）在訓練不穩定時梯度消失有關。採用Wasserstein距離（WGAN損失）取代原始GAN損失，能提供更平滑、更具資訊量的梯度訊號，是解決模式崩潰最常用的方法之一。","options":{"A":"梯度懲罰主要用於穩定WGAN訓練、強制滿足Lipschitz約束，是WGAN-GP的輔助技術，但並非解決模式崩潰最核心、最常被提及的根本方法","B":"正確，採用Wasserstein距離替代原始GAN損失函數，能提供更平滑穩定的梯度訊號，是解決模式崩潰最常見且根本的方法","C":"對潛在向量加入隨機擾動僅能局部增加輸出變化，無法從根本解決模式崩潰背後訓練不穩定的問題","D":"多尺度鑑別器架構有助於提升判別細節的能力，但並非針對模式崩潰最直接、最常用的標準解法"},"note":"選項A(梯度懲罰)實務上也能改善模式崩潰——WGAN-GP 正是「WGAN損失＋梯度懲罰」的組合,GP 是讓 WGAN 真正穩定的關鍵;選項D(多尺度鑑別器)同樣有助於提升生成多樣性。官方答案取B,是因為「以 Wasserstein 距離取代原始 GAN 損失」被視為針對模式崩潰的根本性改動(提供更平滑、不飽和的梯度訊號),GP 與多尺度鑑別器則多被歸類為訓練穩定化的輔助技巧。應試選B。"},"origin":"past"},{"id":"middle_114-2_s1_q21","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":21,"context":null,"stem":"在多模態AI模型訓練或推論過程中，遇到某一模態資料缺失（例如僅有影像資料但缺少文本說明），下列哪一種策略最有效維持模型效能？","options":{"A":"以零向量或固定向量填充缺失模態輸入","B":"訓練具備模態缺失感知能力的模型，使其適應缺失狀況","C":"利用生成模型（如GAN或自迴歸模型）預測並補全缺失模態資料","D":"直接捨棄缺少模態的樣本，避免干擾訓練或推論"},"answer":"B","figures":[],"explanation":{"approach":"面對多模態資料缺失情境，最能維持模型效能的策略是在訓練階段就讓模型具備「模態缺失感知（Modality-missing Awareness）」能力，使其學習如何在缺少特定模態時仍能有效運作，而非僅以簡單填充或捨棄資料因應。","options":{"A":"以零向量或固定向量填充是較簡易的處理方式，但無法讓模型真正學會因應缺失情境，效果有限","B":"正確，訓練具備模態缺失感知能力的模型，使其在訓練階段就適應缺失狀況，是維持模型效能最有效的策略","C":"以生成模型預測補全缺失模態存在補全結果不準確、引入額外噪音的風險，效果不一定優於讓模型直接學會適應缺失","D":"直接捨棄缺少模態的樣本會造成資料浪費，且無法讓模型具備處理真實情境中缺失資料的能力"}},"origin":"past"},{"id":"middle_114-2_s1_q22","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":22,"context":null,"stem":"某電商平台開發的顧客流失預測模型在上線數月後，預測準確率明顯下降。專案團隊懷疑顧客行為模式改變，導致模型輸入特徵的分佈與原始訓練資料不同，出現典型的資料漂移（Data Drift）問題。為了偵測並確認資料分佈是否發生變化，下列哪一種作法最合適？","options":{"A":"定期重新訓練模型以應對外部變化","B":"提升模型複雜度以捕捉更多資料變異性","C":"增加測試資料量以提高評估準確度","D":"計算輸入特徵分佈間的KL散度（KL Divergence）"},"answer":"D","figures":[],"explanation":{"approach":"偵測資料漂移的標準做法，是比較目前輸入特徵分佈與原始訓練資料分佈間的差異，KL散度（KL Divergence）是常用的分佈差異量化指標，能明確判斷分佈是否發生顯著變化。","options":{"A":"定期重新訓練是偵測到漂移後的「因應對策」，並非用於「偵測並確認」分佈是否變化的方法","B":"提升模型複雜度與偵測資料分佈是否變化無關，且可能增加過擬合風險","C":"增加測試資料量有助於提升評估的統計穩健性，但並非直接偵測特徵分佈變化的方法","D":"正確，計算輸入特徵分佈與訓練資料分佈間的KL散度，能明確量化並確認分佈是否發生顯著變化，是偵測資料漂移的合適方法"}},"origin":"past"},{"id":"middle_114-2_s1_q23","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":23,"context":null,"stem":"某大型醫院即將部署一套輔助診斷的AI系統，為降低對臨床流程的衝擊，同時確保風險可控與回饋可收斂，應採取何種『漸進式部署』（Phased Rollout）策略最為合適？","options":{"A":"從單一專科（如放射科）或特定病房開始啟用，逐步擴展至全院","B":"先部署於病例量較高的急診單位，加速收集高頻使用回饋","C":"僅在夜班或離峰時段啟用，避免影響主要臨床工作負載","D":"在使用者界面啟用提示模式，讓全院同步體驗但不影響診斷流程"},"answer":"A","figures":[],"explanation":{"approach":"漸進式部署的核心精神是先在範圍可控的小規模場域（如單一科別或病房）試行，蒐集回饋並驗證風險可控後，再逐步擴大至全院，藉此在降低臨床衝擊的同時確保回饋能有效收斂與修正。","options":{"A":"正確，從單一專科或特定病房開始，逐步擴展至全院，符合漸進式部署「風險可控、逐步收斂回饋」的核心精神","B":"急診單位病例量高、臨床情境緊急複雜，優先部署於此會提高初期風險暴露，並非漸進式部署應優先考量的低風險起點","C":"僅在離峰時段啟用雖降低即時衝擊，但無法真實反映主要臨床工作負載下的實際效果，回饋代表性不足","D":"全院同步啟用提示模式並非「漸進式」，而是同步大範圍推行，與題目要求的漸進式策略相違背"}},"origin":"past"},{"id":"middle_114-2_s1_q24","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":24,"context":null,"stem":"某金融機構的AI風控系統遭受對抗性攻擊，駭客透過對輸入特徵進行微小但惡意的擾動，成功欺騙了模型。為了從根本上解決模型自身對這類攻擊的脆弱性，下列何者並非針對此種攻擊型態的技術手段？","options":{"A":"強化資料前處理，用以過濾掉格式不符或數值極端異常的輸入","B":"在模型訓練階段導入對抗樣本訓練，以提升模型對惡意特徵擾動的辨識與防禦能力","C":"於推論後階段使用規則引擎，以確保模型的預測結果不違反既有的業務硬性規定","D":"在模型部署環境中強化網路防火牆，以阻擋來自未授權來源的網路連線"},"answer":"D","figures":[],"explanation":{"approach":"題目要求找出「並非」針對模型自身脆弱性的技術手段。對抗性攻擊利用輸入微擾騙過模型，因此資料前處理過濾、對抗樣本訓練、推論後規則檢核皆是直接強化模型或推論流程本身穩健性的技術；而網路防火牆屬於基礎設施層級的存取控制，並不能改善模型對輸入擾動本身的脆弱性。","options":{"A":"強化資料前處理過濾異常輸入，是針對輸入層防範對抗擾動的直接技術手段","B":"對抗樣本訓練直接提升模型本身對惡意擾動的辨識與防禦能力，是從根本強化模型脆弱性的核心技術","C":"推論後規則引擎可作為防線之一，攔截違反業務規則的異常預測結果，仍屬於因應此類攻擊的技術手段","D":"正確（此為並非解決模型自身脆弱性的手段），網路防火牆僅能阻擋未授權的網路連線存取，無法改善模型對輸入特徵微小擾動的內在脆弱性，與對抗性攻擊的本質問題無關"},"note":"題幹有兩個限定條件並存——「從根本上解決模型自身的脆弱性」與「並非針對此種攻擊型態」——兩者其實會指向不同選項。選項C(推論後規則引擎)確實不在「模型自身」層級,容易被誤選;但它仍是針對對抗性攻擊後果的緩解手段。選項D(網路防火牆)擋的是網路連線來源,與惡意輸入擾動完全無關,才是唯一真正「並非針對此攻擊型態」的答案。判斷準則:問這個手段跟「惡意構造的輸入」有沒有關係。"},"origin":"past"},{"id":"middle_114-2_s1_q25","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":25,"context":null,"stem":"某企業部署生成式AI系統協助行銷與內容產出，但近期遭質疑部分生成內容可能涉及著作權侵權。為降低企業在法律層面的潛在責任與風險，下列哪一項策略最能有效預防侵權問題產生？","options":{"A":"對生成內容進行語意相似度比對，自動標註可能涉及既有著作的輸出結果，以降低侵權風險","B":"建立訓練資料篩選與授權驗證機制，排除未授權或高風險資料來源","C":"在訓練與微調過程中採用差分隱私技術，避免模型記憶特定受著作權保護的樣本","D":"在模型輸出端嵌入浮水印（Watermarking）或數位指紋（DigitalFingerprint）技術，以確保生成內容可追溯"},"answer":"B","figures":[],"explanation":{"approach":"要從根本預防生成式AI的著作權侵權風險，最有效的做法是在源頭即建立訓練資料的篩選與授權驗證機制，確保訓練資料本身不含未授權或高風險來源，從而避免模型學習並生成侵權內容。","options":{"A":"語意相似度比對與標註屬於生成後的偵測與示警機制，是事後補救而非從根本預防侵權發生","B":"正確，建立訓練資料篩選與授權驗證機制，從源頭排除未授權或高風險資料來源，是最能從根本預防侵權風險的策略","C":"差分隱私主要目的是防止模型記憶並洩漏特定訓練樣本，屬於隱私保護技術，並非專門針對著作權侵權設計的預防機制","D":"浮水印與數位指紋技術是為了讓生成內容「可追溯」，屬於事後究責與識別手段，並非事前預防侵權產生的做法"}},"origin":"past"},{"id":"middle_114-2_s1_q26","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":26,"context":null,"stem":"在房價預測任務中，若發現特徵如「房間數」與「坪數」存在高度多重共線性（Multicollinearity），為降低共線性對模型參數估計的負面影響，應優先選擇下列哪種模型？","options":{"A":"不受多重共線性影響的決策樹模型","B":"傳統線性迴歸模型，不含正則化項","C":"支持向量機搭配線性核函數","D":"含L1正則化的LASSO迴歸模型"},"answer":"D","figures":[],"explanation":{"approach":"面對特徵間高度多重共線性，含L1正則化的LASSO迴歸能透過懲罰項壓縮不重要特徵的係數（甚至趨近於零），有效降低共線性對參數估計穩定性的負面影響，同時具備特徵選擇效果。","options":{"A":"決策樹屬於非參數模型，不進行迴歸係數估計，並非針對「降低共線性對迴歸參數估計影響」此需求的對應解法","B":"不含正則化項的傳統線性迴歸正是容易受多重共線性影響、導致係數不穩定的模型，並非解決方案","C":"支持向量機搭配線性核函數同樣未針對特徵共線性設計懲罰機制，無法有效緩解此問題","D":"正確，LASSO迴歸的L1正則化項能壓縮相關特徵的係數，有效降低多重共線性對參數估計的負面影響，是此情境下的優先選擇"}},"origin":"past"},{"id":"middle_114-2_s1_q27","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":27,"context":null,"stem":"某企業需分析半結構化的系統日誌（JSON格式），以提取關鍵的時序特徵供故障預測模型使用。考量日誌結構複雜且包含巢狀欄位（Nested Fields），下列哪一種策略最有效且實務可行？","options":{"A":"先將JSON資料扁平化轉成CSV，再對欄位計算統計量（如均值、次數）作為特徵","B":"使用遞歸神經網路（RNN）直接輸入原始JSON字串進行時序特徵抽取","C":"設計遞迴函式展開巢狀欄位，並基於時間窗口（Time Window）進行聚合與特徵萃取","D":"只保留時間戳記欄位，忽略其他巢狀內容以簡化特徵工程"},"answer":"C","figures":[],"explanation":{"approach":"面對包含巢狀欄位的半結構化JSON日誌，最實務可行的做法是設計遞迴函式展開巢狀結構，取得完整欄位資訊後，再依時間窗口進行聚合與特徵萃取，兼顧結構完整性與時序特徵的萃取需求。","options":{"A":"直接扁平化轉成CSV可能簡化過度、遺失巢狀欄位間的階層關係與細節資訊，難以完整反映複雜結構特性","B":"以RNN直接輸入原始JSON字串進行特徵抽取並不實務，JSON字串本身不具備適合序列模型直接處理的結構化語意","C":"正確，設計遞迴函式展開巢狀欄位，並依時間窗口進行聚合與特徵萃取，能兼顧巢狀結構完整性與時序特徵需求，最為實務可行","D":"只保留時間戳記而忽略其他巢狀內容，會遺失大量對故障預測有價值的資訊，過度簡化"}},"origin":"past"},{"id":"middle_114-2_s1_q28","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":28,"context":null,"stem":"在一個同時包含連續型特徵與類別型特徵的資料集中，若希望透過適當的特徵工程流程來提升模型整體表現，下列哪一種作法最為合適？","options":{"A":"將類別型特徵使用標籤編碼（Label Encoding）轉換後，與連續特徵直接合併進行模型訓練","B":"將連續特徵進行離散化（Discretization）或分桶（Binning）轉為類別型特徵，統一以類別方式處理","C":"對連續特徵做標準化（Standardization），類別特徵採用目標編碼（Target Encoding），並生成交互特徵提升模型表現","D":"只保留連續特徵，忽略類別型變量以簡化模型"},"answer":"C","figures":[],"explanation":{"approach":"面對連續型與類別型特徵混合的資料集，較完整的特徵工程流程應對連續特徵做標準化以消除尺度差異，對類別特徵採用目標編碼等方式有效編碼，並可進一步生成交互特徵以捕捉變數間的關聯，藉此提升模型整體表現。","options":{"A":"標籤編碼會為類別賦予人為的順序關係，可能誤導模型將無序類別誤判為具大小關係，並非最合適的處理方式","B":"將連續特徵離散化為類別型會犧牲原始數值資訊的精細度，並非提升表現最合適的統一處理方式","C":"正確，對連續特徵標準化、類別特徵採用目標編碼，並生成交互特徵，是能完整運用兩類特徵資訊、提升模型表現的合適做法","D":"捨棄類別型變量會遺失可能具預測力的資訊，並非提升整體模型表現的合適做法"}},"origin":"past"},{"id":"middle_114-2_s1_q29","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":29,"context":null,"stem":"某AI開發團隊為提升模型開發效率及品質控制，計畫實施持續整合（Continuous Integration, CI）流程。下列哪一項做法最符合CI的核心實踐，且能有效減少整合風險？","options":{"A":"在主分支（Main Branch）每日固定時間手動合併並執行完整測試流程","B":"每次程式碼提交（Commit）後自動觸發建置、單元測試及靜態程式碼分析","C":"於模型訓練完成後，定期安排開發團隊回顧並合併程式碼","D":"透過自動化部署腳本，將模型在特定時間點批次釋出到測試環境"},"answer":"B","figures":[],"explanation":{"approach":"持續整合（CI）的核心精神是頻繁且自動化地整合程式碼變更，每次提交後立即自動觸發建置、測試與程式碼檢查，及早發現整合問題，降低累積衝突與缺陷的風險。","options":{"A":"固定時間手動合併並非自動化觸發，且非「每次提交」即整合，不符合CI強調的高頻率自動整合精神","B":"正確，每次程式碼提交後自動觸發建置、單元測試及靜態程式碼分析，正是CI強調高頻率自動化驗證、及早發現問題的核心實踐","C":"訓練完成後才定期回顧合併，整合頻率低且非自動化，不符合CI精神","D":"自動化部署腳本批次釋出屬於持續部署（CD）範疇，且非提交觸發的建置測試流程，與CI核心實踐不符"}},"origin":"past"},{"id":"middle_114-2_s1_q30","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":30,"context":null,"stem":"某銀行計劃將AI詐欺偵測模組整合至核心交易系統，主管機關要求全流程必須符合金融監管對「不可否認性（Non-repudiation）」的資訊安全規範，以確保日後能進行法務追蹤與稽核。下列哪一項措施最能確保此要求的落實？","options":{"A":"為每筆AI模型推論記錄其輸入與輸出結果的加密雜湊值（Hash），並簽署數位簽章以確保不可竄改性","B":"優化模型效能以降低平均推論延遲至100ms以下，提升使用者體驗","C":"增加主機備援數量，以確保系統在故障時持續可用","D":"將模型推論請求導入負載平衡器，避免單點壅塞導致服務延遲"},"answer":"A","figures":[],"explanation":{"approach":"不可否認性要求任何操作事後皆能明確歸責、不可被否認或竄改。為每筆推論記錄計算加密雜湊值並簽署數位簽章，能確保記錄的完整性與可追溯性，滿足日後法務追蹤與稽核需求。","options":{"A":"正確，為每筆推論記錄雜湊值並簽署數位簽章，能確保記錄不可竄改且可驗證來源，直接滿足不可否認性的稽核與追蹤要求","B":"降低推論延遲屬於效能優化議題，與確保記錄不可否認、可稽核追蹤無直接關聯","C":"增加主機備援數量是提升系統可用性（Availability）的措施，與不可否認性的稽核需求無關","D":"負載平衡器用於避免服務壅塞、提升可用性，同樣與不可否認性的稽核追蹤需求無關"}},"origin":"past"},{"id":"middle_114-2_s1_q31","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":31,"context":null,"stem":"某AI服務系統每次推論請求需約1秒完成，且必須支撐高達10,000次請求每秒（RPS）的流量。為確保系統具備高可用性且能穩定應付流量峰值，下列哪一種架構方案最為合適？","options":{"A":"依賴單台超高效能伺服器進行垂直擴展，提升硬體規格","B":"採用容器化部署並水平擴展服務實例，結合自動彈性伸縮機制（Auto Scaling）","C":"限制最大併發連線數，以避免系統過載","D":"增加批次處理大小，一次同時處理上千筆請求"},"answer":"B","figures":[],"explanation":{"approach":"面對高流量（每秒萬級請求）且需高可用性的AI推論服務，容器化部署搭配水平擴展與自動彈性伸縮機制，能依實際流量動態增減服務實例，兼顧穩定性、彈性與資源效率，是雲原生架構的標準做法。","options":{"A":"依賴單台伺服器垂直擴展存在單點故障風險，且硬體規格提升有其物理上限，難以穩定支撐萬級RPS流量與高可用性需求","B":"正確，容器化部署並水平擴展搭配自動彈性伸縮機制，能依流量動態調整服務實例數量，兼顧高可用性與應付流量峰值的能力","C":"限制最大併發連線數會導致超出限制的請求被拒絕，無法達成支撐高流量的目標，與需求相違背","D":"單純增加批次處理大小可能提升單次處理效率，但無法直接解決系統整體可用性與水平擴展應付高並發流量的需求"}},"origin":"past"},{"id":"middle_114-2_s1_q32","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":32,"context":null,"stem":"某企業已將AI模型部署於生產環境，為確保系統持續穩定運作，並能提前偵測模型效能可能衰退，技術團隊希望透過監控指標進行預警。下列哪一項監控指標最具預測效力，能提早發現模型效能下滑風險？","options":{"A":"系統CPU與記憶體使用率波動幅度","B":"模型推論結果的置信度（Confidence）分佈變化趨勢","C":"API平均回應時間與延遲百分位數變化","D":"輸入特徵與訓練資料分布差異的PSI（Population StabilityIndex）指數"},"answer":"D","figures":[],"explanation":{"approach":"PSI（Population Stability Index）用於量化目前輸入特徵分佈與訓練資料分佈間的差異程度，能在模型準確率明顯下降「之前」即偵測到輸入資料分佈已偏移，具有較高的預測效力，屬於主動預警型指標。","options":{"A":"CPU與記憶體使用率反映的是系統基礎設施運作狀態，與模型預測效能本身的衰退無直接關聯","B":"推論置信度分佈變化雖能反映模型狀態，但通常是模型已受資料變化影響後產生的表徵，預警時效性不如直接監控輸入特徵分佈偏移","C":"API回應時間與延遲百分位數反映系統服務效能，與模型預測準確度的衰退無直接因果關係","D":"正確，PSI直接量化輸入特徵分布與訓練資料分布的差異程度，能在效能明顯下滑前及早發現資料偏移風險，預測效力最高"}},"origin":"past"},{"id":"middle_114-2_s1_q33","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":33,"context":null,"stem":"企業團隊在使用Word2Vec模型訓練客服文本語料時，若訓練資料量龐大且希望模型能更有效捕捉罕見詞的語意關聯，下列哪一種訓練策略最為適合？","options":{"A":"採用Skip-gram模型，但以隨機初始化權重加快高頻詞的訓練收斂","B":"採用CBOW模型（Continuous Bag of Words Model）並結合TF-IDF權重以強化低頻詞表示","C":"採用Skip-gram模型，利用中心詞預測周圍詞語，能更有效學習低頻詞關係","D":"採用CBOW模型（Continuous Bag of Words Model），利用周圍詞預測中心詞，能提升罕見詞的語意穩定度"},"answer":"C","figures":[],"explanation":{"approach":"Skip-gram模型是以中心詞預測其周圍上下文詞，訓練過程中每個中心詞會產生多個訓練樣本，對低頻詞而言能獲得較多學習機會，因此相較CBOW（以周圍詞預測中心詞、會稀釋低頻詞訊號）更能有效捕捉罕見詞的語意關聯。","options":{"A":"隨機初始化權重與訓練收斂速度並非決定能否有效捕捉低頻詞語意的關鍵因素，此描述偏離重點","B":"CBOW以上下文詞平均後預測中心詞，本身就容易稀釋低頻詞的訊號，即使結合TF-IDF權重，仍非最有效捕捉低頻詞的策略","C":"正確，Skip-gram利用中心詞預測周圍詞語，每個中心詞可產生多筆訓練樣本，因此能更有效學習低頻詞的語意關聯","D":"CBOW以周圍詞平均預測中心詞的機制，反而會稀釋低頻詞的訊號，不利於提升罕見詞的語意穩定度，此描述與實際相反"}},"origin":"past"},{"id":"middle_114-2_s1_q34","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":34,"context":null,"stem":"在自駕車影像辨識系統中，開發團隊希望模型能同時辨識每個像素所屬的物件類別（例如道路、建築、行人），又能區分出同類物件的不同個體（例如多位行人）。此時最適合採用下列哪一項電腦視覺技術？","options":{"A":"語義分割（Semantic Segmentation）","B":"物件偵測（Object Detection）","C":"實例分割（Instance Segmentation）","D":"全景分割（Panoptic Segmentation）"},"answer":"D","figures":[],"explanation":{"approach":"全景分割（Panoptic Segmentation）結合了語義分割（為每個像素標註類別）與實例分割（區分同類別的不同個體）的能力，能同時對道路、建築等「背景類別」進行像素級分類，並區分行人等「可數物件」的個別實例，正符合題目需求。","options":{"A":"語義分割僅能為每個像素標註所屬類別，無法區分同類別中不同的個體（如多位行人視為同一類，無法個別區分）","B":"物件偵測僅以邊界框標示物件位置與類別，不提供像素級的精細分類結果","C":"實例分割能區分同類別的不同個體，但通常僅處理可數物件（Things），對道路等不可數背景類別（Stuff）處理能力有限","D":"正確，全景分割同時整合語義分割（像素級類別標註）與實例分割（區分同類物件個體）的能力，完整符合題目需求"}},"origin":"past"},{"id":"middle_114-2_s1_q35","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":35,"context":null,"stem":"某媒體公司計畫導入CLIP（Contrastive Language–Image Pre-training）模型，以協助大量影像自動標註與搜尋，並希望在無需新增標訓資料的情況下，僅透過文字提示（Text Prompt）即可識別影像內容。請問此應用情境中，CLIP能夠達成的關鍵技術特性為何？","options":{"A":"透過圖文對比式學習（Contrastive Learning）將影像與文字映射至共同嵌入空間（Shared Embedding Space），可直接以語意相似度進行零樣本分類","B":"透過影像增強與特徵擴散降低標訓資料需求","C":"以監督式學習結合多層感知器（Multilayer Perceptron, MLP）進行影像特徵分類","D":"以自迴歸生成模型（Autoregressive Model）逐步生成文字標籤描述影像內容"},"answer":"A","figures":[],"explanation":{"approach":"CLIP透過圖文對比式學習，將大量圖文配對資料中的影像與文字分別編碼後映射至同一共同嵌入空間，使語意相近的圖文向量彼此靠近，因此可直接以文字提示與影像的嵌入相似度進行零樣本（Zero-shot）分類，無需額外標訓資料。","options":{"A":"正確，CLIP透過對比式學習將影像與文字映射至共同嵌入空間，可直接以語意相似度進行零樣本分類，這是其關鍵技術特性","B":"CLIP的核心技術並非影像增強與特徵擴散，此描述並未準確反映CLIP降低標訓需求的實際機制（對比式學習）","C":"CLIP採用的是對比式學習而非監督式學習搭配MLP分類，此描述與CLIP實際訓練方式不符","D":"CLIP並非以自迴歸方式逐步生成文字標籤，而是透過嵌入空間相似度比對進行分類，此描述混淆了圖像描述生成模型的機制"}},"origin":"past"},{"id":"middle_114-2_s1_q36","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":36,"context":null,"stem":"某資料科學團隊在開發預測模型時，針對多種模型設定（如學習率、樹深度、正則化係數等）進行系統化測試，希望找出在驗證資料上表現最穩定的組合。此過程最可能採用下列哪一種方法？","options":{"A":"使用交叉驗證（Cross Validation）反覆評估模型以降低過擬合風險","B":"透過網格搜尋（Grid Search）在多組超參數設定中進行系統化搜尋與評估","C":"以隨機搜尋（Random Search）快速探索部分參數空間以提升搜尋效率","D":"採用貝葉斯優化（Bayesian Optimization）根據歷次結果動態調整搜尋方向"},"answer":"B","figures":[],"explanation":{"approach":"題目描述「針對多種模型設定系統化測試，找出所有組合中表現最穩定者」，正對應網格搜尋（Grid Search）窮舉多組超參數設定組合並逐一評估的系統化搜尋方式。","options":{"A":"交叉驗證是評估模型效能、降低過擬合風險的評估方法，本身並非用來「系統化測試多種超參數組合」的搜尋策略","B":"正確，網格搜尋在多組超參數設定中進行窮舉式、系統化的搜尋與評估，正符合題目描述的系統化測試多種模型設定的做法","C":"隨機搜尋是從參數空間中隨機抽樣部分組合，並非「系統化測試」所有組合，與題目描述的系統化特性不符","D":"貝葉斯優化是依據歷次結果動態、機率性地調整搜尋方向，屬於自適應搜尋而非題目所描述的系統化窮舉測試"}},"origin":"past"},{"id":"middle_114-2_s1_q37","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":37,"context":null,"stem":"某公司正在訓練一個大型語音合成模型，開發團隊使用多台GPU進行訓練，但經常出現GPU記憶體不足問題。由於模型架構已固定且無法更換硬體，團隊希望在維持模型效能與收斂品質的前提下，下列哪一種方法最有效降低單張GPU的記憶體壓力？","options":{"A":"減少訓練資料量以降低記憶體使用","B":"採用較小的批次大小（Batch Size）並搭配資料分片（DataSharding）分散訓練負載","C":"增加學習率（Learning Rate）以加快收斂速度","D":"改用測試資料集（Test Set）進行部分訓練以節省空間"},"answer":"B","figures":[],"explanation":{"approach":"在模型架構與硬體皆固定的前提下，降低單張GPU記憶體壓力同時維持效能與收斂品質的常見做法，是採用較小的批次大小（Batch Size）以降低每次前向/反向傳播所需的記憶體，並搭配資料分片將訓練負載分散至多GPU。","options":{"A":"減少訓練資料量雖可能降低整體記憶體用量，但會犧牲模型學習到的資訊量，可能損害模型效能與收斂品質","B":"正確，採用較小批次大小可直接降低單次運算所需的記憶體，搭配資料分片將負載分散至多GPU，能在維持效能與收斂品質下降低記憶體壓力","C":"提高學習率是加快收斂速度的手段，與降低GPU記憶體壓力無直接關聯","D":"使用測試資料集進行部分訓練會造成資料使用不當（訓練/測試資料混淆），且並非解決記憶體壓力問題的合理做法"}},"origin":"past"},{"id":"middle_114-2_s1_q38","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":38,"context":null,"stem":"某影像設計團隊在使用Stable Diffusion生成4K級產品圖時，發現影像邊緣與細節存在顆粒化與模糊現象。若僅能在生成階段進行調整，希望提升畫面清晰度與紋理層次，同時避免過度平滑，下列哪一項作法最適合？","options":{"A":"降低取樣步數，以縮短生成時間","B":"增加取樣步數並選擇高品質取樣器，以強化細節還原度","C":"提高CFG（Classifier-Free Guidance）值，使生成結果更具創意與多樣性","D":"改用低解析度輸入以降低計算成本"},"answer":"B","figures":[],"explanation":{"approach":"在僅能調整生成階段參數的前提下，增加取樣步數（Sampling Steps）能讓擴散模型有更多去噪迭代機會還原細節，搭配選用高品質取樣器，可有效提升影像清晰度與紋理層次，同時避免畫面因步數不足而顆粒化或模糊。","options":{"A":"降低取樣步數雖能縮短生成時間，但會讓去噪過程不充分，反而加劇顆粒化與模糊現象，與題目目標相反","B":"正確，增加取樣步數並選用高品質取樣器，能強化去噪迭代的細節還原度，有效提升清晰度與紋理層次","C":"提高CFG值主要影響生成結果對提示語的服從程度與創意多樣性，過高反而可能造成過度銳化或失真等副作用，並非針對清晰度與細節的直接對症做法","D":"改用低解析度輸入會直接降低影像的原始細節資訊，與提升清晰度、紋理層次的目標相反"}},"origin":"past"},{"id":"middle_114-2_s1_q39","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":39,"context":null,"stem":"某企業的資料科學團隊利用ARIMA模型（AutoRegressiveIntegrated Moving Average Model）預測每週產品銷售量。模型建立完成後，分析人員發現預測誤差隨時間呈現週期性波動，且自相關函數（ACF）顯示殘差在多個時滯（Lag）上仍顯著不為零。根據上述現象，最合理的模型診斷結論為何？","options":{"A":"模型殘差符合白噪音（White Noise）假設，預測表現穩定","B":"模型殘差雖有輕微異常，但可視為隨機誤差忽略不計","C":"模型存在配適不足（Underfitting）問題，需重新調整p或q參數以捕捉時間依賴性","D":"殘差特性不影響預測結果，無須進一步修正"},"answer":"C","figures":[],"explanation":{"approach":"若ARIMA模型的殘差在多個時滯上的自相關函數（ACF）仍顯著不為零，代表殘差中仍存在未被模型捕捉到的時間依賴性結構，並不符合白噪音假設，這通常意味著模型的AR（p）或MA（q）階數設定不足，屬於配適不足（Underfitting），需要重新調整。","options":{"A":"描述錯誤，若ACF在多個時滯上顯著不為零，代表殘差並不符合白噪音假設，與題目描述的現象矛盾","B":"殘差在多個時滯上顯著的自相關屬於系統性、非隨機的殘留結構，並非可忽略的輕微異常","C":"正確，殘差仍具顯著時間依賴性代表模型配適不足，應重新調整p或q參數以更完整捕捉時間序列的依賴結構","D":"殘差特性（是否符合白噪音）直接關係到模型是否已完整捕捉資料的時間結構，會影響預測可靠性，並非無須修正"}},"origin":"past"},{"id":"middle_114-2_s1_q40","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":40,"context":null,"stem":"下列哪一項最正確地描述了VAE（Variational Autoencoder）、GAN（Generative Adversarial Network）與擴散模型（DiffusionModel）在多模態潛在空間對齊（Latent Alignment）與生成策略上的根本差異？","options":{"A":"VAE透過顯式潛在變數建模實現跨模態對齊，適合捕捉整體語意結構但生成解析度有限；GAN透過對抗損失（Adversarial Loss）在不同模態間學習分佈映射，生成品質高但穩定性差；擴散模型則以條件化噪聲反推（Conditional Denoising）方式實現高保真跨模態生成，兼具穩定性與多樣性","B":"VAE與DiffusionＭodel均屬隱式生成架構，主要依賴對抗式訓練實現跨模態對齊；GAN則以顯式後驗估計方式提升樣本一致性","C":"VAE與GAN均使用馬爾可夫鏈（Markov Chain）進行跨模態轉換；Diffusion Model則透過KL散度最小化學習語意對應。","D":"三者在多模態應用中皆依賴同一潛在表徵空間（Shared LatentSpace），僅在解碼器結構不同而已"},"answer":"A","figures":[],"explanation":{"approach":"VAE、GAN與擴散模型在生成機制上有本質差異：VAE以顯式潛在變數建模（含編碼器/解碼器與KL散度正則化）捕捉整體語意結構，但生成解析度受限；GAN以對抗損失學習分佈映射，生成品質高但訓練穩定性較差；擴散模型則透過條件化噪聲反推逐步去噪，兼顧生成穩定性與樣本多樣性。","options":{"A":"正確，此描述準確歸納VAE（顯式潛在變數、語意結構完整但解析度有限）、GAN（對抗損失、品質高但穩定性差）與擴散模型（條件化去噪、穩定性與多樣性兼具）三者的本質差異","B":"描述錯誤，VAE是以顯式潛在變數與KL散度進行後驗估計，並非依賴對抗式訓練；此段落將VAE與GAN的訓練機制錯置","C":"描述錯誤，馬爾可夫鏈是擴散模型的核心生成機制，並非VAE與GAN所使用的方法，此處張冠李戴","D":"描述錯誤，三者的潛在空間建模方式與生成機制本質不同，並非共享同一潛在表徵空間僅解碼器不同，過度簡化三者差異"}},"origin":"past"},{"id":"middle_114-2_s1_q41","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":41,"context":null,"stem":"在進行超參數調校（Hyperparameter Tuning）時，若直接在K-Fold交叉驗證（Cross-Validation）的資料上同時調整模型參數並評估效能，最可能導致下列哪一種問題？","options":{"A":"模型的交叉驗證結果出現過度樂觀偏差（Over-optimisticBias），因測試摺資料間接參與參數選擇，造成資料洩漏（DataLeakage）","B":"模型會在每一摺（Fold）內反覆調整參數，導致訓練不穩與過度正則化","C":"因交叉驗證資料被重複使用，造成效能方差增大，無法獲得穩定估計","D":"K-Fold交叉驗證的假設與超參數搜尋相衝突，導致驗證過程失效"},"answer":"A","figures":[],"explanation":{"approach":"若在K-Fold交叉驗證的同一份資料上同時進行超參數調整與效能評估，測試摺的資訊會間接透過反覆選擇最佳參數的過程「洩漏」進模型選擇中，導致最終評估結果過度樂觀，無法真實反映模型在未見資料上的表現，此即資料洩漏（Data Leakage）問題。","options":{"A":"正確，測試摺資料間接參與了參數選擇過程，形成資料洩漏，使交叉驗證結果呈現過度樂觀偏差，無法真實反映模型的泛化能力","B":"描述並未準確指出問題核心（資料洩漏導致樂觀偏差），而是泛泛地提及訓練不穩與過度正則化，未切中此情境的根本問題","C":"此情境的核心問題是評估結果的樂觀偏差（Bias），而非單純的效能方差增大，描述方向有誤","D":"K-Fold交叉驗證本身與超參數搜尋並不衝突（兩者常搭配使用），此描述誇大了兩者間的矛盾性，並非問題根本所在"}},"origin":"past"},{"id":"middle_114-2_s1_q42","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":42,"context":null,"stem":"若部署一個深度學習模型至金融風控系統，該模型採用鑑別式架構（如Transformer Classifier）。然而上線後，模型對新樣本的分類錯誤率顯著上升，經檢查發現，輸入資料分佈已與原訓練集明顯不同。針對此情形，下列哪一種應對策略最為適合？","options":{"A":"改用生成對抗網路（GAN）生成新樣本並混入訓練集","B":"改用邏輯迴歸模型（Logistic Regression）以提升穩定性","C":"增加模型容量（Model Capacity），以學習更多樣本差異","D":"使用變分自編碼器（VAE）監控潛在空間分佈，偵測輸入資料偏移"},"answer":"D","figures":[],"explanation":{"approach":"當輸入資料分佈已與原訓練集不同（資料漂移）導致鑑別式模型錯誤率上升時，可利用VAE學習正常資料的潛在空間分佈，藉由監控新輸入樣本在潛在空間中的分佈是否偏離正常範圍，達到即時偵測輸入資料偏移的目的。","options":{"A":"以GAN生成新樣本混入訓練集屬於資料增強手法，並非直接針對「偵測」輸入資料是否已偏移這一核心需求的對應做法","B":"改用邏輯迴歸僅是更換模型類型，並未解決輸入資料分佈偏移本身的偵測與因應問題","C":"增加模型容量可能使模型更容易過擬合於舊分佈資料，無助於偵測或因應輸入資料分佈偏移","D":"正確，利用VAE監控潛在空間分佈，能有效偵測新輸入資料是否偏離原訓練資料分佈範圍，是因應資料偏移偵測需求的合適策略"}},"origin":"past"},{"id":"middle_114-2_s1_q43","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":43,"context":null,"stem":"某金融科技公司欲導入AI模型協助客服郵件自動分類（投訴、詢問、表揚）。團隊同時考慮兩種模型設計：方案A（生成式路徑）：採用VAE建構潛在語意空間，再結合下游分類器進行標籤預測；方案B（鑑別式路徑）：採用BERT Classifier直接根據輸入文本進行監督式分類。現有標註資料約2,000筆，資料分佈均勻但擴充成本高。若團隊希望公平比較兩種模型的資料利用效率與泛化能力，下列哪一種實驗設計最能突顯兩者的本質差異？","options":{"A":"在完整資料集上分別訓練兩者，並比較其分類準確率（Accuracy）與推論時間","B":"在低資源情境（Low-resource Setting）下，逐步減少標註比例（100%、50%、10%），比較其F1-score","C":"使用GAN自動生成文本樣本補足資料，觀察兩模型在資料增強後的精確率（Precision）差異","D":"在相同訓練資料上固定輸入維度，僅調整模型參數量，比較其對過擬合的敏感度"},"answer":"B","figures":[],"explanation":{"approach":"要突顯生成式（VAE）與鑑別式（BERT）路徑在「資料利用效率」與泛化能力上的本質差異，最合適的實驗設計是在低資源情境下逐步減少標註資料比例（如100%、50%、10%），觀察兩者F1-score隨資料量減少的變化趨勢，此設計能直接反映兩種路徑對標註資料量的敏感度差異。","options":{"A":"僅在完整資料集上比較準確率與推論時間，無法反映資料量減少時兩者資料利用效率的差異，未觸及題目核心關注點","B":"正確，在低資源情境下逐步減少標註比例並比較F1-score，能直接突顯生成式與鑑別式路徑在資料利用效率與泛化能力上的本質差異","C":"以GAN生成樣本補足資料會引入額外的生成品質、雜訊等混淆變數，無法乾淨地比較兩模型本身的資料利用效率","D":"固定輸入維度僅調整模型參數量比較過擬合敏感度，測試的是模型容量與過擬合關係，並非資料利用效率的本質差異"}},"origin":"past"},{"id":"middle_114-2_s1_q44","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":44,"context":null,"stem":"某電信公司希望建立一個模型來預測顧客是否即將流失，並進一步模擬不同促銷或服務策略下顧客的行為變化，以生成多樣化的虛擬樣本資料進行A/B測試與行銷策略評估。若要同時兼顧預測與資料生成的需求，最適合採用下列哪一種方法？","options":{"A":"使用傳統隨機森林（Random Forest）","B":"使用邏輯迴歸（Logistic Regression）模型","C":"使用變分自編碼器（Variational Autoencoder, VAE）或生成對抗網路（Generative Adversarial Network, GAN）","D":"使用強化學習代理（Reinforcement Learning Agent）"},"answer":"C","figures":[],"explanation":{"approach":"題目同時需要「預測顧客流失」與「生成多樣化虛擬樣本進行模擬」兩項能力，VAE與GAN皆屬於生成式模型，具備學習資料潛在分佈並生成新樣本的能力，同時其潛在表示或衍生模型亦可用於預測任務，是唯一能同時滿足兩項需求的選項。","options":{"A":"隨機森林是純預測（判別式）模型，不具備生成新樣本資料的能力，無法滿足題目對資料生成的需求","B":"邏輯迴歸同樣僅能用於預測分類，不具備生成多樣化虛擬樣本的能力","C":"正確，VAE或GAN皆屬於生成式模型，除可應用於預測相關任務外，更能學習資料分佈並生成多樣化虛擬樣本，同時滿足預測與生成雙重需求","D":"強化學習代理主要用於透過獎勵訊號學習序列決策策略，並非設計用於生成虛擬顧客樣本資料的典型方法"}},"origin":"past"},{"id":"middle_114-2_s1_q45","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":45,"context":null,"stem":"進行影像分類任務時，研究團隊嘗試利用主成分分析（PrincipalComponent Analysis, PCA）將輸入特徵從1024維降至100維，並將降維後的資料輸入支持向量機（Support Vector Machine, SVM）模型進行訓練。關於此作法，下列哪一項描述最為合理？","options":{"A":"PCA保留的主成分必然能提升SVM的分類準確率","B":"使用原始高維資料通常更能保留資訊，因此PCA沒有實際意義","C":"PCA可讓SVM自動適用於非線性（Nonlinear）資料集","D":"降維後可降低訓練時間並減少過擬合（Overfitting）風險"},"answer":"D","figures":[],"explanation":{"approach":"PCA將高維特徵降至較低維度後再輸入SVM訓練，主要效益是減少特徵維度、降低運算複雜度與訓練時間，同時透過去除冗餘與雜訊資訊，有助於降低模型在高維稀疏空間中過擬合的風險。","options":{"A":"「必然」提升準確率的說法過於絕對，PCA降維過程可能損失部分判別性資訊，不保證分類準確率必然提升","B":"使用原始高維資料未必更能保留「有用」資訊，因為高維資料常包含冗餘或雜訊，PCA降維並非「沒有實際意義」","C":"PCA是線性轉換技術，並不會讓SVM自動具備處理非線性資料的能力，這需要透過核函數（Kernel Trick）另行達成，與PCA降維無關","D":"正確，降維後能減少特徵數量，進而降低訓練所需運算時間，並因去除冗餘/雜訊資訊而降低模型過擬合的風險"}},"origin":"past"},{"id":"middle_114-2_s1_q46","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":46,"context":null,"stem":"某企業的AI模型已部署於線上服務環境中，用於即時預測顧客流失機率。近期團隊注意到模型預測準確率逐漸下降，但系統運作正常且未出現錯誤訊息。經分析發現，近期輸入資料的分布與模型訓練資料相比出現顯著偏移。若要在MLOps流程中主動偵測並預警此類問題，最應採用下列哪項措施？","options":{"A":"建立即時的資料漂移（Data Drift）與概念漂移（ConceptDrift）監測機制","B":"將模型轉換為量化版本以降低延遲","C":"增加模型超參數調整次數以強化適應性","D":"使用固定隨機種子（Random Seed）確保訓練穩定"},"answer":"A","figures":[],"explanation":{"approach":"要在MLOps流程中主動偵測並預警因輸入分佈偏移造成的效能衰退，應建立即時的資料漂移與概念漂移監測機制，持續比較線上輸入/預測分佈與訓練時的基準分佈，及早發現異常並觸發警示。","options":{"A":"正確，建立即時的資料漂移與概念漂移監測機制，能主動且持續地偵測輸入分佈變化，及早預警模型效能衰退風險","B":"模型量化主要目的是降低推論延遲與資源占用，與偵測資料分佈偏移、預警效能衰退並無直接關聯","C":"增加超參數調整次數屬於模型開發階段的優化行為，並非上線後主動監測資料分佈變化的預警機制","D":"固定隨機種子確保的是訓練過程的可重現性，與線上資料分佈偏移的即時監測與預警無關"}},"origin":"past"},{"id":"middle_114-2_s1_q47","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":47,"context":null,"stem":"某金融科技公司導入多任務學習架構，讓單一Transformer模型同時執行OCR（Optical Character Recognition）後的文檔分類以及命名實體辨識（Named Entity Recognition, NER）任務，以協助自動歸檔與抽取關鍵金融資訊。在部署初期，團隊發現當模型的NER準確率（Accuracy）提升時，文檔分類準確率反而下降。若模型架構正確且資料品質良好，下列哪一項最可能是造成此現象的原因？","options":{"A":"模型架構無法同時支援文字分類與序列標註任務（SequenceLabeling）","B":"文檔分類任務不需要語意化表徵（ContextualizedRepresentation）","C":"損失函數（Loss Function）未進行權重平衡，導致任務間競爭","D":"所使用的BERT模型無法支援多任務輸出頭（Multi-HeadOutputs）"},"answer":"C","figures":[],"explanation":{"approach":"題目已排除架構不支援與資料品質問題，在多任務學習中，若損失函數未針對各任務的損失進行權重平衡，容易造成某一任務（如NER）在優化過程中主導梯度更新方向，排擠另一任務（文檔分類）的學習資源，形成任務間的負遷移（Negative Transfer）競爭現象。","options":{"A":"題目已說明模型架構正確，故並非架構本身無法支援文字分類與序列標註的雙重任務","B":"文檔分類同樣需要語意化表徵才能有效判斷文件類別，此描述與實際需求不符","C":"正確，損失函數未進行任務間的權重平衡，會使某一任務的損失主導整體梯度更新，造成任務間相互競爭、此消彼長的現象","D":"BERT架構本身可支援多任務輸出頭設計，這是常見的多任務學習架構，並非導致準確率此消彼長的原因"}},"origin":"past"},{"id":"middle_114-2_s1_q48","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":48,"context":null,"stem":"某數據工程師使用DBSCAN演算法對一份數百萬筆的高維顧客資料進行聚類分析，但發現程式執行速度極慢，甚至出現記憶體不足的情況。若要在不改變演算法核心邏輯的前提下，最有效提升其運算效率的作法為何？","options":{"A":"改用以平均連結（Average Linkage）為基礎的階層式群集法（Hierarchical Clustering）","B":"採用高效率的距離索引結構（Distance Index Structure），例如KD-Tree或Ball Tree","C":"將ε（Epsilon）參數調得極小，以減少鄰近點的數量","D":"在資料前處理時增加標準化後的特徵維度數"},"answer":"B","figures":[],"explanation":{"approach":"在不改變DBSCAN核心演算法邏輯的前提下，最有效提升大規模資料鄰近點查詢效率的方式，是採用KD-Tree、Ball Tree等高效率距離索引結構加速鄰域查詢，避免每次都需與所有點逐一計算距離（暴力搜尋）。","options":{"A":"改用階層式群集法屬於更換演算法本身，違反「不改變演算法核心邏輯」的前提要求","B":"正確，採用KD-Tree或Ball Tree等高效距離索引結構，能加速鄰域查詢效率，在不改變DBSCAN核心邏輯的前提下有效提升運算效率","C":"將ε調得極小會改變分群結果的語意（可能使多數點被判為雜訊），屬於改變演算法行為結果，並非單純的效能優化手段","D":"增加特徵維度會加劇高維空間中的維度詛咒（Curse of Dimensionality），使距離計算更困難、運算效率更差，與題目目標相反"},"note":"KD-Tree、Ball Tree等索引結構的加速效果在「極高維度」資料下會因維度詛咒而遞減，此為業界公認的實務限制；但在題目所給選項中，B仍是「不改變演算法核心邏輯」前提下最標準、最常見的效率提升做法，故仍依官方答案採B。"},"origin":"past"},{"id":"middle_114-2_s1_q49","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":49,"context":null,"stem":"某電商平台導入AI情感分析模型，用以自動偵測顧客評論中的負面情緒並觸發客服機制。然而，上線後發現模型在面對不同語言或族群書寫風格的評論時表現不一致，例如部分語氣強烈的正面評論被誤判為負面，而禮貌但含批評意圖的評論卻被判為中性。若從技術與資料治理的角度分析，下列哪一項描述不正確？","options":{"A":"模型未啟用詞嵌入正規化（Embedding Normalization）可能造成語意距離不穩定，導致預測誤差","B":"訓練語料若偏向特定文化或語氣特徵，可能使模型產生內隱偏誤（Implicit Bias）","C":"模型若訓練資料來源不平衡，容易導致對不同語言或族群風格的情緒判斷不準確","D":"Transformer架構能捕捉上下文語意，但若訓練資料偏差仍存在，模型仍可能學習到偏誤判斷"},"answer":"A","figures":[],"explanation":{"approach":"本題詢問「哪一項描述不正確」。題目描述的現象（不同語言/族群書寫風格判讀不一致）根本原因通常在於訓練資料的文化/語氣分佈不平衡所導致的模型偏誤，而非詞嵌入是否正規化；因此選項A將現象歸因於「未啟用詞嵌入正規化」是不準確的技術診斷，為錯誤描述，其餘選項則正確反映資料代表性與模型偏誤間的關係。","options":{"A":"此為不正確描述（即本題答案），詞嵌入正規化與否主要影響向量尺度一致性，並非造成不同語言/族群語氣判讀不一致的主要原因，此現象根本原因應是訓練資料的文化/語氣代表性不足所致的偏誤，而非嵌入正規化問題","B":"此描述正確，訓練語料若偏向特定文化或語氣特徵，確實可能使模型學習到內隱偏誤，導致對不同風格文本的判斷失準","C":"此描述正確，訓練資料來源不平衡是導致模型對不同語言或族群風格情緒判斷不準確的常見且直接原因","D":"此描述正確，Transformer雖能捕捉上下文語意，但模型仍會學習訓練資料中存在的偏差，若資料本身有偏誤，模型仍可能產生偏誤判斷"}},"origin":"past"},{"id":"middle_114-2_s1_q50","level":"middle","session":"114-2","subject":1,"subject_name":"人工智慧技術應用與規劃","number":50,"context":null,"stem":"某設計師使用公司內部建置的生成式AI工具製作行銷素材，並輸入提示語（Prompt）：「請生成一張模特兒手持品牌飲料、背景為海邊夕陽的照片」。系統能正確生成主要主題與場景，但輸出的圖像中，品牌標誌顏色常有誤差，或人物手部姿勢顯得不自然。若從多模態生成模型的技術機制分析，此現象最可能是下列哪一項原因所造成？","options":{"A":"擴散式生成模型的去雜訊過程出現隨機梯度漂移，導致影像像素錯誤","B":"提示語過長造成Transformer的位置編碼超出上下文限制，導致生成混亂","C":"CLIP模型中的文字編碼器與影像編碼器在語意嵌入空間未充分對齊，導致跨模態理解偏差","D":"模型未採用對比學習（Contrastive Learning）損失函數，無法建立多模態語意關聯"},"answer":"C","figures":[],"explanation":{"approach":"多模態生成模型（如結合CLIP的文生圖系統）若在文字編碼器與影像編碼器的語意嵌入空間對齊不夠充分，即使能生成主要主題與場景，對於細節（如特定品牌標誌顏色、手部等精細結構）的跨模態語意理解仍容易出現偏差，導致細節錯誤或不自然。","options":{"A":"「隨機梯度漂移」並非擴散模型去雜訊過程中被廣泛認定、標準化描述的技術現象，此描述並不準確","B":"提示語長度導致位置編碼超出上下文限制，通常會造成生成內容整體混亂或提示被截斷，與題目描述的「主體正確但特定細節有誤」的現象特徵不符","C":"正確，CLIP的文字與影像編碼器若在語意嵌入空間未充分對齊，會導致模型對細節（如品牌標誌顏色、手部姿勢等精細跨模態語意）的理解出現偏差，是此現象最可能的原因","D":"CLIP的核心訓練機制正是採用對比學習（Contrastive Learning），此描述與CLIP實際採用的技術方法相矛盾，並非正確原因"}},"origin":"past"},{"id":"middle_114-2_s2_q01","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":1,"context":null,"stem":"若某數據點的Z分數（Z-Score）= 2，請問代表下列哪一種意涵？","options":{"A":"代表該數據點之原始數值為2","B":"該數據點比平均值低2個標準差","C":"代表數據為異常值","D":"該數據點比平均值高2個標準差"},"answer":"D","figures":[],"explanation":{"approach":"Z分數定義為(X-μ)/σ，表示該數值距離平均值有幾個標準差；Z=2代表該值高於平均值2個標準差，可用於衡量相對位置與離群程度。","options":{"A":"錯誤，Z分數是標準化後的相對位置指標，並非原始數值，原始數值需靠μ與σ換算回推。","B":"錯誤，Z=2為正值，代表高於平均值而非低於，方向搞反。","C":"錯誤，Z=2雖然數值較大，但是否屬異常值需依判斷門檻（如|Z|≥3）而定，不能僅憑Z=2直接判定為異常值。","D":"正確，Z分數計算式為(X-μ)/σ，Z=2代表該數據點高於平均值2個標準差。"}},"origin":"past"},{"id":"middle_114-2_s2_q02","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":2,"context":null,"stem":"使用Python的pandas套件處理各商品銷售數據（變數為df）時，若需計算「總銷售額」欄位的敘述性統計量（如平均值、標準差等），應使用下列哪一種語法？","options":{"A":"df['總銷售額'].sum()","B":"df['總銷售額'].describe()","C":"df['總銷售額'].sort_values()","D":"df['總銷售額'].stats()"},"answer":"B","figures":[],"explanation":{"approach":"pandas的describe()方法會針對數值型Series一次輸出count、mean、std、min、四分位數與max等敘述性統計量，是計算多項統計量最直接的語法。","options":{"A":"錯誤，sum()僅計算總和，無法得到平均值、標準差等統計量。","B":"正確，describe()會一次回傳count、mean、std、min、25%/50%/75%分位數與max，符合題目需求。","C":"錯誤，sort_values()僅用於排序，不會產生統計量。","D":"錯誤，pandas Series並無stats()方法，此為不存在的語法會產生錯誤。"}},"origin":"past"},{"id":"middle_114-2_s2_q03","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":3,"context":null,"stem":"附圖為某資料之分佈圖，此圖資料之偏態（Skewness）值較有可能為下列哪個選項？","options":{"A":"Skewness < 0","B":"Skewness > 0","C":"Skewness = 0","D":"無法計算Skewness"},"answer":"A","figures":[{"src":"images/middle_114-2_s2_q03_fig1.png","position":"stem"}],"explanation":{"approach":"由附圖可見資料分布左側（較小數值）有較長的尾巴延伸至負值，而眾數（峰值）偏向右側較大數值處，此為左偏（負偏）分布的典型特徵，故偏態值應小於0。","options":{"A":"正確，圖形左側尾巴較長、峰值偏右，屬於左偏分布，偏態係數為負，即Skewness < 0。","B":"錯誤，Skewness > 0代表右偏（尾巴在右側），與圖中左側長尾的型態相反。","C":"錯誤，Skewness = 0代表對稱分布，但圖形明顯不對稱，並非左右對稱。","D":"錯誤，只要資料為數值型且有變異，偏態係數皆可計算，並非無法計算。"}},"origin":"past"},{"id":"middle_114-2_s2_q04","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":4,"context":null,"stem":"累積分佈函數（Cumulative Distribution Function, CDF）可用於描述隨機變數的機率分佈特性，其數學定義為下列何者？","options":{"A":"機率密度函數（Probability Density Function, PDF）的平均值","B":"機率密度函數（Probability Density Function, PDF）的積分","C":"機率密度函數（Probability Density Function, PDF）的離散總和","D":"機率密度函數（Probability Density Function, PDF）的標準差"},"answer":"B","figures":[],"explanation":{"approach":"累積分佈函數F(x)=P(X≤x)，對連續隨機變數而言，其定義為機率密度函數（PDF）從負無窮到x的積分，代表隨機變數小於等於某值的累積機率。","options":{"A":"錯誤，CDF並非PDF的平均值，兩者定義完全不同。","B":"正確，CDF的數學定義即為PDF在區間上的積分，F(x)=∫PDF dt。","C":"錯誤，「離散總和」是離散隨機變數機率質量函數（PMF）的累加方式，連續變數的CDF是用積分而非總和。","D":"錯誤，CDF與標準差無直接定義關係，標準差是描述離散程度的另一統計量。"}},"origin":"past"},{"id":"middle_114-2_s2_q05","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":5,"context":null,"stem":"在進行資料前處理時，若使用Label Encoding將類別變數轉換為數字型態，下列何者為最常見的潛在風險？","options":{"A":"無法處理缺值","B":"會引入類別之間的虛假順序關係","C":"無法擴展至新資料","D":"記憶體佔用過高"},"answer":"B","figures":[],"explanation":{"approach":"Label Encoding會將類別以整數編碼（如0,1,2...），若類別本身為無序（Nominal），模型可能誤將編碼數值大小解讀為具有順序或距離關係，造成錯誤的特徵學習，是其最常見的風險。","options":{"A":"錯誤，Label Encoding本身不處理缺值，此非其典型風險。","B":"正確，整數編碼會隱含大小順序，對無序類別而言會產生虛假的順序關係，誤導模型判斷。","C":"錯誤，Label Encoding可對新類別給予新編碼（雖需額外處理），「無法擴展」並非其主要風險。","D":"錯誤，Label Encoding僅用單一整數欄位表示類別，相較One-Hot反而更省記憶體，不會造成記憶體佔用過高。"}},"origin":"past"},{"id":"middle_114-2_s2_q06","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":6,"context":null,"stem":"在進行資料分析時，會遇到類別型（Categorical）與數值型（Numerical）資料格式。關於這兩種資料格式的處理，下列敘述何者不正確？","options":{"A":"One-Hot編碼（One-Hot Encoding）會將類別變數轉換為多維二元向量，適用於無序（Nominal）類別資料，但在高基數（HighCardinality）特徵下可能造成維度爆炸問題","B":"標籤編碼（Label Encoding）會以整數表示不同類別，若應用於無序（Nominal）資料，可能導致模型誤將編碼值解讀為具數值大小關係的特徵","C":"標準化（Standardization）透過將資料平移與縮放，使其平均值為0、標準差為1，可在多數距離型演算法中改善收斂速度，並同時將數值範圍壓縮至0至1之間","D":"對連續變數進行分箱（Binning）可提升模型可解釋性，但若分段方式未依據資料分佈特性設計，可能導致資訊損失或邊界偏誤"},"answer":"C","figures":[],"explanation":{"approach":"本題考察資料前處理方法定義是否正確。標準化（Standardization）是將資料轉換為平均值0、標準差1，數值範圍並不會被限制在0至1之間；會將數值壓縮到0至1的是Min-Max正規化，而非標準化，故C選項敘述有誤，為本題應選出之不正確敘述。","options":{"A":"正確敘述，One-Hot Encoding確實適用於無序類別，但類別數過多（高基數）時會造成維度爆炸，描述無誤。","B":"正確敘述，Label Encoding以整數表示類別，若用於無序資料確實可能被模型誤判為具大小關係。","C":"不正確敘述（為本題答案），標準化只會使平均值為0、標準差為1，並不會將數值範圍壓縮至0至1，此為Min-Max正規化的效果，兩者被誤植混淆。","D":"正確敘述，分箱可提升可解釋性，但不當的分段方式確實可能造成資訊損失或邊界偏誤。"}},"origin":"past"},{"id":"middle_114-2_s2_q07","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":7,"context":null,"stem":"在資料庫的ACID特性中，下列何者為「原子性（Atomicity）」的正確定義？","options":{"A":"所有資料欄位必須為相同型別","B":"每次交易需以批次方式執行","C":"交易不可分割，需完全成功或完全失敗","D":"系統會自動同步交易資料至所有節點"},"answer":"C","figures":[],"explanation":{"approach":"ACID中的原子性（Atomicity）指一個交易（Transaction）中的所有操作被視為單一不可分割的單位，要嘛全部執行成功，要嘛全部失敗回復，不會出現部分完成的狀態。","options":{"A":"錯誤，欄位型別一致與原子性無關，這是資料庫schema設計的問題。","B":"錯誤，批次執行方式描述的是執行模式，並非原子性的定義。","C":"正確，原子性即交易不可分割，需完全成功或完全失敗（全有全無）。","D":"錯誤，自動同步至所有節點描述的較接近分散式系統的複寫或一致性機制，並非原子性定義。"}},"origin":"past"},{"id":"middle_114-2_s2_q08","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":8,"context":null,"stem":"資料科學家為分析顧客行為，利用現有欄位「銷售金額」與「瀏覽次數」，計算出新變數「銷售金額/瀏覽次數」。此動作屬於下列哪一類特徵工程方法？","options":{"A":"特徵選擇（Feature Selection）","B":"特徵衍生（Feature Derivation）","C":"特徵轉換（Feature Transformation）","D":"分箱處理（Binning）"},"answer":"B","figures":[],"explanation":{"approach":"利用既有欄位透過運算（相除）產生具業務意義的新變數（如轉換率），屬於從原始特徵組合、計算衍生出新特徵的過程，即特徵衍生（Feature Derivation）。","options":{"A":"錯誤，特徵選擇是從既有特徵中挑選出重要子集，並未產生新變數，與題目「計算新變數」不符。","B":"正確，將「銷售金額」與「瀏覽次數」透過相除運算組合成新變數，屬於利用既有欄位衍生新特徵的特徵衍生方法。","C":"錯誤，特徵轉換通常指對單一變數做數學轉換（如取對數、標準化），而非結合多個欄位產生新特徵。","D":"錯誤，分箱處理是將連續數值切分為區間類別，與此處計算比率新變數的作法不同。"}},"origin":"past"},{"id":"middle_114-2_s2_q09","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":9,"context":null,"stem":"在進行數值特徵的標準化（Normalization）時，若資料中存在極端值（Outliers），下列哪一種方法最適合使用？","options":{"A":"Min-Max正規化（Min-Max Scaling）","B":"Z-score標準化（Z-score Normalization）","C":"穩健縮放（Robust Scaling）","D":"標準分箱（Standard Binning）"},"answer":"C","figures":[],"explanation":{"approach":"穩健縮放（Robust Scaling）是利用中位數與四分位距（IQR）進行縮放，不受極端值影響，因此在資料含有離群值時最能穩定地標準化數值特徵。","options":{"A":"錯誤，Min-Max正規化會利用最大最小值進行縮放，極端值會嚴重壓縮其餘資料的分布範圍。","B":"錯誤，Z-score標準化使用平均值與標準差，而平均值與標準差皆容易受極端值影響而失真。","C":"正確，Robust Scaling以中位數與IQR為基準，對極端值具有穩健性，最適合含離群值的資料。","D":"錯誤，「標準分箱」並非標準化方法的正式名稱，也不具備處理極端值的穩健特性。"}},"origin":"past"},{"id":"middle_114-2_s2_q10","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":10,"context":null,"stem":"下列哪一種情境最適合應用異常偵測（Anomaly Detection）技術？","options":{"A":"根據歷史銷售資料預測特定商品在旺季期間是否會出現供貨短缺，以提前調整庫存策略","B":"透過信用風險模型預測顧客是否可能發生違約，以輔助核貸決策","C":"即時分析金融交易資料流，偵測與平常交易行為明顯不同的可疑交易紀錄","D":"監控線上服務平台的使用者登入次數，預測次日的登入量變化趨勢"},"answer":"C","figures":[],"explanation":{"approach":"異常偵測技術目的是即時或事後找出與正常行為模式明顯偏離的少數個案，金融交易監控中偵測與平常行為顯著不同的可疑交易，正是異常偵測的典型應用場景。","options":{"A":"錯誤，此為時間序列/需求預測問題，目標是預測未來供貨短缺，屬於預測模型而非異常偵測。","B":"錯誤，違約預測屬於分類（信用評分）模型，是對已知標籤學習違約與否，並非偵測異常。","C":"正確，即時偵測與平常交易模式明顯不同的可疑紀錄，正是異常偵測技術的核心應用。","D":"錯誤，預測次日登入量趨勢屬於時間序列預測問題，而非偵測單筆異常事件。"}},"origin":"past"},{"id":"middle_114-2_s2_q11","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":11,"context":null,"stem":"若一家公司需即時監控大量物聯網裝置的異常行為，下列哪一種組合最適合此應用？","options":{"A":"傳統關聯式資料庫+圖形視覺化","B":"批次資料處理+雲端備份","C":"大數據平台+即時資料分析技術","D":"Word文件+手動標註"},"answer":"C","figures":[],"explanation":{"approach":"大量物聯網裝置產生高速、大量的即時資料，需要具備大數據處理能力的平台搭配即時資料分析技術，才能在裝置產生資料的同時即時偵測異常行為。","options":{"A":"錯誤，傳統關聯式資料庫難以應付大量高速寫入與即時分析需求，圖形視覺化也非即時偵測核心技術。","B":"錯誤，批次資料處理有延遲，無法滿足「即時監控」的要求，雲端備份更與即時分析無關。","C":"正確，大數據平台可承載大量IoT資料，搭配即時資料分析技術才能達成即時監控異常行為的目標。","D":"錯誤，Word文件與手動標註完全無法處理大量、高速的即時資料，不具可行性。"}},"origin":"past"},{"id":"middle_114-2_s2_q12","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":12,"context":null,"stem":"在處理分類問題時，若某一類樣本數明顯少於其他類別，研究人員可能採用隨機過採樣（Random Oversampling）以平衡資料比例，此方法最常造成下列哪一種問題？","options":{"A":"增加過擬合風險","B":"降低模型的收斂速度","C":"減少資料總筆數數量","D":"導致訓練資料欄位缺失"},"answer":"A","figures":[],"explanation":{"approach":"隨機過採樣是直接複製少數類樣本以增加其數量，由於是重複既有樣本而非產生新資訊，模型容易對這些重複樣本過度學習，導致過擬合風險提升。","options":{"A":"正確，過採樣重複複製少數類樣本，使模型容易記住重複資料的特徵，提高過擬合風險。","B":"錯誤，過採樣一般會增加訓練資料量，不必然降低收斂速度，此非其典型問題。","C":"錯誤，過採樣是增加樣本數（複製少數類），而非減少資料總筆數。","D":"錯誤，過採樣是複製既有樣本列，不會導致欄位缺失的問題。"}},"origin":"past"},{"id":"middle_114-2_s2_q13","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":13,"context":null,"stem":"下列何者為同態加密（Homomorphic Encryption）技術的核心特性？","options":{"A":"將資料轉換為匿名識別碼以隱藏身分","B":"對資料進行標準化處理以提升模型精度","C":"自動偵測與排除異常值","D":"可直接在加密狀態下進行數據運算"},"answer":"D","figures":[],"explanation":{"approach":"同態加密的核心特性在於允許對加密後的密文直接執行數學運算，運算結果解密後會與對明文執行相同運算的結果一致，因此資料在整個運算過程中都不需被解密，可保護隱私。","options":{"A":"錯誤，將資料轉為匿名識別碼是匿名化（Anonymization）技術，並非同態加密的核心特性。","B":"錯誤，標準化是資料前處理技術，與加密運算無關。","C":"錯誤，自動偵測異常值屬於異常偵測技術範疇，並非同態加密的功能。","D":"正確，同態加密可讓系統在不解密的情況下直接對加密資料進行運算，是其最核心的技術特性。"}},"origin":"past"},{"id":"middle_114-2_s2_q14","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":14,"context":null,"stem":"某組資料共10項標籤如下：A, A, A, A, A, B, B, B, B, B若該標籤僅有A、B兩種，請問這組資料的「正規化吉尼不純度（Normalized Gini impurity）」為何？","options":{"A":"0","B":"0.42","C":"0.84","D":"1"},"answer":"D","figures":[],"explanation":{"approach":"吉尼不純度（Gini impurity）計算式為1-Σp_i²，此資料A、B各佔一半（p_A=p_B=0.5），故Gini=1-(0.5²+0.5²)=0.5，恰為二元分類下的最大不純度。正規化吉尼不純度是將Gini值除以該類別數下的最大可能值（二元類別最大值為0.5）進行標準化，0.5/0.5=1，代表此資料達到最大混亂（不純）程度。","options":{"A":"錯誤，0代表完全純（只有單一類別），但此資料A、B各半，並非純資料。","B":"錯誤，0.42並非此均勻二元分布計算出的數值，計算有誤。","C":"錯誤，0.84亦非正確計算結果，並非此均勻分布之正規化吉尼值。","D":"正確，A、B各佔50%為二元分類下最不純（最混亂）的情況，其正規化吉尼不純度達到最大值1。"}},"origin":"past"},{"id":"middle_114-2_s2_q15","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":15,"context":null,"stem":"某家客服中心統計資料發現，平均每小時會接到約20通顧客來電，但每分鐘的來電數量不固定，可能為0、1、2通不等。這些來電事件彼此獨立，且在短時間內，發生的機率與時間長短成正比。若要以機率模型描述「每分鐘接到幾通來電」的機率分佈，下列哪一種最適合使用？","options":{"A":"均勻分佈（Uniform distribution）","B":"指數分佈（Exponential distribution）","C":"卜瓦松分佈（Poisson distribution）","D":"常態分佈（Normal distribution）"},"answer":"C","figures":[],"explanation":{"approach":"題目描述的來電事件彼此獨立、發生機率與時間長短成正比、且可能為0、1、2次不等的離散計數事件，符合卜瓦松過程（Poisson Process）的假設，因此描述「單位時間內發生次數」的機率分佈應使用卜瓦松分佈。","options":{"A":"錯誤，均勻分佈用於描述數值在固定區間內每個值出現機率相等，不符合來電次數的計數特性。","B":"錯誤，指數分佈描述的是「事件之間的等待時間」而非「單位時間內發生次數」，兩者是同一卜瓦松過程的不同面向。","C":"正確，每分鐘的來電次數為離散計數、事件獨立且平均發生率固定，正是卜瓦松分佈的典型應用情境。","D":"錯誤，常態分佈是連續型分佈，不適合描述0、1、2通等非負整數的計數資料。"}},"origin":"past"},{"id":"middle_114-2_s2_q16","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":16,"context":null,"stem":"某金融科技公司以Z分數（Z-Score）監控交易金額異常狀況。若交易金額平均為新台幣2,000元，標準差為400元，某筆交易金額為3,200元，且公司以|Z| ≥ 3判定為異常值（Outlier），下列判斷何者最為正確？","options":{"A":"該筆交易的Z分數為3，應標記為異常值","B":"該筆交易的Z分數為2.5，屬於合理變異範圍","C":"該筆交易的Z分數為2，顯示模型標準差估計過高","D":"該筆交易的Z分數為1.5，無須納入異常檢測"},"answer":"A","figures":[],"explanation":{"approach":"Z分數計算公式為(X-μ)/σ=(3200-2000)/400=3，恰好達到公司設定的|Z|≥3門檻，依規則應判定為異常值。","options":{"A":"正確，計算得Z=3，達到|Z|≥3的異常判定門檻，應標記為異常值。","B":"錯誤，計算結果Z應為3而非2.5，數值計算有誤。","C":"錯誤，Z分數計算結果為3並非2，且此推論與「標準差估計過高」無邏輯關聯，屬於錯誤解讀。","D":"錯誤，Z分數計算結果為3並非1.5，數值明顯算錯。"}},"origin":"past"},{"id":"middle_114-2_s2_q17","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":17,"context":null,"stem":"某電商公司欲利用顧客行為資料建立消費預測模型，其中「會員等級」欄位包含「一般、白金、黑卡」三種類別。若模型採用梯度提升樹（Gradient Boosting Tree）演算法，資料科學家在進行特徵編碼時應特別注意下列何種情況？","options":{"A":"應優先採用獨熱編碼（One-Hot Encoding），以減少類別之間的相依性與記憶體使用量","B":"直接使用標籤編碼（Label Encoding）可能使模型誤判類別間存在順序關係，導致特徵重要性偏誤","C":"使用目標編碼（Target Encoding）會自動消除過擬合（Overfitting）風險","D":"若類別數量較少，建議先使用主成分分析（Principal ComponentAnalysis, PCA）進行降維"},"answer":"B","figures":[],"explanation":{"approach":"「會員等級」若以標籤編碼（Label Encoding）轉為整數，梯度提升樹等模型可能依整數大小進行分割，若編碼順序未確實反映類別間真實的重要程度或間距關係，恐使模型誤判類別間存在等距的順序關係，進而影響特徵重要性判讀，此為使用標籤編碼時需特別留意之處。","options":{"A":"錯誤，樹模型（如GBT）本身可直接處理類別的分割，獨熱編碼未必能「減少類別相依性」，且題目類別數少，使用One-Hot並非必要優先考量重點。","B":"正確，直接使用Label Encoding可能讓模型誤判類別間存在數值大小或順序關係，導致特徵重要性出現偏誤，是本情境下最需留意的風險。","C":"錯誤，目標編碼（Target Encoding）本身容易因使用目標變數資訊而更容易造成過擬合，而非「自動消除」過擬合風險，敘述與事實相反。","D":"錯誤，PCA適用於數值型高維特徵降維，對「類別數量少」的類別變數而言並無降維必要，此建議不合理。"}},"origin":"past"},{"id":"middle_114-2_s2_q18","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":18,"context":null,"stem":"某人工智慧團隊使用分散式資料庫（Distributed Database）儲存模型訓練資料，並在更新訓練樣本時啟用多節點交易。若其中一個節點在交易過程中發生錯誤，但系統仍確保整體資料不會出現部分更新、最終狀態維持一致，下列何者最能說明此現象？","options":{"A":"系統透過原子性（Atomicity）確保交易必須全部成功或全部回復（Rollback）","B":"系統透過一致性（Consistency）確保交易完成後資料符合完整性規則","C":"系統透過隔離性（Isolation）避免多筆交易同時存取或修改相同資料","D":"系統透過持久性（Durability）確保交易一旦提交，其結果將永久保留於資料庫中"},"answer":"A","figures":[],"explanation":{"approach":"題目描述交易中某節點發生錯誤，但系統確保不會出現「部分更新」，最終狀態維持一致（要嘛全部成功要嘛整個回復），此正是ACID中原子性（Atomicity）「交易不可分割，全部成功或全部回復」的定義與作用。","options":{"A":"正確，題目所述「不會出現部分更新」正是原子性透過確保交易全部成功或全部回復（Rollback）所達成的效果。","B":"錯誤，一致性著重於交易完成後資料需符合完整性規則（如外鍵、約束），而非描述「部分失敗時整體回復」的機制。","C":"錯誤，隔離性談的是多筆交易同時執行時彼此互不干擾，與題目描述單一交易失敗後的回復機制無關。","D":"錯誤，持久性強調交易提交後結果永久保存，與題目描述交易失敗時如何避免部分更新的情境不符。"}},"origin":"past"},{"id":"middle_114-2_s2_q19","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":19,"context":null,"stem":"某製造企業導入上萬台物聯網（IoT）感測器以進行設備健康監測。系統需在毫秒級回應異常事件，並同時將完整資料保留於雲端供後續AI模型訓練與分析。若企業希望兼顧即時性、資料完整性與可擴展性，下列哪一種資料流程設計最符合此目標？","options":{"A":"感測器→雲端API Gateway →分散式資料庫→批次特徵工程（→模型推論","B":"感測器→ MQTT Broker →雲端資料倉儲→即時儀表板→模型再訓練","C":"感測器→邊緣運算節點→流式資料處理框架（Stream ProcessingFramework）→雲端資料湖→模型推論","D":"感測器→本地快取層→ RESTful API →雲端報表系統）→模型批次更新"},"answer":"C","figures":[],"explanation":{"approach":"為兼顧毫秒級即時反應、資料完整性與可擴展性，應在資料來源端以邊緣運算節點做即時初步處理，再透過流式資料處理框架進行即時分析與異常偵測，同時將完整資料保存至雲端資料湖供後續模型訓練，此架構同時滿足即時性（邊緣+流式處理）與完整性、可擴展性（資料湖）。","options":{"A":"錯誤，全部經由雲端API Gateway與批次特徵工程，經過網路傳輸與批次處理會有明顯延遲，無法達成毫秒級即時反應。","B":"錯誤，MQTT Broker適合傳輸，但直接進雲端資料倉儲並輔以即時儀表板，缺乏流式處理框架做即時運算，難以做到毫秒級異常偵測。","C":"正確，邊緣運算做即時初步處理、流式框架做即時分析、資料湖保留完整資料供訓練，同時兼顧即時性、完整性與可擴展性。","D":"錯誤，本地快取層搭配RESTful API與雲端報表系統、批次更新模型，屬於批次流程，無法滿足毫秒級即時性需求。"}},"origin":"past"},{"id":"middle_114-2_s2_q20","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":20,"context":null,"stem":"某銀行計畫將信用風險評估模型部署至雲端平台，以便即時分析客戶交易行為。由於涉及大量敏感金融資料，銀行要求雲端服務商在不解密原始資料的情況下仍能執行模型運算。為達成此目標，最適合採用下列哪一項技術？","options":{"A":"在上傳資料前進行匿名化（Anonymization），僅保留可識別代碼供比對使用","B":"利用雜湊（Hash）函數轉換資料，以確保模型可追蹤但無法還原個資","C":"採用資料本地化（Data Localization）策略，將所有模型訓練限制於內部伺服器中","D":"透過同態加密（Homomorphic Encryption），讓雲端系統能直接在加密資料上執行運算，解密後結果與原始資料一致"},"answer":"D","figures":[],"explanation":{"approach":"銀行要求雲端服務商「不解密原始資料」的情況下仍能執行模型運算，此正是同態加密（Homomorphic Encryption）技術的應用場景，可在加密狀態下直接進行運算，解密後結果與明文運算結果一致。","options":{"A":"錯誤，匿名化僅移除或替換可識別欄位，運算仍需在（去識別化後的）明文資料上進行，並非在加密狀態下運算。","B":"錯誤，雜湊函數為單向不可逆轉換，通常用於比對驗證，並不能對雜湊後資料進行有意義的模型運算。","C":"錯誤，資料本地化是將運算限制在內部伺服器，屬於治理策略，並非讓雲端服務商能在加密資料上運算的技術。","D":"正確，同態加密可讓雲端系統在不解密資料的情況下直接於加密狀態進行運算，結果解密後與原始資料運算結果一致，完全符合題目需求。"}},"origin":"past"},{"id":"middle_114-2_s2_q21","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":21,"context":null,"stem":"某資料分析師設計在業務績效報告時，希望單一頁面中同時呈現多區域、不同產品線的銷售趨勢變化，並確保主管能在短時間內掌握整體資料走向。若依據Edward Rolf Tufte的數據密度（Data Density）原則，下列哪一種設計方式最能符合該概念？","options":{"A":"將每個區域的銷售資料分成多張獨立折線圖，以避免資訊重疊","B":"使用顏色區分產品線，於同一圖表中整合多區域趨勢線，保持比例一致且標註清晰","C":"移除所有輔助線與標籤，僅保留主要折線以凸顯趨勢","D":"將資料轉換為表格形式，確保數值精確呈現並取代圖表視覺化"},"answer":"B","figures":[],"explanation":{"approach":"Tufte的資料密度（Data Density）概念強調在有限版面中，以精簡且一致的視覺元素呈現盡量多的資訊，同時避免混亂。用顏色區分產品線並將多區域趨勢整合於同一張圖表、保持比例一致與標註清晰，能在單一頁面呈現大量資訊且維持可讀性，符合資料密度原則。","options":{"A":"錯誤，將資料拆成多張獨立圖表雖避免重疊，但降低了單位版面的資訊密度，主管需切換多圖比對，不符合資料密度精神。","B":"正確，以顏色區分並整合於同一圖表、保持比例一致與標註清晰，能在單一版面承載更多資訊同時維持易讀性，符合Tufte資料密度原則。","C":"錯誤，移除輔助線與標籤雖然簡潔，但也犧牲了資訊量，不符合「同時呈現多區域、多產品線」的資料密度需求。","D":"錯誤，改用表格雖數值精確，但犧牲了視覺化帶來的趨勢辨識效率，不利於主管在短時間內快速掌握整體走向。"}},"origin":"past"},{"id":"middle_114-2_s2_q22","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":22,"context":null,"stem":"某投資研究員希望分析四檔科技類股（A、B、C、D）每日報酬率的變化趨勢，以判斷這些股票之間是否存在高度相關性與共變動性，並評估投資組合分散風險的程度。若研究員希望以單一圖表快速呈現各股票間的關聯強度與方向，下列哪一種視覺化呈現方式最適合？","options":{"A":"為每檔股票各自繪製直方圖（Histogram）以比較報酬率分佈","B":"針對任兩檔股票繪製散佈圖並加上趨勢線（Regression Line）","C":"使用雙軸折線圖（Dual-axis Line Chart）同時顯示四檔股價變化","D":"熱力圖（Heatmap）配合相關係數矩陣（Correlation Matrix）"},"answer":"D","figures":[],"explanation":{"approach":"若要在單一圖表中快速呈現多檔股票兩兩之間的關聯強度與方向，熱力圖搭配相關係數矩陣可用顏色深淺直觀呈現所有配對的相關係數，是最有效率的呈現方式。","options":{"A":"錯誤，各自繪製直方圖只能比較單一變數的分布形狀，無法呈現變數之間的相關性。","B":"錯誤，逐一針對兩檔股票繪製散佈圖雖可看出關聯，但四檔股票需繪製多張圖，無法「以單一圖表」呈現整體關聯。","C":"錯誤，雙軸折線圖只能呈現數值隨時間的變化趨勢，無法直接量化呈現股票間的相關程度。","D":"正確，熱力圖搭配相關係數矩陣可用單一圖表同時呈現所有股票兩兩之間的相關係數大小與方向，最符合題目需求。"}},"origin":"past"},{"id":"middle_114-2_s2_q23","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":23,"context":null,"stem":"某研究團隊以單樣本t檢定（one-sample t-test）檢驗「新行銷策略後的平均月銷售額是否與原本的100萬元不同」，顯著水準設定為α=0.05。檢定結果顯示：p值=0.08，且95%信賴區間為[95萬元, 108萬元]。根據上述結果，下列敘述何者正確？","options":{"A":"因p值< 0.05，可拒絕虛無假設","B":"若顯著水準改為0.10，仍不顯著","C":"因100萬元落在信賴區間內，無法拒絕虛無假設","D":"信賴區間寬度僅與顯著水準有關"},"answer":"C","figures":[],"explanation":{"approach":"由於95%信賴區間[95萬元,108萬元]涵蓋虛無假設的100萬元，且p值0.08大於顯著水準0.05，兩者結論一致，皆顯示沒有足夠證據拒絕虛無假設（平均銷售額與100萬元無顯著差異）。","options":{"A":"錯誤，p值0.08大於顯著水準0.05，應該「無法拒絕」虛無假設，而非拒絕。","B":"錯誤，若將顯著水準放寬至0.10，則p值0.08 < 0.10，此時會拒絕虛無假設，變為顯著，而非仍不顯著。","C":"正確，100萬元落在95%信賴區間[95萬元,108萬元]內，代表在此顯著水準下無法拒絕虛無假設，與p值0.08>0.05的結論一致。","D":"錯誤，信賴區間寬度除了受顯著水準影響外，也受樣本數與資料變異程度（標準誤）影響，並非僅與顯著水準有關。"}},"origin":"past"},{"id":"middle_114-2_s2_q24","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":24,"context":null,"stem":"某企業建置生成式AI系統，利用大量客服紀錄與產品評論資料訓練語言模型，以自動生成客服回覆與知識摘要。由於資料來源多樣，且包含非結構化文字、影像與表格資訊，團隊希望在不降低模型效能的前提下，提升資料處理效率與一致性，下列哪一種資料處理策略最適合？","options":{"A":"建立資料湖（Data Lake）結構，並以Apache Spark或Ray進行分散式資料預處理與特徵抽取，再串接至模型訓練管線（Pipeline）","B":"採用單節點高效能伺服器搭配批次處理模式，集中執行資料清理與格式轉換","C":"將所有文字資料轉換為向量，並以資料庫索引方式直接餵入語言模型訓練","D":"使用生成式模型先行自動清理資料內容，再將結果輸入至下游訓練流程"},"answer":"A","figures":[],"explanation":{"approach":"面對多樣化且大量的非結構化資料（文字、影像、表格），建立資料湖可彈性儲存各種格式資料，搭配Apache Spark或Ray等分散式運算框架進行平行化前處理與特徵抽取，再串接至模型訓練管線，才能兼顧處理效率與一致性，符合大規模、多模態資料處理的最佳實務。","options":{"A":"正確，資料湖可彈性儲存多樣化非結構化資料，搭配分散式框架平行處理並串接訓練管線，兼顧效率與一致性，最符合題目需求。","B":"錯誤，單節點伺服器搭配批次處理在面對大量多樣化資料時，運算能力與擴展性有限，效率明顯不如分散式架構。","C":"錯誤，僅將文字資料向量化無法涵蓋影像與表格等其他型態資料，忽略了資料多樣性的處理需求。","D":"錯誤，用生成式模型自動清理資料本身可能引入不穩定或錯誤的清理結果，且缺乏對影像、表格等多模態資料的系統化處理流程。"}},"origin":"past"},{"id":"middle_114-2_s2_q25","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":25,"context":null,"stem":"某電商資料團隊繪製顧客單筆消費金額的箱型圖後發現：四分位距（IQR）範圍極小，但上鬚線拉得很長，且在高金額區域有多筆離群值。若希望協助行銷部門依據消費層級設計分群策略，下列哪一種視覺化方式最有助於凸顯不同消費層級間的差異？","options":{"A":"以對數刻度繪製箱型圖或長條圖，放大高金額消費族群的變化差異","B":"移除所有離群值，確保資料呈現集中分布","C":"採用等距分箱（Equal-Width Binning）方式分群","D":"改以折線圖（Line Chart）觀察時間變化趨勢"},"answer":"A","figures":[],"explanation":{"approach":"資料在低金額區間高度集中（IQR小）但高金額區域存在長尾與離群值，若直接以線性刻度呈現，高金額族群間的差異會被壓縮而難以辨識；採用對數刻度繪製箱型圖或長條圖可放大高金額族群的變化差異，有助於凸顯不同消費層級間的區別。","options":{"A":"正確，對數刻度可壓縮低值密集區、放大高值差異，讓原本被長尾掩蓋的高消費族群差異清楚呈現，有助於分群策略設計。","B":"錯誤，直接移除離群值會喪失高消費族群的重要資訊，反而不利於凸顯消費層級差異。","C":"錯誤，等距分箱在資料高度偏態、離群值明顯的情況下，容易使多數資料集中在少數區間，無法有效區分高消費族群的差異。","D":"錯誤，題目探討的是消費金額的分布與分群，與時間變化趨勢無關，折線圖並不適用於此情境。"}},"origin":"past"},{"id":"middle_114-2_s2_q26","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":26,"context":null,"stem":"某串流影音平台運用關聯規則學習（Association Rule Learning）分析用戶的觀影行為，發現若使用者觀看了科幻影集，則有較高機率接著觀看超級英雄電影。分析顯示，同時觀看這兩種類型的使用者約佔全部觀影紀錄的12%，而觀看科幻影集的使用者中，有50%也觀看了超級英雄電影，該規則的提升度（Lift）為1.8。根據上述資訊，下列哪一項推論最為正確？","options":{"A":"支持度（Support）過低，代表此規則不具任何商業價值","B":"提升度（Lift）大於1表示兩種類型內容無關，僅屬於隨機重疊","C":"信賴度（Confidence）為50%，代表觀看科幻影集者有明顯傾向觀看超級英雄電影","D":"同時觀看比例僅12%，代表兩種類型互相排斥"},"answer":"C","figures":[],"explanation":{"approach":"信賴度（Confidence）定義為同時發生的比例除以前提事件發生的比例，題目中信賴度50%代表在觀看科幻影集的使用者中，有一半也觀看了超級英雄電影，顯示出科幻影集觀眾對超級英雄電影有明顯的觀看傾向。","options":{"A":"錯誤，支持度反映的是同時發生事件在全體中的普遍程度，支持度較低不代表規則「不具任何商業價值」，仍需搭配信賴度與提升度綜合判斷。","B":"錯誤，提升度（Lift）大於1代表兩事件的關聯性高於隨機獨立情況下的期望值，即兩者正相關，並非「無關、僅屬隨機重疊」，此敘述與Lift的定義相反。","C":"正確，信賴度50%表示觀看科幻影集的使用者中有一半也觀看超級英雄電影，顯示出明顯的觀看傾向關聯。","D":"錯誤，同時觀看比例（支持度）僅是全體中同時發生的比例，加上Lift=1.8（大於1）顯示兩者為正相關而非互斥，此敘述與資料矛盾。"}},"origin":"past"},{"id":"middle_114-2_s2_q27","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":27,"context":null,"stem":"某金融科技公司分析每日上億筆交易資料，以監控客戶轉帳金額分佈與異常波動。由於資料量極大，為兼顧效率與準確度，團隊決定採用「近似分位數（Approximate Quantile）」方法進行資料摘要統計。下列何者最能正確反映該技術的核心目的？","options":{"A":"確保每個分位值的結果完全精確，即使計算時間較長","B":"利用機器學習模型預測分位數位置，以減少統計計算量","C":"僅能對結構化資料進行批次處理，無法應用於即時資料流","D":"在可容忍誤差範圍內，快速估算分位值以支援即時分析"},"answer":"D","figures":[],"explanation":{"approach":"近似分位數方法的核心目的，是在可容忍的誤差範圍內，以較低的運算成本快速估算分位值，藉此支援大規模資料或即時資料流下的統計摘要分析，兼顧效率與可用的準確度。","options":{"A":"錯誤，近似分位數方法本質上是犧牲部分精確度以換取運算效率，並非追求「完全精確」。","B":"錯誤，近似分位數通常採用如t-digest、GK演算法等統計/機率演算法進行估算，並非利用機器學習模型預測分位數位置。","C":"錯誤，近似分位數方法常被設計用於串流（即時）資料場景，能對即時資料流進行增量估算，並非僅能批次處理結構化資料。","D":"正確，近似分位數方法在可容忍的誤差範圍內快速估算分位值，以支援大規模或即時分析，兼顧效率與可用準確度，正確反映其核心目的。"}},"origin":"past"},{"id":"middle_114-2_s2_q28","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":28,"context":null,"stem":"若在高維度（>500維）的資料上應用DBSCAN（Density-Based SpatialClustering of Applications with Noise）演算法，卻發現所有資料點皆被判定為雜訊（Noise），下列何者為最有可能的原因？","options":{"A":"高維下距離變化趨同，導致ε（Epsilon）閾值選擇失效","B":"使用錯誤的距離函數（Distance Function）","C":"MinPts參數設得太小","D":"資料過度標準化導致特徵消失"},"answer":"A","figures":[],"explanation":{"approach":"在高維空間中，「距離集中現象」（distance concentration）會使得所有資料點兩兩之間的距離趨於相近，導致原本用來界定鄰域範圍的ε閾值難以有效區分密集區域與稀疏區域，使DBSCAN幾乎將所有點判定為雜訊，這是高維度應用密度型分群方法常見的問題。","options":{"A":"正確，高維度下距離度量趨同（集中現象），使ε閾值無法有效區分密度差異，是DBSCAN在高維資料下全部判為雜訊最可能的原因。","B":"錯誤，距離函數選擇錯誤雖可能造成分群不佳，但並非高維度下「所有點皆為雜訊」此一特定現象的最主要原因。","C":"錯誤，若MinPts設得太小應該更容易形成群集（判定為雜訊的門檻降低），與題目「全部被判為雜訊」的結果方向相反。","D":"錯誤，標準化通常是為了消除量綱差異、改善分群效果，並不會導致特徵消失，且非本題「全為雜訊」現象的主因。"}},"origin":"past"},{"id":"middle_114-2_s2_q29","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":29,"context":null,"stem":"某團隊在開發風險評估模型時，使用主成分分析（Principal ComponentAnalysis, PCA）進行降維。輸入資料包含三個數值欄位：「交易金額（單位：新台幣）」、「交易次數（次／月）」與「年齡（歲）」，其數值量級分別約為10⁵、10¹與10²。分析人員直接將原始數據帶入PCA，結果第一主成分（PC1）幾乎完全由「交易金額」主導。下列哪一項作法或判斷最合理？","options":{"A":"這是正常現象，金額本身變異較大，應主導主要成分","B":"若改用特徵選擇法，可自動解決變數量級問題","C":"可刪除「交易金額」欄位以平衡各主成分的影響","D":"在進行PCA前應先進行標準化（Standardization），以避免因數值尺度差異造成特徵偏誤"},"answer":"D","figures":[],"explanation":{"approach":"三個變數的數值量級差異懸殊（10⁵、10¹、10²），PCA是以變異數為基礎尋找主成分方向，若未先標準化，量級最大的「交易金額」會因變異數遠大於其他變數而主導第一主成分，無法反映各變數對整體結構的真實貢獻，因此應在PCA前先進行標準化以消除量級差異造成的偏誤。","options":{"A":"錯誤，PC1被單一變數主導是量級差異造成的偏誤現象，並非正常且合理的結果，應予以修正而非視為理所當然。","B":"錯誤，特徵選擇（挑選變數子集）無法解決變數之間量級不一致的問題，兩者是不同層次的議題。","C":"錯誤，直接刪除交易金額欄位會喪失重要資訊，並非解決量級差異問題的合理作法。","D":"正確，PCA對變數尺度敏感，應先進行標準化使各變數具有可比較的變異數尺度，避免因量級差異造成PC1被單一變數主導。"}},"origin":"past"},{"id":"middle_114-2_s2_q30","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":30,"context":null,"stem":"某行銷團隊想了解「廣告預算」與「銷售金額」之間的關聯程度。經繪製散佈圖後發現兩者呈現明顯線性趨勢，且資料中無明顯離群值（Outliers）。若希望衡量兩者之間線性關係的強度與方向，下列哪一種方法最適合？","options":{"A":"均方根誤差（Root Mean Squared Error, RMSE）","B":"共變異數（Covariance）","C":"皮爾森相關係數（Pearson Correlation Coefficient）","D":"平均絕對誤差（Mean Absolute Error, MAE）"},"answer":"C","figures":[],"explanation":{"approach":"皮爾森相關係數（Pearson Correlation Coefficient）專門用於衡量兩連續變數之間線性關係的強度（絕對值大小）與方向（正負號），且其數值已標準化至-1到1之間，便於比較解讀，是衡量「廣告預算」與「銷售金額」線性關聯程度最適合的指標。","options":{"A":"錯誤，RMSE是用於評估預測模型誤差大小的指標，並非用於衡量兩變數間線性關係的強度與方向。","B":"錯誤，共變異數雖可反映關係方向，但其數值大小受變數單位與尺度影響，無法標準化比較關係強度。","C":"正確，皮爾森相關係數同時反映線性關係的方向（正負）與強度（數值大小，範圍-1至1），最適合衡量兩連續變數間的線性關聯程度。","D":"錯誤，MAE同樣是模型預測誤差的評估指標，並非用於衡量兩變數之間的相關程度。"}},"origin":"past"},{"id":"middle_114-2_s2_q31","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":31,"context":null,"stem":"某電商團隊觀察到，每位顧客對廣告推播的點擊行為可視為一次伯努利試驗（Bernoulli Trial），單次點擊成功機率為p=0.4。當推播對象擴增至5,000位顧客時，團隊想快速預估「成功點擊總數」的分佈情形，以進行模型效能模擬與預測。若希望以常態分佈（Normal Distribution）近似原始分佈，下列哪一項判斷最為合理？","options":{"A":"因樣本數極大，可直接以常態分佈近似二項分佈（BinomialDistribution）","B":"只有當np與n(1-p)皆大於5時，才能以常態分佈作近似","C":"常態近似只適用於p=0.5的情況","D":"無論樣本數多大，二項分佈都不能以常態分佈近似"},"answer":"B","figures":[],"explanation":{"approach":"常態近似二項分佈的標準判準是 np 與 n(1-p) 皆需大於門檻(常見取 5),用以確保分佈形狀夠對稱、近似誤差夠小,而不是只看樣本數大不大。本題 n=5000、p=0.4,np=2000、n(1-p)=3000,兩者都遠超過門檻,因此「可以用常態近似」這個結論本身是成立的——選項A與B的差別不在結論對錯,而在判準是否完整(見選項A說明)。官方答案取B,因為只有B寫出了正確且可一般化的判準。","options":{"A":"官方未採此選項。在本題的數值下(np=2000、n(1-p)=3000)A的結論其實成立,但它的理由不完整:只憑「樣本數極大」不足以保證可近似——若 n 很大而 p 極小(例如 n=5000、p=0.0005,np=2.5),二項分佈會嚴重右偏,此時應改用卜瓦松近似而非常態近似。B 給出的才是可一般化的正確判準。","B":"正確，常態近似二項分佈的常見準則即為np與n(1-p)皆需大於5，此為判斷是否可用常態分佈近似的標準條件。","C":"錯誤，常態近似並非只適用於p=0.5，只要np與n(1-p)皆滿足門檻條件，即使p不等於0.5仍可近似，只是p越接近0.5近似效果越佳。","D":"錯誤，當樣本數夠大且np、n(1-p)皆滿足門檻時，二項分佈仍可用常態分佈有效近似，並非「無論樣本數多大都不能近似」。"},"note":"選項A的「結論」在本題條件下其實沒錯——n=5000、p=0.4 時 np=2000、n(1-p)=3000,都遠大於 5,確實可以用常態近似。A 的問題在「理由不完整」:它只憑「樣本數極大」就下結論,但樣本數大不足以保證可近似(例如 n 很大而 p 極小時,np 仍可能小於 5,此時應改用卜瓦松近似)。官方答案取B,是因為B講出了完整且正確的判準(np 與 n(1-p) 皆大於 5)。應試選B。"},"origin":"past"},{"id":"middle_114-2_s2_q32","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":32,"context":null,"stem":"某電信公司導入生成式AI客服系統，利用過去對話紀錄與用戶行為資料訓練語言模型，在資料治理與合規審查過程中，團隊發現模型可能會在回答中生成包含真實姓名、電話或交易資訊的內容。為確保系統符合個資法及生成式AI的安全與隱私要求，下列哪一項作法最符合實務可行及法規原則？","options":{"A":"在訓練資料前進行資料匿名化（Anonymization）或偽匿名化（Pseudonymization）處理，並建立輸出內容稽核機制","B":"改以強化學習（Reinforcement Learning）微調模型，使模型學習避免產出真實資訊","C":"採用同態加密（Homomorphic Encryption）以加密所有文字輸入，確保模型無法辨識任何個資","D":"僅設定模型回覆時不顯示用戶姓名，即可視為隱私防護完成"},"answer":"A","figures":[],"explanation":{"approach":"為避免生成式AI在輸出中洩漏真實姓名、電話等個資，實務上應從資料源頭進行匿名化或偽匿名化處理，降低訓練資料中個資外洩風險，並搭配輸出內容稽核機制，在模型產出階段進行把關，雙重防護才能兼顧法規遵循與實務可行性。","options":{"A":"正確，訓練資料先做匿名化/偽匿名化並建立輸出稽核機制，同時從資料源頭與輸出端把關，是兼顧實務可行性與個資法規要求的合理作法。","B":"錯誤，強化學習微調雖可能降低模型產出個資的機率，但無法保證完全避免，且缺乏資料端與輸出端的系統性防護機制，並非最完整合適的作法。","C":"錯誤，同態加密適用於「在加密狀態下進行運算」的情境，並非用於防止語言模型生成文字中包含個資，且加密輸入會使模型難以理解文字語意，不具實務可行性。","D":"錯誤，僅設定不顯示用戶姓名過於片面，電話、交易資訊等其他個資仍可能外洩，不能視為隱私防護已完成。"}},"origin":"past"},{"id":"middle_114-2_s2_q33","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":33,"context":null,"stem":"某金融機構的量化分析師在建立資產風險評估模型時，發現報酬率資料分佈明顯非對稱，且出現多次極端損失事件，使得傳統假設常態分佈的模型無法準確反映真實風險。若希望在不依賴常態分佈假設的前提下，採取更能捕捉資料極端情況的建模策略，下列哪一種方法最為合適？","options":{"A":"採用線性迴歸模型（Linear Regression Model），以常態分佈殘差（Residuals）為基礎進行推估","B":"使用平均數（Mean）與標準差（Standard Deviation）估計波動範圍","C":"將資料裁剪至±3σ範圍內以排除異常值影響","D":"採用分位數回歸模型（Quantile Regression Model），聚焦於尾部分位（Tail Quantiles）以評估極端風險"},"answer":"D","figures":[],"explanation":{"approach":"報酬率分布明顯非對稱且有極端損失事件，傳統常態分佈假設的模型無法準確捕捉尾部風險。分位數回歸模型可針對不同分位數（尤其是尾部分位）直接建模，不依賴常態分佈假設，能更準確評估極端風險，最符合題目需求。","options":{"A":"錯誤，線性迴歸並以常態分佈殘差為基礎進行推估，正是題目所要避免的常態分佈假設，不符合需求。","B":"錯誤，平均數與標準差是基於對稱、常態假設下的統計量，無法適當描述非對稱且具極端事件的資料波動特性。","C":"錯誤，將資料裁剪至±3σ範圍會直接排除掉正是分析人員最關心的極端損失事件，反而喪失尾部風險資訊。","D":"正確，分位數回歸可針對尾部分位（如極端分位數）直接建模，不依賴常態分佈假設，能有效捕捉極端風險情況，符合題目需求。"}},"origin":"past"},{"id":"middle_114-2_s2_q34","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":34,"context":null,"stem":"在圖形資料庫（Graph Database）中建模社群平台資料時，若每筆「按讚」行為都包含時間戳記（Timestamp）與裝置類型（Device Type）等資訊。若希望同時保留使用者與貼文之間的互動關係，並能有效查詢「按讚」的行為屬性，下列哪一種設計方式最為合適？","options":{"A":"將「按讚」視為節點（Node），與使用者建立邊（Edge）","B":"將「按讚」資訊作為邊的屬性（Property）儲存，連結使用者與被按讚的貼文節點","C":"把「按讚」資訊直接寫入使用者節點中作為屬性","D":"建立「按讚紀錄表」並將資料存入關聯式資料庫"},"answer":"B","figures":[],"explanation":{"approach":"「按讚」本質是使用者與貼文之間的一種互動關係，若將其屬性（時間戳記、裝置類型）儲存為連接使用者節點與貼文節點的邊（Edge）屬性，既能保留兩者的互動關係，又能有效查詢按讚行為的相關屬性，是圖形資料庫中最自然且有效率的建模方式。","options":{"A":"錯誤，將「按讚」視為獨立節點會使圖結構過於複雜，且不必要地增加節點數量，不是最有效率的設計方式。","B":"正確，將按讚資訊作為連結使用者與貼文節點的邊屬性，可同時保留互動關係與行為屬性，便於後續查詢，是最合適的設計。","C":"錯誤，把按讚資訊寫入使用者節點屬性，會混淆使用者本身的屬性與其對外的互動行為，且無法對應到特定貼文，不利於查詢按讚與貼文的關係。","D":"錯誤，改用關聯式資料庫的按讚紀錄表，會喪失圖形資料庫在查詢多層次關聯（如使用者-按讚-貼文-其他使用者）上的效率優勢，不符合題目情境。"}},"origin":"past"},{"id":"middle_114-2_s2_q35","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":35,"context":null,"stem":"某企業欲建構知識圖譜（Knowledge Graph），以整合內部的研究報告、專利資料與專家知識，並支援語意查詢與關聯推理。若希望模型能具備良好的語意擴展性與高效推理能力，下列哪一種圖模型設計最為合適？","options":{"A":"僅以節點（Node）與邊（Edge）表示，所有資訊存放於節點屬性中","B":"將資料結構建為RDF（Resource Description Framework）三元組（Subject–Predicate–Object）","C":"使用文件型資料庫儲存內容，並以標籤（Tag）連接節點","D":"採用關聯式資料庫儲存對應關係，並搭配預建索引加速查詢"},"answer":"B","figures":[],"explanation":{"approach":"RDF（Resource Description Framework）以主詞-述詞-受詞（Subject-Predicate-Object）三元組表示知識，具備標準化的語意表示能力，搭配本體與推理引擎可支援語意查詢與關聯推理，並具良好的擴展性，最適合用於建構支援語意推理的知識圖譜。","options":{"A":"錯誤，僅以節點與邊表示、所有資訊放於節點屬性中，缺乏標準化的語意描述格式，不利於跨系統的語意擴展與推理。","B":"正確，RDF三元組是知識圖譜的標準表示方式，具有良好的語意表達能力與擴展性，並可搭配推理引擎進行高效的語意推理。","C":"錯誤，文件型資料庫搭配標籤連接節點缺乏標準化的語意關係定義，難以支援複雜的語意推理需求。","D":"錯誤，關聯式資料庫搭配預建索引雖然查詢效能佳，但表格結構在表達複雜、多變的語意關聯與推理上彈性不足。"}},"origin":"past"},{"id":"middle_114-2_s2_q36","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":36,"context":null,"stem":"某研究人員欲使用線性迴歸模型（Linear Regression Model）分析變數Y與X之間的關係，但發現Y的分佈明顯右偏，且其變異數隨X的增大而增加。為滿足模型假設並提升配適效果，下列哪一種前處理方法最為合適？","options":{"A":"對X進行標準化（Standardization）","B":"對Y進行Box–Cox轉換（Box–Cox Transformation）","C":"對資料進行一次差分（First Differencing）","D":"將Y中變異較大的樣本移除"},"answer":"B","figures":[],"explanation":{"approach":"Y呈右偏且變異數隨X增大而增加（異質變異，Heteroscedasticity），違反線性迴歸對常態性與同質變異的假設。Box-Cox轉換可透過冪次轉換降低偏態並穩定變異數，是改善此類問題最常見且合適的前處理方法。","options":{"A":"錯誤，標準化X僅改變X的尺度（平移縮放），不會改變Y分布的偏態或變異數隨X增加的異質變異問題。","B":"正確，Box-Cox轉換能有效降低Y的右偏程度並穩定變異數，同時改善模型的常態性與同質變異假設，最適合此情境。","C":"錯誤，一次差分主要用於處理時間序列資料的非定態（trend）問題，並非用於處理橫斷面資料的偏態與異質變異問題。","D":"錯誤，直接移除變異較大的樣本會損失資訊且可能引入選擇偏誤，並非解決偏態與異質變異的合理作法。"}},"origin":"past"},{"id":"middle_114-2_s2_q37","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":37,"context":null,"stem":"若開發一個用於罕見疾病自動診斷的分類模型，目前資料集中確診樣本僅佔不到1%，且因為標註成本高，短期內無法取得更多資料。在此情況下，若希望提升模型對少數類的偵測能力，同時避免過擬合，下列哪一種策略最為合理？","options":{"A":"對少數類進行隨機過採樣（Random Oversampling）","B":"對多數類進行欠採樣（Random Undersampling）","C":"使用SMOTE（Synthetic Minority Over-sampling Technique）生成合成少數類樣本後再訓練分類模型","D":"僅使用現有資料調整模型決策閾值（Decision Threshold）以提升召回率"},"answer":"C","figures":[],"explanation":{"approach":"面對極度不平衡且無法輕易取得更多真實資料的情境，SMOTE透過在少數類樣本間進行內插產生「合成」的新樣本，相較單純複製樣本的隨機過採樣更能增加樣本多樣性，有助於提升模型對少數類的偵測能力，同時降低過擬合風險。","options":{"A":"錯誤，隨機過採樣是直接複製既有少數類樣本，容易讓模型記住重複樣本，提高過擬合風險，不符合題目「避免過擬合」的要求。","B":"錯誤，對多數類欠採樣會捨棄大量正常樣本資訊，在資料本身已經稀少（標註成本高）的情況下，進一步損失資料並不理想。","C":"正確，SMOTE透過生成合成樣本增加少數類多樣性，相較單純複製更能提升少數類偵測能力，同時降低過擬合風險，最符合題目需求。","D":"錯誤，僅調整決策閾值雖可提升召回率，但並未增加模型對少數類特徵的學習能力，對「提升偵測能力」的效果有限，且未處理資料不平衡本身的問題。"}},"origin":"past"},{"id":"middle_114-2_s2_q38","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":38,"context":null,"stem":"一家製造廠評估新生產線推出後，產品良率是否較原生產線提升。工程師分別從兩條生產線各抽樣100件產品，原生產線良率為95%，新生產線為97%。若欲檢定兩條生產線良率的差異是否具有統計意義，下列哪一種方法最為合適？","options":{"A":"雙樣本平均數t檢定（Two-sample t-test）","B":"雙比例Z檢定（Two-proportion Z-test）","C":"卡方檢定（Chi-square test）","D":"變異數分析（ANOVA）"},"answer":"B","figures":[],"explanation":{"approach":"良率屬於二元（合格/不合格）比例資料，比較兩條生產線的良率（比例）差異是否具統計意義，應使用雙比例Z檢定（Two-proportion Z-test），此檢定專門用於檢定兩獨立樣本比例之間的差異。","options":{"A":"錯誤，t檢定適用於比較兩組「平均數」（連續型資料），而良率屬於比例（類別型二元結果），並非平均數比較。","B":"正確，良率是比例型資料，比較兩組獨立樣本比例的差異，應使用雙比例Z檢定，為此情境最適合的方法。","C":"錯誤，卡方檢定通常用於檢定類別變數之間的獨立性或適合度，雖也可用於2x2列聯表，但對於「兩比例差異」的直接檢定，雙比例Z檢定更為對應且直接。","D":"錯誤，ANOVA用於比較三組以上平均數的差異，本題僅比較兩組比例，並不適用ANOVA。"},"note":"選項C(卡方檢定)在此情境也成立——2×2 列聯表的卡方檢定與雙比例 Z 檢定在數學上等價(χ² = z²),兩者結論完全相同。官方答案取B,是因為題目問的是「兩個比例的差異」,雙比例 Z 檢定是最直接對應的工具,而且可做單尾檢定並給出差異的信賴區間。應試選B,但要知道兩者等價。"},"origin":"past"},{"id":"middle_114-2_s2_q39","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":39,"context":null,"stem":"若評估一個新開發的腫瘤分類模型，其資料集中有80%的樣本來自良性病例。若直接使用5-fold交叉驗證（Cross-Validation）進行模型評估，可能導致模型效能評估出現偏差，為避免此問題，下列哪一種作法最合適？","options":{"A":"降低K值以減少交叉驗證次數","B":"改為使用拔靴法（Bootstrap）","C":"調整測試集使良性樣本比例更高，以模擬真實分佈","D":"使用分層交叉驗證（Stratified K-Fold Cross-Validation），以確保每折類別比例一致"},"answer":"D","figures":[],"explanation":{"approach":"資料類別比例不平衡（80%良性）時，若直接進行一般k-fold交叉驗證，可能因隨機切分導致某些折（fold）中類別比例與整體差異過大，造成評估結果偏差。分層交叉驗證（Stratified K-Fold）會確保每一折中的類別比例與原始資料一致，可有效避免此問題。","options":{"A":"錯誤，降低K值只是減少切分次數，並未解決各折類別比例不一致的根本問題。","B":"錯誤，改用拔靴法（Bootstrap）雖是另一種重抽樣方法，但同樣未保證抽樣結果的類別比例與原資料一致，無法直接解決類別不平衡造成的評估偏差。","C":"錯誤，刻意調整測試集比例使其偏離真實資料分布，反而會使評估結果無法反映模型在真實情境下的表現，並非正確作法。","D":"正確，分層交叉驗證可確保每一折的類別比例與原始資料一致，避免因隨機切分導致類別比例失衡而造成的評估偏差，是最合適的作法。"}},"origin":"past"},{"id":"middle_114-2_s2_q40","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":40,"context":null,"stem":"請參考附圖，下列虛擬程式碼（pseudocode）最可能是在描述何種驗證法？","options":{"A":"Hold-out驗證（Hold-out Validation）","B":"留一交叉驗證LOOCV（Leave-One-Out Cross Validation）","C":"K-fold交叉驗證（K-fold Cross Validation）","D":"拔靴法（Bootstrap）驗證"},"answer":"B","figures":[{"src":"images/middle_114-2_s2_q40_fig1.png","position":"stem"}],"explanation":{"approach":"由附圖虛擬程式碼可見，演算法對N筆資料進行迴圈，每次僅取「第i筆」資料作為測試集，其餘N-1筆作為訓練集，重複N次後計算平均評估指標，此作法正是留一交叉驗證（LOOCV）的定義，即每次僅留下一筆資料做測試。","options":{"A":"錯誤，Hold-out驗證僅將資料切分為一組訓練集與一組測試集，執行一次即可，並不會像圖中迴圈執行N次、每次僅留一筆資料。","B":"正確，圖中演算法對N筆資料進行迴圈，每次以單一筆資料作為測試集、其餘N-1筆作為訓練集，正是LOOCV的標準流程。","C":"錯誤，K-fold交叉驗證是將資料切成K份（K通常遠小於N）進行K次驗證，每次以其中一份（非單一筆資料）作為測試集，與圖中「每次僅留一筆」不同。","D":"錯誤，拔靴法是以取後放回的方式重複抽樣產生訓練樣本，與圖中「依序將每一筆資料輪流作為測試集」的作法不同。"}},"origin":"past"},{"id":"middle_114-2_s2_q41","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":41,"context":null,"stem":"請參考附圖，下列虛擬程式碼（pseudocode）最可能是在描述何種演算法？","options":{"A":"K-means分群（K-means Clustering）","B":"高斯混合模型分群（Gaussian Mixture Model Clustering）","C":"階層式分群（Hierarchical Clustering）","D":"DBSCAN分群（Density-based Spatial Clustering of Applicationswith Noise Clustering）"},"answer":"A","figures":[{"src":"images/middle_114-2_s2_q41_fig1.png","position":"stem"}],"explanation":{"approach":"附圖演算法先隨機選擇X個資料點作為初始中心，接著重複「將每個資料點指派給距離最近的中心」與「將各群中心更新為群內資料點的平均值」，直到中心不再變動為止，此流程正是K-means分群演算法的標準步驟。","options":{"A":"正確，隨機選初始中心、依最近距離分群、以群內平均值更新中心並重複至收斂，完全符合K-means演算法的定義流程。","B":"錯誤，高斯混合模型分群是基於機率模型（以EM演算法估計各群的高斯分布參數），並非以「距離最近中心」硬性分派資料點，與圖中流程不同。","C":"錯誤，階層式分群是透過逐步合併（凝聚式）或分裂群集建立樹狀結構，並不需要事先指定X個初始中心點，與圖中流程不符。","D":"錯誤，DBSCAN是以密度（鄰域半徑與最少點數）定義群集與雜訊，不需指定群數X，也不是以「更新中心點」的方式迭代，與圖中演算法不同。"}},"origin":"past"},{"id":"middle_114-2_s2_q42","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":42,"context":null,"stem":"考慮某生產線每小時出現瑕疵品的個數符合卜瓦松分佈（PoissonDistribution），已知平均每小時產生5個瑕疵品，附圖程式碼展示資料處理，請問下列敘述何者正確？","options":{"A":"lambda_poisson = 5表示每小時最多5個瑕疵品","B":"poisson.pmf(5, lambda_poisson)表示小於5個瑕疵品的機率","C":"卜瓦松分佈的適用條件為事件彼此獨立，且平均發生率固定","D":"poisson.cdf(10, 5)表示大於或等於10個瑕疵品的機率"},"answer":"C","figures":[{"src":"images/middle_114-2_s2_q42_fig1.png","position":"stem"}],"explanation":{"approach":"卜瓦松分佈的基本假設為：事件的發生彼此獨立，且在單位時間內事件平均發生率（λ）保持固定，此為使用卜瓦松分佈建模瑕疵品個數的前提條件，故選項C為正確敘述。","options":{"A":"錯誤，lambda_poisson=5是卜瓦松分佈的平均發生率（期望值），並非「最多」發生5個，實際發生數仍可能大於5（只是機率較低）。","B":"錯誤，poisson.pmf(k, λ)計算的是「恰好發生k個事件」的機率（機率質量函數），並非「小於k個」的累積機率，後者應使用poisson.cdf。","C":"正確，卜瓦松分佈適用的前提條件即為事件彼此獨立發生，且在固定時間區間內平均發生率（λ）保持不變，此為其核心假設。","D":"錯誤，poisson.cdf(k, λ)計算的是「小於或等於k個事件」的累積機率（即P(X≤k)），而非「大於或等於k個」的機率，敘述方向相反。"}},"origin":"past"},{"id":"middle_114-2_s2_q43","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":43,"context":{"text":"一間遊戲市場研究公司正在分析全球電子遊戲銷售情況，並準備建立一份「熱銷遊戲銷售報告」。分析師取得了一份名為vgsales.csv的資料集，內容包含了全球銷量超過10萬份的電子遊戲清單。研究團隊希望透過這份資料，了解不同年份、平台與地區的銷售趨勢。資料集的欄位說明如下，請根據下述資料情境回答以43~47題。\nName：遊戲名稱\nPlatform：遊戲平台（如PS4、X360、Wii等）\nYear：發售年份\nGenre：遊戲類型（如Action、Sports、Role-Playing等）\nPublisher：發行商名稱\nNA_Sales / EU_Sales / JP_Sales / Other_Sales：各地區銷售量（單\n位：百萬份）\nGlobal_Sales：全球總銷售量（單位：百萬份）\n資料的欄位概觀如下：","figures":["images/middle_114-2_s2_ctx2_fig1.png","images/middle_114-2_s2_ctx2_fig2.png"]},"stem":"分析師在載入資料後，檢視Year欄位的資料型態，發現它是float64，而非一般年份常用的整數。他想了解這樣的情形為什麼會發生。請問下列哪些原因可能導致這種狀況？原因A：CSV檔中Year欄位有缺失值(NaN)，導致Pandas自動將整欄轉為浮點數。原因B：CSV檔中的年份資料原本是字串(如\"2006\")，Pandas轉換時出錯而變成浮點數。原因C：Pandas預設會將所有數值型態讀取為float64，不論資料是否為整數。原因D：CSV檔中的年份資料可能包含小數點(例如2006.0)，因此被視為浮點數。","options":{"A":"原因B、原因C","B":"原因A、原因D","C":"原因A、原因B、原因D","D":"原因C、原因D"},"answer":"B","figures":[],"explanation":{"approach":"Pandas在讀取CSV時，若某數值欄位存在缺失值（NaN），由於int64型態無法表示NaN，Pandas會自動將整欄向上轉型為float64以容納缺失值（原因A）；另外，若CSV原始資料中年份本身即以帶小數點的形式呈現（如2006.0），Pandas讀取時也會直接判斷為float64（原因D）。兩者皆是實務上常見造成Year欄位變為float64的原因。","options":{"A":"錯誤，此選項僅包含原因B與C，而原因B（字串轉換出錯）並非事實，pandas讀取字串型年份時通常會保持為object而非自動轉為浮點數；原因C（pandas預設所有數值皆讀為float64）也不正確，pandas會依資料實際內容判斷為int64或float64，並非一律強制轉為float64。","B":"正確，欄位存在缺失值（原因A）會使pandas將整欄轉為float64以容納NaN；而CSV中年份原始資料若本身帶有小數點（原因D）也會直接被讀為float64，兩者皆為合理且常見的原因。","C":"錯誤，此選項多納入了原因B，而原因B（字串轉換出錯導致變浮點數）並不成立，字串轉換失敗通常會保留為object型態或拋出錯誤，而非靜默轉為float64。","D":"錯誤，此選項包含原因C，但pandas並不會將所有數值欄位「不論是否為整數」一律預設讀取為float64，若欄位無缺失值且皆為整數，預設會讀取為int64，原因C的敘述不正確。"}},"origin":"past"},{"id":"middle_114-2_s2_q44","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":44,"context":{"text":"一間遊戲市場研究公司正在分析全球電子遊戲銷售情況，並準備建立一份「熱銷遊戲銷售報告」。分析師取得了一份名為vgsales.csv的資料集，內容包含了全球銷量超過10萬份的電子遊戲清單。研究團隊希望透過這份資料，了解不同年份、平台與地區的銷售趨勢。資料集的欄位說明如下，請根據下述資料情境回答以43~47題。\nName：遊戲名稱\nPlatform：遊戲平台（如PS4、X360、Wii等）\nYear：發售年份\nGenre：遊戲類型（如Action、Sports、Role-Playing等）\nPublisher：發行商名稱\nNA_Sales / EU_Sales / JP_Sales / Other_Sales：各地區銷售量（單\n位：百萬份）\nGlobal_Sales：全球總銷售量（單位：百萬份）\n資料的欄位概觀如下：","figures":["images/middle_114-2_s2_ctx2_fig1.png","images/middle_114-2_s2_ctx2_fig2.png"]},"stem":"研究團隊接下來想要將Year欄位轉換為整數型態，以便後續進行年份趨勢分析。考慮到資料中可能包含缺失值（NaN），請選出最合適的轉換方式。","options":{"A":"data['Year'] = data['Year'].astype(int)","B":"data['Year'] = data['Year'].fillna(0).astype(int)","C":"data['Year'] = data['Year'].fillna(1).astype(int)","D":"data['Year'] = data['Year'].astype('Int64')"},"answer":"D","figures":[],"explanation":{"approach":"由於Year欄位可能包含缺失值（NaN），傳統的int64型態無法容納NaN，若直接呼叫astype(int)會因欄位存在NaN而報錯；而任意以0或1填補NaN會扭曲原始年份資料的意義。Pandas提供的可為空整數型態Int64（注意大寫I）可在保留NaN的同時將其餘數值以整數方式儲存，是兼顧資料完整性與型態需求的最合適作法。","options":{"A":"錯誤，若Year欄位存在NaN，直接astype(int)轉換為傳統int64會因無法表示NaN而拋出錯誤，無法成功執行。","B":"錯誤，以0填補缺失的年份會產生不具意義甚至嚴重錯誤的年份資料（西元0年），扭曲後續年份趨勢分析的正確性。","C":"錯誤，以1填補缺失的年份同樣是人為捏造不具意義的年份數值（西元1年），同樣會扭曲分析結果，並非合適作法。","D":"正確，astype('Int64')轉換為pandas可為空的整數型態，能在保留缺失值（呈現為<NA>）的同時，將有值的資料以整數形式儲存，是兼顧資料完整性與型態需求最合適的方式。"}},"origin":"past"},{"id":"middle_114-2_s2_q45","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":45,"context":{"text":"一間遊戲市場研究公司正在分析全球電子遊戲銷售情況，並準備建立一份「熱銷遊戲銷售報告」。分析師取得了一份名為vgsales.csv的資料集，內容包含了全球銷量超過10萬份的電子遊戲清單。研究團隊希望透過這份資料，了解不同年份、平台與地區的銷售趨勢。資料集的欄位說明如下，請根據下述資料情境回答以43~47題。\nName：遊戲名稱\nPlatform：遊戲平台（如PS4、X360、Wii等）\nYear：發售年份\nGenre：遊戲類型（如Action、Sports、Role-Playing等）\nPublisher：發行商名稱\nNA_Sales / EU_Sales / JP_Sales / Other_Sales：各地區銷售量（單\n位：百萬份）\nGlobal_Sales：全球總銷售量（單位：百萬份）\n資料的欄位概觀如下：","figures":["images/middle_114-2_s2_ctx2_fig1.png","images/middle_114-2_s2_ctx2_fig2.png"]},"stem":"為了觀察各遊戲平台的市場表現，分析師想要統計每個平台的全球銷售總額，並以長條圖呈現。請選出最能正確實現此分析的程式碼。","options":{"A":"data.groupby(\"Platform\")[\"Global_Sales\"].sum().plot(kind=\"bar\")","B":"data.groupby(\"Platform\")[\"Global_Sales\"].count().plot(kind=\"bar\")","C":"data[\"Platform\"].value_counts().plot(kind=\"bar\")","D":"data.groupby(\"Platform\")[\"Global_Sales\"].mean().plot(kind=\"bar\")"},"answer":"A","figures":[],"explanation":{"approach":"「統計每個平台的全球銷售『總額』」代表需要先依Platform分組，再對Global_Sales欄位進行加總（sum），最後以長條圖（kind=\"bar\"）呈現，對應的語法即為data.groupby(\"Platform\")[\"Global_Sales\"].sum().plot(kind=\"bar\")。","options":{"A":"正確，先依Platform分組並對Global_Sales加總，取得各平台銷售總額，再繪製長條圖，完全符合題目「統計銷售總額」的需求。","B":"錯誤，count()計算的是各平台的資料筆數（遊戲數量），而非銷售金額的加總，與題目要求的「銷售總額」不符。","C":"錯誤，value_counts()僅統計Platform欄位各類別出現的次數（遊戲數量），同樣未涉及Global_Sales銷售金額的加總。","D":"錯誤，mean()計算的是各平台的平均銷售額，而非題目要求的「銷售總額」，統計量選錯。"}},"origin":"past"},{"id":"middle_114-2_s2_q46","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":46,"context":{"text":"一間遊戲市場研究公司正在分析全球電子遊戲銷售情況，並準備建立一份「熱銷遊戲銷售報告」。分析師取得了一份名為vgsales.csv的資料集，內容包含了全球銷量超過10萬份的電子遊戲清單。研究團隊希望透過這份資料，了解不同年份、平台與地區的銷售趨勢。資料集的欄位說明如下，請根據下述資料情境回答以43~47題。\nName：遊戲名稱\nPlatform：遊戲平台（如PS4、X360、Wii等）\nYear：發售年份\nGenre：遊戲類型（如Action、Sports、Role-Playing等）\nPublisher：發行商名稱\nNA_Sales / EU_Sales / JP_Sales / Other_Sales：各地區銷售量（單\n位：百萬份）\nGlobal_Sales：全球總銷售量（單位：百萬份）\n資料的欄位概觀如下：","figures":["images/middle_114-2_s2_ctx2_fig1.png","images/middle_114-2_s2_ctx2_fig2.png"]},"stem":"團隊希望比較北美、歐洲、日本及其他地區的整體銷售比例，並使用seaborn套件以長條圖的形式進行可視化分析。請選出能正確顯示這些地區銷售總額比例的程式碼。","options":{"A":"sns.countplot(x=[\"NA_Sales\",\"EU_Sales\",\"JP_Sales\",\"Other_Sales\"],data=data)","B":"sns.lineplot(x=\"Platform\",y=[\"NA_Sales\",\"EU_Sales\",\"JP_Sales\",\"Other_Sales\"],data=data)","C":"sns.barplot(x=\"variable\", y=\"value\",data=pd.melt(data,value_vars=[\"NA_Sales\",\"EU_Sales\",\"JP_Sales\",\"Other_Sales\"]),estimator=sum)","D":"sns.histplot(data[[\"NA_Sales\",\"EU_Sales\",\"JP_Sales\",\"Other_Sales\"]])"},"answer":"C","figures":[],"explanation":{"approach":"由於NA_Sales、EU_Sales、JP_Sales、Other_Sales為分別的欄位（寬格式），須先用pd.melt()將資料轉為長格式，產生「variable」（地區名稱）與「value」（銷售額）兩欄，再以sns.barplot(x=\"variable\", y=\"value\", ..., estimator=sum)依地區加總銷售額並繪製長條圖，才能正確比較各地區銷售總額比例。","options":{"A":"錯誤，countplot是用來計算類別出現的「筆數」，且x參數不能直接傳入欄位名稱清單，無法用來加總銷售金額，語法與目的均不符。","B":"錯誤，lineplot用於呈現數值隨連續變數（如時間）變化的趨勢，且y參數同樣不能直接傳入多個欄位名稱清單，並不適合用來比較各地區銷售總額比例。","C":"正確，先以pd.melt()將寬格式轉為長格式，再用barplot搭配estimator=sum依地區加總銷售額並繪圖，是正確呈現各地區銷售總額比例的做法。","D":"錯誤，histplot用於呈現數值變數的分布（直方圖），並非用來比較不同類別（地區）之間的加總銷售比例。"}},"origin":"past"},{"id":"middle_114-2_s2_q47","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":47,"context":{"text":"一間遊戲市場研究公司正在分析全球電子遊戲銷售情況，並準備建立一份「熱銷遊戲銷售報告」。分析師取得了一份名為vgsales.csv的資料集，內容包含了全球銷量超過10萬份的電子遊戲清單。研究團隊希望透過這份資料，了解不同年份、平台與地區的銷售趨勢。資料集的欄位說明如下，請根據下述資料情境回答以43~47題。\nName：遊戲名稱\nPlatform：遊戲平台（如PS4、X360、Wii等）\nYear：發售年份\nGenre：遊戲類型（如Action、Sports、Role-Playing等）\nPublisher：發行商名稱\nNA_Sales / EU_Sales / JP_Sales / Other_Sales：各地區銷售量（單\n位：百萬份）\nGlobal_Sales：全球總銷售量（單位：百萬份）\n資料的欄位概觀如下：","figures":["images/middle_114-2_s2_ctx2_fig1.png","images/middle_114-2_s2_ctx2_fig2.png"]},"stem":"研究團隊想要知道在北美地區（NA）銷售成績最好的遊戲前五名，並希望以seaborn的條狀圖呈現結果。請選出能正確完成這項分析的程式碼。","options":{"A":"sns.barplot(x=\"NA_Sales\", y=\"Name\", data=data.head(5))","B":"sns.barplot(x=\"Name\", y=\"NA_Sales\", data=data.nlargest(5,\"NA_Sales\"))","C":"sns.lineplot(x=\"Name\", y=\"NA_Sales\", data=data.nlargest(5,\"NA_Sales\"))","D":"sns.countplot(x=\"Name\", y=\"NA_Sales\", data=data)"},"answer":"B","figures":[],"explanation":{"approach":"「北美地區銷售成績最好的前五名」需先以data.nlargest(5,\"NA_Sales\")依NA_Sales由大到小取出前五筆資料，再以sns.barplot(x=\"Name\", y=\"NA_Sales\", ...)繪製條狀圖呈現各遊戲名稱與其對應銷售額，才能正確且完整地呈現北美銷售前五名。","options":{"A":"錯誤，data.head(5)僅取資料集「前5筆列」，並非依NA_Sales排序後的前五名，若原始資料未依銷售額排序，結果將不正確。","B":"正確，先以nlargest(5,\"NA_Sales\")正確篩選出NA_Sales最高的前五筆資料，再以barplot繪製，x軸為遊戲名稱、y軸為銷售額，完整符合題目需求。","C":"錯誤，lineplot用於呈現數值隨連續變數變化的趨勢，並不適合用來比較離散類別（遊戲名稱）之間的銷售額高低，題目要求為條狀圖。","D":"錯誤，countplot用於計算類別出現次數，其設計本就不支援同時指定x與y兩個欄位（尤其y為數值加總的情境），無法用來呈現各遊戲的NA_Sales數值。"}},"origin":"past"},{"id":"middle_114-2_s2_q48","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":48,"context":{"text":"使用銷售資料集(marketing.csv)進行迴歸分析，附圖程式碼展示資料載入與處理，請回答後續48~50題。\n下圖顯示資料集的前5筆資料與相關資訊。","figures":["images/middle_114-2_s2_ctx4_fig1.png"]},"stem":"根據上述結果，下列何者正確？","options":{"A":"資料集個數為199筆，變數個數為4個","B":"sales變數的中位數是16.827","C":"facebook變數的第三四分位數(Q3)是11.94","D":"youtube變數的第一四分位數(Q1)是89.25"},"answer":"D","figures":[],"explanation":{"approach":"本題根據data.describe()等敘述性統計摘要結果作答，資料集為常見的行銷分析資料集（youtube、facebook、newspaper、sales共4個變數，200筆觀測值）。逐一核對各選項所述的筆數、中位數與四分位數後，僅D「youtube變數的Q1為89.25」與統計結果相符，其餘選項在筆數或分位數位置上均有誤植。","options":{"A":"錯誤，該資料集實際觀測值筆數為200筆而非199筆，雖然變數個數4個正確，但筆數敘述有誤。","B":"錯誤，sales變數的中位數並非16.827，此數值與資料集實際的中位數統計結果不符。","C":"錯誤，11.94較接近facebook變數第一四分位數（Q1）附近的數值，並非其第三四分位數（Q3），選項將分位數位置誤植。","D":"正確，依據資料集的敘述統計結果，youtube變數的第一四分位數（Q1）為89.25，與統計結果相符。"}},"origin":"past"},{"id":"middle_114-2_s2_q49","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":49,"context":{"text":"使用銷售資料集(marketing.csv)進行迴歸分析，附圖程式碼展示資料載入與處理，請回答後續48~50題。\n下圖顯示資料集的前5筆資料與相關資訊。","figures":["images/middle_114-2_s2_ctx4_fig1.png"]},"stem":"參考下圖計算各變數的遺漏值(NaN)個數結果，下列何者正確？選項A: df.isnull().sum()選項B: df.isNaN().sum()選項C: df.isna().sum()選項D: df.isnan().sum()","options":{"A":"選項D","B":"選項B、選項C、選項D","C":"選項A、選項C","D":"選項A、選項B、選項C"},"answer":"C","figures":[{"src":"images/middle_114-2_s2_q49_fig1.png","position":"stem"}],"explanation":{"approach":"pandas的DataFrame同時提供isnull()與isna()兩個方法，兩者功能完全相同（isna()是isnull()的別名），皆能正確計算各欄位的遺漏值（NaN）個數，與附圖顯示的youtube:0、facebook:1、newspaper:0、sales:0結果一致；而isNaN()與isnan()並非pandas DataFrame實際存在的方法名稱，執行時會產生錯誤。","options":{"A":"錯誤，此選項僅列出「選項D」，但isnan()並非DataFrame的有效方法，執行會報錯，不應被視為正確答案。","B":"錯誤，此選項包含選項B（isNaN()，方法名稱不存在）與選項D（isnan()，同樣不存在），兩者皆會導致錯誤，不能與正確的選項C混列。","C":"正確，isnull()與isna()皆是pandas DataFrame內建且功能相同的有效方法，能正確計算各欄位遺漏值個數，結果與附圖相符。","D":"錯誤，此選項雖包含正確的選項A、C，但同時納入不存在的方法選項B（isNaN()），使整體判斷錯誤。"}},"origin":"past"},{"id":"middle_114-2_s2_q50","level":"middle","session":"114-2","subject":2,"subject_name":"大數據處理分析與應用","number":50,"context":{"text":"使用銷售資料集(marketing.csv)進行迴歸分析，附圖程式碼展示資料載入與處理，請回答後續48~50題。\n下圖顯示資料集的前5筆資料與相關資訊。","figures":["images/middle_114-2_s2_ctx4_fig1.png"]},"stem":"考慮資料集已經填補遺漏值，參考下圖執行結果，下列何者正確？A：空格1完整語法reg = LinearRegression().fit(y, X)B：空格1完整語法reg = LinearRegression().fit(X, y)C：print(reg.coef_)結果為包括截距項等4個係數值D：空格2完整語法sm.OLS(X2, y).fit()E：model_sm迴歸模型的所有迴歸係數在α=0.05之下具有顯著的解釋力F：截距項係數值為3.5561","options":{"A":"B、C、F","B":"B、F","C":"A、C、D、F","D":"B、E"},"answer":"B","figures":[{"src":"images/middle_114-2_s2_q50_fig1.png","position":"stem"}],"explanation":{"approach":"依附圖程式碼，X為特徵矩陣（youtube、facebook、newspaper三欄），y為目標變數sales。sklearn的LinearRegression().fit()語法慣例為fit(X, y)（特徵在前、目標在後），故空格1應為reg = LinearRegression().fit(X, y)（敘述B成立）；而由OLS Regression Results摘要表可知const（截距項）係數為3.5561（敘述F成立）。其餘敘述經檢視後皆與程式邏輯或報表結果不符。","options":{"A":"錯誤，此組合「B、C、F」中的C（reg.coef_結果包含截距項共4個係數）不成立，reg.coef_僅回傳3個特徵（youtube、facebook、newspaper）的係數，截距項需另外以reg.intercept_取得，並不包含在coef_內，故A為錯誤組合。","B":"正確，敘述B（fit(X, y)符合sklearn語法慣例，特徵在前目標在後）與敘述F（由摘要表可知const截距項係數為3.5561）皆為真，兩者組合正確。","C":"錯誤，此組合「A、C、D、F」中，A（fit(y, X)語法順序顛倒）、C（coef_誤稱包含截距項）、D（sm.OLS(X2, y)語法順序顛倒，statsmodels慣例應為sm.OLS(y, X2)即依變數在前）皆為錯誤敘述，不應與F並列為正確組合。","D":"錯誤，此組合「B、E」中的E（所有迴歸係數在α=0.05下皆顯著）不成立，由摘要表可見newspaper的p值（P>|t|）高達0.914，遠大於0.05，並不顯著，故E為錯誤敘述，D組合有誤。"}},"origin":"past"},{"id":"middle_114-2_s3_q01","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":1,"context":null,"stem":"某零售企業建立一個銷售預測模型，希望評估該模型在不同月份的新資料上，是否仍能維持穩定的預測表現。資料科學團隊計畫利用統計方法檢驗模型對未觀察資料的適應能力與泛化效果。下列哪一種方法最適合用於此目的？","options":{"A":"F檢定（F-test）","B":"交叉驗證（Cross-Validation）","C":"配對樣本t檢定（Paired-sample t-test）","D":"卡方檢定（Chi-square Test）"},"answer":"B","figures":[],"explanation":{"approach":"題目要評估模型在「不同月份新資料」上是否仍能維持穩定表現，也就是檢驗模型的泛化能力。交叉驗證（Cross-Validation）透過反覆切分訓練/驗證集，觀察模型在多個未見過的子集上的表現是否穩定，正是評估泛化能力的標準統計方法。","options":{"A":"F檢定用於比較兩組變異數是否有顯著差異（如比較不同模型的變異），並非用來評估單一模型對未觀察資料的適應能力。","B":"正確答案。交叉驗證透過多次切分不同的訓練/驗證子集重複評估，可直接檢驗模型在未見資料上的穩定性與泛化效果。","C":"配對樣本t檢定用於比較兩組相依樣本的平均數是否有顯著差異，屬於假設檢定工具，不是評估泛化能力的方法。","D":"卡方檢定用於檢驗類別變數之間的獨立性或分布是否符合預期，與評估模型泛化能力無關。"}},"origin":"past"},{"id":"middle_114-2_s3_q02","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":2,"context":null,"stem":"在建立迴歸或分類模型時，若希望避免模型過度擬合（Overfitting），可透過加入正則化項以限制模型的複雜度。其中，L1正則化（Lasso）的主要效果為何？","options":{"A":"增加模型參數的數量，以提升表現靈活度","B":"強化梯度穩定性，避免參數更新過度震盪","C":"產生稀疏模型（Sparse Model），使部分參數權重收斂為零","D":"提高學習率（Learning Rate），加速模型收斂速度"},"answer":"C","figures":[],"explanation":{"approach":"L1正則化（Lasso）在損失函數中加入權重絕對值的懲罰項，由於此懲罰項在最佳化過程中會使部分權重被壓縮至恰好等於零，因此具有自動特徵選擇的效果，產生稀疏模型。","options":{"A":"正則化的目的是限制模型複雜度，而非增加參數數量，此敘述與正則化的本意相反。","B":"梯度穩定性通常與梯度裁剪、Batch Normalization等技巧有關，不是L1正則化的主要效果。","C":"正確答案。L1正則化的懲罰項會使部分不重要的參數權重收斂為零，形成稀疏模型，達到特徵篩選效果。","D":"學習率是獨立的超參數，由優化器設定，L1正則化不會改變或提高學習率。"}},"origin":"past"},{"id":"middle_114-2_s3_q03","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":3,"context":null,"stem":"在訓練非線性模型時，若目標函數為非凸函數（Non-convex Function），演算法在參數更新過程中可能出現多個極值點，導致最佳化結果不穩定。請問此時最可能發生下列哪一種情況？","options":{"A":"梯度消失","B":"資料過少","C":"局部最優解","D":"過擬合"},"answer":"C","figures":[],"explanation":{"approach":"非凸目標函數的損失曲面存在多個局部極值點，梯度下降類演算法在更新過程中容易被困在其中某個局部極小值，導致最佳化結果不穩定、無法保證找到全域最優解，此現象即為局部最優解問題。","options":{"A":"梯度消失是指深層網路反向傳播時梯度逐層衰減趨近於零，主要與網路深度及激活函數飽和有關，並非非凸性直接造成的現象。","B":"資料量不足會影響模型的統計效力與過擬合風險，與目標函數非凸、存在多個極值點無直接關係。","C":"正確答案。非凸函數存在多個局部極值，最佳化過程可能收斂到局部最優解而非全域最優解，導致結果不穩定。","D":"過擬合是模型在訓練集表現過好但泛化能力差的現象，與非凸最佳化過程中陷入局部極值是不同的概念。"}},"origin":"past"},{"id":"middle_114-2_s3_q04","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":4,"context":null,"stem":"在執行DBSCAN（Density-Based Spatial Clustering of Applicationswith Noise）群集分析時，若某資料點鄰域內的樣本數不足以形成核心點（Core Point），且該點未被任何核心點的鄰域所包含，也未與其他群集形成密度可達關係（Density Reachability），此資料點最終將被歸類為哪一種類型？","options":{"A":"鄰近點（Neighbor Point）","B":"雜訊點（Noise Point）","C":"邊界點（Border Point）","D":"潛在點（Potential Point）"},"answer":"B","figures":[],"explanation":{"approach":"DBSCAN將資料點分為核心點、邊界點與雜訊點三類。題目描述的資料點鄰域內樣本數不足以成為核心點、也未落入任何核心點鄰域內，且與其他群集不具密度可達關係，代表它不屬於任何群集，依定義應歸類為雜訊點。","options":{"A":"「鄰近點」並非DBSCAN演算法中的正式分類名稱，DBSCAN僅定義核心點、邊界點與雜訊點三種類型。","B":"正確答案。既非核心點、也未被任何核心點鄰域涵蓋、且不具密度可達關係，依DBSCAN定義即為雜訊點（離群點）。","C":"邊界點是指本身不是核心點，但落在某核心點鄰域內的點；題目已說明該點未被任何核心點鄰域涵蓋，故不符合邊界點定義。","D":"「潛在點」不是DBSCAN演算法的標準術語，該演算法沒有此分類。"}},"origin":"past"},{"id":"middle_114-2_s3_q05","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":5,"context":null,"stem":"某智慧製造公司開發一套影像辨識系統，用於自動檢測生產線上的瑕疵產品。系統採用卷積神經網路（Convolutional Neural Network, CNN）作為主要模型架構，其中第一層卷積層（Convolutional Layer）主要負責的功能為下列何者？","options":{"A":"自動提取輸入影像中的局部特徵","B":"降低影像維度以加速運算效率","C":"增加神經元與參數數量以提升模型容量","D":"整合所有特徵並輸出最終分類結果"},"answer":"A","figures":[],"explanation":{"approach":"CNN的第一層卷積層直接對原始影像進行卷積運算，透過小範圍的濾波器（filter）掃描影像，主要功能是自動提取邊緣、紋理等局部特徵，作為後續層的輸入基礎。","options":{"A":"正確答案。卷積層以局部感受野掃描影像，自動學習並提取局部特徵（如邊緣、紋理），是CNN最基礎的特徵擷取機制。","B":"降低影像維度主要是池化層（Pooling Layer）的功能，而非卷積層的主要任務。","C":"增加參數量以提升模型容量並非卷積層的設計目的，事實上卷積層透過參數共享是為了「減少」參數量。","D":"整合所有特徵並輸出分類結果是網路末端全連接層（Fully Connected Layer）與輸出層的工作，不是第一層卷積層的功能。"}},"origin":"past"},{"id":"middle_114-2_s3_q06","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":6,"context":null,"stem":"某智慧城市團隊開發一套交通監控系統，用於即時辨識路口監視器影像中的車輛與行人。團隊比較後發現，卷積神經網路（Convolutional NeuralNetwork, CNN）在訓練與推論效率上，明顯優於傳統的全連接神經網路（Fully Connected Neural Network, FCNN）。請問下列何者為主要原因？","options":{"A":"CNN能自動學習影像的旋轉與比例不變性","B":"CNN可直接跳過人工特徵提取步驟進行分類","C":"CNN透過區域感知（Local Receptive Field）與參數共享（ParameterSharing）機制，降低模型參數量與運算複雜度","D":"CNN捨棄激勵函數（Activation Function），以加快運算速度"},"answer":"C","figures":[],"explanation":{"approach":"CNN相較於全連接神經網路效率更高的關鍵在於架構設計：透過區域感知（每個神經元只連接輸入的局部區域）與參數共享（同一濾波器在整張影像上重複使用），大幅降低模型參數量與運算複雜度，因此訓練與推論效率明顯提升。","options":{"A":"CNN對平移具有一定不變性，但對旋轉、比例的不變性並非CNN架構天生自動具備的特性，也不是其效率優於FCNN的主因。","B":"CNN仍需透過卷積層學習特徵，並非「跳過」特徵提取，且此敘述未說明效率提升的技術原因。","C":"正確答案。區域感知與參數共享機制讓CNN不需為每個輸入位置建立獨立權重，大幅降低參數量與運算量，這是效率優於FCNN的核心原因。","D":"CNN仍會使用激活函數（如ReLU）以引入非線性，並未捨棄激勵函數，此敘述錯誤。"}},"origin":"past"},{"id":"middle_114-2_s3_q07","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":7,"context":null,"stem":"下列哪一種應用最適合採用長短期記憶網路（Long Short-Term Memory,LSTM）模型？","options":{"A":"預測未來七天的電力需求變化趨勢","B":"辨識監視影像中不同類別的物件","C":"將大量顧客資料依相似特徵自動分群","D":"將高維度的感測器資料壓縮成低維表示"},"answer":"A","figures":[],"explanation":{"approach":"LSTM是為處理序列資料設計的循環神經網路變體，擅長捕捉時間序列中的長期依賴關係。預測未來七天電力需求屬於時間序列預測任務，資料具有明顯的時序相依性，最適合以LSTM建模。","options":{"A":"正確答案。電力需求預測是典型的時間序列問題，需要模型記憶過去趨勢以預測未來走勢，正是LSTM擅長的應用場景。","B":"辨識影像中的物件類別屬於空間特徵擷取任務，通常採用CNN，而非處理序列資料的LSTM。","C":"將顧客資料依相似特徵分群屬於非監督式的聚類任務（如K-means），與LSTM處理序列資料的特性無關。","D":"將高維資料壓縮為低維表示屬於降維任務，通常使用PCA或Autoencoder，並非LSTM的典型應用。"}},"origin":"past"},{"id":"middle_114-2_s3_q08","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":8,"context":null,"stem":"資訊增益（Information Gain）常用於衡量特徵對分類結果的不確定性貢獻程度，並據以進行特徵選擇。此方法主要應用於下列哪一類模型架構中？","options":{"A":"使用L1正則化進行特徵篩選的線性模型","B":"利用激活函數（Activation Function）進行特徵擷取的深度神經網路","C":"透過核函數（Kernel Function）將特徵映射至高維空間的分類模型","D":"透過遞迴分裂方式建立分類規則的決策樹模型"},"answer":"D","figures":[],"explanation":{"approach":"資訊增益是衡量某特徵能降低分類不確定性（熵）的程度，決策樹演算法（如ID3、C4.5）在每次遞迴分裂節點時，會選擇資訊增益最大的特徵作為分裂依據，因此資訊增益主要應用於決策樹模型架構。","options":{"A":"L1正則化進行特徵篩選是線性模型透過懲罰項使係數收斂為零的做法，與資訊增益衡量不確定性下降的機制不同。","B":"深度神經網路透過激活函數進行非線性轉換以擷取特徵，其特徵學習方式與資訊增益的分裂準則無關。","C":"核函數是SVM等模型將特徵映射至高維空間以利分類的技巧，與決策樹使用資訊增益做分裂準則的機制不同。","D":"正確答案。決策樹透過遞迴分裂建立分類規則，每次選擇分裂特徵時常以資訊增益衡量該特徵降低不確定性的貢獻程度。"}},"origin":"past"},{"id":"middle_114-2_s3_q09","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":9,"context":null,"stem":"在建構以距離為基礎的機器學習模型（如KNN、SVM）時，下列哪一項資料前處理方式最為關鍵？","options":{"A":"進行特徵縮放（Feature Scaling），使各特徵變數具有相似的數值範圍","B":"將連續型特徵變數轉換為類別型變數","C":"以平均值或中位數進行缺失值補齊","D":"進行隨機抽樣以平衡資料筆數"},"answer":"A","figures":[],"explanation":{"approach":"KNN、SVM等以距離為基礎的模型，其分類依據直接來自特徵空間中的距離計算，若各特徵數值範圍差異懸殊，數值範圍大的特徵會主導距離計算結果，因此進行特徵縮放使各特徵具有相似數值範圍，是此類模型最關鍵的前處理步驟。","options":{"A":"正確答案。距離基礎模型的判斷依賴特徵間的距離計算，未經縮放的特徵會因數值範圍不同而扭曲距離結果，因此特徵縮放最為關鍵。","B":"將連續特徵轉為類別型變數反而會損失數值資訊，且不是距離基礎模型的關鍵前處理步驟，一般也較少如此處理。","C":"缺失值補齊是通用的資料清理步驟，對所有模型都重要，但並非距離基礎模型「特有」的關鍵前處理需求。","D":"隨機抽樣平衡資料筆數是處理類別不平衡問題的作法，與距離計算是否受數值範圍影響無直接關聯。"}},"origin":"past"},{"id":"middle_114-2_s3_q10","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":10,"context":null,"stem":"下列哪一種應用情境最適合導入AutoML，以提升模型開發效率？","options":{"A":"公司已有完整的MLOps平台與資深資料科學團隊，模型更新採固定流程","B":"製造部門的生產良率模型已長期穩定運作，只需定期調整參數","C":"行銷部門希望在短時間內比較多種顧客流失預測模型，缺乏專職工程師與時間進行手動建模","D":"財務部門正在開發高度客製化的信用風險評估模型，需要精細控制特徵工程與演算法細節"},"answer":"C","figures":[],"explanation":{"approach":"AutoML的核心價值在於自動化模型選擇、超參數調整與特徵處理流程，最適合用於時間或人力資源有限、需要快速比較多種模型的場景，例如行銷部門想在短時間內比較多種顧客流失預測模型但缺乏專職工程師的情境。","options":{"A":"公司已有完整MLOps平台與資深團隊、流程已固定，此情境不需要藉助AutoML來提升開發效率。","B":"生產良率模型已穩定運作且僅需定期微調參數，不屬於需要快速嘗試多種模型的情境，AutoML的效益有限。","C":"正確答案。缺乏專職工程師與時間、又需要在短時間內比較多種模型，正是AutoML自動化建模能發揮最大效益的典型情境。","D":"高度客製化且需要精細控制特徵工程與演算法細節的任務，AutoML的自動化流程反而會限制手動調校的彈性，較不適合。"}},"origin":"past"},{"id":"middle_114-2_s3_q11","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":11,"context":null,"stem":"相較於Grid Search，Random Search在超參數調整上具備哪一項主要優勢？","options":{"A":"可自動產生模型架構","B":"可使用更大的訓練集","C":"避免模型過擬合","D":"能更有效率搜尋高維參數空間"},"answer":"D","figures":[],"explanation":{"approach":"Grid Search需窮舉所有超參數組合，在高維參數空間中組合數會呈指數成長，運算成本極高；Random Search則以隨機取樣方式探索參數空間，能以較少的嘗試次數涵蓋更廣的參數範圍，因此在高維空間中搜尋效率通常優於Grid Search。","options":{"A":"Random Search僅是超參數搜尋策略，並不會自動產生模型架構（那是屬於神經架構搜尋NAS的範疇）。","B":"Random Search與訓練集大小的使用無關，兩種搜尋方法使用的訓練資料量相同。","C":"避免過擬合主要靠正則化、資料量、模型設計等因素，並非Random Search相較Grid Search的主要優勢。","D":"正確答案。在高維參數空間中，Random Search能以隨機取樣涵蓋更多元的參數組合，通常比窮舉式的Grid Search更有效率找到較佳解。"}},"origin":"past"},{"id":"middle_114-2_s3_q12","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":12,"context":null,"stem":"某智慧製造公司開發一套設備故障預測系統，利用感測器資料訓練深度神經網路（Deep Neural Network, DNN）模型，以提前偵測異常運作跡象。在訓練過程中，團隊發現模型收斂速度不穩定：有時過快導致過擬合，有時又遲遲無法達到最佳準確率。開發團隊可以藉由調整下列哪一項超參數（Hyperparameter）以改善此問題？","options":{"A":"每個神經元的輸出結果","B":"損失函數（Loss Function）在訓練過程中的梯度變化值（Gradient）","C":"學習率（Learning Rate），控制模型權重更新的速度","D":"模型在訓練後產生的權重值"},"answer":"C","figures":[],"explanation":{"approach":"模型收斂速度不穩定（有時過快過擬合、有時遲遲未達最佳準確率），通常與權重更新步伐大小有關。學習率（Learning Rate）直接控制每次參數更新的幅度，過大會震盪或過擬合風險增加，過小則收斂緩慢，因此調整學習率是改善此問題的關鍵超參數。","options":{"A":"神經元輸出結果是模型運算的中間結果，屬於前向傳播的產物，並非可直接設定的超參數。","B":"損失函數的梯度變化值是訓練過程中依資料與權重計算出來的結果，是被觀察量而非可調整的超參數本身。","C":"正確答案。學習率直接控制權重更新步伐，是解決收斂不穩定問題最直接可調整的超參數。","D":"訓練後產生的權重值是模型學習的結果（參數），不是使用者可預先設定調整的超參數。"}},"origin":"past"},{"id":"middle_114-2_s3_q13","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":13,"context":null,"stem":"標籤偏差(Label Bias)通常是因為什麼原因造成？","options":{"A":"訓練資料量過大","B":"標記資料本身帶有主觀偏見","C":"模型結構設計不當","D":"特徵數量設定過多"},"answer":"B","figures":[],"explanation":{"approach":"標籤偏差是指訓練資料的標記（Label）本身在標註過程中就帶有標註者的主觀認知或偏見，導致模型學習到帶有偏誤的標準答案，即使模型與特徵處理都正確，最終預測結果仍會複製這種偏見。","options":{"A":"訓練資料量過大通常與過擬合或運算成本有關，不是標籤偏差的成因。","B":"正確答案。標記資料本身在人工標註時帶有主觀偏見，是造成標籤偏差最直接且常見的原因。","C":"模型結構設計不當可能導致欠擬合或過擬合等問題，與標記本身是否帶有偏見是不同層次的問題。","D":"特徵數量設定過多可能造成維度災難或過擬合，與標籤本身的標註品質無關。"}},"origin":"past"},{"id":"middle_114-2_s3_q14","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":14,"context":null,"stem":"下列哪一種AI應用情境中，模型的可解釋性（Explainability）最為關鍵？","options":{"A":"電商平台利用深度學習模型預測用戶的下一次購買時間，以優化推播行銷策略","B":"新創公司使用機器學習演算法自動調整廣告出價策略，以提升點擊轉換率","C":"醫院導入AI模型分析病患影像並給出腫瘤惡性可能性，作為臨床醫師診斷依據","D":"銀行導入AI模型預測客戶流失率，並自動推薦留客優惠方案"},"answer":"C","figures":[],"explanation":{"approach":"可解釋性的重要程度取決於決策後果的嚴重性與是否涉及人身安全。醫療診斷直接影響病患生命健康，臨床醫師需要理解AI模型判斷腫瘤惡性可能性的依據才能放心採信作為診斷參考，因此此情境對可解釋性的要求最為關鍵。","options":{"A":"預測購買時間用於優化行銷推播，即使判斷失準，後果通常僅為行銷效益的損失，可解釋性的急迫性相對較低。","B":"自動調整廣告出價策略著重提升點擊轉換率，屬於商業效益最佳化問題，對可解釋性的要求不如醫療決策關鍵。","C":"正確答案。醫療診斷結果攸關病患生命健康，醫師必須理解模型判斷依據才能負責任地採用，因此可解釋性在此情境最為關鍵。","D":"預測客戶流失並推薦優惠方案屬於商業行銷決策，錯誤成本主要是行銷資源浪費，重要性不及攸關生命的醫療決策。"}},"origin":"past"},{"id":"middle_114-2_s3_q15","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":15,"context":null,"stem":"在線性迴歸模型中，若R²值為0.85，其意義為何？","options":{"A":"模型準確率為85%","B":"85%的變異可被模型解釋","C":"預測誤差為15%","D":"模型有85%的信心水準"},"answer":"B","figures":[],"explanation":{"approach":"R²（決定係數）衡量的是應變數的變異中，有多少比例可被模型（自變數）解釋。R²=0.85表示模型所建立的迴歸關係能解釋依變數85%的變異，其餘15%的變異則無法由模型解釋。","options":{"A":"R²不是分類模型的準確率指標，「模型準確率85%」的說法混淆了迴歸模型的解釋力與分類模型的準確率概念。","B":"正確答案。R²=0.85的正確意義是模型能解釋依變數85%的變異量，這是R²在統計上的標準定義。","C":"R²並非直接等於預測誤差的比例，1-R²代表未被解釋的變異比例，而非傳統定義下的「預測誤差」百分比。","D":"R²與統計假設檢定中的信心水準（Confidence Level）是完全不同的概念，兩者不能互相替代解讀。"}},"origin":"past"},{"id":"middle_114-2_s3_q16","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":16,"context":null,"stem":"在二元分類問題中，若精確率（Precision）為0.8，召回率（Recall）為0.6，則F1分數（F1 Score）為何？","options":{"A":"0.686","B":"0.700","C":"0.720","D":"0.750"},"answer":"A","figures":[],"explanation":{"approach":"F1 Score為精確率與召回率的調和平均數，公式為F1 = 2×(Precision×Recall)/(Precision+Recall)。代入Precision=0.8、Recall=0.6，計算得2×0.8×0.6/(0.8+0.6)=0.96/1.4≈0.686。","options":{"A":"正確答案。依F1公式計算：2×0.8×0.6/(0.8+0.6)=0.96/1.4≈0.686，與選項數值相符。","B":"0.700並非依F1公式計算所得的正確數值，可能是誤用算術平均（(0.8+0.6)/2=0.7）而非調和平均所致的錯誤。","C":"0.720不符合F1公式的計算結果，屬於計算錯誤的選項。","D":"0.750不符合F1公式的計算結果，屬於計算錯誤的選項。"}},"origin":"past"},{"id":"middle_114-2_s3_q17","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":17,"context":null,"stem":"下列哪一種優化演算法內建動量（Momentum）的設計機制？","options":{"A":"SGD+Momentum","B":"Adam","C":"RMSProp","D":"Adagrad"},"answer":"B","figures":[],"explanation":{"approach":"Adam（Adaptive Moment Estimation）在其演算法設計中內建了梯度的一階動量估計（即過去梯度的指數加權移動平均，作用類似動量）與二階動量估計（自適應學習率），因此動量機制是Adam演算法核心設計的一部分。","options":{"A":"SGD+Momentum是在原始SGD基礎上「額外加裝」動量項的變形做法，並非本題官方定義中「內建」於演算法核心設計的動量機制（依官方答案，此選項非最佳解）。","B":"正確答案。Adam的一階動量估計（梯度的移動平均）在演算法公式中即為其核心組成部分，屬於內建的動量設計機制。","C":"RMSProp僅對梯度平方進行指數加權移動平均以調整學習率，並未包含動量項的設計。","D":"Adagrad僅累加歷史梯度平方以遞減學習率，同樣沒有動量機制的設計。"},"note":"此題官方答案為B（Adam）。但選項A「SGD+Momentum」從名稱與公式定義上即明確包含動量項，嚴格來說也屬於「內建動量機制」的演算法，與官方答案在概念上略有可討論之處，本題判斷可能側重於Adam是「原生設計即包含動量估計」而非「後加動量的變形」。"},"origin":"past"},{"id":"middle_114-2_s3_q18","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":18,"context":null,"stem":"下列何者最能同時反映XGBoost（eXtreme Gradient Boosting）相較於傳統梯度提升決策樹（Gradient Boosting Decision Tree, GBDT）的主要技術改進？","options":{"A":"引入正則化項（Regularization）以抑制過擬合，並支援缺失值自動處理與並行化訓練","B":"改以隨機森林（Random Forest）架構取代樹模型以提升準確率","C":"以類神經網路（Neural Network）取代弱分類器（Weak Learners）","D":"採用批次正規化（Batch Normalization）技術提升模型穩定性"},"answer":"A","figures":[],"explanation":{"approach":"XGBoost相較傳統GBDT的關鍵改進，在於目標函數中加入正則化項以抑制過擬合、支援自動處理缺失值，並透過特徵層級的平行化運算大幅提升訓練速度，這些是XGBoost論文與實作中明確標榜的技術特色。","options":{"A":"正確答案。XGBoost在損失函數中加入L1/L2正則化項控制模型複雜度，並內建缺失值自動處理機制與平行化訓練，是其相較傳統GBDT的核心技術改進。","B":"XGBoost仍以梯度提升樹（Boosting）為核心架構，並未改為隨機森林（Bagging）架構，兩者集成方式本質不同。","C":"XGBoost的弱分類器仍為決策樹，並未以類神經網路取代樹模型作為基礎學習器。","D":"Batch Normalization是深度神經網路訓練中用於穩定激活值分布的技術，與樹模型架構的XGBoost無關，XGBoost未採用此技術。"}},"origin":"past"},{"id":"middle_114-2_s3_q19","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":19,"context":null,"stem":"某醫療機構開發疾病早期偵測模型，正樣本（確診病例）僅佔3%。在模型訓練與評估過程中，下列哪一種作法最不適合用於提升對少數類病例的預測能力？","options":{"A":"使用SMOTE過採樣","B":"調整類別權重","C":"使用準確率（Accuracy）作為評估指標","D":"欠採樣多數類(Undersampling the majority class)"},"answer":"C","figures":[],"explanation":{"approach":"當正樣本僅佔3%屬於高度不平衡資料，若僅以整體準確率（Accuracy）評估模型，模型只要將所有樣本都預測為多數類（陰性）即可得到97%的高準確率，卻完全無法偵測出少數類病例，因此準確率是此情境下最不適合、最具誤導性的評估方式。","options":{"A":"SMOTE過採樣透過合成少數類樣本增加其數量，是提升不平衡資料中少數類預測能力的常見有效方法。","B":"調整類別權重可讓模型在訓練時更重視少數類樣本的誤判成本，是處理不平衡資料常用且有效的做法。","C":"正確答案。在極度不平衡資料下，準確率會被多數類主導而失去鑑別力，無法反映模型對少數類（確診病例）的實際預測能力，是最不適合的評估方式。","D":"欠採樣多數類可降低類別數量差距、平衡訓練資料比例，是處理不平衡資料的常見有效方法之一。"}},"origin":"past"},{"id":"middle_114-2_s3_q20","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":20,"context":null,"stem":"某電子商務公司為開發商品評論情感分析模型，希望模型能捕捉評論中不同特徵之間的關聯影響，例如「商品價格」與「顧客滿意度」的互動效果。下列哪一種特徵工程設計方式最適合用於建立互動特徵（InteractionFeatures）？","options":{"A":"將單一特徵取平方","B":"對所有特徵進行對數轉換","C":"將兩個或多個特徵進行乘積或交互組合","D":"對特徵進行標準化"},"answer":"C","figures":[],"explanation":{"approach":"互動特徵（Interaction Features）的目的是捕捉兩個或多個特徵之間的交互影響關係，最直接的建立方式就是將相關特徵進行乘積或組合運算，例如將「商品價格」與「顧客滿意度」相乘，藉此表達兩者的共同作用效果。","options":{"A":"將單一特徵取平方屬於多項式特徵（Polynomial Feature）擴展，反映的是單一變數的非線性效果，並非不同特徵之間的交互關係。","B":"對數轉換是針對單一特徵進行數值分佈調整（如處理偏態分佈），無法捕捉特徵之間的交互效果。","C":"正確答案。將兩個或多個特徵相乘或組合，能直接表達特徵之間的交互作用，是建立互動特徵最典型的做法。","D":"標準化是調整單一特徵的數值尺度（使其均值為0、標準差為1），與捕捉特徵間交互關係無關。"}},"origin":"past"},{"id":"middle_114-2_s3_q21","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":21,"context":null,"stem":"某語音辨識系統開發團隊採用Transformer架構，為了讓模型能同時理解語音片段中的發音特徵、語速變化與語意脈絡等多層次資訊，團隊在設計中導入了多頭注意力（Multi-head Attention）機制。請問下列何者為此機制的主要優點？","options":{"A":"減少模型參數量以降低訓練成本","B":"加速整體注意力計算過程","C":"從不同表示子空間（Representation Subspaces）同時捕捉多樣化關聯資訊","D":"避免梯度消失（Gradient Vanishing）問題"},"answer":"C","figures":[],"explanation":{"approach":"多頭注意力機制將輸入投影到多組不同的表示子空間，讓每個頭能各自關注不同面向的關聯資訊（例如發音特徵、語速變化、語意脈絡等），再將各頭結果整合，因此能同時捕捉多樣化且互補的關聯資訊，是其主要優點。","options":{"A":"多頭注意力是將原本單一注意力拆成多組並行運算，通常不會減少模型整體參數量，此敘述與其設計目的不符。","B":"多頭注意力需要平行計算多組注意力並整合，運算量並未因此減少，此敘述並非其主要優點。","C":"正確答案。多頭機制讓模型能從不同表示子空間平行擷取多樣化的關聯資訊，捕捉輸入資料更豐富的特徵面向，是其核心優勢。","D":"梯度消失問題主要透過殘差連接（Residual Connection）與層正規化（Layer Normalization）等機制緩解，並非多頭注意力機制本身的主要作用。"}},"origin":"past"},{"id":"middle_114-2_s3_q22","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":22,"context":null,"stem":"某電商平台希望預測顧客是否會購買特定商品。系統蒐集顧客的瀏覽紀錄、停留時間、商品類別偏好與過去購買行為，並以此推估「在觀察到這些行為特徵的情況下，該顧客會購買的機率」。若模型採用貝氏定理（Bayes’Theorem）進行推論，下列敘述何者最符合其核心運作機制？","options":{"A":"根據歷史樣本自動分群，找出行為相似的顧客群","B":"以條件機率方式計算顧客屬於「會購買」或「不會購買」的分類機率","C":"以最小平方誤差（Mean Squared Error）為損失函數，預測顧客的購買金額","D":"依據回饋信號（Feedback Signal）透過強化學習（ReinforcementLearning）動態調整推薦策略"},"answer":"B","figures":[],"explanation":{"approach":"貝氏定理的核心運作是利用已知的先驗機率與觀察到的證據（特徵），計算在該證據條件下事件發生的後驗（條件）機率。應用於此情境，即是以顧客的瀏覽紀錄等特徵為條件，計算其屬於「會購買」或「不會購買」類別的條件機率，據以進行分類判斷。","options":{"A":"根據歷史樣本自動分群、找出相似顧客群屬於非監督式的聚類方法，並非貝氏定理計算條件機率分類的核心機制。","B":"正確答案。貝氏定理的核心即是以條件機率的方式，依觀察到的特徵計算樣本屬於各類別（會購買/不會購買）的機率，藉此進行分類。","C":"以最小平方誤差作為損失函數預測連續數值（購買金額）屬於迴歸問題的損失設計，與貝氏定理進行分類推論的機制不同。","D":"依回饋訊號動態調整策略是強化學習的核心運作方式，與貝氏定理以條件機率進行分類推論的機制不同。"}},"origin":"past"},{"id":"middle_114-2_s3_q23","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":23,"context":null,"stem":"一家再生能源公司希望預測未來三個月太陽能發電量的波動範圍。由於氣候條件具有高度隨機性，且輸入變數（如日照時數、雲量、溫度）之間存在不確定關係，工程團隊決定以隨機抽樣方式模擬多種可能情境，以估算整體發電量的機率分佈與風險區間。請問此時所採用的技術最符合下列哪一種方法？","options":{"A":"蒙地卡羅方法（Monte Carlo Method）","B":"K-means聚類（K-means Clustering）","C":"支持向量迴歸（Support Vector Regression, SVR）","D":"特徵選取（Feature Selection）"},"answer":"A","figures":[],"explanation":{"approach":"題目描述以隨機抽樣方式模擬多種可能情境（氣候變數的不確定性），藉此估算整體發電量的機率分佈與風險區間，這正是蒙地卡羅方法（Monte Carlo Method）的典型應用：透過大量隨機取樣模擬不確定系統的可能結果分布。","options":{"A":"正確答案。以隨機抽樣模擬多種情境來估算機率分佈與風險區間，是蒙地卡羅方法處理不確定性問題的標準做法。","B":"K-means聚類是將資料依相似性分群的非監督式方法，與隨機抽樣模擬不確定性情境的目的不同。","C":"支持向量迴歸是監督式的迴歸預測方法，用於學習輸入輸出的映射關係，並非以隨機抽樣模擬不確定性分佈的方法。","D":"特徵選取是篩選對模型有貢獻的輸入變數的前處理技術，與模擬多種情境估算機率分佈的目的無關。"}},"origin":"past"},{"id":"middle_114-2_s3_q24","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":24,"context":null,"stem":"某房地產公司利用多元迴歸模型（Multiple Regression Model）預測房價，並繪製殘差圖（Residual Plot）檢查模型品質。結果顯示部分資料點的殘差極大，且在高價區樣本中出現系統性彎曲分佈現象。根據此觀察，下列何者為最可能的正確解釋？","options":{"A":"模型過度擬合（Overfitting），導致在訓練資料上表現過好、泛化能力不足","B":"模型特徵數量不足，導致欠擬合（Underfitting）","C":"模型存在異常值（Outlier）或非線性關係，違反迴歸假設","D":"殘差圖呈現隨機分佈，表示模型已完全符合所有假設"},"answer":"C","figures":[],"explanation":{"approach":"殘差圖中若出現部分資料點殘差極大、且在高價區樣本呈現系統性彎曲（非隨機）分佈，代表資料中存在離群值，或者真實關係並非線性、模型未能捕捉到的非線性結構，這違反了線性迴歸「殘差應隨機分佈」的基本假設。","options":{"A":"過擬合通常需比較訓練集與測試集/驗證集表現的落差來判斷，單純從殘差圖出現系統性彎曲並不能直接推論為過擬合。","B":"欠擬合會使整體殘差普遍偏大，但題目描述的是「系統性彎曲分佈」這種特定非隨機模式，比起單純特徵不足，更直接指向非線性關係或離群值問題。","C":"正確答案。殘差呈系統性彎曲且部分點殘差極大，正是存在離群值或資料真實關係為非線性、違反迴歸線性假設的典型徵兆。","D":"題目明確描述殘差呈現「系統性彎曲」而非隨機分佈，此敘述與題目觀察到的現象矛盾，且隨機分佈才代表模型假設成立。"}},"origin":"past"},{"id":"middle_114-2_s3_q25","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":25,"context":null,"stem":"某金融機構正在建立傳統信用評分卡模型，採用邏輯迴歸（LogisticRegression）作為建模方法，並依循監理機關建議的標準化流程進行模型開發。下列哪一項不是傳統信用評分卡模型開發流程中的常見步驟？","options":{"A":"使用生成式模型進行特徵學習","B":"進行特徵選擇與多重共線性（Multicollinearity）分析","C":"進行分箱（Binning）與資訊值（Information Value, IV）檢定","D":"使用樣本穩定性指標（Population Stability Index, PSI）檢驗模型穩定性"},"answer":"A","figures":[],"explanation":{"approach":"傳統信用評分卡模型是以邏輯迴歸為核心、講求可解釋性與監理合規性的建模流程，標準步驟包含特徵篩選、共線性檢查、分箱與IV值檢定，以及PSI穩定性監控。使用生成式模型進行特徵學習並非此類傳統、強調可解釋性流程中的常見步驟。","options":{"A":"正確答案。生成式模型屬於較新穎的深度學習技術，並非傳統信用評分卡建模流程中常見或監理機關建議的標準步驟。","B":"特徵選擇與多重共線性分析是邏輯迴歸信用評分卡建模的常見且必要步驟，用以確保模型穩定與係數可解釋。","C":"分箱與資訊值（IV）檢定是信用評分卡開發中評估特徵預測力的標準流程，屬於常見步驟。","D":"PSI是監理機關要求用於檢驗模型上線後穩定性的常用指標，屬於信用評分卡開發流程中的常見步驟。"}},"origin":"past"},{"id":"middle_114-2_s3_q26","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":26,"context":null,"stem":"在防止監督式學習模型過擬合（Overfitting）時，下列哪一種策略不屬於降低模型複雜度或限制學習能力的作法？","options":{"A":"採用L1或L2正則化","B":"在訓練過程中使用Dropout技術","C":"採取早期停止（Early Stopping）機制","D":"擴增輸入特徵變數以提升模型表達能力"},"answer":"D","figures":[],"explanation":{"approach":"防止過擬合的策略核心邏輯是限制模型的學習能力或複雜度。L1/L2正則化、Dropout、Early Stopping都是透過限制參數大小、隨機丟棄神經元或提前結束訓練來降低模型複雜度；而擴增輸入特徵變數反而是增加模型的表達能力與複雜度，方向與防止過擬合相反。","options":{"A":"L1或L2正則化透過懲罰項限制權重大小，屬於降低模型複雜度以防止過擬合的常見作法。","B":"Dropout在訓練過程隨機丟棄部分神經元，限制模型過度依賴特定神經元，屬於降低有效學習能力以防止過擬合的做法。","C":"早期停止機制在驗證表現不再改善時提前結束訓練，限制模型過度學習訓練資料，屬於防止過擬合的常見策略。","D":"正確答案。擴增輸入特徵變數是提升模型表達能力、增加複雜度的作法，方向與「降低複雜度以防止過擬合」相反，因此不屬於此類策略。"}},"origin":"past"},{"id":"middle_114-2_s3_q27","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":27,"context":null,"stem":"某智慧製造團隊在開發瑕疵影像檢測模型時，發現使用線性激活函數（Activation Function）後，模型的訓練準確率長期停滯，懷疑模型無法學習到足夠複雜的特徵表達。若要改善此問題，下列哪一項調整方案最為合適？","options":{"A":"增加卷積層（Convolutional Layer）數量，使網路更深以強化特徵提取","B":"將輸入影像先進行灰階化處理，降低運算量","C":"使用Sigmoid激活函數，以將輸出壓縮至[0,1]範圍","D":"改用ReLU（Rectified Linear Unit）激活函數，以引入非線性並提升模型表達能力"},"answer":"D","figures":[],"explanation":{"approach":"若模型全程使用線性激活函數，無論疊加多少層，整體運算仍等效於單一線性轉換，無法學習複雜的非線性特徵，導致準確率停滯。解決方法是改用ReLU等非線性激活函數，為網路引入非線性轉換能力，讓深層網路真正能學習複雜特徵表達。","options":{"A":"若激活函數仍維持線性，即使增加卷積層數量，整體運算仍會退化為等效的線性轉換，無法真正提升模型表達複雜特徵的能力。","B":"灰階化處理僅是降低輸入影像的通道數以減少運算量，並不能解決激活函數線性導致模型無法學習非線性特徵的根本問題。","C":"Sigmoid雖具備非線性特性，但在深層網路中容易發生飽和導致梯度消失，訓練效果不如ReLU穩定，並非此情境下的最佳解方。","D":"正確答案。改用ReLU可為模型引入非線性轉換能力，且能有效緩解深層網路的梯度消失問題，是解決訓練停滯最合適的作法。"}},"origin":"past"},{"id":"middle_114-2_s3_q28","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":28,"context":null,"stem":"一家零售電商公司希望建立顧客流失預測模型，用以判斷哪些會員可能在三個月內不再消費。團隊以去年會員資料進行訓練，並僅採用「曾經購買三次以上」的活躍顧客紀錄作為樣本。模型上線後，對整體會員進行預測時，發現模型對於新註冊會員與低消費會員的預測準確率明顯偏低。下列何者為造成此現象最可能的原因？","options":{"A":"特徵設計未排除與會員忠誠度高度相關的變數，導致特徵偏差（Feature Bias）","B":"標記（Label）由人工標註，導致標籤偏差（Label Bias）","C":"訓練樣本僅涵蓋高活躍顧客，造成取樣偏差（Sampling Bias）","D":"模型未進行超參數調整，導致過擬合（Overfitting）"},"answer":"C","figures":[],"explanation":{"approach":"訓練資料僅採用「曾經購買三次以上」的活躍顧客紀錄，代表訓練樣本本身的分布已系統性偏離母體（全體會員）的真實分布，導致模型上線後在新註冊會員、低消費會員等訓練時未充分涵蓋的族群上表現不佳，這是典型的取樣偏差（Sampling Bias）問題。","options":{"A":"特徵偏差通常是指特徵設計本身系統性地偏向某些變數或洩漏未來資訊，題目描述的問題根源在於「樣本涵蓋範圍」而非特徵設計本身。","B":"題目並未提及標記由人工主觀標註產生偏誤，流失與否的標籤（是否於三個月內消費）是客觀事實，與標籤偏差無關。","C":"正確答案。訓練樣本僅涵蓋「活躍顧客」，未能代表全體會員（尤其新會員與低消費會員），屬於取樣偏差，導致模型對未被充分代表的族群預測失準。","D":"題目並未提及超參數調整或訓練集/測試集表現落差等過擬合徵兆，問題核心在於樣本涵蓋範圍不足，而非模型過度擬合。"}},"origin":"past"},{"id":"middle_114-2_s3_q29","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":29,"context":null,"stem":"在工業設備故障預測專案中，模型訓練與超參數調整均依賴於一段歷史數據作為驗證集。然而，隨著設備運行環境與工況條件的變化，原有驗證集已無法充分反映現況，導致模型在實際部署後的預測準確率逐漸下降。下列哪一種策略最能有效提升模型在長期運行環境中的穩健性與泛化能力？","options":{"A":"固定驗證集內容，並透過模型正則化技巧（如L2正則化）強化模型泛化","B":"將全部歷史資料納入訓練，不使用驗證集，依靠早期停止（EarlyStopping）控制訓練","C":"簡化模型架構，減少模型參數數量以降低過擬合風險","D":"採用時間序列交叉驗證（Time Series Cross Validation）或滑動視窗驗證（Rolling Window Validation）方法，動態更新驗證資料以適應時間演進"},"answer":"D","figures":[],"explanation":{"approach":"設備運行環境與工況條件會隨時間改變，固定不變的驗證集會逐漸無法反映當下真實狀況（資料飄移）。時間序列交叉驗證或滑動視窗驗證能隨時間動態更新驗證資料，讓模型持續在貼近當下環境的資料上被評估與調整，因此最能提升模型長期運行下的穩健性與泛化能力。","options":{"A":"固定驗證集內容並未解決驗證資料與實際環境逐漸脫節的根本問題，僅加強正則化無法彌補驗證資料本身已過時的缺陷。","B":"完全捨棄驗證集、僅依賴早期停止機制，會失去獨立監控模型在近期真實環境下表現的依據，難以確保泛化能力。","C":"簡化模型架構可降低過擬合風險，但無法解決驗證集內容過時、未能反映當前工況變化的核心問題。","D":"正確答案。時間序列交叉驗證或滑動視窗驗證能隨時間動態更新驗證資料，持續反映最新工況環境，是應對環境變化、提升長期泛化能力最有效的策略。"}},"origin":"past"},{"id":"middle_114-2_s3_q30","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":30,"context":null,"stem":"某情感分析模型在英文資料集上取得macro F1-score = 0.91。當該模型部署於西班牙文資料集時，F1-score驟降至0.58。下列哪一項解釋最合理，且與F1-score變化相關？","options":{"A":"macro F1-score本身波動性高，建議改用micro-average F1-score評估","B":"模型在西班牙文語料上過度擬合，導致評估結果偏高","C":"語言轉移造成召回率（Recall）下降，模型無法正確辨識關鍵情緒詞彙","D":"以均方誤差（MSE）取代F1-score評估可獲得更準確的結果"},"answer":"C","figures":[],"explanation":{"approach":"模型在英文語料訓練得到高F1分數，但直接套用到西班牙文語料時分數大幅下降，最合理的解釋是語言轉移（Language Transfer）問題：模型原本學習到的關鍵情緒詞彙、語言特徵在西班牙文中並不適用，導致無法正確辨識出關鍵情緒詞彙，使召回率大幅下降，進而拖累F1分數。","options":{"A":"macro F1本身的計算方式並不會因為換了語言而「波動性變高」，問題根源在於模型未能適應新語言，而非評估指標選擇不當。","B":"若模型在西班牙文語料上「過度擬合」，理論上會在該語料的評估中表現較好而非分數下降，此敘述與F1驟降的方向矛盾。","C":"正確答案。模型未曾在西班牙文語料上訓練，語言轉移導致其無法辨識該語言中的關鍵情緒詞彙，使召回率下降，是F1分數驟降最合理的解釋。","D":"情感分析屬於分類任務，MSE是用於連續數值迴歸的誤差指標，並不適用於評估分類任務的表現，此建議並不合理。"}},"origin":"past"},{"id":"middle_114-2_s3_q31","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":31,"context":null,"stem":"某能源公司利用歷史氣象與用電資料，開發長期電力需求預測模型，採用深度神經網路架構進行訓練。在訓練過程中，模型在訓練集上的損失值持續下降，但在驗證集上，損失在第80輪後開始波動，呈現週期性上升與下降。團隊懷疑模型受到季節性資料波動與隨機噪音影響，導致驗證損失難以穩定收斂。若要在此情境下合理運用早期停止法（Early Stopping）以確保模型具最佳泛化能力，下列哪一項策略最為適當？","options":{"A":"直接根據訓練集損失最低點停止訓練，以確保模型充分擬合所有樣本","B":"監控驗證集損失並設定適度的耐心值（Patience），在連續多輪未改善後再停止訓練","C":"改以測試集損失作為早停依據，以提升模型最終評估一致性","D":"將所有資料重新合併後訓練至收斂，避免因資料分割導致評估波動"},"answer":"B","figures":[],"explanation":{"approach":"由於驗證損失會受季節性波動與隨機噪音影響而呈現週期性起伏，若直接以單點損失最低就停止訓練容易受噪音誤導。合理做法是持續監控驗證集損失，並設定適度的耐心值（Patience），只有在連續多輪都未見改善時才真正停止訓練，避免因短期波動而誤判。","options":{"A":"根據訓練集損失最低點停止訓練，只會讓模型持續擬合訓練資料本身，無法反映模型在未見資料上的泛化表現，容易導致過擬合。","B":"正確答案。監控驗證損失並搭配耐心值，能容忍短期波動、只在真正持續未改善時才停止，是在噪音干擾下合理運用早期停止法的作法。","C":"測試集應保留作為模型訓練完成後的最終、獨立評估，若用於早停決策會使測試集資訊滲入訓練過程，破壞評估的公正性。","D":"將所有資料合併訓練至收斂會失去可用來監控泛化表現的獨立驗證資料，無法判斷模型何時應該停止，也無法避免過擬合。"}},"origin":"past"},{"id":"middle_114-2_s3_q32","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":32,"context":null,"stem":"某電信公司開發客戶流失預測模型，使用大量顧客行為特徵，例如通話時長、上網頻率、帳單金額、客服聯絡次數等。在訓練過程中，團隊發現部分特徵彼此高度相關，但同時也懷疑有些特徵對流失預測的貢獻度有限。若希望模型在避免過擬合（Overfitting）的同時，能自動篩選出較具代表性的特徵，採用下列哪一種方法最為合適？","options":{"A":"使用早期停止法（Early Stopping）控制訓練回合數，避免過擬合（Overfitting）","B":"同時移除多重共線性特徵並採用L2正則化（Ridge），以確保模型穩定收斂","C":"僅使用L2正則化（Ridge），抑制所有權重幅度但保留全部特徵","D":"採用L1正則化（Lasso），透過懲罰項使部分特徵係數縮為0"},"answer":"D","figures":[],"explanation":{"approach":"題目要求在避免過擬合的同時，能「自動」篩選出較具代表性的特徵。L1正則化（Lasso）的懲罰項會使不重要特徵的係數直接收斂為0，等同於自動完成特徵選擇，同時透過限制權重大小達到抑制過擬合的效果，最符合題目需求。","options":{"A":"早期停止法僅控制訓練回合數以避免過擬合，並不具備自動篩選特徵、使部分特徵係數歸零的能力。","B":"手動移除多重共線性特徵需要額外的人工分析步驟，並非「自動」篩選特徵，且L2正則化不會使特徵係數收斂為零。","C":"L2正則化僅會壓縮所有權重的幅度，但會保留全部特徵、不會使任何係數為零，因此不具備自動特徵選擇的效果。","D":"正確答案。L1正則化的懲罰項會使不具代表性特徵的係數自動收縮為0，同時達到降低模型複雜度、避免過擬合與自動特徵選擇的雙重效果。"}},"origin":"past"},{"id":"middle_114-2_s3_q33","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":33,"context":null,"stem":"某資料科學團隊正在開發一個客戶相似度比對系統，用於計算所有客戶之間的相似度分數。若系統需逐一比對每一位客戶與其他所有客戶的資料組合，此時演算法的時間複雜度最可能為哪一種？其代表意義為何？","options":{"A":"O(n) —執行時間與資料量成線性關係","B":"O(n²) —執行時間與資料量平方成正比","C":"O(1) —執行時間固定不變","D":"O(log n) —執行時間與資料量呈對數成長關係"},"answer":"B","figures":[],"explanation":{"approach":"若需逐一比對每位客戶與其他所有客戶的資料組合，等同於對n筆資料進行所有兩兩配對的比較，比較次數會隨資料量呈平方成長（約n×(n-1)/2對），因此時間複雜度屬於O(n²)，代表執行時間會隨資料量的平方而增加。","options":{"A":"O(n)代表執行時間與資料量呈線性關係，僅適用於每筆資料只需處理一次的情況，不符合「逐一比對所有客戶組合」需要兩兩配對的運算特性。","B":"正確答案。逐一比對每位客戶與其他所有客戶，屬於所有兩兩組合的窮舉比較，執行時間隨資料量n的平方成長，即為O(n²)。","C":"O(1)代表執行時間固定、與資料量無關，明顯不符合需要對所有客戶兩兩比對、運算量隨資料量增加的情境。","D":"O(log n)代表執行時間隨資料量呈對數成長，通常出現在如二分搜尋等演算法中，與逐一比對所有配對組合的窮舉特性不符。"}},"origin":"past"},{"id":"middle_114-2_s3_q34","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":34,"context":null,"stem":"某醫療人工智慧團隊正在開發心臟病風險預測模型，資料量僅有150筆，其中陽性個案不到8%。由於樣本數稀少且類別分布極不平衡，團隊希望在有限資料下，仍能準確評估模型在不同資料上的表現穩定性，同時避免訓練資料被過度切分而影響模型效能。若團隊希望在有限樣本下，同時兼顧資料的利用率與各類別在驗證折中的比例一致性，最適合採用下列哪一種交叉驗證方法？","options":{"A":"5-Fold交叉驗證（5-Fold Cross Validation）","B":"留一法交叉驗證（Leave-One-Out Cross Validation）","C":"隨機交叉驗證（Random Cross Validation）","D":"分層留一法交叉驗證（Stratified Leave-One-Out CrossValidation）"},"answer":"D","figures":[],"explanation":{"approach":"題目要在「樣本稀少(150筆)」與「類別極度不平衡(陽性不到8%,約12筆)」的雙重限制下,挑出兼顧「資料利用率」與「各折類別比例一致」的驗證方式。官方答案取「分層留一法」,命題邏輯是把留一法的高資料利用率、與分層抽樣維持類別比例兩個優點疊在一起。實務操作上這個組合有技術問題(詳見下方註記),作答時理解為命題者要的是這兩個概念的結合即可。","options":{"A":"5-Fold交叉驗證在僅約12筆陽性樣本的情況下，每一折可能僅分配到極少數陽性樣本甚至掛零，難以兼顧資料利用率與類別比例的穩定性。","B":"留一法能最大化資料利用率（每筆資料都輪流作為驗證樣本），但單純的留一法並未特別針對每次切分時類別比例的一致性做設計。","C":"隨機交叉驗證的切分方式未考慮類別比例，在極度不平衡且樣本稀少的資料下，容易造成驗證折中陽性樣本分佈不均。","D":"官方答案。命題邏輯是「留一法=資料利用率最大化」加上「分層=維持類別比例」,同時對應題目給的兩個限制條件(樣本稀少、極度不平衡)。"},"note":"嚴格來說,留一法每一折的驗證集只有1筆樣本,折內根本無從維持類別比例,「分層留一法」也不是 scikit-learn 提供的標準做法(LeaveOneOut 不支援分層),且單筆驗證集無法計算 AUC 等指標。此情境實務上會採用 Stratified K-Fold 或 Repeated Stratified K-Fold。應試仍依官方答案選 D。"},"origin":"past"},{"id":"middle_114-2_s3_q35","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":35,"context":null,"stem":"某公司針對製程感測器資料進行主成分分析（PCA），經標準化與協方差矩陣分解後，得到三個主成分的特徵值如下：λ1=6.0, λ2=3.0, λ3=1.0。若團隊決定僅保留能解釋至少80%總變異量的主成分，以進行後續模型建構，下列哪一項敘述最合理且數據解讀正確？","options":{"A":"前兩個主成分合計解釋90%的總變異量，因此可安全降維至二維，且仍保留大部分資訊","B":"第一主成分解釋60%的變異量，表示資料結構呈現明顯線性關係，僅保留一維即可避免過擬合","C":"雖然前兩個主成分可解釋超過80%變異量，但第二主成分貢獻仍高達30%，不宜捨棄第三主成分","D":"三個特徵值相差不大，顯示各主成分變異均衡，降維可能導致資訊損失"},"answer":"A","figures":[],"explanation":{"approach":"三個特徵值總和為6+3+1=10。第一主成分解釋6/10=60%的變異，第二主成分解釋3/10=30%，兩者合計90%，已超過80%的門檻，因此保留前兩個主成分即可安全降維至二維，同時仍保留絕大部分的資訊量。","options":{"A":"正確答案。前兩主成分合計解釋60%+30%=90%的總變異量，已達成保留至少80%變異量的目標，可安全降維至二維並保留大部分資訊。","B":"第一主成分僅解釋60%的變異量，未達80%的門檻，若僅保留一維會損失過多資訊，「僅保留一維即可避免過擬合」的說法並不合理。","C":"前兩主成分合計已達90%，超過80%的既定門檻，依此決策原則第三主成分（僅貢獻10%）可以捨棄，此敘述與決策邏輯矛盾。","D":"三個特徵值6、3、1差異其實相當懸殊（相差6倍），並非「相差不大」，此敘述對數據的解讀有誤。"}},"origin":"past"},{"id":"middle_114-2_s3_q36","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":36,"context":null,"stem":"某銀行計畫與多家合作機構共同訓練一個AI信用風險預測模型，為避免客戶交易資料在傳輸與運算過程中外洩，技術團隊評估使用同態加密（Homomorphic Encryption）技術。下列何者最能正確描述同態加密在此應用中的關鍵特性？","options":{"A":"系統以隨機雜訊（Noise）干擾輸出，確保統計結果不洩漏個資","B":"各參與銀行透過安全通道交換私鑰，確保模型參數一致","C":"將原始資料壓縮並同時加密，以減少加密後資料量與運算時間","D":"資料在加密狀態下仍可進行數值運算，模型訓練可於未解密資料上完成"},"answer":"D","figures":[],"explanation":{"approach":"同態加密的核心特性是允許在資料保持加密狀態下直接進行數值運算（如加法、乘法），運算結果解密後與先對明文運算再加密的結果一致，因此可讓模型訓練在資料完全不被解密的情況下完成，達到保護原始資料隱私的目的。","options":{"A":"以隨機雜訊干擾輸出結果以保護個資，描述的是差分隱私（Differential Privacy）的機制，並非同態加密的特性。","B":"透過安全通道交換私鑰以確保模型參數一致，屬於金鑰交換與模型同步的議題，並非同態加密「可對密文直接運算」的核心特性。","C":"同態加密通常會使資料量與運算成本「增加」而非減少，此敘述與同態加密實際運算開銷的特性相反。","D":"正確答案。同態加密最核心的特性即是資料在加密狀態下仍可直接進行數值運算，使模型訓練得以在未解密的資料上完成。"}},"origin":"past"},{"id":"middle_114-2_s3_q37","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":37,"context":null,"stem":"某跨銀行風控平台希望整合多家銀行的用戶行為資料，用於訓練信用風險預測模型。由於競爭與法規限制，各銀行僅願意提供加密後資料，且資料在任何時間不得被平台解密。同時，平台需建立安全通訊協議以確保資料在傳輸過程未被竄改或重放。下列哪一組技術最能完整對應上述需求？","options":{"A":"對稱加密（Symmetric Encryption）＋單向雜湊（Hash Function）＋非對稱加密（Asymmetric Encryption）＋差分隱私（DifferentialPrivacy）","B":"同態加密（Homomorphic Encryption）＋非對稱加密（AsymmetricEncryption）＋單向雜湊（One-way Hash Function）＋對稱加密（Symmetric Encryption）","C":"差分隱私（Differential Privacy）＋對稱加密（SymmetricEncryption）＋同態加密（Homomorphic Encryption）＋數位簽章（Digital Signature）","D":"同態加密（Homomorphic Encryption）＋安全多方計算（SecureMulti-party Computation, MPC）＋雜湊函數（Hash Function）＋對稱加密（Symmetric Encryption）"},"answer":"B","figures":[],"explanation":{"approach":"情境需求有三:(1)資料全程加密、平台任何時候都不得解密即可運算 (2)多方共同建模 (3)通訊過程不得被竄改或重放。第一項是最硬的門檻——只有同態加密能在密文上直接運算,而B、C、D 三個選項都含同態加密,只有A沒有(A用差分隱私,那是加雜訊保護統計結果,不能取代密文運算),所以A可以先刪掉。剩下B、C、D 的取捨就沒那麼乾淨了:官方答案取B,理由是它把「密文運算＋金鑰交換與身分驗證＋完整性＋傳輸效率」四個面向都配了一個對應工具,是最像標準通訊協定的完整組合。但C與D也各有其合理處,且防重放這項需求四個選項都沒有真正對應的機制(詳見下方註記)。","options":{"A":"此組合以差分隱私取代同態加密，但差分隱私是透過加入雜訊保護統計結果隱私，並不能讓模型在完全不解密的密文上直接完成運算，未能滿足「不得被解密」的核心要求。","B":"官方答案,四個面向配置最均衡的組合:同態加密滿足「全程加密仍可運算」、非對稱加密處理金鑰交換與身分驗證、單向雜湊偵測資料是否變動、對稱加密提升大量資料的傳輸效率。要注意它在防竄改上其實比C弱——單向雜湊只有在雜湊值本身可信時才能偵測變動,主動攻擊者可把內容與雜湊一起重算;而且雜湊無法辨識同一份合法封包被重複送出,擋不了重放。","C":"此組合同樣包含同態加密,能滿足「全程加密仍可運算」;而且它的數位簽章在防竄改上比B的普通雜湊更直接有效(簽章同時提供完整性與來源驗證,攻擊者無法偽造)。它相對B的主要弱點在於少了通用的非對稱加密金鑰交換機制。至於差分隱私,它與同態加密是互補而非重複的技術(前者降低模型輸出或參數更新洩漏個體資訊的風險,後者保護運算過程中的資料),只是並非本題直接要求的機制、且有隱私與效用的取捨,不能單憑「多了差分隱私」就判定C較差。整體而言C是有相當合理性的選項,官方未採用。","D":"此組合以安全多方計算取代非對稱加密。MPC 其實相當契合本題「多家銀行共同訓練」的場景,同樣是有合理性的選項;但缺少非對稱加密的金鑰交換與身分驗證機制,在「建立安全通訊協定」這項需求上覆蓋度不如B,故官方答案未採用。"},"note":"此題選項設計不夠嚴謹,B、C、D 三者都有合理性:(1)選項C同樣含同態加密,且其數位簽章在防竄改上比官方答案B的普通雜湊更直接有效,C相對B的差別主要在少了通用金鑰交換機制,而非「多了差分隱私」(差分隱私與同態加密互補,只是非本題直接要求);(2)選項D的安全多方計算正是「多家銀行共同訓練」的典型技術。(3)另外題目要求防重放,但四個選項都沒有 nonce、序號或時戳,沒有任何一組真的做得到。密碼學上要防惡意竄改需要 MAC、數位簽章或 AEAD,一般單向雜湊只有在雜湊值本身可信(例如另以簽章保護)時才有效。應試時以「哪個組合把密文運算＋金鑰交換＋完整性＋傳輸效率四個面向配置得最均衡」判斷,選B。"},"origin":"past"},{"id":"middle_114-2_s3_q38","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":38,"context":null,"stem":"附圖程式碼所計算的是哪一類型的評估指標？","options":{"A":"MAE","B":"MSE","C":"RMSE","D":"R²"},"answer":"B","figures":[{"src":"images/middle_114-2_s3_q38_fig1.png","position":"stem"}],"explanation":{"approach":"附圖程式碼為 return sum((y_true - y_pred) ** 2) / len(y_true)，即先計算預測值與真實值差的平方，加總後除以樣本數，此為均方誤差（Mean Squared Error, MSE）的標準定義公式。","options":{"A":"MAE（平均絕對誤差）的計算應取誤差的「絕對值」而非「平方」，程式碼中使用的是平方運算，與MAE定義不符。","B":"正確答案。程式碼將誤差平方後加總並除以樣本數，正是MSE（均方誤差）的標準計算公式。","C":"RMSE需在MSE的基礎上再取平方根，但程式碼中並未有開根號的運算，因此不是RMSE。","D":"R²的計算公式涉及殘差平方和與總變異平方和的比值關係，與此程式碼單純計算誤差平方平均的邏輯完全不同。"}},"origin":"past"},{"id":"middle_114-2_s3_q39","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":39,"context":null,"stem":"附圖程式碼實現的是哪一種正則化技術？","options":{"A":"L1正則化","B":"L2正則化","C":"Dropout","D":"Batch Normalization"},"answer":"C","figures":[{"src":"images/middle_114-2_s3_q39_fig1.png","position":"stem"}],"explanation":{"approach":"附圖程式碼在訓練模式下，以np.random.binomial產生服從二項分布的隨機遮罩（mask），將輸入x與遮罩相乘後再除以保留機率p進行縮放，推論模式則直接輸出原始x，此為典型的Inverted Dropout實作方式。","options":{"A":"L1正則化是在損失函數中加入權重絕對值的懲罰項，屬於損失函數層級的設計，並非在前向傳播中對輸入進行隨機遮罩。","B":"L2正則化是在損失函數中加入權重平方的懲罰項，同樣屬於損失函數設計，與程式碼中對輸入進行隨機遮罩的機制不同。","C":"正確答案。程式碼利用二項分布隨機生成遮罩對輸入進行隨機丟棄，並以除以p的方式進行縮放，是典型的Dropout（Inverted Dropout）實作。","D":"Batch Normalization是利用批次資料的均值與變異數對激活值進行標準化，程式碼中並未計算均值變異數，而是進行隨機遮罩，兩者機制不同。"}},"origin":"past"},{"id":"middle_114-2_s3_q40","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":40,"context":null,"stem":"依據附圖程式碼進行資料處理，下列何者正確？","options":{"A":"np.linalg.inv(A)計算矩陣A的行列式","B":"v1 * v2結果為array([5, 7, 9])","C":"np.dot(v1, v2)結果為np.int64(32)","D":"np.linalg.eig(A)計算矩陣A的反矩陣"},"answer":"C","figures":[{"src":"images/middle_114-2_s3_q40_fig1.png","position":"stem"}],"explanation":{"approach":"附圖程式碼定義v1=[1,2,3]、v2=[4,5,6]，np.dot(v1, v2)計算的是向量內積，即1×4+2×5+3×6=4+10+18=32，結果型別為np.int64(32)。","options":{"A":"np.linalg.inv(A)計算的是矩陣A的「反矩陣」，而非行列式，行列式應使用np.linalg.det(A)計算，此敘述將兩者功能混淆。","B":"v1 * v2為元素對元素（element-wise）相乘，結果應為array([4, 10, 18])，而非[5, 7, 9]（[5,7,9]其實是v1+v2的結果）。","C":"正確答案。np.dot(v1, v2)計算向量內積，1×4+2×5+3×6=32，結果為np.int64(32)，與選項描述相符。","D":"np.linalg.eig(A)計算的是矩陣A的特徵值與特徵向量，而非反矩陣，此敘述將特徵分解與求反矩陣的功能混淆。"}},"origin":"past"},{"id":"middle_114-2_s3_q41","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":41,"context":null,"stem":"考慮擲出骰子並採用Monte Carlo方法估算條件機率，參考附圖程式碼。事件A：擲出偶數事件B：擲出大於3請問下列何者為條件機率P(A∣B)的正確值？","options":{"A":"A_and_B.sum() / (A.sum() * B.sum())","B":"A_and_B.sum() / (A.sum() + B.sum())","C":"A_and_B.sum() / A.sum()","D":"A_and_B.sum() / B.sum()"},"answer":"D","figures":[{"src":"images/middle_114-2_s3_q41_fig1.png","position":"stem"}],"explanation":{"approach":"條件機率公式為P(A|B) = P(A∩B) / P(B)，在蒙地卡羅模擬中以樣本比例估計機率，即以「同時滿足A且B的樣本數」除以「滿足B的樣本數」，對應程式寫法為A_and_B.sum() / B.sum()，故選項D為正確的條件機率P(A|B)計算方式。","options":{"A":"以A.sum()乘以B.sum()作為分母並非機率論中定義條件機率的方式，該公式沒有對應的統計意義。","B":"以A.sum()加B.sum()作為分母同樣不是條件機率的正確定義，機率的組合關係應以聯集或交集表示，而非直接相加事件次數作分母。","C":"A_and_B.sum() / A.sum()計算的其實是P(B|A)（在A發生條件下B發生的機率），條件顛倒，並非題目要求的P(A|B)。","D":"正確答案。依條件機率定義P(A|B)=P(A∩B)/P(B)，以樣本估計即為A_and_B.sum()/B.sum()，正確對應題目要求。"}},"origin":"past"},{"id":"middle_114-2_s3_q42","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":42,"context":{"text":"VGG16是由牛津大學Visual Geometry Group(VGG)在2014年提出的經典卷積神經網路（Convolutional Neural Network, CNN）架構。該模型以簡潔且規則的層堆疊設計聞名，廣泛應用於影像分類、特徵提取及遷移學習等任務。附圖程式碼載入了預訓練的VGG16模型，並輸出其完整層級結構及參數統計摘要（如附表）。請根據此資訊回答42~45題。\n----------------------------------------------------------------\nLayer (type) Output Shape Param #\n================================================================\nConv2d-1 [-1, 64, 150, 150] 1,792\nReLU-2 [-1, 64, 150, 150] 0\nConv2d-3 [-1, 64, 150, 150] 36,928\nReLU-4 [-1, 64, 150, 150] 0\nMaxPool2d-5 [-1, 64, 75, 75] 0\nConv2d-6 [-1, 128, 75, 75] 73,856\nReLU-7 [-1, 128, 75, 75] 0\nConv2d-8 [-1, 128, 75, 75] 147,584\nReLU-9 [-1, 128, 75, 75] 0\nMaxPool2d-10 [-1, 128, 37, 37] 0\nConv2d-11 [-1, 256, 37, 37] 295,168\nReLU-12 [-1, 256, 37, 37] 0\nConv2d-13 [-1, 256, 37, 37] 590,080\nReLU-14 [-1, 256, 37, 37] 0\nConv2d-15 [-1, 256, 37, 37] 590,080\nReLU-16 [-1, 256, 37, 37] 0\nMaxPool2d-17 [-1, 256, 18, 18] 0\nConv2d-18 [-1, 512, 18, 18] 1,180,160\nReLU-19 [-1, 512, 18, 18] 0\nConv2d-20 [-1, 512, 18, 18] 2,359,808\nReLU-21 [-1, 512, 18, 18] 0\nConv2d-22 [-1, 512, 18, 18] 2,359,808\nReLU-23 [-1, 512, 18, 18] 0\nMaxPool2d-24 [-1, 512, 9, 9] 0\nConv2d-25 [-1, 512, 9, 9] 2,359,808\nReLU-26 [-1, 512, 9, 9] 0\nConv2d-27 [-1, 512, 9, 9] 2,359,808\nReLU-28 [-1, 512, 9, 9] 0\nConv2d-29 [-1, 512, 9, 9] 2,359,808\nReLU-30 [-1, 512, 9, 9] 0\nMaxPool2d-31 [-1, 512, 4, 4] 0\nAdaptiveAvgPool2d-32 [-1, 512, 7, 7] 0\nLinear-33 [-1, 4096] 102,764,544\nReLU-34 [-1, 4096] 0\nDropout-35 [-1, 4096] 0\nLinear-36 [-1, 4096] 16,781,312\nReLU-37 [-1, 4096] 0\nDropout-38 [-1, 4096] 0\nLinear-39 [-1, 1000] 4,097,000\n================================================================\nTotal params: 138,357,544\nTrainable params: 138,357,544\nNon-trainable params: 0\n----------------------------------------------------------------\nInput size (MB): 0.26\nForward/backward pass size (MB): 96.93\nParams size (MB): 527.79\nEstimated Total Size (MB): 624.98\n----------------------------------------------------------------","figures":[]},"stem":"在深度神經網路中，不同層的參數量（parameter count）差異極大。有些層雖然數量少但計算量大，有些則相反。了解參數分佈情形，有助於模型壓縮與遷移學習設計。請問在VGG16中，下列何者的參數量最多？","options":{"A":"卷積層(Conv2d)","B":"全連接層(Linear)","C":"ReLU激活函數","D":"池化層(MaxPool2d, AdaptiveAvgPool2d)"},"answer":"B","figures":[],"explanation":{"approach":"由附表（VGG16模型摘要）可見，三個全連接層（Linear-33、Linear-36、Linear-39）的參數量分別為102,764,544、16,781,312、4,097,000，合計超過1.23億，遠高於所有卷積層參數量的總和，是VGG16中參數量最多的層別類型。","options":{"A":"所有卷積層（Conv2d）參數量加總約1,400多萬，雖然層數多，但單層參數規模遠小於全連接層，總量不及全連接層。","B":"正確答案。全連接層（尤其是Linear-33的一億零兩百多萬參數）在VGG16中佔了絕大部分的參數量，是參數量最多的層別。","C":"ReLU為單純的激活函數，不具有可學習的權重參數，附表中所有ReLU層的Param數皆為0。","D":"池化層（MaxPool2d、AdaptiveAvgPool2d）同樣不具有可學習權重，僅執行固定的取樣運算，附表中Param數皆為0。"}},"origin":"past"},{"id":"middle_114-2_s3_q43","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":43,"context":{"text":"VGG16是由牛津大學Visual Geometry Group(VGG)在2014年提出的經典卷積神經網路（Convolutional Neural Network, CNN）架構。該模型以簡潔且規則的層堆疊設計聞名，廣泛應用於影像分類、特徵提取及遷移學習等任務。附圖程式碼載入了預訓練的VGG16模型，並輸出其完整層級結構及參數統計摘要（如附表）。請根據此資訊回答42~45題。\n----------------------------------------------------------------\nLayer (type) Output Shape Param #\n================================================================\nConv2d-1 [-1, 64, 150, 150] 1,792\nReLU-2 [-1, 64, 150, 150] 0\nConv2d-3 [-1, 64, 150, 150] 36,928\nReLU-4 [-1, 64, 150, 150] 0\nMaxPool2d-5 [-1, 64, 75, 75] 0\nConv2d-6 [-1, 128, 75, 75] 73,856\nReLU-7 [-1, 128, 75, 75] 0\nConv2d-8 [-1, 128, 75, 75] 147,584\nReLU-9 [-1, 128, 75, 75] 0\nMaxPool2d-10 [-1, 128, 37, 37] 0\nConv2d-11 [-1, 256, 37, 37] 295,168\nReLU-12 [-1, 256, 37, 37] 0\nConv2d-13 [-1, 256, 37, 37] 590,080\nReLU-14 [-1, 256, 37, 37] 0\nConv2d-15 [-1, 256, 37, 37] 590,080\nReLU-16 [-1, 256, 37, 37] 0\nMaxPool2d-17 [-1, 256, 18, 18] 0\nConv2d-18 [-1, 512, 18, 18] 1,180,160\nReLU-19 [-1, 512, 18, 18] 0\nConv2d-20 [-1, 512, 18, 18] 2,359,808\nReLU-21 [-1, 512, 18, 18] 0\nConv2d-22 [-1, 512, 18, 18] 2,359,808\nReLU-23 [-1, 512, 18, 18] 0\nMaxPool2d-24 [-1, 512, 9, 9] 0\nConv2d-25 [-1, 512, 9, 9] 2,359,808\nReLU-26 [-1, 512, 9, 9] 0\nConv2d-27 [-1, 512, 9, 9] 2,359,808\nReLU-28 [-1, 512, 9, 9] 0\nConv2d-29 [-1, 512, 9, 9] 2,359,808\nReLU-30 [-1, 512, 9, 9] 0\nMaxPool2d-31 [-1, 512, 4, 4] 0\nAdaptiveAvgPool2d-32 [-1, 512, 7, 7] 0\nLinear-33 [-1, 4096] 102,764,544\nReLU-34 [-1, 4096] 0\nDropout-35 [-1, 4096] 0\nLinear-36 [-1, 4096] 16,781,312\nReLU-37 [-1, 4096] 0\nDropout-38 [-1, 4096] 0\nLinear-39 [-1, 1000] 4,097,000\n================================================================\nTotal params: 138,357,544\nTrainable params: 138,357,544\nNon-trainable params: 0\n----------------------------------------------------------------\nInput size (MB): 0.26\nForward/backward pass size (MB): 96.93\nParams size (MB): 527.79\nEstimated Total Size (MB): 624.98\n----------------------------------------------------------------","figures":[]},"stem":"在神經網路中，了解各層的運算量分佈，有助於模型壓縮與硬體加速的策略設計。請問在VGG16中，下列何者運算量(FLOPs)最多？","options":{"A":"卷積層(Conv2d)","B":"全連接層(Linear)","C":"ReLU激活函數","D":"池化層(MaxPool2d, AdaptiveAvgPool2d)"},"answer":"A","figures":[],"explanation":{"approach":"雖然卷積層的參數量遠少於全連接層，但由於卷積運算需在較大的空間特徵圖（如150×150、75×75等）上以滑動視窗方式對每個位置重複進行乘加運算，實際運算量（FLOPs）反而遠高於僅對已攤平向量做一次矩陣乘法的全連接層，因此VGG16中運算量最大的是卷積層。","options":{"A":"正確答案。卷積層需在大範圍的特徵圖空間上重複進行卷積運算，即使參數量較少，實際乘加運算次數（FLOPs）仍是VGG16中最高的。","B":"全連接層雖參數量最多，但只對已攤平的低維向量（如4096維）做一次矩陣乘法，運算量相較於在大尺寸特徵圖上滑動運算的卷積層小得多。","C":"ReLU僅對每個元素做一次簡單的比較（取最大值0），運算量遠低於卷積或全連接層的乘加運算，不會是運算量最高者。","D":"池化層僅進行取最大值或平均值等簡單運算，運算量遠低於卷積層的乘加運算，不會是運算量最高者。"}},"origin":"past"},{"id":"middle_114-2_s3_q44","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":44,"context":{"text":"VGG16是由牛津大學Visual Geometry Group(VGG)在2014年提出的經典卷積神經網路（Convolutional Neural Network, CNN）架構。該模型以簡潔且規則的層堆疊設計聞名，廣泛應用於影像分類、特徵提取及遷移學習等任務。附圖程式碼載入了預訓練的VGG16模型，並輸出其完整層級結構及參數統計摘要（如附表）。請根據此資訊回答42~45題。\n----------------------------------------------------------------\nLayer (type) Output Shape Param #\n================================================================\nConv2d-1 [-1, 64, 150, 150] 1,792\nReLU-2 [-1, 64, 150, 150] 0\nConv2d-3 [-1, 64, 150, 150] 36,928\nReLU-4 [-1, 64, 150, 150] 0\nMaxPool2d-5 [-1, 64, 75, 75] 0\nConv2d-6 [-1, 128, 75, 75] 73,856\nReLU-7 [-1, 128, 75, 75] 0\nConv2d-8 [-1, 128, 75, 75] 147,584\nReLU-9 [-1, 128, 75, 75] 0\nMaxPool2d-10 [-1, 128, 37, 37] 0\nConv2d-11 [-1, 256, 37, 37] 295,168\nReLU-12 [-1, 256, 37, 37] 0\nConv2d-13 [-1, 256, 37, 37] 590,080\nReLU-14 [-1, 256, 37, 37] 0\nConv2d-15 [-1, 256, 37, 37] 590,080\nReLU-16 [-1, 256, 37, 37] 0\nMaxPool2d-17 [-1, 256, 18, 18] 0\nConv2d-18 [-1, 512, 18, 18] 1,180,160\nReLU-19 [-1, 512, 18, 18] 0\nConv2d-20 [-1, 512, 18, 18] 2,359,808\nReLU-21 [-1, 512, 18, 18] 0\nConv2d-22 [-1, 512, 18, 18] 2,359,808\nReLU-23 [-1, 512, 18, 18] 0\nMaxPool2d-24 [-1, 512, 9, 9] 0\nConv2d-25 [-1, 512, 9, 9] 2,359,808\nReLU-26 [-1, 512, 9, 9] 0\nConv2d-27 [-1, 512, 9, 9] 2,359,808\nReLU-28 [-1, 512, 9, 9] 0\nConv2d-29 [-1, 512, 9, 9] 2,359,808\nReLU-30 [-1, 512, 9, 9] 0\nMaxPool2d-31 [-1, 512, 4, 4] 0\nAdaptiveAvgPool2d-32 [-1, 512, 7, 7] 0\nLinear-33 [-1, 4096] 102,764,544\nReLU-34 [-1, 4096] 0\nDropout-35 [-1, 4096] 0\nLinear-36 [-1, 4096] 16,781,312\nReLU-37 [-1, 4096] 0\nDropout-38 [-1, 4096] 0\nLinear-39 [-1, 1000] 4,097,000\n================================================================\nTotal params: 138,357,544\nTrainable params: 138,357,544\nNon-trainable params: 0\n----------------------------------------------------------------\nInput size (MB): 0.26\nForward/backward pass size (MB): 96.93\nParams size (MB): 527.79\nEstimated Total Size (MB): 624.98\n----------------------------------------------------------------","figures":[]},"stem":"VGG16層數深且結構規則，由多層卷積、池化及全連接層組成。了解各層的輸入/輸出維度、參數量及記憶體需求，有助於掌握CNN模型的組成邏輯與實作技巧。根據VGG16的模型架構，下列敘述何者正確？","options":{"A":"AdaptiveAvgPool2d的輸出會被攤平後傳入第一個全連接層；由於前一層池化輸出空間為4×4，所以第一個線性層的輸入維度是512×4×4 =8192","B":"Linear-33（第一個全連接層）報出的102,764,544參數只包含權重，偏差（bias）沒有算在內","C":"根據列出的「Estimated Total Size (MB) = 624.98」，表示訓練此模型只需大約625MB的GPU記憶體（包含所有optimizer state與梯度），所以一張1 GB的GPU就足夠訓練","D":"VGG16包含13層卷積層（conv）與3層全連接層（FC），總參數數目約為138,357,544（約138.36M）"},"answer":"D","figures":[],"explanation":{"approach":"依附表所示，VGG16由13層卷積層（Conv2d）搭配ReLU與池化層堆疊而成，末端接3層全連接層（Linear-33、Linear-36、Linear-39），附表底部亦明確列出Total params為138,357,544（約138.36M），此敘述與模型摘要完全相符。","options":{"A":"附表顯示AdaptiveAvgPool2d-32的輸出形狀為[-1, 512, 7, 7]，攤平後應為512×7×7=25,088維，而非512×4×4=8,192，此敘述的空間尺寸計算有誤。","B":"Linear-33層的102,764,544個參數，其計算方式為輸入維度25,088×輸出維度4,096再加上4,096個偏差項（25088×4096+4096=102,764,544），實際上已包含權重與偏差（bias），此敘述並不正確。","C":"附表中「Estimated Total Size」僅估算了輸入、參數與前向/反向傳播暫存的記憶體需求，並未包含Adam等優化器所需的額外動量緩衝區與其他訓練開銷，實際訓練所需GPU記憶體會遠高於625MB，「1GB GPU即足夠訓練」的推論並不成立。","D":"正確答案。VGG16確實由13層卷積層與3層全連接層組成，附表明確列出總參數量為138,357,544（約138.36M），此敘述與模型摘要完全一致。"}},"origin":"past"},{"id":"middle_114-2_s3_q45","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":45,"context":{"text":"VGG16是由牛津大學Visual Geometry Group(VGG)在2014年提出的經典卷積神經網路（Convolutional Neural Network, CNN）架構。該模型以簡潔且規則的層堆疊設計聞名，廣泛應用於影像分類、特徵提取及遷移學習等任務。附圖程式碼載入了預訓練的VGG16模型，並輸出其完整層級結構及參數統計摘要（如附表）。請根據此資訊回答42~45題。\n----------------------------------------------------------------\nLayer (type) Output Shape Param #\n================================================================\nConv2d-1 [-1, 64, 150, 150] 1,792\nReLU-2 [-1, 64, 150, 150] 0\nConv2d-3 [-1, 64, 150, 150] 36,928\nReLU-4 [-1, 64, 150, 150] 0\nMaxPool2d-5 [-1, 64, 75, 75] 0\nConv2d-6 [-1, 128, 75, 75] 73,856\nReLU-7 [-1, 128, 75, 75] 0\nConv2d-8 [-1, 128, 75, 75] 147,584\nReLU-9 [-1, 128, 75, 75] 0\nMaxPool2d-10 [-1, 128, 37, 37] 0\nConv2d-11 [-1, 256, 37, 37] 295,168\nReLU-12 [-1, 256, 37, 37] 0\nConv2d-13 [-1, 256, 37, 37] 590,080\nReLU-14 [-1, 256, 37, 37] 0\nConv2d-15 [-1, 256, 37, 37] 590,080\nReLU-16 [-1, 256, 37, 37] 0\nMaxPool2d-17 [-1, 256, 18, 18] 0\nConv2d-18 [-1, 512, 18, 18] 1,180,160\nReLU-19 [-1, 512, 18, 18] 0\nConv2d-20 [-1, 512, 18, 18] 2,359,808\nReLU-21 [-1, 512, 18, 18] 0\nConv2d-22 [-1, 512, 18, 18] 2,359,808\nReLU-23 [-1, 512, 18, 18] 0\nMaxPool2d-24 [-1, 512, 9, 9] 0\nConv2d-25 [-1, 512, 9, 9] 2,359,808\nReLU-26 [-1, 512, 9, 9] 0\nConv2d-27 [-1, 512, 9, 9] 2,359,808\nReLU-28 [-1, 512, 9, 9] 0\nConv2d-29 [-1, 512, 9, 9] 2,359,808\nReLU-30 [-1, 512, 9, 9] 0\nMaxPool2d-31 [-1, 512, 4, 4] 0\nAdaptiveAvgPool2d-32 [-1, 512, 7, 7] 0\nLinear-33 [-1, 4096] 102,764,544\nReLU-34 [-1, 4096] 0\nDropout-35 [-1, 4096] 0\nLinear-36 [-1, 4096] 16,781,312\nReLU-37 [-1, 4096] 0\nDropout-38 [-1, 4096] 0\nLinear-39 [-1, 1000] 4,097,000\n================================================================\nTotal params: 138,357,544\nTrainable params: 138,357,544\nNon-trainable params: 0\n----------------------------------------------------------------\nInput size (MB): 0.26\nForward/backward pass size (MB): 96.93\nParams size (MB): 527.79\nEstimated Total Size (MB): 624.98\n----------------------------------------------------------------","figures":[]},"stem":"在實務應用中，我們常使用遷移學習(transfer learning)技巧，即載入預訓練模型（如VGG16），凍結部分層的參數，只針對特定任務重新訓練最後幾層，這種做法可節省訓練時間並提升模型效能。假設你要對VGG16進行遷移學習(transfer learning)，希望凍結卷積層的參數，只訓練最後全連接層(classifier)。下列哪段程式碼寫法正確？","options":{"A":"","B":"","C":"","D":""},"answer":"B","figures":[{"src":"images/middle_114-2_s3_q45_fig1.png","position":"option:A"},{"src":"images/middle_114-2_s3_q45_fig2.png","position":"option:B"},{"src":"images/middle_114-2_s3_q45_fig3.png","position":"option:C"},{"src":"images/middle_114-2_s3_q45_fig4.png","position":"option:D"}],"explanation":{"approach":"遷移學習中若要凍結卷積層（特徵提取部分）、只訓練最後的全連接分類層，正確做法是遍歷model.features.parameters()（即卷積特徵提取部分的參數）並設定requires_grad=False，讓分類層（classifier）保持預設的requires_grad=True以便訓練。","options":{"A":"圖1程式碼遍歷model.parameters()（模型「全部」參數，含分類層），將所有參數的requires_grad都設為False，會導致連分類層也一併凍結，完全無法訓練，不符合題目「只訓練最後全連接層」的需求。","B":"正確答案。圖2程式碼僅遍歷model.features.parameters()（卷積特徵提取層的參數）並設為不可訓練，保留分類層（classifier）可訓練，正確對應「凍結卷積層、只訓練全連接層」的需求。","C":"圖3程式碼遍歷model.classifier.parameters()並凍結，凍結的對象恰好相反：凍結的是「全連接分類層」，而保留卷積層可訓練，與題目需求正好相反。","D":"圖4程式碼寫的是model.requires_grad = False，這只是在Module物件上新增一個無意義的屬性，並不會實際改變模型內部各個參數張量的requires_grad狀態，因此無法真正凍結任何一層，凍結機制本身是無效的。"}},"origin":"past"},{"id":"middle_114-2_s3_q46","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":46,"context":{"text":"在郵遞區號自動辨識的研究中，研究人員收集了一份手寫數字影像資料集，每一張影像為8×8的灰階圖片，共包含多個手寫數字樣本。這份資料集來自UCI Machine Learning Repository，常被用於數字辨識與機器學習方法的教學與實驗。\n在過程中，研究人員發現資料中可能存在雜訊，例如筆跡模糊或影像中附加的干擾點，這會影響後續分類模型的效能。因此，他們希望透過資料降噪的方法，提升後續分類的準確度。同時，他們也想透過KNN (K-Nearest Neighbors) 搭配交叉驗證來評估模型表現，確保模型在不同資料切割下都能有穩定的預測能力。\n部分樣本經繪製後的外觀如下圖所示：\n根據這份資料來回答46~47題。","figures":["images/middle_114-2_s3_q45_fig5.png","images/middle_114-2_s3_q45_fig6.png"]},"stem":"假設研究人員已將含有雜訊的手寫數字影像存放在變數noisy中。部分資料經視覺化後的外觀如下：他們嘗試使用PCA進行降噪，並希望能保留影像的主要特徵，同時去除影像中的雜訊。然而，當程式執行後，觀察到影像仍然含有明顯的雜訊。研究人員懷疑是程式中某個步驟的設定不正確，導致PCA沒有發揮降噪的作用，需要修改程式碼才能讓降噪有效。請問哪一段程式碼需要修改，才能讓PCA對noisy影像有效去噪？","options":{"A":"程式碼A","B":"程式碼B","C":"程式碼C","D":"程式碼D"},"answer":"B","figures":[{"src":"images/middle_114-2_s3_q46_fig1.png","position":"stem"},{"src":"images/middle_114-2_s3_q46_fig2.png","position":"stem"}],"explanation":{"approach":"附圖程式碼中，pca = PCA()未指定n_components，預設會保留與原始資料維度相同（或樣本數與特徵數較小值）的全部主成分，這種情況下transform後再inverse_transform幾乎能無損還原原始（含雜訊的）資料，等於沒有真正過濾掉雜訊。要讓PCA發揮降噪效果，必須在建立PCA物件時指定較小的n_components，僅保留能代表主要訊號、捨棄雜訊主導的低變異成分，因此需要修改的是「程式碼B」（pca = PCA()）。","options":{"A":"程式碼A僅為import PCA套件的陳述式，本身不影響降噪效果，不需修改。","B":"正確答案。程式碼B建立PCA物件時未限制n_components，導致保留全部主成分、資料重建後幾乎沒有濾除雜訊的效果，是需要修改之處，應改為指定較小的n_components。","C":"程式碼C僅是以noisy資料擬合PCA模型，此步驟本身沒有錯誤，降噪效果不佳的根源在於PCA物件建立時的成分數設定，而非fit步驟。","D":"程式碼D是將noisy資料投影到主成分空間，此轉換步驟本身沒有錯誤，其結果是否具降噪效果，取決於前面PCA物件所保留的成分數量設定。"}},"origin":"past"},{"id":"middle_114-2_s3_q47","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":47,"context":{"text":"在郵遞區號自動辨識的研究中，研究人員收集了一份手寫數字影像資料集，每一張影像為8×8的灰階圖片，共包含多個手寫數字樣本。這份資料集來自UCI Machine Learning Repository，常被用於數字辨識與機器學習方法的教學與實驗。\n在過程中，研究人員發現資料中可能存在雜訊，例如筆跡模糊或影像中附加的干擾點，這會影響後續分類模型的效能。因此，他們希望透過資料降噪的方法，提升後續分類的準確度。同時，他們也想透過KNN (K-Nearest Neighbors) 搭配交叉驗證來評估模型表現，確保模型在不同資料切割下都能有穩定的預測能力。\n部分樣本經繪製後的外觀如下圖所示：\n根據這份資料來回答46~47題。","figures":["images/middle_114-2_s3_q45_fig5.png","images/middle_114-2_s3_q45_fig6.png"]},"stem":"研究人員在對digits資料集進行分類時，決定使用KNN並搭配交叉驗證來評估模型準確率。他們撰寫了四組不同的程式碼來進行KNN訓練與交叉驗證，但不確定哪幾組程式碼能正確執行並輸出準確率。每組程式碼在資料切割、模型訓練、交叉驗證函數的使用上略有差異，研究人員希望找出可以正確完成任務的程式碼組合，以確保模型評估的可靠性。請問哪幾組程式碼能正確使用KNN搭配交叉驗證，對digits資料集進行訓練並輸出準確率？","options":{"A":"程式碼A、程式碼B、程式碼C、程式碼D","B":"程式碼A、程式碼C","C":"程式碼A、程式碼B","D":"程式碼C、程式碼D"},"answer":"B","figures":[{"src":"images/middle_114-2_s3_q47_fig1.png","position":"stem"},{"src":"images/middle_114-2_s3_q47_fig2.png","position":"stem"},{"src":"images/middle_114-2_s3_q47_fig3.png","position":"stem"},{"src":"images/middle_114-2_s3_q47_fig4.png","position":"stem"}],"explanation":{"approach":"四段程式碼的差別只在兩處:交叉驗證怎麼給(明寫 cv=StratifiedKFold(...) 或直接 cv=5),以及 scoring 用什麼。關鍵在 digits 是 0~9 的十類別資料集,scoring=\"f1\" 在多類別情況下必須指定 average(如 \"f1_macro\"),否則 scikit-learn 會直接拋出 ValueError。至於 cv=5,對分類器而言 scikit-learn 預設就會使用 StratifiedKFold,與明寫 StratifiedKFold 效果相同。因此能正確執行並輸出準確率的是程式碼A與程式碼C。","options":{"A":"錯誤。程式碼B與程式碼D都使用 scoring=\"f1\",在十類別的 digits 資料集上未指定 average 會報錯,四段不可能全部正確。","B":"正確答案。程式碼A明寫 StratifiedKFold(n_splits=5, shuffle=True) 搭配 scoring=\"accuracy\";程式碼C使用 cv=5(對分類器預設即為 StratifiedKFold)搭配 scoring=\"accuracy\",兩者都能正常輸出平均準確率。","C":"錯誤。程式碼A可以執行,但程式碼B雖然分層設定正確,scoring=\"f1\" 在多類別下未指定 average 仍會拋出 ValueError。","D":"錯誤。程式碼C可以執行,但程式碼D同樣踩到多類別 scoring=\"f1\" 未指定 average 的錯誤。"}},"origin":"past"},{"id":"middle_114-2_s3_q48","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":48,"context":{"text":"使用鐵達尼號(Titanic)資料集進行多層感知機(Multilayer Perceptron, MLP)分類預測分析，其中survived為反應變數(1表示存活，0表示死亡)。附圖程式碼展示資料載入與處理，請根據此資料回答第48~50題。\n下圖顯示資料集的前5筆資料。","figures":["images/middle_114-2_s3_ctx5_fig1.png","images/middle_114-2_s3_ctx5_fig2.png","images/middle_114-2_s3_ctx5_fig3.png"]},"stem":"參考下圖程式碼，下列何者正確？A：X_train -= X_train.mean(axis=0)將每個訓練集特徵的平均值調整為0B：X_train /= X_train.std(axis=0)將每個訓練集特徵的標準差調整為0C：X_train處理結果會將資料壓縮到0和1之間D：標準化結果防止梯度爆炸或消失E：標準化是屬於特徵選擇(Feature Selection)方法F：X_train程式碼應修正為X_train = X_train.std(axis=0), X_test程式碼應修正為X_test = X_test.std(axis=0)","options":{"A":"A、B、C、D","B":"A、E","C":"A、D","D":"A、C、F"},"answer":"C","figures":[{"src":"images/middle_114-2_s3_q48_fig1.png","position":"stem"}],"explanation":{"approach":"附圖程式碼依序對X_train、X_test執行「減去平均值、除以標準差」的標準化（Standardization）處理。逐一檢視題幹中的敘述：A（訓練集各特徵平均值調整為0）正確；B（除以標準差會使標準差變為0）錯誤，應為變成1；C（結果會被壓縮到0與1之間）錯誤，那是Min-Max正規化的特性而非標準化；D（標準化有助防止梯度爆炸或消失）為標準化常見且合理的效益，正確；E（標準化屬於特徵選擇方法）錯誤，標準化是特徵縮放而非挑選特徵；F所提出的修正方式在邏輯上並不成立。故正確敘述為A與D，對應答案C。","options":{"A":"此選項包含B、C、D四項，但B（除以標準差使標準差變為0）與C（壓縮至0~1之間）皆為錯誤敘述，此組合並不成立。","B":"此選項包含A、E，其中E主張標準化屬於特徵選擇方法，但標準化是調整數值尺度的特徵縮放技術，並非挑選特徵的方法，此組合不正確。","C":"正確答案。A敘述（訓練集特徵平均值調整為0）與D敘述（標準化有助防止梯度爆炸或消失）皆為正確描述，符合附圖程式碼的處理效果。","D":"此選項包含A、C、F，但C（結果壓縮至0與1之間）是Min-Max正規化的特性、並非標準化的效果，F所提之程式碼修正方式也不合理，此組合不正確。"}},"origin":"past"},{"id":"middle_114-2_s3_q49","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":49,"context":{"text":"使用鐵達尼號(Titanic)資料集進行多層感知機(Multilayer Perceptron, MLP)分類預測分析，其中survived為反應變數(1表示存活，0表示死亡)。附圖程式碼展示資料載入與處理，請根據此資料回答第48~50題。\n下圖顯示資料集的前5筆資料。","figures":["images/middle_114-2_s3_ctx5_fig1.png","images/middle_114-2_s3_ctx5_fig2.png","images/middle_114-2_s3_ctx5_fig3.png"]},"stem":"參考下圖執行結果，下列何者正確？","options":{"A":"activation=\"relu\"其數學式為","B":"空格1值為110，空格2值為100","C":"空格1值為100，空格2值為110","D":"activation=\"sigmoid\"一般用於多類別分類預測模型"},"answer":"C","figures":[{"src":"images/middle_114-2_s3_q49_fig1.png","position":"stem"}],"explanation":{"approach":"模型架構為Dense(10, relu)→Dense(10, relu)→Dense(1, sigmoid)。第二個隱藏層dense_1接收前一層10個輸出，參數量固定為10×10+10=110（與輸入特徵數無關）；已知輸出層dense_2參數為11（10×1+1），可反推第一層dense的參數量為輸入特徵數×10+10。依官方答案空格1=100、空格2=110，可反推輸入特徵數為9（9×10+10=100），與Titanic資料集常見前處理後的特徵數量相符。","options":{"A":"圖中所附之數學式（形如1/(1+e^-x)）其實是Sigmoid函數的公式，而非ReLU的定義（ReLU應為f(x)=max(0,x)），選項將此公式誤植為activation=\"relu\"的數學式，敘述有誤。","B":"依模型架構反推，第一層dense（空格1）的參數量應為100，第二層dense_1（空格2）應為110，此選項的數值恰好相反，因此不正確。","C":"正確答案。dense_1層固定接收10個輸入，參數量為10×10+10=110；dense層參數量則為輸入特徵數×10+10，依此反推空格1為100、空格2為110，與官方答案相符。","D":"Sigmoid函數輸出介於0與1之間、常用於「二元分類」的輸出層（如本題survived存活與否的預測），而非用於多類別分類（多類別通常使用Softmax），此敘述描述錯誤。"}},"origin":"past"},{"id":"middle_114-2_s3_q50","level":"middle","session":"114-2","subject":3,"subject_name":"機器學習技術與應用","number":50,"context":{"text":"使用鐵達尼號(Titanic)資料集進行多層感知機(Multilayer Perceptron, MLP)分類預測分析，其中survived為反應變數(1表示存活，0表示死亡)。附圖程式碼展示資料載入與處理，請根據此資料回答第48~50題。\n下圖顯示資料集的前5筆資料。","figures":["images/middle_114-2_s3_ctx5_fig1.png","images/middle_114-2_s3_ctx5_fig2.png","images/middle_114-2_s3_ctx5_fig3.png"]},"stem":"參考下圖執行結果，下列何者正確？A：空格1須填入\"b-\"B：空格2須填入\"b--\"C：空格1須填入\"r-\"D：空格2須填入\"r--\"E：驗證損失明顯較訓練損失減少更明顯","options":{"A":"B、C","B":"A、C、D","C":"A、D","D":"C、D、E"},"answer":"C","figures":[{"src":"images/middle_114-2_s3_q50_fig1.png","position":"stem"},{"src":"images/middle_114-2_s3_q50_fig2.png","position":"stem"}],"explanation":{"approach":"附圖程式碼繪製訓練損失（Training Loss）與驗證損失（Validation Loss）的雙曲線比較圖。依繪圖慣例，通常以實線代表訓練損失、虛線代表驗證損失，並以不同顏色區分兩條曲線；依官方答案，空格1（訓練損失樣式）應填入\"b-\"（藍色實線），空格2（驗證損失樣式）應填入\"r--\"（紅色虛線），使兩條曲線在顏色與線型上皆能清楚區別。","options":{"A":"此選項對應敘述B、C，即空格2為\"b--\"、空格1為\"r-\"，與官方認定的空格1=\"b-\"、空格2=\"r--\"顏色配置相反，不正確。","B":"此選項對應敘述A、C、D，其中C（空格1為\"r-\"）與官方答案空格1應為\"b-\"矛盾，同一空格被賦予兩種不同數值，內部邏輯即不一致，不正確。","C":"正確答案。對應敘述A（空格1為\"b-\"）與D（空格2為\"r--\"），即訓練損失以藍色實線、驗證損失以紅色虛線繪製，是常見且清楚區分兩條曲線的繪圖慣例，符合官方答案。","D":"此選項包含敘述C、D、E，其中C（空格1為\"r-\"）與官方答案的空格1=\"b-\"矛盾；且E主張驗證損失比訓練損失下降更明顯，若模型訓練正常，訓練損失通常會較穩定持續下降，驗證損失反而較易受雜訊影響而波動，此敘述並不合理。"}},"origin":"past"},{"id":"middle_115-1_s1_q01","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":1,"context":null,"stem":"某工程師正在建置一套法律文件解析系統，在進行資訊擷取（InformationExtraction）前，需要對文本進行詞性標註（Part-of-Speech Tagging, POS Tagging）。請問此步驟的主要目的為何？","options":{"A":"將文本翻譯為其他語言以利跨語言分析","B":"將文本切分為基本詞彙單位，以便後續處理","C":"判斷文本中各詞彙的情感傾向","D":"為每個詞彙標記其語法類別，如名詞、動詞與形容詞"},"answer":"D","figures":[],"explanation":{"approach":"詞性標註（POS Tagging）是為文本中每個詞彙標記其語法類別（如名詞、動詞、形容詞），屬於NLP前處理步驟，能為後續句法分析與資訊擷取提供依據。","options":{"A":"錯誤，將文本轉換為其他語言是機器翻譯的任務，與詞性標註無關","B":"錯誤，將文本切分為基本詞彙單位是斷詞（Tokenization），並非詞性標註的目的","C":"錯誤，判斷詞彙情感傾向屬於情感分析（Sentiment Analysis）任務，非POS Tagging","D":"正確，POS Tagging的核心目的就是為每個詞彙標記其語法類別，供後續句法與語意分析使用"}},"origin":"past"},{"id":"middle_115-1_s1_q02","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":2,"context":null,"stem":"一家新創公司希望對Llama3 70B模型進行領域微調（Domain Fine-Tuning）以建立企業專用助理，但GPU記憶體有限，無法支撐完整模型的反向傳播梯度計算。工程師希望凍結（freeze）原模型權重、僅訓練少量額外參數的前提下，評估採用LoRA（Low-Rank Adaptation）方案。請問LoRA在此場景下的主要優勢為何？","options":{"A":"透過知識蒸餾（Knowledge Distillation）將70B模型壓縮為較小的學生模型","B":"對原始模型各層權重進行剪枝（Pruning），移除低重要性參數後再進行微調","C":"凍結原始預訓練權重，僅在各層加入低秩分解的可訓練矩陣，大幅降低可訓練參數量與GPU記憶體需求","D":"將模型中的注意力機制改為稀疏注意力（Sparse Attention），以降低長序列計算成本"},"answer":"C","figures":[],"explanation":{"approach":"LoRA凍結原始預訓練權重，只在各層插入低秩分解的可訓練矩陣，大幅降低可訓練參數量與所需的GPU記憶體，適合在資源有限情況下對大型模型進行領域微調。","options":{"A":"錯誤，這是知識蒸餾（Knowledge Distillation）的做法，屬於模型壓縮技術，並非LoRA的原理","B":"錯誤，這是剪枝（Pruning）的做法，透過移除低重要性參數壓縮模型，與LoRA的低秩分解機制不同","C":"正確，LoRA凍結原模型權重、僅訓練新增的低秩矩陣，因此能大幅降低可訓練參數量與記憶體需求","D":"錯誤，這是稀疏注意力（Sparse Attention）的做法，用於降低長序列計算成本，與LoRA無關"}},"origin":"past"},{"id":"middle_115-1_s1_q03","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":3,"context":null,"stem":"某工程師在建構搜尋引擎的詞向量模型時，語料庫規模達數十億token，且包含大量長尾詞彙（Long-tail Terms）。他在Word2Vec的CBOW與Skip-gram兩種訓練策略之間進行選擇，需考量訓練效率與低頻詞表示品質之差異。下列何者最能準確地反映兩者在此情境下的取捨？","options":{"A":"CBOW對長尾詞表現更好，因為它透過多個上下文詞的平均來強化稀疏詞的訓練訊號","B":"CBOW訓練速度較快、整體語意平滑，但對低頻詞的向量品質較差；Skip-gram以中心詞預測周圍詞，對長尾詞累積更多訓練樣本，向量品質較優","C":"Skip-gram訓練速度更快，因為每次只需預測單一目標詞，計算量低於CBOW","D":"兩者對低頻詞的表現完全相同，差異僅在於訓練時的Batch組織方式"},"answer":"B","figures":[],"explanation":{"approach":"CBOW以多個上下文詞的平均來預測中心詞，訓練速度較快但會稀釋低頻詞的訓練訊號；Skip-gram以中心詞預測周圍多個詞，能為長尾詞產生更多訓練樣本，因此低頻詞向量品質通常較佳，兩者在效率與品質上互有取捨。","options":{"A":"錯誤，CBOW對上下文詞取平均反而會稀釋稀疏詞的訓練訊號，使其對長尾詞表現較差，而非更好","B":"正確，準確反映CBOW速度快但低頻詞品質較差、Skip-gram速度較慢但低頻詞品質較優的取捨關係","C":"錯誤，Skip-gram每次需為中心詞預測多個上下文詞，計算量通常大於CBOW，訓練速度較慢而非更快","D":"錯誤，兩者對低頻詞的表現有明顯差異，差異源自模型結構本身而非batch組織方式"}},"origin":"past"},{"id":"middle_115-1_s1_q04","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":4,"context":null,"stem":"某金融科技公司的工程師正在準備內部客服對話與交易紀錄文本，進行BERT模型的預訓練，以提升模型對金融語境的理解能力，並採用遮蔽語言建模（MaskedLanguage Model, MLM）作為訓練任務。請問MLM的核心訓練目標為何？","options":{"A":"讓模型自左至右逐token生成句子，學習自迴歸語言模型（Autoregressive LM）能力","B":"透過對抗訓練（Adversarial Training）縮小真實句與生成句之間的語意差異","C":"隨機遮蔽輸入序列中部分token，訓練模型根據雙向上下文預測被遮蔽的原始內容","D":"透過遮蔽低頻詞來減少詞彙表大小，降低Embedding的記憶體使用"},"answer":"C","figures":[],"explanation":{"approach":"MLM隨機遮蔽輸入序列中部分token，訓練模型利用雙向（左右兩側）上下文預測被遮蔽的原始內容，使BERT能學習到雙向語境表示，這與GPT等自迴歸模型的單向生成方式不同。","options":{"A":"錯誤，自左至右逐token生成句子是自迴歸語言模型（如GPT）的訓練方式，並非MLM","B":"錯誤，MLM並非透過對抗訓練縮小真實句與生成句的差異，這不是其核心機制","C":"正確，MLM的核心即是隨機遮蔽部分token，訓練模型根據雙向上下文預測被遮蔽的原始內容","D":"錯誤，MLM的目的是學習雙向語境表示，並非為了遮蔽低頻詞以縮小詞彙表或節省記憶體"}},"origin":"past"},{"id":"middle_115-1_s1_q05","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":5,"context":null,"stem":"某電商平台的工程師在開發商品評論情感分析系統時，發現使用One-Hot編碼無法表達詞語之間的語意關係，且隨著詞彙表擴大，向量維度與記憶體需求快速增加。工程師因此改用Word2Vec進行詞語表示。請問Word2Vec從根本上解決了上述問題的哪項限制？","options":{"A":"建立詞語之間的序列依賴關係，以捕捉長距離上下文語意","B":"根據詞語在語料中的出現頻率調整其重要性，使模型更重視高頻詞","C":"降低詞彙表示的維度，同時保留語意結構，避免高維稀疏表示所帶來的限制","D":"透過監督式學習利用標註語料，提升詞語分類的準確性"},"answer":"C","figures":[],"explanation":{"approach":"One-Hot編碼維度隨詞彙表擴大而線性增加，且各向量彼此正交無法表達語意關係；Word2Vec將詞映射至低維稠密向量空間，同時保留語意結構，從根本上解決高維稀疏表示的維度與語意限制。","options":{"A":"錯誤，Word2Vec主要透過局部上下文共現學習詞向量，並非用來建立長距離序列依賴關係（那較接近RNN／Transformer的能力）","B":"錯誤，Word2Vec並非依出現頻率調整詞的重要性使模型更重視高頻詞，其負採樣機制反而是為了平衡高頻詞的過度影響","C":"正確，Word2Vec將詞表示降至低維稠密向量，同時保留語意結構，解決了One-Hot高維稀疏表示的限制","D":"錯誤，Word2Vec是透過上下文預測進行自監督學習，並非依賴標註語料的監督式學習"}},"origin":"past"},{"id":"middle_115-1_s1_q06","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":6,"context":null,"stem":"某自駕車感知系統需要在同一張影像中同時完成道路、建築、行人的逐像素分類，並且能夠區分畫面中兩名相鄰行人（標記為「行人#1」和「行人#2」）。工程師在選擇語義分割（Semantic Segmentation）與實例分割（Instance Segmentation）時，請問兩者的根本差異為何？","options":{"A":"實例分割對每個像素進行分類但不產生Bounding Box；語義分割產生Bounding Box但不進行像素級標記","B":"實例分割僅用於影像層級的類別分類，語義分割才進行逐像素標記","C":"語義分割將每個像素分配至預定義類別，但同一類別內的不同個體無法區分；實例分割能對同一類別的不同物件（如兩名行人）分別建立獨立遮罩（Mask）","D":"語義分割與實例分割皆為逐像素分類任務，但兩者在是否需要區分不同物件個體上並無差異"},"answer":"C","figures":[],"explanation":{"approach":"語義分割將每個像素分類至預定義類別，但同一類別內的不同個體無法區分；實例分割則能對同一類別中的不同物件（如兩名行人）分別建立獨立遮罩，兩者根本差異在於是否能區分同類別的不同個體。","options":{"A":"錯誤，敘述完全對調，且兩者皆非以Bounding Box為主要輸出形式，與實際定義不符","B":"錯誤，敘述對調，實例分割才是能逐像素標記並區分個體，語義分割才是像素級分類但不分個體","C":"正確，準確描述語義分割不分個體、實例分割能為同類別不同物件分別建立獨立遮罩的根本差異","D":"錯誤，兩者在是否需要區分不同物件個體上有本質差異，並非「無差異」"}},"origin":"past"},{"id":"middle_115-1_s1_q07","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":7,"context":null,"stem":"某大型超市的防損系統需要即時偵測多名顧客各自手持的購物籃、手機與商品，並需對每個物件進行精確區域標記（Pixel-level Mask），同時能區分畫面中不同個體（即使不同顧客拿著相同商品，也需分別標記）。請問下列哪一項技術最適合此場景的需求？","options":{"A":"影像分類（Image Classification）","B":"目標檢測（Object Detection）","C":"實例分割（Instance Segmentation）","D":"語義分割（Semantic Segmentation）"},"answer":"C","figures":[],"explanation":{"approach":"場景需求為精確的pixel-level mask，且即使是相同商品也需區分不同顧客持有的個體，這正是實例分割（Instance Segmentation）的定義：結合像素級標記與個體級區分能力。","options":{"A":"錯誤，影像分類僅能對整張影像給出單一類別標籤，無法提供像素級標記或區分個體","B":"錯誤，目標檢測僅提供Bounding Box與類別標籤，無法提供pixel-level mask","C":"正確，實例分割能提供pixel-level mask，且能區分同類別中不同的物件個體，最符合需求","D":"錯誤，語義分割僅做像素級分類，無法區分同一類別中的不同個體（如不同顧客手持的相同商品）"}},"origin":"past"},{"id":"middle_115-1_s1_q08","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":8,"context":null,"stem":"某工程師訓練了一個皮膚病變二元分類模型（惡性/良性），在向臨床醫師報告模型效能時，使用ROC曲線（Receiver Operating Characteristic Curve）進行呈現。請問ROC曲線的橫軸（X軸）與縱軸（Y軸）分別代表哪些指標，且在醫療情境中代表哪一種意義？","options":{"A":"X軸為準確率（Accuracy），Y軸為召回率（Recall），表示模型整體分類正確比例與偵測能力","B":"X軸為假陽率（False Positive Rate, FPR），Y軸為真陽率（True Positive Rate,TPR），反映誤診健康個體的風險與正確識別病患的能力","C":"X軸為精確率（Precision），Y軸為召回率（Recall），表示預測為陽性樣本的準確性與完整性","D":"X軸為IoU閾值，Y軸為mAP，反映物件偵測模型在不同重疊條件下的表現"},"answer":"B","figures":[],"explanation":{"approach":"ROC曲線的X軸為False Positive Rate（FPR）、Y軸為True Positive Rate（TPR）。在醫療情境中，FPR反映將健康個體誤判為病患（誤診）的風險，TPR反映正確識別出真正病患的能力，兩者共同呈現模型在不同判斷閾值下的權衡表現。","options":{"A":"錯誤，ROC曲線的兩軸為FPR與TPR，並非Accuracy與Recall","B":"正確，X軸為FPR、Y軸為TPR，分別對應誤診健康個體的風險與正確識別病患的能力","C":"錯誤，X軸Precision、Y軸Recall是Precision-Recall曲線的定義，並非ROC曲線","D":"錯誤，X軸IoU閾值、Y軸mAP是物件偵測評估常用的曲線，與ROC曲線無關"}},"origin":"past"},{"id":"middle_115-1_s1_q09","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":9,"context":null,"stem":"某團隊在監控影像分類模型的線上效能時，透過儀表板呈現混淆矩陣（ConfusionMatrix），以觀察模型預測結果與實際標籤的分佈情形。請問下列哪一項無法從混淆矩陣中直接計算？","options":{"A":"精確率（Precision）","B":"準確率（Accuracy）","C":"召回率（Recall）","D":"ROC曲線下面積（AUC）"},"answer":"D","figures":[],"explanation":{"approach":"混淆矩陣僅包含在單一決策閾值下的TP／FP／TN／FN計數，可直接計算Precision、Recall、Accuracy；但AUC需要模型在不同閾值下的多組TPR與FPR資料（即完整機率分數），單一混淆矩陣無法提供這些資訊，因此無法直接計算AUC。","options":{"A":"錯誤，Precision可由TP／(TP+FP)直接由混淆矩陣計算得出","B":"錯誤，Accuracy可由(TP+TN)／總樣本數直接由混淆矩陣計算得出","C":"錯誤，Recall可由TP／(TP+FN)直接由混淆矩陣計算得出","D":"正確，AUC需要模型在不同判斷閾值下的多組TPR/FPR資料，單一混淆矩陣（單一閾值）無法直接計算"}},"origin":"past"},{"id":"middle_115-1_s1_q10","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":10,"context":null,"stem":"某工廠導入即時影像瑕疵偵測系統，需在高頻影像流中進行快速推論。工程師在YOLO與Faster R-CNN兩種物件偵測架構之間進行評估，請問下列哪一個針對兩者在偵測流程設計上的差異最為正確？","options":{"A":"YOLO採用單階段偵測，直接從整張影像預測物件位置與類別；Faster R-CNN則先產生候選區域再進行分類","B":"YOLO與Faster R-CNN皆採用兩階段流程，但在特徵擷取方式上有所不同","C":"YOLO採用單階段架構，主要透過增加候選區域數量來提升偵測準確率","D":"Faster R-CNN採用單階段偵測方式，將物件定位與分類整合於同一模型中"},"answer":"A","figures":[],"explanation":{"approach":"YOLO採用單階段（one-stage）架構，直接從整張影像預測物件的位置與類別；Faster R-CNN採用兩階段（two-stage）架構，先透過RPN產生候選區域，再對候選區域進行分類與精修，因此YOLO推論速度通常較快，適合即時應用。","options":{"A":"正確，準確描述YOLO單階段直接預測、Faster R-CNN先產生候選區域再分類的流程差異","B":"錯誤，YOLO是單階段架構，並非兩階段，兩者流程本質不同而非僅特徵擷取方式不同","C":"錯誤，YOLO並非透過增加候選區域數量提升準確率，它根本不採用候選區域機制","D":"錯誤，Faster R-CNN是兩階段偵測架構，並非單階段，此敘述與實際相反"}},"origin":"past"},{"id":"middle_115-1_s1_q11","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":11,"context":null,"stem":"某工程師在分析Transformer架構時，發現自注意力機制（Self-Attention）能夠有效提升模型對序列中長距離依賴關係的建模能力。請問Self-Attention的核心功能為何？","options":{"A":"透過隱藏狀態的遞迴傳遞，逐步累積序列中的上下文資訊","B":"讓序列中每個token能與其他所有token建立關聯，並根據重要性分配權重","C":"對輸入序列進行局部運算，以捕捉相鄰詞之間的關係","D":"將整個序列壓縮為固定長度表示，以提供後續任務使用"},"answer":"B","figures":[],"explanation":{"approach":"Self-Attention讓序列中每個token都能與其他所有token直接建立關聯，並透過Query-Key-Value機制依重要性分配權重，因此能有效捕捉長距離依賴關係，不受序列位置距離的限制。","options":{"A":"錯誤，這是RNN透過隱藏狀態遞迴傳遞來累積上下文的方式，並非self-attention的機制","B":"正確，self-attention讓每個token都能與序列中所有其他token建立關聯，並依重要性分配權重","C":"錯誤，self-attention並非僅做局部運算，而是能捕捉全域（整個序列範圍）的關聯","D":"錯誤，將整個序列壓縮為固定長度表示是傳統Seq2Seq/RNN encoder的做法，非self-attention核心功能"}},"origin":"past"},{"id":"middle_115-1_s1_q12","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":12,"context":null,"stem":"某工程師在設計一個二元分類器（Binary Classifier）時，考慮在輸出層使用Sigmoid函數。請問Sigmoid函數的主要特性與限制為何？","options":{"A":"可將輸入轉換為任意實數範圍，適合用於迴歸任務","B":"可將輸入壓縮至(0, 1)區間，可解釋為機率值，但在輸入值過大或過小時可能產生梯度消失問題","C":"可將輸入轉換為多類別機率分布，常用於多分類任務","D":"可在整個輸入範圍內梯度保持穩定，適合用於深層神經網路"},"answer":"B","figures":[],"explanation":{"approach":"Sigmoid函數可將輸入壓縮至(0,1)區間，可解釋為機率值，適合二元分類輸出層；但當輸入值過大或過小時，其梯度會趨近於0，深層網路容易產生梯度消失（vanishing gradient）問題。","options":{"A":"錯誤，Sigmoid輸出範圍限定在(0,1)，並非任意實數範圍，不適合直接用於迴歸任務","B":"正確，準確描述Sigmoid的輸出區間、機率解釋，以及極端輸入下的梯度消失限制","C":"錯誤，將輸入轉換為多類別機率分布是Softmax的功能，並非Sigmoid","D":"錯誤，Sigmoid在極端輸入時梯度會趨近於0而非保持穩定，這正是其主要缺點"}},"origin":"past"},{"id":"middle_115-1_s1_q13","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":13,"context":null,"stem":"某公司評估兩種方案，將大型語言模型客製化為內部客服助理：方案A為提示微調（Prompt Tuning），在輸入端加入可學習的軟提示（Soft Prompt）；方案B為傳統微調（Fine-Tuning），以標註問答資料調整模型。兩方案最本質的技術差異為何？","options":{"A":"提示微調主要用於降低推論延遲，而傳統微調則用於提升模型容量","B":"兩者技術本質相同，差別僅在於學習率（Learning Rate）設定不同","C":"傳統微調通常需要更新模型參數，而提示微調主要透過調整輸入表示來影響模型行為","D":"提示微調與傳統微調的差異僅在於是否使用預訓練模型"},"answer":"C","figures":[],"explanation":{"approach":"傳統微調需要更新模型本身的權重參數；提示微調則凍結模型權重，僅在輸入端學習一組可訓練的soft prompt向量來引導模型行為，兩者最本質的差異在於是否更新模型參數本身。","options":{"A":"錯誤，兩者的差異並非以降低延遲或提升模型容量為劃分依據，而在於是否更新模型參數","B":"錯誤，兩者是技術路徑本質不同的方法，並非僅學習率設定不同","C":"正確，準確指出傳統微調更新模型參數、提示微調透過調整輸入表示影響模型行為的本質差異","D":"錯誤，兩種方法通常都是基於預訓練模型進行，差異不在是否使用預訓練模型"}},"origin":"past"},{"id":"middle_115-1_s1_q14","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":14,"context":null,"stem":"某工程師計劃將通用LLM在醫療問答語料上進行監督微調（Supervised Fine-Tuning, SFT），但發生了災難性遺忘（Catastrophic Forgetting）問題。在計算資源有限的情況下，工程師希望透過調整微調策略來緩解此問題。下列哪一種訓練設計最能有效率地學習新任務的同時保留原有能力？","options":{"A":"凍結大部分預訓練參數，僅對少量新增模組（如LoRA層）進行微調，並控制更新範圍以減少對原有知識的干擾","B":"提高學習率（Learning Rate）並縮短訓練步數，使模型快速收斂至新任務，避免長時間訓練造成遺忘","C":"僅使用醫療語料進行多輪訓練，強化模型對新任務的專注程度","D":"增加批次大小（Batch Size）以穩定梯度更新，使模型同時保留舊知識與學習新知識"},"answer":"A","figures":[],"explanation":{"approach":"凍結大部分預訓練參數、僅對少量新增模組（如LoRA層）進行微調，能將更新範圍限制在小範圍參數上，減少對原有知識的干擾，在有限計算資源下有效緩解災難性遺忘、同時學習新任務。","options":{"A":"正確，凍結大部分參數並僅微調少量新增模組，能以低成本控制更新範圍、減少對原有知識的干擾","B":"錯誤，提高學習率並縮短訓練步數容易使模型對新任務過擬合，且無法保證保留原有能力，反而可能加劇遺忘","C":"錯誤，僅用醫療語料多輪訓練會讓模型過度專注新任務，覆蓋原有通用知識，加重災難性遺忘","D":"錯誤，增加批次大小主要影響梯度更新的穩定性，並非緩解災難性遺忘的有效手段，無法確保同時保留舊知識"}},"origin":"past"},{"id":"middle_115-1_s1_q15","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":15,"context":null,"stem":"某企業建置一套多代理人（Multi-Agent）系統，由一個Orchestrator Agent負責任務分配，多個Worker Agent分別執行網路搜尋、程式撰寫與結果彙整。若Orchestrator發現某Worker Agent回傳結果品質不符合預期，從系統容錯與任務可靠性角度，下列哪一項機制最能確保整體任務仍能正確完成？","options":{"A":"直接採用該Worker Agent的輸出，避免重試機制造成延遲","B":"Orchestrator具備結果評估能力，對不合格結果觸發重試（Retry）或重新分配給不同Worker，並記錄失敗原因供後續改善","C":"強制所有Worker Agent統一使用相同的LLM模型，以減少輸出差異","D":"當任何一個Worker失敗時，整個Multi-Agent任務直接中止並通知使用者重新啟動"},"answer":"B","figures":[],"explanation":{"approach":"從系統容錯與任務可靠性角度，Orchestrator應具備評估Worker輸出品質的能力，對不合格結果觸發重試或重新分配給其他Worker，並記錄失敗原因供後續改善，才能在部分Worker表現不佳時仍確保整體任務正確完成。","options":{"A":"錯誤，直接採用品質不符的輸出會犧牲結果正確性，無法確保整體任務可靠完成","B":"正確，具備結果評估能力並對不合格結果重試或轉派，同時記錄失敗原因，是確保容錯與可靠性的核心機制","C":"錯誤，強制統一LLM模型與容錯機制無直接關聯，無法解決個別結果品質不符的問題","D":"錯誤，任一Worker失敗就整體中止任務過於僵化，會犧牲系統的可用性與容錯能力"}},"origin":"past"},{"id":"middle_115-1_s1_q16","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":16,"context":null,"stem":"一位工程師正在實作一個ReAct框架的AI Agent，該Agent需要回答「台灣目前最大的電動車充電站營運商是哪間公司，以及其充電樁總數」。Agent的工具清單如下：•web_search(query)：回傳搜尋結果摘要•get_webpage(url)：回傳網頁內文•calculator(expression)：回傳計算結果•get_current_date()：回傳今日日期工程師設計了以下的System Prompt與ReAct Loop，請問此Agent設計存在哪些問題？應如何改善？[System Prompt]你是一個資料查詢助理。每次只能使用一個工具。當你知道答案時，直接輸出最終答案。[第一輪Agent輸出]Thought:我已經知道台灣電動車市場的概況，不需要搜尋，可以直接回答。Action:無Answer:台灣最大充電站營運商是XX公司，共有500個充電樁。","options":{"A":"System Prompt未要求Agent在回答前使用工具驗證，導致直接依賴既有知識產生幻覺（Hallucination）；應明確規定即時性問題需先執行web_search","B":"工具清單提供了calculator與get_current_date，屬於多餘工具，可能增加Agent的選擇複雜度","C":"ReAct框架的核心問題在於Thought步驟佔用過多token，應移除Thought欄位，直接讓Agent輸出Action，以提升推理效率","D":"Agent應在第一輪就呼叫所有可用工具並彙整結果，避免多輪Loop造成的延遲"},"answer":"A","figures":[],"explanation":{"approach":"此Agent面對需要即時查證的問題時，未使用任何工具驗證便直接依賴模型既有知識作答，屬於典型的幻覺（Hallucination）風險。System Prompt應明確要求對即時性或事實性問題先呼叫web_search等工具驗證後再作答，才能避免此類問題。","options":{"A":"正確，System Prompt未要求先以工具驗證即時性問題，導致Agent僅依賴既有知識產生幻覺，應明確規定先執行搜尋","B":"錯誤，calculator與get_current_date並非本案例失敗的原因，提供多樣工具本身不必然造成問題，且與此題無關","C":"錯誤，Thought步驟是ReAct框架讓模型進行推理與決策的核心機制，移除它會降低Agent決策品質，並非解方","D":"錯誤，一次呼叫所有工具並非ReAct的設計精神，也非必要，且不是此案例失敗的根源（根源是完全未呼叫任何工具）"}},"origin":"past"},{"id":"middle_115-1_s1_q17","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":17,"context":null,"stem":"某醫療新創公司正在開發一套「多模態患者風險評估系統」，需同時處理三種異質資料來源：胸腔X光影像（影像模態）、臨床診斷筆記（文字模態），以及心率與血氧的時序感測資料（數值時序模態）。工程師在進行各模態的特徵擷取模型選擇時，需為每種模態挑選最適合的模型架構。下列哪一組模型配置最符合三種模態各自的資料特性？","options":{"A":"影像模態用LSTM、文字模態用CNN、時序模態用BERT","B":"影像模態用TF-IDF、文字模態用ResNet、時序模態用Word2Vec","C":"三種模態統一使用BERT，因為Transformer架構具備通用性，可處理任意形式的輸入資料","D":"影像模態用CNN、文字模態用Transformer、時序模態用LSTM或TemporalCNN"},"answer":"D","figures":[],"explanation":{"approach":"不同模態應搭配最適合其資料結構的模型：影像適合以CNN擷取空間特徵，文字適合以Transformer處理語意與長距依賴，時序數值資料適合以LSTM或Temporal CNN捕捉時間動態，此組合最符合三種模態各自的資料特性。","options":{"A":"錯誤，LSTM用於影像、CNN用於文字、BERT用於時序，模型與模態特性完全錯置","B":"錯誤，TF-IDF用於影像、ResNet用於文字、Word2Vec用於時序，同樣錯置，且TF-IDF與Word2Vec無法有效處理影像或時序數值資料","C":"錯誤，雖然Transformer具通用性，但直接以BERT處理原始影像與時序訊號並非最適合的做法，忽略了各模態的資料結構特性","D":"正確，影像用CNN、文字用Transformer、時序用LSTM或Temporal CNN，最符合三種模態各自的資料特性"}},"origin":"past"},{"id":"middle_115-1_s1_q18","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":18,"context":null,"stem":"某醫院的AI研究團隊正在開發一套整合「CT影像+電子病歷文本+基因序列」三種模態資料的癌症預測模型。請問在此場景中採用「跨模態對齊（Cross-ModalAlignment）」技術主要解決什麼問題？","options":{"A":"使模型僅聚焦於CT影像資料，避免文本與基因資料引入雜訊","B":"自動生成跨模態配對標註，以減少人工標記需求","C":"降低多模態資料的儲存與計算成本，以提升訓練效率","D":"將不同模態的資料表示對齊至共同語意空間，使模型能建立跨模態之間的語意關聯"},"answer":"D","figures":[],"explanation":{"approach":"跨模態對齊（Cross-Modal Alignment）的目的是將不同模態（影像、文字、基因序列）的特徵表示映射至共同的語意空間，使模型能建立跨模態之間的語意關聯，進而支援多模態融合預測。","options":{"A":"錯誤，跨模態對齊的目的並非排除其他模態或使模型僅聚焦單一模態，而是整合多模態資訊","B":"錯誤，自動生成跨模態配對標註並非跨模態對齊技術本身的核心目的","C":"錯誤，跨模態對齊著重於語意空間的一致性建立，並非以降低儲存與計算成本為主要目的","D":"正確，跨模態對齊的核心是將不同模態表示對齊至共同語意空間，使模型能建立跨模態語意關聯"}},"origin":"past"},{"id":"middle_115-1_s1_q19","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":19,"context":null,"stem":"一家電商公司已將推薦系統AI模型上線三個月，業務主管要求專案團隊評估導入成效。團隊根據下圖數據得出結論：「因為AUC高達0.91，模型表現優異，AI導入成效良好。」請問此評估結論存在什麼根本問題？","options":{"A":"僅依賴離線指標AUC判斷模型成效，忽略線上業務指標（如CTR與營收）的變化，可能導致錯誤結論","B":"AUC已達0.91，代表模型排序能力優異，即使CTR略為下降，仍可視為推薦品質提升","C":"CTR從3.2%降至3.1%，顯示模型效果變差，應立即還原（Rollback）至舊模型","D":"平均訂單金額提升至$1,020，代表模型已成功優化營收，因此無需考慮其他指標"},"answer":"A","figures":[{"src":"images/middle_115-1_s1_q19_fig1.png","position":"stem"}],"explanation":{"approach":"圖表顯示雖然離線AUC達0.91，但線上業務指標CTR從3.2%降至3.1%，顯示僅憑離線指標判斷模型成效良好，忽略了實際線上業務指標（如CTR、營收品質）的變化，可能導致與實際成效不符的錯誤結論。","options":{"A":"正確，僅依賴離線指標AUC判斷成效、忽略CTR等線上業務指標的下降，可能導致錯誤結論，應同時檢視線上業務指標","B":"錯誤，CTR下降代表推薦點擊效果實際變差，不能因AUC高就忽視此負面訊號，此結論與資料矛盾","C":"錯誤，CTR僅小幅下降0.1個百分點，且平均訂單金額明顯提升，尚不足以斷定「應立即rollback」，結論過於武斷","D":"錯誤，平均訂單金額提升可能受其他因素（如同期促銷）影響，不能僅憑此單一指標斷定成效良好而忽略CTR下降"}},"origin":"past"},{"id":"middle_115-1_s1_q20","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":20,"context":null,"stem":"某電商公司計畫導入即時推薦系統，希望使用者進入網站後能在100毫秒內取得推薦結果，且推薦結果需依據最新使用者行為進行調整。系統需支援每日約50萬活躍使用者，尖峰時段每秒約3,000筆請求（QPS）。目前公司已累積歷史購買紀錄與瀏覽行為資料，並持續接收即時點擊流（Streaming Data）。IT基礎架構採用雲端環境，團隊配置為2名資料工程師與1名機器學習工程師。某工程師提出以下導入規劃：(1)使用批次訓練（Batch Training）建立協同過濾模型(2)將模型部署為REST API提供即時推論服務(3)使用Kafka串流處理即時使用者行為特徵(4)將所有即時資料先寫入資料倉儲（Data Warehouse）再進行特徵計算(5)使用Redis或Feature Store快取即時特徵請問以下哪一項最合理的技術導入規劃組合與調整建議？","options":{"A":"保留(1)(2)(3)，移除(4)，並加入(5)以降低延遲","B":"保留(1)(4)，移除(3)，以確保資料一致性與系統穩定","C":"保留(2)(4)(5)，移除(1)，改用即時線上學習（Online Learning）","D":"全部保留(1)~(5)，可同時兼顧即時性與資料完整性"},"answer":"A","figures":[],"explanation":{"approach":"系統需求為低延遲（100ms）且需即時反映使用者行為，應保留批次訓練建立基礎模型(1)、以REST API提供推論(2)、以Kafka處理即時特徵串流(3)，並用Redis或Feature Store快取即時特徵(5)以降低延遲；若即時資料須先寫入Data Warehouse再計算特徵(4)，會因批次ETL延遲而無法滿足100ms需求，故應移除。","options":{"A":"正確，保留(1)(2)(3)並移除(4)、加入(5)，能兼顧模型基礎、即時串流特徵處理與低延遲快取需求","B":"錯誤，移除(3)等於捨棄即時串流特徵處理，模型將無法依最新使用者行為即時調整，不符合即時性需求","C":"錯誤，以現有僅3人團隊貿然改為全面即時線上學習，技術複雜度與維運成本過高，並非合理的第一階段規劃","D":"錯誤，保留(4)會使即時特徵計算經過資料倉儲的批次流程，增加延遲，無法滿足100毫秒的即時性需求"}},"origin":"past"},{"id":"middle_115-1_s1_q21","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":21,"context":null,"stem":"一位機器學習工程師正在優化公司內部的RAG法律文件問答系統。近期因營運成本壓力，公司要求在不更換模型且不影響回答品質的前提下，將整體token成本降低至目前的60%，且目前成本主要集中於輸入tokens。工程師在檢查系統後，盤點出目前的使用情況如下：◆使用模型：GPT-4o（輸入$5／1M tokens、輸出$15／1M tokens）◆每次查詢：將前10筆檢索文件區塊全部加入Prompt（每塊約600 tokens）◆System Prompt：每次請求均包含約500tokens的公司背景說明◆對話機制：保留完整對話歷史，平均累積約8,000tokens◆每日查詢量：約5,000次◆平均輸出：約300tokens／次在上述限制與系統現況下，請問下列哪一項優化組合，最能在維持回答品質的前提下有效降低token成本？","options":{"A":"將輸出max_tokens從1,000壓縮至200，強制模型給出更短的回答，以降低輸出費用","B":"將System Prompt改為Prompt Caching或靜態前綴重用，並對對話歷史實作摘要壓縮，以保留語意而非完整對話","C":"將所有查詢改為Batch API模式送出，透過非同步處理降低單次費用","D":"在Prompt中明確要求模型「回答時盡量簡短」，透過指令引導模型自行縮減輸出長度"},"answer":"B","figures":[],"explanation":{"approach":"成本主要集中於輸入tokens（重複的System Prompt與累積的對話歷史），因此應優先以Prompt Caching或靜態前綴重用降低System Prompt的重複成本，並對長對話歷史進行摘要壓縮以縮減輸入token量，同時盡量保留語意完整性以維持回答品質。","options":{"A":"錯誤，題目指出成本主要集中於輸入tokens，僅壓縮輸出長度對整體成本影響有限，且可能犧牲回答的完整性與品質","B":"正確，透過Prompt Caching重用固定前綴並對對話歷史做摘要壓縮，能有效降低輸入token成本同時保留語意品質","C":"錯誤，Batch API適合非即時、可延遲回應的場景，不適合法律問答系統這類需要即時回覆的情境，也未解決輸入token量過大的問題","D":"錯誤，僅以自然語言指令要求模型簡短回答，效果不穩定且無法保證，也未解決輸入端（System Prompt/對話歷史）token過大的根本問題"}},"origin":"past"},{"id":"middle_115-1_s1_q22","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":22,"context":null,"stem":"某金融科技公司計劃建立完整的AI開發到維運流程，希望實現「模型訓練→測試→部署→監控→再訓練」的自動化流程串接，並確保線上模型的版本可追溯。技術主管建議引入MLOps框架。MLOps在此AI開發生命週期中的核心角色為何？","options":{"A":"專注於訓練資料的標註與品質控管，以提升模型訓練效果","B":"透過自動化模型搜尋與參數調整，降低模型開發門檻","C":"建立機器學習流程的自動化與版本管理機制，支援模型部署、監控與持續更新","D":"確保模型在部署後維持穩定效能，減少後續維運與更新需求"},"answer":"C","figures":[],"explanation":{"approach":"MLOps的核心角色是建立機器學習生命週期（訓練、測試、部署、監控、再訓練）的自動化流程與版本管理機制，確保模型可追溯、可重現，並支援模型的持續部署、監控與更新。","options":{"A":"錯誤，訓練資料的標註與品質控管屬於資料工程/資料治理範疇，並非MLOps的核心定義","B":"錯誤，自動化模型搜尋與參數調整屬於AutoML/超參數優化（HPO）範疇，並非MLOps的核心角色","C":"正確，MLOps的核心是建立機器學習流程的自動化與版本管理機制，支援部署、監控與持續更新","D":"錯誤，此描述僅聚焦於部署後穩定效能的結果，未涵蓋MLOps完整的自動化流程與版本追溯核心能力，過於片面"}},"origin":"past"},{"id":"middle_115-1_s1_q23","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":23,"context":null,"stem":"某製造業公司計劃將AI導入生產線瑕疵檢測流程，目前瑕疵樣本約800張（含各類瑕疵類型）、正常樣本約15,000張，現有IT基礎設施為地端伺服器且無GPU，且生產線環境需於地端即時完成推論，檢測需求為每片零件須在100毫秒內完成檢測，且預算為中等、無法於短期內大規模採購硬體。工程師正在規劃第一階段的AI導入方案，請問下列哪一種規劃最為合適？","options":{"A":"從零訓練一個大型CNN模型，並採購高階GPU伺服器以滿足推論速度需求","B":"採用預訓練模型進行Transfer Learning，針對瑕疵樣本進行Fine-tuning，並使用模型量化（Quantization）或蒸餾（Distillation）技術壓縮模型以符合延遲需求，部署於地端","C":"因樣本數不足，建議先暫緩AI導入，待蒐集至少10萬筆瑕疵樣本後再啟動專案","D":"將所有影像上傳至雲端，使用第三方AutoML平台自動訓練並部署，以節省開發時間"},"answer":"B","figures":[],"explanation":{"approach":"樣本量有限（僅800張瑕疵樣本）、地端無GPU、需低延遲（100ms）、預算中等且無法短期大規模採購硬體，應採用預訓練模型進行遷移學習（Transfer Learning）微調以緩解資料不足問題，並以模型量化或蒸餾壓縮模型以在地端環境滿足延遲需求，是最務實可行的第一階段方案。","options":{"A":"錯誤，從零訓練大型CNN需要大量資料與運算資源，且需採購高階GPU，不符合題目預算與硬體限制","B":"正確，透過遷移學習緩解樣本不足問題，並以量化或蒸餾壓縮模型以滿足地端低延遲需求，最符合題目所有限制條件","C":"錯誤，暫緩導入等待10萬筆樣本不符合「第一階段快速導入」的實務需求，遷移學習本可在少量樣本下有效運作，無需等待大量資料","D":"錯誤，題目要求於地端即時完成推論，將影像上傳雲端會產生網路延遲並違反地端即時推論的限制，也可能有資料外流疑慮"}},"origin":"past"},{"id":"middle_115-1_s1_q24","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":24,"context":null,"stem":"某即時詐欺偵測系統對模型回應時間有嚴格限制，若推論延遲過高將影響交易核准流程。維運工程師在模型上線前進行延遲測試（Latency Testing）時，主要評估的目標為何？","options":{"A":"評估模型推論過程中的記憶體使用量，以確認部署資源是否足夠","B":"驗證模型對異常或攻擊輸入的穩定性與安全性","C":"評估模型在不同使用者族群上的預測結果是否一致","D":"評估模型從接收輸入到產生預測結果所需的回應時間是否符合系統要求"},"answer":"D","figures":[],"explanation":{"approach":"延遲測試（Latency Testing）主要評估模型從接收輸入到產生預測結果所需的回應時間，確認是否符合系統對即時性（如交易核准流程）的嚴格要求。","options":{"A":"錯誤，記憶體使用量屬於資源／容量測試範疇，並非延遲測試的主要評估目標","B":"錯誤，對異常或攻擊輸入的穩定性與安全性屬於健壯性（Robustness）／對抗測試範疇","C":"錯誤，不同使用者族群預測結果一致性屬於公平性（Fairness）測試範疇","D":"正確，延遲測試主要評估模型從接收輸入到產生預測結果所需的回應時間是否符合系統要求"}},"origin":"past"},{"id":"middle_115-1_s1_q25","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":25,"context":null,"stem":"某企業欲將其AI輔助決策系統提交給外部稽核單位審查，並宣稱符合NIST《AI風險管理框架》（NIST AI RMF）中可驗證性（Verifiability）的要求。為讓第三方稽核人員能獨立重現模型評估結果，下列哪一項技術實踐最直接符合此要求？","options":{"A":"將模型測試準確率優化至99%以上，以達到業界公認的高可靠標準","B":"建立可追溯的測試資料與評估流程，並記錄模型訓練與評估過程中的關鍵設定，以確保結果可被重現","C":"加快模型迭代速度，縮短版本發布週期以盡快累積外部驗證數據","D":"擴充訓練資料量至數百萬筆，以統計方式確保模型的泛化能力達標"},"answer":"B","figures":[],"explanation":{"approach":"可驗證性（Verifiability）要求第三方能獨立重現模型評估結果，因此應建立可追溯的測試資料與評估流程，並記錄訓練與評估過程中的關鍵設定（如版本、超參數、資料集），使結果能被外部稽核人員重現與驗證。","options":{"A":"錯誤，提升準確率與「可被第三方獨立重現驗證」並無直接關聯，準確率高不代表評估過程透明可追溯","B":"正確，建立可追溯的測試資料與評估流程並記錄關鍵設定，才能讓第三方稽核人員獨立重現模型評估結果","C":"錯誤，加快模型迭代速度縮短發布週期與可驗證性無關，甚至可能因記錄不完整而降低可重現性","D":"錯誤，擴充訓練資料量是提升泛化能力的手段，並非確保稽核人員能獨立重現評估結果的作法"}},"origin":"past"},{"id":"middle_115-1_s1_q26","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":26,"context":null,"stem":"某銀行導入一套AI授信審核系統，針對貸款申請人進行自動化決策。監理單位要求系統必須符合負責任AI（Responsible AI）原則，特別是對被拒絕的申請人提供每筆決策的具體理由說明。從技術與合規的角度，此要求的核心能力需求為何？","options":{"A":"系統必須在收到申請後10秒內自動刪除申請人個資","B":"系統應隨機調整部分決策以確保多元性","C":"系統必須保證所有決策準確率達到100%","D":"系統必須具備可解釋性（Explainability）能力，能提供特徵貢獻說明"},"answer":"D","figures":[],"explanation":{"approach":"對被拒絕的申請人提供具體決策理由，核心技術需求是系統須具備可解釋性（Explainability）能力，能提供特徵貢獻度等說明，使決策過程透明可追溯，符合負責任AI原則與監理合規要求。","options":{"A":"錯誤，自動刪除個資屬於資料保護／隱私範疇，與「提供具體決策理由說明」的要求無關","B":"錯誤，隨機調整部分決策違反決策一致性與公平性原則，並非合規要求，也無法提供理由說明","C":"錯誤，100%準確率不可能達成，且與「提供每筆決策理由」的可解釋性需求無直接關聯","D":"正確，系統須具備可解釋性能力、提供特徵貢獻說明，才能為被拒絕的申請人給出具體決策理由"}},"origin":"past"},{"id":"middle_115-1_s1_q27","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":27,"context":null,"stem":"某醫院計劃導入一套AI醫療影像診斷輔助系統，用於輔助放射科醫師判讀CT影像。院方技術委員會討論在人命攸關且需確保最終臨床決策責任由人類承擔的情境下，從系統設計架構層面，最關鍵的安全機制為何？","options":{"A":"採用人機協作（Human-in-the-Loop, HITL）架構，由醫師最終審核決策","B":"模型信心低於閾值（Threshold）即自動關機","C":"隨機切換模型並以多數決決策","D":"對輸入影像加入隨機擾動"},"answer":"A","figures":[],"explanation":{"approach":"在人命攸關且需由人類承擔最終臨床決策責任的情境下，系統設計應採用人機協作（Human-in-the-Loop, HITL）架構，AI僅提供輔助判讀建議，最終診斷決策仍由醫師審核確認，以確保責任歸屬與病患安全。","options":{"A":"正確，HITL架構讓醫師最終審核決策，確保臨床決策責任由人類承擔，是最關鍵的安全機制設計","B":"錯誤，信心低於閾值即自動關機無法確保「由人類承擔最終決策」，反而可能中斷必要的輔助判讀功能","C":"錯誤，隨機切換模型並以多數決決策缺乏穩定性與可控性，也未涉及人類最終審核確認機制","D":"錯誤，對輸入影像加入隨機擾動通常用於對抗測試或資料增強，與確保人類最終決策責任無關"}},"origin":"past"},{"id":"middle_115-1_s1_q28","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":28,"context":null,"stem":"一位資料科學家使用XGBoost建立信用風險評分模型，並使用SHAP解釋模型對某申請人的預測結果。SHAP summary plot顯示該樣本中「月收入」的SHAP值為-2.3，「負債比率」為+1.8，其中SHAP值代表各特徵對模型輸出值的影響程度與方向。關於對SHAP值的解讀，下列敘述何者正確？","options":{"A":"「月收入」的SHAP值-2.3代表該特徵使此申請人的違約預測機率降低了2.3%","B":"「月收入」的SHAP值-2.3代表相對於基準值（base value），此特徵將模型輸出值往負方向推移了2.3個單位，表示月收入對該申請人有降低違約風險的貢獻","C":"SHAP值為負代表該特徵對模型整體來說是不重要的特徵，應考慮從模型中移除","D":"負債比率」SHAP值+1.8代表負債比率是整個訓練集中對違約影響最大的特徵"},"answer":"B","figures":[],"explanation":{"approach":"SHAP值代表相對於基準值（base value），各特徵將模型輸出值往正或負方向推移的貢獻量。「月收入」SHAP值-2.3代表此特徵使模型輸出往負方向（降低違約風險預測）推移2.3個單位，而非直接等於機率變化的百分比。","options":{"A":"錯誤，SHAP值是對模型輸出值（如log-odds或原始分數）的貢獻量，不能直接解讀為違約機率下降的百分比","B":"正確，SHAP值-2.3代表相對於基準值，月收入將模型輸出往負方向推移2.3個單位，顯示對降低違約風險有貢獻","C":"錯誤，SHAP值為負只代表該特徵將輸出往負方向推移，並非代表其不重要，重要性應以絕對值大小判斷","D":"錯誤，單一樣本的SHAP值僅反映該筆樣本的貢獻，不能代表該特徵在整個訓練集中的整體重要性排名"}},"origin":"past"},{"id":"middle_115-1_s1_q29","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":29,"context":null,"stem":"某工程師為一套卷積神經網路（CNN）的醫療影像輔助診斷系統設計模型可解釋性機制。該系統需滿足下列需求：1.能向醫師說明影像被判定為異常的原因2.支援近即時推論，每次解釋須於200毫秒內完成，且不可進行大量重複採樣計算3.解釋結果須以影像中具代表性的視覺化像素區域呈現在此情境下，下列何種方法最為適合？","options":{"A":"使用LIME，透過超像素擾動取樣分析影像區塊對預測的影響","B":"使用SHAP KernelExplainer，計算各像素的Shapley值並疊加於原始影像","C":"使用Grad-CAM（Class Activation Map），透過梯度反向傳播生成類別關注區域","D":"使用SHAP TreeExplainer，計算特徵貢獻並以熱力圖呈現"},"answer":"C","figures":[],"explanation":{"approach":"需求為近即時（200ms內完成）、不可進行大量重複採樣、且以視覺化像素區域呈現，Grad-CAM僅需一次反向傳播梯度即可生成類別關注熱區圖，運算成本低、速度快，最符合此情境的需求。","options":{"A":"錯誤，LIME需要透過大量超像素擾動取樣分析，運算成本高，難以在200ms內完成","B":"錯誤，SHAP KernelExplainer需大量取樣計算Shapley值，運算成本極高，不符合近即時且不可大量取樣的限制","C":"正確，Grad-CAM僅需一次梯度反向傳播即可生成類別關注區域熱力圖，符合近即時、不需大量採樣的需求","D":"錯誤，SHAP TreeExplainer適用於樹模型（如XGBoost），並不適用於CNN這類深度學習影像模型"}},"origin":"past"},{"id":"middle_115-1_s1_q30","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":30,"context":null,"stem":"某資料科學家正在處理一份包含200個感測器特徵的工廠設備監測資料集，為了降低模型複雜度並保留主要變異資訊，他先對資料進行標準化（Standardization），再使用主成分分析（PCA）進行降維。在PCA過程中，為了找出能最大化資料變異量的主成分方向，演算法主要依賴哪一項數學操作？","options":{"A":"透過對目標函數進行梯度下降（Gradient Descent）最佳化，迭代求得主成分方向","B":"根據特徵與目標變數之間的相關性（Correlation）進行排序，選擇重要特徵","C":"對資料的協方差矩陣（Covariance Matrix）進行特徵值分解（EigenDecomposition），取得對應主要變異方向的特徵向量","D":"對資料矩陣進行卷積運算（Convolution），擷取特徵之間的局部關係"},"answer":"C","figures":[],"explanation":{"approach":"PCA為找出能最大化資料變異量的主成分方向，核心是對資料的共變異數矩陣（Covariance Matrix）進行特徵值分解（Eigen Decomposition），取得對應主要變異方向的特徵向量與特徵值。","options":{"A":"錯誤，傳統PCA是透過共變異數矩陣的特徵值分解（或奇異值分解）求解，並非以梯度下降迭代最佳化","B":"錯誤，PCA是非監督式方法，不依賴與目標變數的相關性排序，那屬於監督式特徵選擇（如filter method）的做法","C":"正確，PCA依賴對共變異數矩陣進行特徵值分解，取得對應主要變異方向的特徵向量作為主成分","D":"錯誤，卷積運算用於擷取局部空間特徵（如CNN），並非PCA降維所依賴的數學操作"}},"origin":"past"},{"id":"middle_115-1_s1_q31","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":31,"context":null,"stem":"某資料工程師嘗試對包含300個特徵的使用者行為資料集使用DBSCAN進行群集分析，但發現幾乎所有資料點都被判定為雜訊點（Noise Points），難以形成有意義的群集，即使不斷調整ε（Epsilon）與MinPts參數也無濟於事。請問下列何者為此問題最可能的根本原因？","options":{"A":"在高維空間中，維度詛咒（Curse of Dimensionality）使得資料點之間的距離趨於相近，導致DBSCAN的密度估計失效","B":"DBSCAN演算法僅適用於低維資料，無法處理高維資料","C":"300個特徵的資料必然不具備群集結構，因此無法進行有效的分群","D":"高維空間中核心點的數量會受到數學限制，導致無法形成群集"},"answer":"A","figures":[],"explanation":{"approach":"在高維空間（300個特徵）中，維度詛咒（Curse of Dimensionality）會使資料點間的距離度量趨於相近、失去區辨力，導致DBSCAN依賴的密度估計（基於ε鄰域的距離判斷）失效，即使調整參數也難以形成有意義的群集。","options":{"A":"正確，高維空間中維度詛咒使距離趨於相近，導致DBSCAN的密度估計失效，是此問題最可能的根本原因","B":"錯誤，DBSCAN並非「僅適用於低維資料而完全無法處理高維資料」，而是在高維時因距離度量失效而效果變差，敘述過於絕對","C":"錯誤，不能斷言300個特徵的資料「必然不具備群集結構」，問題根源在距離度量失效而非資料本身缺乏結構","D":"錯誤，並非「核心點數量受數學限制」，而是高維空間中距離度量失去區辨力導致密度估計失效"}},"origin":"past"},{"id":"middle_115-1_s1_q32","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":32,"context":null,"stem":"某工程師正在實作一個CNN影像分類模型，在PyTorch中定義模型架構時，需要在卷積擷取特徵後接上全連結層（Fully Connected Layer）進行分類。在模型程式碼中，需要在卷積輸出與全連結層之間插入什麼操作？","options":{"A":"使用全域平均池化（Global Average Pooling）將特徵圖壓縮後再接全連結層","B":"使用Flatten將特徵圖展平成一維向量","C":"直接將卷積輸出接到全連結層，系統會自動轉換維度","D":"先對特徵圖做Softmax，再輸入全連結層"},"answer":"B","figures":[],"explanation":{"approach":"卷積層輸出為多維特徵圖（channel×height×width），而全連結層需要一維向量作為輸入，因此需在兩者之間插入Flatten操作，將特徵圖展平為一維向量後才能接入全連結層。","options":{"A":"錯誤，Global Average Pooling是可行的替代做法（常用於減少參數量），但並非銜接卷積輸出與全連結層的標準必要操作，標準做法是Flatten","B":"正確，需使用Flatten將卷積輸出的多維特徵圖展平成一維向量，才能輸入全連結層","C":"錯誤，PyTorch不會自動轉換維度，若直接將多維卷積輸出接入全連結層會產生維度不匹配的錯誤","D":"錯誤，Softmax是用於分類機率轉換，通常置於模型輸出層，而非卷積輸出與全連結層之間的維度轉換操作"},"note":"選項A(全域平均池化,GAP)也是完全合法且常見的做法——ResNet 等現代架構正是用 GAP 接全連結層,還能大幅減少參數量。官方答案取B,是因為題目問「卷積輸出與全連結層之間需要插入什麼操作」,Flatten 是最基本、最直接的維度轉換答案。應試選B;實務上兩者都對,GAP 還更省參數。"},"origin":"past"},{"id":"middle_115-1_s1_q33","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":33,"context":null,"stem":"某自駕車公司的AI訓練團隊面臨標註成本高的問題，無法取得足夠的真實惡劣天氣（大雨、濃霧）駕駛場景資料，工程師提議使用合成資料（Synthetic Data）來補充訓練集。請問下列何者最能正確敘述合成資料在AI訓練中的角色？","options":{"A":"合成資料主要用於文字任務的資料擴增，影像任務仍需依賴真實資料","B":"合成資料可完全取代真實資料，直接用於模型訓練","C":"合成資料主要用於降低模型推論時的計算成本","D":"合成資料可在控制條件下產生多樣化場景，用於擴充訓練資料並提升模型的泛化能力"},"answer":"D","figures":[],"explanation":{"approach":"合成資料（Synthetic Data）可在可控條件下產生多樣化場景（如惡劣天氣的模擬駕駛場景），用來擴充訓練資料集、彌補真實資料稀缺的問題，並提升模型對少見情境的泛化能力。","options":{"A":"錯誤，合成資料廣泛應用於影像、感測器等多種任務，並非僅限於文字任務的資料擴增","B":"錯誤，合成資料通常作為真實資料的補充而非完全取代，過度依賴合成資料可能有sim-to-real gap的落差問題","C":"錯誤，合成資料用於擴充訓練資料，與降低「推論時」的計算成本無直接關係","D":"正確，合成資料可在控制條件下產生多樣化場景，用於擴充訓練資料並提升模型的泛化能力"}},"origin":"past"},{"id":"middle_115-1_s1_q34","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":34,"context":null,"stem":"某廣告技術公司的點擊率（CTR）預測系統每天新增數百個用戶行為特徵（如新廣告位、新設備類型），特徵空間持續動態擴展。若採用傳統靜態模型每週批次重訓一次，會導致嚴重的模型過期問題。為在特徵空間頻繁變化的情況下維持模型即時準確度，最適合的模型架構方向為何？","options":{"A":"採用傳統靜態羅吉斯迴歸（Logistic Regression），縮短批次重訓週期從每週改為每日","B":"採用支援增量學習（Incremental Learning）的模型，使模型能隨新資料即時更新並適應新增特徵，而不需重新訓練整個模型","C":"採用固定架構的深度神經網路（DNN），每次有新特徵時重新定義輸入層後全量重訓","D":"改用預訓練圖神經網路（GNN），透過圖結構建立特徵間的關聯，自動應對新增特徵"},"answer":"B","figures":[],"explanation":{"approach":"特徵空間持續動態擴展且需維持即時準確度，應採用支援增量學習（Incremental Learning）的模型架構，使模型能隨新資料與新特徵即時更新，而不需每次都重新訓練整個模型，兼顧即時性與效率。","options":{"A":"錯誤，僅將批次重訓週期從每週縮短為每日仍屬批次方式，無法解決特徵持續動態新增所導致的即時適應問題","B":"正確，支援增量學習的模型能隨新資料即時更新並適應新增特徵，而不需重新訓練整個模型，最適合此頻繁變化情境","C":"錯誤，固定架構的DNN每次新增特徵就要重新定義輸入層並全量重訓，成本高且無法即時因應特徵頻繁變化","D":"錯誤，GNN主要用於處理圖結構關聯資料，並非針對「特徵空間動態擴展下即時更新」問題的直接解方，也非此情境最合適架構"}},"origin":"past"},{"id":"middle_115-1_s1_q35","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":35,"context":null,"stem":"某生物醫學研究機構正在建構一個整合「基因序列特徵」與「電子病歷文本特徵」的疾病風險預測模型。由於高維數值特徵和語意文本特徵的性質差異顯著，請問下列哪一種特徵處理與選擇策略最為合適？","options":{"A":"將所有特徵合併為單一特徵矩陣後，使用主成分分析（PCA）進行降維，作為模型輸入","B":"採分層策略，先對基因序列特徵進行特徵選擇，再對文本特徵進行語意表示，最後將兩類特徵融合（Feature Fusion）後輸入模型","C":"將所有特徵合併後，使用隨機森林（Random Forest）的特徵重要性進行一次性排序與篩選","D":"將文本特徵轉換為簡單統計特徵（如詞頻）後與基因特徵一併建模，以降低特徵處理複雜度"},"answer":"B","figures":[],"explanation":{"approach":"基因序列（高維數值特徵）與電子病歷文本（語意型特徵）性質差異顯著，應採分層策略：先對基因特徵進行特徵選擇、再對文本進行語意表示，最後透過Feature Fusion整合兩類特徵後輸入模型，才能兼顧各模態的資料特性。","options":{"A":"錯誤，將異質特徵直接合併後統一做PCA，會忽略文本語意結構與數值特徵性質的差異，降維效果與語意保留皆可能失真","B":"正確，分層處理各模態特徵（基因做特徵選擇、文本做語意表示）後再進行Feature Fusion，最能兼顧兩類特徵的性質差異","C":"錯誤，將文本與基因特徵合併後直接用隨機森林重要性一次性篩選，未考量文本需要語意表示轉換的前處理步驟，不利文本語意保留","D":"錯誤，將文本轉為簡單詞頻統計會喪失語意資訊，降低文本特徵品質，並非最適合的處理方式"}},"origin":"past"},{"id":"middle_115-1_s1_q36","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":36,"context":null,"stem":"某公司希望開發一個工業零件瑕疵辨識分類模型，共有10個類別，但每類僅約50張人工標註影像（總計約500張）。由於標註成本高昂，短期內無法擴充資料集。在此情境下，工程師需要在有限標註資料下建構高效能模型。請問下列哪一種策略最為適合？","options":{"A":"使用在大型資料集預訓練完成的卷積神經網路（CNN），並進行遷移學習微調","B":"從頭訓練大型Vision Transformer（ViT），完全使用現有500張影像","C":"使用K-means對影像進行分群，並直接將群集結果作為分類模型輸出","D":"複製既有的資料以增加標註影像數量，並從頭訓練深度CNN模型"},"answer":"A","figures":[],"explanation":{"approach":"每類僅約50張、標註成本高且短期無法擴充資料集，應使用在大型資料集（如ImageNet）預訓練完成的CNN，透過遷移學習（Transfer Learning）微調，善用預訓練模型已學到的通用特徵，在少量標註資料下仍能獲得較佳效能。","options":{"A":"正確，使用預訓練CNN進行遷移學習微調，能在有限標註資料下善用預訓練模型的通用特徵，獲得較佳效能","B":"錯誤，ViT通常需要大量資料才能有效訓練（歸納偏誤較弱），從頭以僅500張影像訓練大型ViT容易嚴重過擬合","C":"錯誤，K-means是非監督分群方法，分群結果不等於監督式分類標籤，無法直接作為分類模型輸出使用","D":"錯誤，單純複製既有影像只是重複相同資訊而非真正增加多樣性，且從頭訓練深度CNN在資料量仍不足下容易過擬合"}},"origin":"past"},{"id":"middle_115-1_s1_q37","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":37,"context":null,"stem":"某製造廠開發產線瑕疵檢測模型時，資料集存在嚴重類別不平衡問題，其中良品約占99%，瑕疵品僅占1%。若直接使用原始資料進行訓練，模型容易偏向預測多數類別（良品），導致對少數類別（瑕疵品）辨識能力不足。在不調整模型架構與學習演算法的前提下，僅透過資料前處理方式改善此問題，下列何者最適當？","options":{"A":"使用SMOTE等過採樣方法進行少數類別擴增","B":"加入L1／L2正則化（Regularization）以防止過擬合","C":"大幅增加深度神經網路的層數，以強化特徵萃取能力","D":"複製更多良品數據，以進一步提升模型的準確率（Accuracy）"},"answer":"A","figures":[],"explanation":{"approach":"題目限制僅能透過資料前處理（不調整模型架構與學習演算法）改善類別不平衡，SMOTE等過採樣方法能合成少數類別（瑕疵品）樣本以平衡類別分布，提升模型對少數類別的辨識能力。","options":{"A":"正確，SMOTE等過採樣方法屬於資料前處理技術，能有效擴增少數類別樣本，改善類別不平衡問題","B":"錯誤，L1/L2正則化是模型訓練層面的技術（防止過擬合），並非資料前處理方法，也無法直接解決類別不平衡問題","C":"錯誤，增加神經網路層數屬於模型架構調整，題目已限制不可調整模型架構","D":"錯誤，複製更多良品資料只會加劇類別不平衡問題而非改善，且Accuracy在不平衡資料下容易產生誤導性高值"}},"origin":"past"},{"id":"middle_115-1_s1_q38","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":38,"context":null,"stem":"某IoT平台接收工廠溫度感測器資料，發現在常態分佈（均值25°C，標準差2°C）的數萬筆紀錄中，出現數筆「999°C」的極端值，研判為感測器通訊錯誤（網路封包延遲導致數值溢位）所致，且該異常數值在實際情況下不可能發生。在進行模型訓練前的資料清洗階段，針對這類離群值，最適當的處理策略為何？","options":{"A":"保留所有原始數值，並使用平均數（Mean）作為特徵輸入模型","B":"對數據進行Z-score標準化，使數值落於約[-3, 3]範圍","C":"將999°C以獨熱編碼（One-Hot Encoding）轉為獨立類別特徵","D":"刪除異常的999°C記錄，或以中位數（Median）進行填補"},"answer":"D","figures":[],"explanation":{"approach":"999°C為明顯不合理的感測器錯誤值（超出物理常態範圍），資料清洗階段應直接刪除該異常記錄，或以中位數（對極端值較不敏感）進行填補，避免此類離群值污染模型訓練。","options":{"A":"錯誤，保留原始異常值並用對離群值敏感的平均數作為輸入，反而會讓999°C嚴重扭曲平均值，影響模型訓練","B":"錯誤，Z-score標準化只是縮放數值分布，並不會移除或修正999°C這種已知的錯誤資料，異常值依然存在並扭曲統計量","C":"錯誤，999°C是感測器錯誤值而非有意義的類別資訊，以One-Hot編碼保留反而讓錯誤資訊繼續存在於模型輸入中","D":"正確，刪除異常的999°C記錄或以中位數填補，是處理已知感測器錯誤離群值最適當的資料清洗策略"}},"origin":"past"},{"id":"middle_115-1_s1_q39","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":39,"context":null,"stem":"某AI平台工程師正在為多模態模型訓練系統規劃資料儲存架構，需要同時處理原始影像、非結構化文本，以及經過整理的結構化特徵資料。在此情境下，應如何選擇資料湖（Data Lake）與資料倉儲（Data Warehouse）的使用方式？","options":{"A":"將原始影像與文本資料儲存在Data Lake，將整理後的結構化特徵資料儲存在Data Warehouse","B":"將所有資料統一儲存在Data Warehouse，以提升查詢效率","C":"將所有資料統一儲存在Data Lake，但犧牲結構化資料的查詢效率","D":"僅將原始影像資料儲存在Data Lake，其餘資料統一存入Data Warehouse"},"answer":"A","figures":[],"explanation":{"approach":"資料湖（Data Lake）適合儲存原始、非結構化或半結構化資料（如原始影像、文本），彈性高、成本低；資料倉儲（Data Warehouse）適合儲存已整理過的結構化資料，便於高效查詢與分析，應依資料型態分別存放於合適的儲存架構。","options":{"A":"正確，將原始影像與文本存於Data Lake、整理後的結構化特徵存於Data Warehouse，最符合兩種儲存架構的設計初衷","B":"錯誤，將所有資料（含原始影像、文本）統一存入Data Warehouse，成本高且不適合非結構化資料的彈性儲存需求","C":"錯誤，將結構化特徵資料也放入Data Lake會犧牲其查詢效率，不符合結構化資料應存於Data Warehouse以利高效查詢的原則","D":"錯誤，僅將影像存入Data Lake而其餘資料（含非結構化文本）統一存入Data Warehouse並不恰當，文本同樣更適合存放於Data Lake"}},"origin":"past"},{"id":"middle_115-1_s1_q40","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":40,"context":null,"stem":"某智慧製造公司在產線上部署工業相機進行即時外觀瑕疵檢測，原先將影像傳至雲端進行AI推論，但因網路延遲與連線不穩導致系統無法滿足即時需求（需低於200ms）。工程師因此改為將模型部署於產線端的邊緣裝置後，但仍未達系統需求。在不更換硬體設備的前提下，下列哪一組技術最能有效降低推論延遲，同時維持合理準確率？","options":{"A":"減少訓練資料的使用數量，並重新訓練模型以提升推論效率","B":"使用批次推論（Batch Inference）處理多張影像以提升計算效率","C":"採用模型集成（Model Ensemble），透過多模型投票提升準確率","D":"將模型由FP32量化為INT8，並進行推論加速優化"},"answer":"D","figures":[],"explanation":{"approach":"在不更換硬體的前提下，將模型從FP32量化為INT8可大幅降低運算量與記憶體頻寬需求，並搭配推論加速優化，是最直接有效降低邊緣裝置推論延遲、同時維持合理準確率的做法。","options":{"A":"錯誤，減少訓練資料量主要影響模型準確度，與推論階段的延遲並無直接關聯","B":"錯誤，批次推論雖可提升整體吞吐量，但對單張影像即時檢測反而可能因等待湊批而增加單筆延遲，不利即時性需求","C":"錯誤，模型集成需同時執行多個模型再投票，會增加而非降低推論延遲","D":"正確，將模型量化為INT8並進行推論加速優化，能在不更換硬體下有效降低延遲，同時維持合理準確率"}},"origin":"past"},{"id":"middle_115-1_s1_q41","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":41,"context":null,"stem":"某AI影像辨識平台以單一GPU伺服器提供多租戶推論服務，系統長期觀察到GPU使用率約維持在60%左右，且在執行過程中可觀察到GPU kernel之間存在明顯閒置間隔，單次推論多以小批次方式執行。然而，在尖峰時段時，請求延遲會出現明顯波動甚至突增。同時，CPU與記憶體資源使用率均未達瓶頸，且系統團隊已排除硬體、網路與請求併發控制異常。在此情境下，請判斷最可能造成問題的原因為何？","options":{"A":"GPU排程策略與批次大小設定不當，導致GPU運算單元未被有效利用","B":"請求併發控制機制不佳，導致多個請求同時搶占GPU Context資源造成延遲","C":"GPU硬體效能不足，無法支撐推論負載","D":"模型未進行量化優化，導致推論計算成本過高"},"answer":"A","figures":[],"explanation":{"approach":"GPU使用率僅60%、kernel之間存在明顯閒置間隔、且採小批次推論，同時已排除硬體、網路與併發控制異常，顯示問題出在GPU排程策略與批次大小（batch size）設定不當，導致GPU運算單元未被充分利用而產生延遲波動。","options":{"A":"正確，GPU排程策略與批次大小設定不當，導致GPU運算單元未被有效利用，是最符合題目描述現象的根本原因","B":"錯誤，題目已明確排除「請求併發控制異常」，故不應是此選項所述的原因","C":"錯誤，GPU使用率僅60%且非持續滿載，顯示問題並非硬體效能不足，而是資源未被有效利用","D":"錯誤，題目聚焦於GPU閒置間隔與小批次現象，並未提及推論計算成本過高的證據，量化並非此情境直接指向的根本原因"}},"origin":"past"},{"id":"middle_115-1_s1_q42","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":42,"context":null,"stem":"某保險公司將理賠金額預測模型正式部署上線，MLOps團隊設計監控機制。三個月後模型整體均方根誤差（RMSE）無明顯變化，但業務單位反映高額理賠案件的預測誤差明顯增加。經分析，高額理賠案件僅佔約5%的樣本比例，且未被監控機制及時發現。請問最可能的設計缺陷為何？","options":{"A":"監控頻率不足，應由每日批次監控改為即時串流監控","B":"高額理賠案件屬於長尾分布，難以透過監控指標偵測，因此無法透過監控機制發現問題","C":"RMSE無法有效反映高額誤差，應改以平均絕對誤差（MAE）作為主要監控指標","D":"僅監控整體RMSE，未針對不同理賠金額區間進行分群監控"},"answer":"D","figures":[],"explanation":{"approach":"監控機制僅追蹤整體RMSE，但高額理賠案件僅佔約5%樣本，其誤差被大量正常案件的樣本數稀釋，導致整體RMSE無明顯變化；根本設計缺陷是未針對不同理賠金額區間進行分群監控，才會忽略高額案件效能劣化的訊號。","options":{"A":"錯誤，問題根源不在監控頻率，而在監控指標未依區間分群，即使改為即時監控整體RMSE仍會忽略高額案件的問題","B":"錯誤，高額理賠雖屬長尾分布，但並非「無法透過監控機制發現」，只要採用分群監控即可偵測，此說法過於消極且非根本設計缺陷","C":"錯誤，MAE同樣是整體性指標，若不分群監控，同樣會被大量正常樣本稀釋而無法凸顯高額案件誤差，更換整體指標並非根本解方","D":"正確，僅監控整體RMSE而未針對不同理賠金額區間分群監控，才會使高額理賠案件的誤差惡化未被及時發現"}},"origin":"past"},{"id":"middle_115-1_s1_q43","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":43,"context":null,"stem":"某電商平台的演算法工程師開發了一個新版商品推薦模型，在離線A/B測試中，新模型的各項評估指標（AUC、NDCG@10）均顯著優於現行線上模型。然而，離線測試無法完全反映真實使用者的互動行為（點擊、購買、停留時間）。在正式全面上線前，若希望在可控制風險下量化真實業務指標，應採用下列何種線上驗證策略？","options":{"A":"影子模式（Shadow Mode）：新舊模型同時產生預測，但僅顯示舊模型結果，於後端比較輸出差異","B":"回測（Backtesting）：使用歷史日誌模擬模型表現作為上線依據","C":"金絲雀發布（Canary Release）：將1–5%使用者流量導向新模型，量測CTR、CVR等指標並逐步擴量","D":"負載測試（Load Testing）：於測試環境進行高流量壓力測試後直接全面上線"},"answer":"C","figures":[],"explanation":{"approach":"在可控風險下量化真實業務指標，金絲雀發布（Canary Release）將小比例流量（1-5%）導向新模型，實際量測CTR、CVR等真實業務指標後再逐步擴大流量，是兼顧風險控制與真實效果驗證的合適線上策略。","options":{"A":"錯誤，影子模式僅在後端比較輸出差異，不會讓使用者實際看到新模型結果，因此無法量測真實使用者互動下的業務指標","B":"錯誤，回測僅使用歷史日誌模擬，仍屬離線範疇，無法反映真實即時使用者互動行為","C":"正確，金絲雀發布以小比例流量量測真實業務指標並逐步擴量，最能在可控風險下驗證真實效果","D":"錯誤，負載測試僅評估系統承載效能而非業務指標，且「直接全面上線」風險過高，不符合可控風險上線的要求"}},"origin":"past"},{"id":"middle_115-1_s1_q44","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":44,"context":null,"stem":"某MLOps工程師正在設計AI模型的推論服務API，需要處理使用者上傳的高解析度影像（平均5MB）進行即時分類。在RESTful API設計時，選擇HTTP請求方法與資料傳輸格式的最佳實踐為何？","options":{"A":"使用HTTP GET方法，將影像資料Base64編碼後附加於URL Query String中","B":"採用HTTP POST請求，將影像資料以multipart/form-data或application/octet-stream傳輸於Request Body","C":"使用HTTP PUT方法，透過Content-Type: application/xml傳遞影像資料","D":"要求客戶端下載模型於本地推論，僅回傳分類結果"},"answer":"B","figures":[],"explanation":{"approach":"上傳高解析度影像應採用HTTP POST方法，將影像以multipart/form-data或application/octet-stream格式置於Request Body傳輸，這是處理二進位檔案上傳的標準實踐，可避免受限於URL長度或編碼效率問題。","options":{"A":"錯誤，GET方法搭配Base64編碼影像置於URL Query String會遠超過URL長度限制，且Base64編碼會使資料量增加約33%，不切實際","B":"正確，POST搭配multipart/form-data或application/octet-stream是傳輸二進位影像資料至Request Body的標準最佳實踐","C":"錯誤，PUT搭配application/xml並非傳輸二進位影像資料的合適格式，XML不適合承載原始影像位元組資料","D":"錯誤，要求客戶端下載模型於本地推論違背題目「提供推論服務API」的設計目的，也無法滿足伺服器端統一控管與更新模型的需求"}},"origin":"past"},{"id":"middle_115-1_s1_q45","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":45,"context":null,"stem":"某AI平台整合多個外部AI微服務（語音辨識API、NLP分析API、知識圖譜查詢服務），在高峰期間某外部服務偶發延遲或逾時（Timeout），導致請求鏈路壅塞，最終造成平台級服務中斷（Cascading Failure）。為從架構層面預防此類連鎖故障，最有效的設計模式為何？","options":{"A":"將所有外部API呼叫改為同步串行處理，並取消逾時限制，確保每個請求皆完成後再繼續","B":"為外部服務導入斷路器模式（Circuit Breaker），在異常時暫停呼叫並提供替代回應","C":"擴充各微服務的執行緒池（Thread Pool）上限，以提升併發處理能力","D":"停用服務健康檢查，減少不必要的額外負載"},"answer":"B","figures":[],"explanation":{"approach":"為防止外部服務延遲或逾時導致連鎖故障擴散至整個平台，應導入斷路器模式（Circuit Breaker），在偵測到異常時暫停對故障服務的呼叫並提供替代回應（fallback），避免請求持續堆積壅塞。","options":{"A":"錯誤，同步串行處理並取消逾時限制，反而會讓故障服務的延遲直接拖垮整個呼叫鏈，加劇連鎖故障風險","B":"正確，斷路器模式能在異常時暫停呼叫並提供替代回應，從架構層面有效預防連鎖故障擴散","C":"錯誤，擴充執行緒池上限只是增加併發容量，無法解決外部服務本身異常延遲的根本問題，故障仍會持續佔用資源","D":"錯誤，停用健康檢查會讓系統無法及早偵測異常服務，反而增加連鎖故障的風險"}},"origin":"past"},{"id":"middle_115-1_s1_q46","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":46,"context":null,"stem":"某醫院計劃建立混合雲AI平台：使用公有雲GPU叢集進行CT影像模型訓練，但基於HIPAA（Health Insurance Portability and Accountability Act）法規要求，患者影像原始資料不得離開醫院院內環境。下列何者最符合「利用公有雲算力訓練模型」與「不傳輸原始患者資料」雙重限制的技術方案？","options":{"A":"將患者影像資料以AES-256加密後上傳至公有雲，並於雲端解密後進行模型訓練","B":"在院內部署同態加密（Homomorphic Encryption）模組，對推論請求進行加密處理","C":"採用聯邦學習（Federated Learning）於院內訓練模型，僅傳送模型更新至雲端聚合，原始資料不外流","D":"建立專線VPN連接醫院與雲端，以網路層安全保護資料傳輸"},"answer":"C","figures":[],"explanation":{"approach":"需同時滿足「利用公有雲算力訓練」與「原始資料不可離開院內」雙重限制，聯邦學習（Federated Learning）讓模型在院內本地訓練，僅將模型參數更新（而非原始資料）傳送至雲端進行聚合，原始患者影像始終不離開院內環境，最符合此雙重限制。","options":{"A":"錯誤，即使加密上傳，雲端仍需解密後才能訓練，代表原始資料實際上仍離開院內環境並在雲端還原，違反法規要求","B":"錯誤，同態加密理論上可對加密資料運算，但計算成本極高，且題目描述用於「推論請求」而非模型訓練場景，並非解決此訓練情境的合適方案","C":"正確，聯邦學習於院內訓練模型、僅傳送模型更新至雲端聚合，原始資料始終不離開院內，同時利用公有雲算力","D":"錯誤，專線VPN僅強化傳輸層安全性，資料本質上仍會傳輸至雲端，並未滿足「原始資料不得離開院內」的限制"}},"origin":"past"},{"id":"middle_115-1_s1_q47","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":47,"context":null,"stem":"某電商平台將新的推薦模型部署至線上系統，為降低風險，團隊採用漸進式部署策略（Phased Rollout），先將新模型流量從5%逐步提升至100%。在部署初期，團隊發現轉換率（Conversion Rate）略有提升，但在流量提升至30%時，系統延遲（Latency）明顯上升，且部分使用者體驗變差。請問在此情境下，最適當的下一步策略為何？","options":{"A":"立即將新模型全面部署至100%，以觀察整體效果並評估系統表現變化","B":"還原（Rollback）至舊模型並停止新模型測試流程，以確保系統穩定與使用者體驗品質","C":"維持目前30%流量並持續觀察，即使延遲問題存在也暫不進行調整","D":"暫停流量提升，針對延遲問題進行效能分析與優化後再繼續部署"},"answer":"D","figures":[],"explanation":{"approach":"流量提升至30%後出現延遲明顯上升與使用者體驗變差，顯示系統存在效能瓶頸，此時最適當做法是暫停繼續提升流量，先針對延遲問題進行效能分析與優化，確認問題解決後再繼續漸進式擴量，而非貿然前進或全面撤退。","options":{"A":"錯誤，在已出現延遲與體驗變差的情況下直接全面部署至100%，會讓問題影響擴大到所有使用者，風險過高","B":"錯誤，轉換率已有提升的正向訊號，問題出在延遲而非模型效果本身，直接rollback並停止測試過於保守，浪費已有的正面成效","C":"錯誤，已發現延遲問題卻選擇「暫不進行調整」，放任使用者體驗持續變差，不符合風險控管的漸進式部署精神","D":"正確，暫停流量提升、針對延遲問題進行效能分析與優化後再繼續部署，兼顧風險控管與問題排除"}},"origin":"past"},{"id":"middle_115-1_s1_q48","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":48,"context":null,"stem":"某銀行的信用卡風控模型已穩定上線一年，主要用於偵測盜刷交易提醒。近期在未對模型或特徵工程進行調整的情況下，系統觀察到深夜電商交易的核准率明顯上升，盜刷攔截率下降，但模型AUC幾乎維持不變，且交易金額、地區與裝置等特徵分布未出現明顯變化。進一步分析發現，疫情後使用者行為改變，使原本被視為高風險的交易型態逐漸轉為一般消費。下列何者最能敘述此現象的原因？","options":{"A":"資料漂移（Data Drift），因輸入特徵分布發生變化","B":"訓練與服務偏差（Training-Serving Skew），因線上與離線特徵處理不一致","C":"概念漂移（Concept Drift），因特徵與目標標籤之間的關聯性改變","D":"決策閾值偏移（Threshold Shift），因分類門檻設定不當導致預測偏差"},"answer":"C","figures":[],"explanation":{"approach":"特徵分布（交易金額、地區、裝置）未改變、AUC也大致不變，但使用者行為改變導致原本判定為高風險的交易型態轉為一般消費，即「特徵與目標標籤之間的關聯性」改變，這正是概念漂移（Concept Drift）的定義，而非輸入特徵分布本身改變。","options":{"A":"錯誤，資料漂移指的是輸入特徵分布發生變化，但題目明確指出各項特徵分布並未出現明顯變化，故不符合","B":"錯誤，訓練與服務偏差是指線上與離線特徵處理邏輯不一致所致，題目未提及此類技術實作落差","C":"正確，特徵與目標標籤之間的關聯性因使用者行為改變而改變，正是概念漂移的定義，最能解釋此現象","D":"錯誤，題目未提及模型或系統對決策閾值做過調整，現象源於使用者行為與風險型態轉變，而非閾值設定不當"}},"origin":"past"},{"id":"middle_115-1_s1_q49","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":49,"context":null,"stem":"某零售電商平台已建立模型監控儀表板，用於追蹤線上推薦模型的運作狀態與效能表現。維運工程師需判斷哪些指標屬於「線上持續監控（ContinuousMonitoring）」的範疇。下列指標中，哪一項最不適合在即時監控系統中追蹤，而應改由離線實驗追蹤系統管理？","options":{"A":"訓練實驗中每個Epoch的學習率（Learning Rate）變化曲線與超參數（Hyperparameter）設定軌跡","B":"線上推論API的P50/P95/P99回應延遲與每日請求量（RPS）趨勢","C":"輸入特徵分佈的族群穩定性指數（Population Stability Index, PSI），偵測資料漂移","D":"模型預測結果分佈（如CTR）與定期回收的人工標註結果之對比"},"answer":"A","figures":[],"explanation":{"approach":"每個Epoch的學習率變化曲線與超參數設定軌跡屬於「訓練實驗」階段的紀錄，應由離線實驗追蹤系統（如MLflow、W&B）管理，而非放入線上持續監控儀表板，因為這些資訊與模型上線後的即時運作狀態無關。","options":{"A":"正確，訓練Epoch的學習率曲線與超參數設定軌跡屬於離線訓練實驗紀錄，應由離線實驗追蹤系統管理，而非線上持續監控","B":"錯誤，API回應延遲與RPS趨勢是線上服務運作狀態的關鍵指標，理應納入線上持續監控","C":"錯誤，PSI用於偵測線上輸入資料是否隨時間偏移（資料漂移），是線上持續監控的典型指標","D":"錯誤，預測結果分佈與人工標註結果的對比用於監控線上模型效能是否持續穩定，屬於持續監控範疇"}},"origin":"past"},{"id":"middle_115-1_s1_q50","level":"middle","session":"115-1","subject":1,"subject_name":"人工智慧技術應用與規劃","number":50,"context":null,"stem":"某醫療團隊建立肺炎診斷系統，採用晚期融合（Late Fusion）策略，將胸腔X光影像與病患問診文字分別進行預測後再整合結果。測試發現，當問診紀錄品質不佳（如描述簡短或資訊缺漏）時，整體模型效能僅小幅下降。關於此現象，下列何者最不可能為其原因？","options":{"A":"各模態獨立進行預測，可降低單一模態品質不佳對整體結果的影響","B":"融合階段可調整不同模態的權重，使低品質模態影響降低","C":"各模態使用獨立模型，使錯誤不會在特徵層被放大","D":"晚期融合會在輸入階段整合多模態特徵，因此能避免低品質資料影響"},"answer":"D","figures":[],"explanation":{"approach":"晚期融合（Late Fusion）是在各模態分別完成預測後才整合結果，並非在輸入階段整合特徵（那是早期融合Early Fusion的做法）。因此當某一模態（問診文字）品質不佳時，其影響會被獨立預測與加權整合機制所侷限，整體效能僅小幅下降。","options":{"A":"為合理原因，各模態獨立進行預測時，單一模態品質不佳不會直接汙染其他模態的預測結果，故整體影響有限","B":"為合理原因，融合階段可透過調整不同模態的權重，降低低品質模態（問診文字）對最終結果的影響","C":"為合理原因，各模態使用獨立模型分別訓練與推論，錯誤不會在特徵層被放大","D":"最不可能為原因，晚期融合是在各模態分別完成預測後才整合結果，並非在輸入階段整合多模態特徵，此敘述與晚期融合的定義相反"}},"origin":"past"},{"id":"middle_115-1_s2_q01","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":1,"context":null,"stem":"工程師使用盒鬚圖（Box Plot）比較三個城市的房價分布，觀察到城市A的盒子很短但鬚很長，城市B的盒子很長且對稱，城市C的中位數位置明顯偏向盒子下方。依統計圖形判讀原則，下列敘述何者正確？","options":{"A":"城市A中段房價集中但存在極端值；城市C中位數偏低，資料呈右偏分布","B":"城市A房價集中且離群值少；城市C資料呈左偏分布","C":"城市B的盒子較長代表房價變異較大；城市C呈左偏分布","D":"盒鬚圖無法判斷偏態，需搭配直方圖才能得出以上結論"},"answer":"A","figures":[],"explanation":{"approach":"盒鬚圖判讀重點在於盒子（IQR）長短代表資料集中程度、鬚的長短代表資料延伸範圍是否有極端值、中位數在盒子內的相對位置則反映偏態方向。城市A盒子短代表中段（IQR內）房價集中，但鬚很長表示存在極端值；城市C中位數偏向盒子下方（靠近Q1），代表下半段資料壓縮、上半段延伸較長，屬於右偏（正偏）分布。","options":{"A":"正確。盒子短＝中段房價集中，鬚長＝存在極端值；中位數偏低（靠近Q1）＝右偏分布，判讀方向正確。","B":"城市A鬚很長恰好代表離群值/極端值可能存在而非「離群值少」；且城市C中位數偏向盒子下方應為右偏而非左偏，方向判斷錯誤。","C":"盒子長代表IQR大、變異較大這點正確，但城市C中位數偏下應為右偏分布，此選項誤判為左偏，方向相反。","D":"錯誤。盒鬚圖本身即可透過中位數在盒內的相對位置與鬚長不對稱程度判讀偏態方向，不需要額外搭配直方圖才能得出結論。"}},"origin":"past"},{"id":"middle_115-1_s2_q02","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":2,"context":null,"stem":"下圖為吉尼不純度（Gini Impurity）的計算公式，在決策樹（Decision Tree）中，吉尼不純度用於評估節點分裂的品質。關於吉尼不純度，下列敘述何者不正確？","options":{"A":"公式中的pᵢ代表第i類在該節點中的樣本數，並直接帶入公式計算","B":"公式中的k代表節點內資料的類別數量","C":"吉尼不純度用於衡量節點內資料的類別混雜程度，數值越高代表越混雜","D":"當節點內所有樣本屬於同一類別時（完全純淨），吉尼不純度為0"},"answer":"A","figures":[{"src":"images/middle_115-1_s2_q02_fig1.png","position":"stem"}],"explanation":{"approach":"吉尼不純度公式 G = 1 − Σpᵢ² 中，pᵢ須為第i類樣本佔該節點「總樣本數的比例」（機率），而非原始樣本數。公式衡量節點內類別混雜程度，數值介於0（完全純淨）到理論上限之間，數值愈高代表類別愈混雜。","options":{"A":"不正確（本題答案）。pᵢ代表第i類樣本佔節點總數的比例（機率），而非樣本數本身；若直接把樣本數帶入公式會使計算結果錯誤。","B":"正確敘述。k確實代表節點內資料的類別數量，對應公式中Σ的上界。","C":"正確敘述。吉尼不純度數值愈高代表節點內類別混雜程度愈高，是常見的節點分裂品質衡量指標。","D":"正確敘述。當節點所有樣本屬同一類別時，該類別pᵢ=1、其餘為0，代入公式得G=1−1²=0，即完全純淨。"}},"origin":"past"},{"id":"middle_115-1_s2_q03","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":3,"context":null,"stem":"某物流平台要預測「每小時客服來電數量」，資料顯示平均每小時12通，且來電事件彼此獨立，並在固定時間區間內發生率穩定。工程師在選擇機率模型時，應優先考慮哪個分布？若實際資料的變異數明顯大於平均數，應如何調整？","options":{"A":"使用常態分布（Normal Distribution）；變異數偏大時改用t分布","B":"使用卜瓦松分布（Poisson Distribution）；變異數>平均數時改用負二項分布（NegativeBinomial）","C":"使用卜瓦松分布（Poisson Distribution）；變異數偏大時增加樣本數即可修正","D":"使用二項分布（Binomial Distribution）；變異數偏大時改用卜瓦松分布（PoissonDstribution）"},"answer":"B","figures":[],"explanation":{"approach":"來電事件彼此獨立、發生率在固定時間區間內穩定，屬於典型的卜瓦松過程（Poisson Process），故應優先採用卜瓦松分布建模計數資料。若實際觀察到變異數明顯大於平均數（over-dispersion），已違反卜瓦松分布「平均數=變異數」的假設，此時常見的調整方式是改用負二項分布（Negative Binomial Distribution）來容納額外的變異。","options":{"A":"常態分布不適合離散計數型資料（尤其平均值不大時），且變異數偏大應改用能處理over-dispersion的模型，而非改用t分布（t分布是針對小樣本估計平均值不確定性的工具，與此問題無關）。","B":"正確。獨立事件、固定發生率的計數資料應優先用卜瓦松分布；當變異數>平均數（over-dispersion）時，負二項分布是標準且正確的調整方向。","C":"卜瓦松分布的選擇正確，但「增加樣本數」並不能修正over-dispersion問題，over-dispersion是模型假設不符的結構性問題，須改換分布而非靠擴大樣本數解決。","D":"二項分布適用於固定次數試驗中成功次數的計數，並非用於單位時間內事件發生次數的建模，起始分布選擇本身就不適當。"}},"origin":"past"},{"id":"middle_115-1_s2_q04","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":4,"context":null,"stem":"某工程師使用MLflow進行實驗追蹤，評估三種不同學習率（0.001、0.01、0.1）對同一模型在驗證資料集上的損失表現。每種學習率皆以不同隨機種子重複訓練10次，形成三組彼此獨立的樣本資料。經檢查後，這些資料近似常態分布且變異數相近。工程師希望判斷三組平均損失是否存在顯著差異，同時避免因進行多次兩兩比較而提高第一類型錯誤率。請問下列何者為最適合採用的統計方法？","options":{"A":"單因子變異數分析（One-Way ANOVA）","B":"獨立樣本t檢定（Independent Samples t-test）","C":"卡方獨立性檢定（Chi-Square Test）","D":"Wilcoxon符號等級檢定（Wilcoxon Signed-Rank Test）"},"answer":"A","figures":[],"explanation":{"approach":"情境為比較三組（三種學習率）獨立、近似常態且變異數相近的樣本平均數是否有顯著差異，且需避免多次兩兩比較造成第一型錯誤率膨脹，這正是單因子變異數分析（One-Way ANOVA）的典型應用場景，ANOVA可用單一F檢定同時比較三組以上的平均數。","options":{"A":"正確。三組獨立樣本、常態、變異數相近，且需一次性比較三組平均數、避免多重比較膨脹型一錯誤，正是One-Way ANOVA的設計目的。","B":"獨立樣本t檢定僅能比較兩組平均數，若用於三組資料需進行多次兩兩比較，反而會提高第一型錯誤率，與題目要求相違背。","C":"卡方獨立性檢定用於類別變數間關聯性的檢定，並非用於比較連續型變數（損失值）的平均數差異，資料型態不符。","D":"Wilcoxon符號等級檢定是無母數方法，用於成對樣本或單一樣本中位數比較，不適用於三組獨立樣本平均數之比較，且本題資料已近似常態、應優先用母數方法。"}},"origin":"past"},{"id":"middle_115-1_s2_q05","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":5,"context":null,"stem":"某AI團隊在模型上線後，透過監控系統持續追蹤輸入特徵的分布變化，系統使用Z-score（Z）作為異常判斷依據，並設定當|Z| ≥ 2時需觸發警示。假設該特徵近似常態分布，某次監控中發現某特徵值的Z-score為-2，請問就實務判讀而言，此數值最可能代表什麼意義？","options":{"A":"該特徵值低於該特徵歷史平均值2個標準差","B":"該特徵值高於該特徵歷史平均值2個標準差","C":"該特徵值等於該特徵的歷史平均值","D":"Z-score為負值代表該數值位於母體分布之外，無法以常態分布解釋"},"answer":"A","figures":[],"explanation":{"approach":"Z-score定義為 Z=(x−μ)/σ，代表觀測值偏離平均值的標準差倍數。Z=-2表示該特徵值低於歷史平均值2個標準差，屬於監控系統設定的異常下界警示範圍。","options":{"A":"正確。負的Z-score代表數值低於平均值，Z=-2即代表低於平均值2個標準差。","B":"方向相反，Z為負值代表低於平均值而非高於平均值。","C":"Z=0才代表數值等於平均值，Z=-2明顯偏離平均值。","D":"錯誤。負值Z-score在常態分布下是完全正常且可解釋的現象，僅代表數值落在平均值以下，並非「無法以常態分布解釋」。"}},"origin":"past"},{"id":"middle_115-1_s2_q06","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":6,"context":null,"stem":"在AI模型評估的假說檢定框架中，「女士品茶」實驗是理解型一／型二錯誤的經典案例。實驗中某女士宣稱能分辨8杯奶茶中哪4杯先加牛奶，若以顯著水準α=0.05進行假說檢定，下列敘述何者不正確？","options":{"A":"虛無假說（H₀）為「女士無此能力（隨機猜測）」，對立假說（H₁）為「女士確實有此能力」","B":"在α=0.05下，若女士完全答對（8選4全對），其p值約為1/70≈0.014，小於顯著水準，可達統計顯著","C":"若女士完全答對且p值<α，則拒絕虛無假說，統計上支持女士有此能力","D":"若女士未完全答對，則「接受虛無假說」，代表確認女士無此能力"},"answer":"D","figures":[],"explanation":{"approach":"此題以「女士品茶」實驗說明型一／型二錯誤觀念：H₀為女士無分辨能力（隨機猜測），H₁為女士確有此能力；在8選4情境下，全對的機率為1/C(8,4)=1/70≈0.014，小於α=0.05，達統計顯著可拒絕H₀。但統計假說檢定中，未能拒絕H₀只能說「無法拒絕虛無假說」，並不能倒果為因地說是「接受H₀」並確認其為真。","options":{"A":"正確敘述。H₀（無能力／隨機猜測）與H₁（確有能力）的設定符合此實驗的假說檢定架構。","B":"正確敘述。8選4全對機率為1/70≈0.0143＜0.05，符合統計顯著的判定標準。","C":"正確敘述。p值小於α即可拒絕H₀，支持對立假說（女士確有此能力）成立。","D":"不正確（本題答案）。統計假說檢定架構下並不存在「接受虛無假說」的說法，只能說「未能拒絕H₀」；未完全答對不代表能確認女士無此能力，可能只是樣本太小、檢定力不足或表現不穩定。"}},"origin":"past"},{"id":"middle_115-1_s2_q07","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":7,"context":null,"stem":"某醫療AI研究團隊開發了一套個人化用藥劑量推薦系統，並設計實驗評估其效果。研究團隊招募40名高血壓患者，分別在導入AI推薦系統前後各測量一次收縮壓，且資料近似常態分布。研究目標是判斷同一批患者在依據AI推薦調整用藥劑量前後，血壓是否有顯著差異。請問此研究情境應選用哪種統計檢定方法？","options":{"A":"獨立樣本t檢定（Independent Samples t-test）","B":"成對樣本t檢定（Paired Samples t-test）","C":"單因子變異數分析（One-Way ANOVA）","D":"魏克遜符號等級檢定（Wilcoxon Signed-Rank Test）"},"answer":"B","figures":[],"explanation":{"approach":"此研究對「同一批患者」在用藥前後各測量一次血壓，屬於同一組樣本的重複測量（配對資料），且資料近似常態分布，因此應採用成對樣本t檢定（Paired Samples t-test），可利用配對差異降低個體間變異的干擾，提高檢定力。","options":{"A":"獨立樣本t檢定適用於兩組互不相關、不同受試者的資料，但此題是同一批患者前後測量，屬於配對資料，用獨立樣本t檢定會忽略配對相關性，並不適當。","B":"正確。同一群患者用藥前後各測一次血壓，屬典型配對（重複測量）設計，成對樣本t檢定最能捕捉個體內差異並提高檢定效率。","C":"單因子ANOVA用於比較三組以上獨立樣本的平均數，本題僅有「前」與「後」兩個相關（非獨立）測量，並不適用。","D":"Wilcoxon符號等級檢定是配對資料的無母數替代方法，但題目已說明資料近似常態分布，應優先選擇檢定力較高的母數方法（成對t檢定），而非無母數方法。"}},"origin":"past"},{"id":"middle_115-1_s2_q08","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":8,"context":null,"stem":"某咖啡店聲稱其平均外送時間為36分鐘，母體標準差為16分鐘。顧客保護團體抽樣9筆訂單，發現平均外送時間為40分鐘。若採用右尾Z檢定（H₁: μ > 36），顯著水準α= 0.05（臨界值Z₀.₀₅ = 1.645），請問Z值與檢定結果為何？（參考公式如下圖）","options":{"A":"Z ≈ 0.08，拒絕虛無假說","B":"Z ≈ 0.08，不拒絕虛無假說","C":"Z ≈ 0.75，拒絕虛無假說","D":"Z ≈ 0.75，不拒絕虛無假說"},"answer":"D","figures":[{"src":"images/middle_115-1_s2_q08_fig1.png","position":"stem"}],"explanation":{"approach":"採用公式 Z=(x̄−μ₀)/(σ/√n)，帶入 x̄=40、μ₀=36、σ=16、n=9 得 Z=(40−36)/(16/3)=4/(16/3)=0.75。因為Z≈0.75小於臨界值Z₀.₀₅=1.645，落在不拒絕域內，故不拒絕虛無假說（即無足夠證據顯示平均外送時間顯著大於36分鐘）。","options":{"A":"Z值計算錯誤（應為0.75而非0.08），且0.75小於臨界值1.645，結論應為不拒絕虛無假說而非拒絕。","B":"Z值計算錯誤，正確Z值應為0.75而非0.08，數值計算有誤。","C":"Z值計算正確（≈0.75），但結論錯誤：0.75小於臨界值1.645，未落入右尾拒絕域，應為「不拒絕虛無假說」而非「拒絕」。","D":"正確。Z=(40−36)/(16/√9)=4/(16/3)=0.75，小於臨界值1.645，未達顯著水準，故不拒絕虛無假說。"}},"origin":"past"},{"id":"middle_115-1_s2_q09","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":9,"context":null,"stem":"某生技公司正在進行新型AI輔助新藥篩選的臨床試驗，並將顯著水準由α=0.05降低至α=0.01。在新藥療效安全試驗的情境下，此調整對統計檢定的直接影響為何？","options":{"A":"降低型二錯誤（Type II Error／β）的發生機率，減少未能偵測到有效藥物的風險","B":"降低型一錯誤（Type I Error／α，偽陽性）的發生機率，減少將無效藥物誤判為有效並進入後續高成本試驗的風險","C":"增加樣本數以提升統計功效（Statistical Power），進而改善估計精度","D":"降低統計計算過程中的數值誤差，提高p值的精確度"},"answer":"B","figures":[],"explanation":{"approach":"將顯著水準由0.05降至0.01，代表對「拒絕虛無假說」設下更嚴格的門檻，直接效果是降低型一錯誤（偽陽性，將無效藥物誤判為有效）的發生機率，這在新藥安全試驗情境中，能有效減少誤判無效藥物為有效並進入後續高成本試驗的風險（雖然通常會伴隨型二錯誤上升的取捨）。","options":{"A":"方向錯誤。降低α通常會使檢定門檻更嚴格，在樣本數與效應量不變下，反而容易提高型二錯誤（β）的發生機率，而非降低。","B":"正確。α即為型一錯誤機率上限，將α由0.05降至0.01，直接降低偽陽性（誤判無效藥物為有效）的風險，符合新藥安全試驗保守判定的需求。","C":"調整α本身不會自動增加樣本數，樣本數與統計功效是需另外主動規劃的設計決策，並非α調整的直接效果。","D":"α是決策的顯著水準門檻，與p值計算過程的數值精確度或誤差無關，調整α不會改變p值本身的計算精度。"}},"origin":"past"},{"id":"middle_115-1_s2_q10","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":10,"context":null,"stem":"某團隊為職業籃球隊建立球員受傷風險預測模型，原始特徵280個。初始模型訓練集AUC為0.94、測試集僅0.68，顯示嚴重過擬合。為改善模型，團隊進行以下處理步驟：第一步於全體資料（含測試集）上計算特徵間線性相關係數並移除高度相關特徵；第二步依模型重要性篩選特徵後重新訓練模型。最終測試集AUC提升至0.81。關於上述調整流程，下列敘述何者最為正確？","options":{"A":"使用相關係數進行特徵篩選方向正確，主要問題在於相關係數門檻設定過高","B":"在全體資料（含測試集）上進行特徵篩選會造成資料洩漏，且線性相關無法捕捉非線性關係","C":"特徵篩選後需重新對測試集進行標準化，否則會影響模型表現","D":"測試集表現提升代表過擬合已解決，流程可直接部署"},"answer":"B","figures":[],"explanation":{"approach":"此流程的關鍵錯誤在於特徵篩選（計算相關係數並移除高相關特徵）是在「全體資料（含測試集）」上執行，這使得測試集資訊提前滲入了訓練/特徵選擇流程，造成資料洩漏（Data Leakage），使測試集AUC虛高、無法真實反映模型的泛化能力；此外，線性相關係數只能偵測線性關係，無法捕捉特徵間的非線性依賴。","options":{"A":"問題核心並非相關係數門檻設定，而是特徵篩選使用了包含測試集的全體資料，導致資料洩漏，這才是根本性的流程錯誤。","B":"正確。在訓練/測試切分「之前」就對含測試集的全體資料做特徵篩選會造成資料洩漏；且線性相關係數僅能捕捉線性關係，無法反映特徵間的非線性依存關係，兩者皆為此流程的實質缺陷。","C":"題目情境並未提及標準化相關操作，此為無關的推論，並非造成此流程失真的主要原因。","D":"測試集AUC提升不代表過擬合已解決，尤其在特徵篩選階段已發生資料洩漏的情況下，該提升可能只是虛高表現，不能直接視為問題已解決並貿然部署。"}},"origin":"past"},{"id":"middle_115-1_s2_q11","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":11,"context":null,"stem":"某團隊為電信公司建立用戶月租方案續約預測模型，資料集包含兩個類別特徵：「客服評價」共有5個等級（非常不滿意至非常滿意），具明確順序關係；「居住縣市」共有22個不同類別，類別之間無順序關係。團隊計劃分別以Logistic Regression與XGBoost訓練模型，並對上述特徵進行編碼。請問下列哪個編碼方案最適當？","options":{"A":"兩模型皆將「客服評價」與「居住縣市」進行One-Hot Encoding，保留全部欄位並使用相同特徵矩陣訓練模型","B":"Logistic Regression將「客服評價」做Ordinal Encoding、「居住縣市」以歷史續約率進行編碼且於資料切分前計算；XGBoost對兩個特徵皆採Ordinal Encoding處理","C":"Logistic Regression將「客服評價」做Ordinal Encoding、「居住縣市」進行One-HotEncoding並採Drop First；XGBoost將「客服評價」採Ordinal Encoding，「居住縣市」以類別型態輸入並啟用enable_categorical","D":"兩個模型均將「客服評價」以平均續約率進行編碼，「居住縣市」先做One-HotEncoding再以PCA降維，並統一作為兩模型輸入特徵"},"answer":"C","figures":[],"explanation":{"approach":"「客服評價」具明確順序關係，適合用Ordinal Encoding保留順序資訊；「居住縣市」為22個無序類別，若用於線性模型（Logistic Regression）須避免造成假的線性順序關係，宜採One-Hot Encoding（並用Drop First避免虛擬變數陷阱／共線性）；而樹模型（XGBoost）可直接以類別型態輸入並啟用enable_categorical，由樹狀分裂機制處理高基數類別，不需One-Hot造成維度爆炸。","options":{"A":"兩模型皆對「客服評價」做One-Hot會丟失其原本的順序資訊，且對高基數「居住縣市」做One-Hot對XGBoost而言並非必要甚至造成維度過高，未依模型特性選用最適合的編碼方式。","B":"「居住縣市」以歷史續約率編碼且於資料切分前計算，會造成目標洩漏（Target Leakage）；且XGBoost對「居住縣市」用Ordinal Encoding會強加不存在的順序關係，並不恰當。","C":"正確。Logistic Regression對「客服評價」用Ordinal Encoding（保留順序）、對「居住縣市」用One-Hot＋Drop First（避免共線性且不強加順序）；XGBoost則對「客服評價」用Ordinal Encoding、對「居住縣市」以原生類別型態＋enable_categorical處理，充分依模型特性選擇最適合編碼。","D":"以平均續約率（目標編碼）取代原本具順序意義的「客服評價」不必要且增加洩漏風險；對高基數類別先One-Hot再PCA降維也增加不必要複雜度，且未依模型差異調整策略。"}},"origin":"past"},{"id":"middle_115-1_s2_q12","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":12,"context":null,"stem":"某資料工程師在建構AI訓練資料處理流程時，需要處理一個50GB的CSV檔案，其大小遠超過系統可用記憶體。他使用Python的Pandas進行資料前處理，但直接呼叫pd.read_csv()時出現記憶體溢位（Out of Memory, OOM）錯誤。在不改用其他分散式框架的前提下，下列哪個參數最能有效解決此問題？","options":{"A":"nrows=10000：限制僅讀取前N筆資料以避免記憶體溢位","B":"usecols=0.5：隨機載入50%的資料欄位，以減半記憶體使用量","C":"chunksize=10000：分批讀取資料並逐批處理，避免一次載入整個檔案","D":"dtype：指定欄位資料型別以降低記憶體使用量"},"answer":"C","figures":[],"explanation":{"approach":"50GB CSV遠超系統記憶體，直接pd.read_csv()會整檔載入記憶體造成OOM。在不改用分散式框架的前提下，最直接有效的解法是使用chunksize參數，將資料分批讀取並逐批處理，避免一次性載入整個檔案到記憶體中。","options":{"A":"nrows只會截取前N筆資料，等於捨棄大部分資料，無法完整處理整個50GB檔案，不是解決OOM同時保留完整資料的方法。","B":"usecols參數用於指定要讀取的欄位名稱或索引清單，並非用來設定「隨機載入50%欄位的比例」，此為對參數用法的誤解，也無法真正解決記憶體問題。","C":"正確。chunksize可讓read_csv以生成器方式分批讀取資料並逐批處理，避免一次性將50GB資料全部載入記憶體，是不改用分散式框架下最有效的解法。","D":"dtype指定型別確實有助於降低記憶體使用量，但單靠型別優化未必能讓50GB資料完全塞入可用記憶體，效果不如直接分批讀取（chunksize）來得直接有效。"}},"origin":"past"},{"id":"middle_115-1_s2_q13","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":13,"context":null,"stem":"某電商平台正在重構商品資料架構，需同時支援三個系統：商品管理後台需處理結構化與半結構化資料（如巢狀庫存與不同類別商品欄位差異），並支援複雜條件查詢；AI推薦系統需儲存高維向量（1,536維）並進行高效相似度搜尋（高QPS）；即時庫存服務則要求ACID且延遲低於10ms，以避免超賣。在此情境下，哪種資料庫架構最適合？","options":{"A":"全部使用關聯式資料庫，透過JSON欄位儲存巢狀資料，並以延伸套件支援向量搜尋，同時以資料列鎖（Row-level Lock）處理庫存扣減","B":"商品資料使用文件型資料庫，向量搜尋使用專用向量資料庫，庫存服務使用關聯式資料庫，各系統依需求選擇最適合的資料庫","C":"全部使用文件型資料庫，同時處理商品資料、向量搜尋與庫存服務，以統一技術棧降低維運複雜度","D":"商品與向量資料使用搜尋引擎型資料庫，並以文件更新機制處理庫存扣減"},"answer":"B","figures":[],"explanation":{"approach":"三個系統對資料庫的需求截然不同：商品管理需彈性schema與複雜查詢（適合文件型資料庫）、AI推薦需高維向量高效相似度搜尋（適合專用向量資料庫）、即時庫存則要求ACID與低延遲（適合關聯式資料庫）。依各系統特性分別選用最適合的資料庫（Polyglot Persistence），是此情境下最合理的架構設計。","options":{"A":"把所有需求硬塞進單一關聯式資料庫，即使透過延伸套件支援向量搜尋，在高QPS向量相似度搜尋的效能與擴展性上通常不如專用向量資料庫，且整體架構耦合度過高，並非最適合的設計。","B":"正確。依各系統的資料特性與需求分別採用文件型資料庫（彈性schema、複雜查詢）、專用向量資料庫（高效相似度搜尋）與關聯式資料庫（ACID、低延遲庫存），是符合各自需求的最適合架構。","C":"全部改用文件型資料庫雖降低維運複雜度，但文件型資料庫通常難以同時滿足向量高效相似度搜尋的效能需求，以及庫存服務所需的強ACID保證與低延遲，犧牲了關鍵功能需求。","D":"搜尋引擎型資料庫（如Elasticsearch）多為最終一致性設計，並非為強ACID交易與低延遲庫存扣減設計，以文件更新機制處理庫存容易產生超賣風險，不符即時庫存服務的嚴格需求。"}},"origin":"past"},{"id":"middle_115-1_s2_q14","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":14,"context":null,"stem":"某AI平台的資料量已達PB級，單一資料庫節點已無法負荷，決定採用分片（Sharding）策略。下列何者為Sharding設計的主要目的？","options":{"A":"增加資料備份數量以提升安全性","B":"將查詢結果預先計算以降低延遲","C":"將資料水平分割以提升擴展性與負載均衡","D":"將資料壓縮以減少儲存成本"},"answer":"C","figures":[],"explanation":{"approach":"Sharding（分片）是將龐大資料集依某種規則水平切分並分散存放到多個資料庫節點，目的是突破單一節點的儲存與運算負載上限，達到系統擴展性提升與各節點間負載均衡的效果，是應對PB級資料量的常見架構策略。","options":{"A":"增加備份數量是複寫（Replication）的目的，用於提高可用性與容錯，而非Sharding水平分割資料以提升擴展性的核心目的。","B":"預先計算查詢結果以降低延遲屬於快取或物化視圖（Materialized View）的概念，並非Sharding的設計目的。","C":"正確。Sharding的核心目的就是將資料水平分割到多個節點，藉此提升系統擴展性並達成各節點間的負載均衡，解決單一節點無法負荷大量資料的問題。","D":"資料壓縮以減少儲存成本屬於儲存優化技術，與Sharding著重於水平切分以擴展運算/儲存容量的目的不同。"}},"origin":"past"},{"id":"middle_115-1_s2_q15","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":15,"context":null,"stem":"某資料工程師在建構大規模影像資料處理流程時，需要處理數千萬筆訓練影像，並發現模型出現嚴重的過度擬合（Overfitting）：訓練集準確率達99%，但驗證集僅有72%。在不改變模型架構的前提下，下列哪一項「資料處理層面」的調整最無法有效改善過度擬合，甚至可能使問題惡化？","options":{"A":"在資料處理流程中加入資料增強（Data Augmentation），於訓練時動態生成多樣化影像樣本","B":"擴充資料來源，收集更多不同場景與條件的影像，以提升訓練資料分布的多樣性","C":"為了提升資料處理吞吐量（Throughput），預先將影像轉為固定特徵並快取（Cache），反覆使用相同訓練資料以加速訓練流程","D":"在資料前處理階段進行資料清理，移除標註錯誤或品質不佳的影像資料"},"answer":"C","figures":[],"explanation":{"approach":"題目要求找出「無法有效改善、甚至可能使過擬合惡化」的資料處理調整。將影像預先轉為固定特徵並快取、反覆使用相同訓練資料，等於犧牲了原始影像的多樣性與訓練時的隨機變化（例如失去動態資料增強的機會），讓模型更容易記憶固定特徵組合，反而可能加劇過擬合，而非改善它。","options":{"A":"資料增強能在訓練時動態產生多樣化樣本，提升資料多樣性、降低模型死記硬背訓練樣本的傾向，是改善過擬合的有效手段，非本題答案。","B":"擴充不同場景與條件的影像資料能提升訓練資料分布的代表性與多樣性，是改善過擬合的正向作法，非本題答案。","C":"正確（本題答案）。將影像預先轉為固定特徵並快取、反覆重複使用相同的固定訓練資料，會降低訓練過程的資料多樣性與隨機性，讓模型更容易記憶而非泛化，無法改善甚至可能加劇過擬合。","D":"移除標註錯誤或品質不佳的影像屬於資料清理，有助於減少雜訊對模型學習的干擾，是改善模型表現（含過擬合問題）的正向作法，非本題答案。"}},"origin":"past"},{"id":"middle_115-1_s2_q16","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":16,"context":null,"stem":"某工程師在建立推薦系統時，評估使用奇異值分解（Singular Value Decomposition, SVD）對使用者-商品評分矩陣進行潛在語意分析（Latent Semantic Analysis, LSA）。關於SVD的數學性質，下列何者不正確？","options":{"A":"SVD只能分解方陣（Square Matrix），無法應用於行列數不相等的長方形矩陣","B":"SVD常用於降維（Dimensionality Reduction），透過保留最大的k個奇異值來近似原始矩陣（截斷SVD）","C":"SVD比PCA更一般化，因為PCA可視為對資料的共變異數矩陣（Covariance Matrix）進行的特殊SVD運算","D":"LSA是SVD在文字-文件矩陣上的應用，透過截斷SVD捕捉詞語與文件的潛在語意關係"},"answer":"A","figures":[],"explanation":{"approach":"SVD（奇異值分解）可應用於「任意」m×n矩陣（不限方陣），將矩陣分解為 U、Σ、Vᵀ的乘積，這也是它能廣泛用於降維、LSA等長方形資料矩陣（如使用者-商品評分矩陣、詞語-文件矩陣）的原因。題目問「何者不正確」，即找出違反SVD基本數學性質的敘述。","options":{"A":"不正確（本題答案）。SVD可應用於任意行列數的矩陣（含長方形矩陣），並非只能分解方陣，這是SVD相較於特徵分解（Eigendecomposition，僅限方陣）的重要優勢與差異點。","B":"正確敘述。截斷SVD保留前k個最大奇異值以近似原始矩陣，是SVD用於降維的標準作法。","C":"正確敘述。PCA可視為對資料共變異數矩陣進行特徵分解（等價於對中心化資料矩陣做SVD）的特例，SVD確實較PCA更一般化，可直接處理非方陣資料。","D":"正確敘述。LSA正是將SVD應用於詞語-文件矩陣，透過截斷SVD萃取詞語與文件間的潛在語意結構。"}},"origin":"past"},{"id":"middle_115-1_s2_q17","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":17,"context":null,"stem":"某醫院欲建立一套加護病房（ICU）敗血症預測模型，資料來自120位病患之生命徵象（如心率、血壓、體溫等），每5分鐘記錄一次。資料中敗血症相關樣本僅佔3.2%，屬於高度不平衡資料。在資料檢查過程中發現數項問題，包括血氧資料會出現10至30分鐘的連續缺失、部分血壓感測器隨使用時間產生系統性偏高（感測器漂移）、敗血症標註時間存在約±2小時誤差，以及不同病患之正常生命徵象基準差異甚大。請問下列何種資料處理與建模方式最為適當？","options":{"A":"將缺失值以整體平均填補，未額外處理感測器漂移，並將敗血症標註區間由6小時擴大至8小時以涵蓋時間誤差，模型評估採用ROC-AUC作為主要指標","B":"對缺失值進行線性插值，若連續缺失時間過長則刪除該段資料，並以Z-score標準化處理感測器漂移，交叉驗證採隨機切分，未避免同一病患資料同時出現在訓練與測試集中","C":"刪除所有含缺失值之資料，對資料進行Min-Max正規化處理，未考慮病患間差異直接建模，並以Accuracy作為評估指標，交叉驗證採分層K-Fold方式進行","D":"對缺失值採前向填補並加入缺失指標特徵，利用感測器72小時滾動中位數進行漂移校正，並處理標註雜訊，同時以個別病患基準建模，交叉驗證採病患分組，評估採PR-AUC與Recall指標"},"answer":"D","figures":[],"explanation":{"approach":"此ICU敗血症預測情境同時存在多項資料品質與建模陷阱：時序缺失、感測器系統性偏移（漂移）、標註時間誤差、病患間基準差異，以及高度不平衡資料。最適當的作法須逐一對症下藥：前向填補並加缺失指標特徵保留缺失資訊、以滾動中位數校正感測器漂移、處理標註雜訊、依個別病患基準建模，並用病患分組交叉驗證避免同一病患資料同時出現於訓練與測試集（資料洩漏），同時以PR-AUC與Recall取代對極度不平衡資料不敏感的Accuracy或單純ROC-AUC。","options":{"A":"以整體平均值填補會忽略個別病患的生命徵象差異，未處理感測器漂移問題，任意將標註區間由6小時擴大至8小時缺乏依據，且僅用ROC-AUC在高度不平衡資料下容易過度樂觀，未能完整反映少數類（敗血症）的偵測能力。","B":"隨機切分交叉驗證未依病患分組，會讓同一病患資料同時出現在訓練與測試集，造成資料洩漏使評估結果失真；且僅用Z-score標準化無法針對性校正感測器隨時間產生的系統性漂移。","C":"直接刪除所有含缺失值的資料會損失大量資訊且可能產生偏誤（尤其血氧缺失可能與病情本身相關，非隨機缺失）；未考量病患間生命徵象基準差異；且在高度不平衡資料下使用Accuracy作為主要評估指標會嚴重高估模型表現。","D":"正確。前向填補加缺失指標特徵保留缺失資訊、以滾動中位數校正感測器漂移、處理標註雜訊、以個別病患基準建模、採病患分組交叉驗證避免資料洩漏，並以PR-AUC與Recall（而非Accuracy或單獨ROC-AUC）評估高度不平衡資料，是最完整且對症下藥的處理方式。"}},"origin":"past"},{"id":"middle_115-1_s2_q18","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":18,"context":null,"stem":"某零售企業的AI工程師正在用關聯規則學習（Association Rule Learning）分析購物籃資料，評估商品A跟商品B之間同時購買的關係。關於「支援度（Support）」、「信賴度（Confidence）」、「提升度（Lift）」三個指標，下列敘述何者正確？","options":{"A":"信賴度=P(A∩B)，即A與B同時出現的機率，範圍[0,1]","B":"支援度=P(B|A)，即A出現時B也出現的條件機率，範圍[0,1]","C":"提升度=P(A∩B) / [P(A)×P(B)]，範圍固定在[0,1]之間","D":"提升度=1表示A與B獨立（無關聯），<1表示負相關，>1表示正向關聯，因此提升度並非數值愈大即代表關聯愈強"},"answer":"D","figures":[],"explanation":{"approach":"三指標定義為：Support(A→B)=P(A∩B)（A、B同時出現的機率）；Confidence(A→B)=P(B|A)（在A出現條件下B也出現的機率）；Lift(A→B)=P(A∩B)/[P(A)×P(B)]，其值域為[0,+∞)，Lift=1表示A、B獨立、<1表示負相關、>1表示正相關，但Lift值大小僅反映關聯方向與強度的相對指標，並不能單純以數值愈大代表關聯「愈強」（仍須配合支援度等指標綜合判斷實際意義）。","options":{"A":"定義錯置。P(A∩B)是支援度（Support）的定義，並非信賴度（Confidence）的定義。","B":"定義錯置。P(B|A)是信賴度（Confidence）的定義，並非支援度（Support）的定義。","C":"提升度（Lift）的值域並非固定在[0,1]之間，其理論上限可超過1、甚至趨向無窮大，並非有界於[0,1]的機率值。","D":"正確。Lift=1代表A與B獨立無關聯，<1代表負相關，>1代表正向關聯；但Lift數值大小僅反映關聯方向與相對程度，並非其值愈大就必然代表關聯性愈強，仍需搭配支援度、樣本數等資訊綜合判斷。"}},"origin":"past"},{"id":"middle_115-1_s2_q19","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":19,"context":null,"stem":"下圖表為電商平台某時段的交易紀錄（共8筆訂單），對圖表內的資料執行Apriori演算法，設定最低支援度為3。請問最終保留下來的最大頻繁項目集為何？","options":{"A":"{A}","B":"{A, D}","C":"{A, B, E}","D":"{B, E}"},"answer":"D","figures":[{"src":"images/middle_115-1_s2_q19_fig1.png","position":"stem"}],"explanation":{"approach":"先計算各單一商品支援度計數（8筆訂單中出現次數）：A=5、B=4、C=2、D=4、E=4，門檻為3，故C（2）不合格出局，剩A、B、D、E為頻繁項目。再檢視兩兩組合：AB=2、AD=2、AE=2、BD=1、DE=1皆低於3不合格，只有BE同時出現於訂單1、3、4、5共4次，達到門檻，是唯一的頻繁二項組合；且因AB、BD等不足以支撐三項組合，無法再擴展出頻繁三項集。因此保留下來項目數最多（最大）的頻繁項目集為{B, E}。","options":{"A":"{A}雖為頻繁項目（支援度5），但其為單一項目集，並非「最大」（項目數最多）的頻繁項目集，因B、E可組成支援度達4的二項頻繁項目集{B,E}。","B":"{A, D}的支援度計數僅2（訂單6、8），低於最低支援度門檻3，並非頻繁項目集。","C":"{A, B, E}的支援度須以AB同時出現次數為上限，AB僅在訂單1、4出現共2次，低於門檻3，故此三項組合不可能是頻繁項目集。","D":"正確。{B, E}在訂單1、3、4、5中同時出現，支援度計數為4，達到最低支援度門檻3，且是項目數最多（2項）的頻繁項目集，故為最終保留的最大頻繁項目集。"}},"origin":"past"},{"id":"middle_115-1_s2_q20","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":20,"context":null,"stem":"某電信公司的AI反詐欺模型在正常交易佔99.5%、詐欺交易僅佔0.5%的類別嚴重不平衡資料集上訓練。若工程師僅以整體準確率（Accuracy）作為模型選擇的唯一指標，最可能產生什麼嚴重問題？","options":{"A":"模型訓練時間會因類別不平衡而大幅增加","B":"一個永遠預測為正常交易的模型即可達到99.5%準確率，但對詐欺交易的召回率為0%，使準確率失去判別能力","C":"類別不平衡會導致模型訓練過程出現梯度爆炸","D":"類別不平衡會直接導致模型過擬合，使測試集表現下降"},"answer":"B","figures":[],"explanation":{"approach":"在正常交易佔99.5%、詐欺僅0.5%的高度不平衡資料下，一個「永遠預測為正常交易」的無效模型即可輕易達到99.5%準確率，但其對真正想偵測的詐欺類別召回率為0%，完全喪失偵測能力。這說明在極度不平衡資料情境下，僅以整體Accuracy作為唯一評估指標會嚴重失去判別模型好壞的能力，應搭配Precision、Recall、F1、PR-AUC等更適合的指標。","options":{"A":"類別不平衡本身不必然直接顯著拉長模型訓練時間，這並非此情境下的主要風險。","B":"正確。永遠預測正常交易的簡單模型即可達99.5%準確率，卻對詐欺交易毫無偵測能力（召回率0%），凸顯僅用Accuracy評估在極度不平衡資料下會失去判別意義，是最嚴重的實務問題。","C":"類別不平衡與梯度爆炸（通常源自網路深度、初始化或學習率設定不當）並無直接因果關係，此為不相關的推論。","D":"類別不平衡不會直接等同於「導致模型過擬合」，過擬合與訓練/驗證表現落差有關，而本題的核心問題是評估指標（Accuracy）在不平衡資料下失去判別力，而非過擬合本身。"}},"origin":"past"},{"id":"middle_115-1_s2_q21","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":21,"context":null,"stem":"某AI平台的資料工程師需要在Apache Spark叢集上，對包含10億筆使用者行為紀錄的RDD/DataFrame計算整體標準差（Standard Deviation）。請問下列哪種策略在分散式環境中最正確且有效率？","options":{"A":"呼叫collect()將所有資料傳回Driver節點的本機記憶體後，再使用Python的statistics.stdev()計算","B":"先對資料進行全域排序（sortBy），再取中間值計算變異數","C":"將資料輸出為CSV，再以Excel的STDEV函數計算","D":"使用DataFrame.agg({'col': 'stddev'})或RDD.aggregate()等分散式統計方法，由各Executor計算局部統計量後再進行彙總"},"answer":"D","figures":[],"explanation":{"approach":"在Spark分散式環境下計算10億筆資料的整體標準差，應善用Spark提供的分散式聚合機制（如DataFrame.agg對欄位計算stddev，或RDD.aggregate），讓各Executor先計算局部統計量，再由框架彙總合併為全域結果，這才是符合分散式運算原則、可擴展且高效的作法。","options":{"A":"collect()會把全部10億筆資料傳回Driver節點的本機記憶體，極可能造成記憶體不足或效能瓶頸，完全違背分散式運算的設計初衷。","B":"計算標準差/變異數不需要對全域資料進行完整排序，全域sortBy在10億筆資料規模下需要昂貴的全量shuffle，效率極差且非必要作法。","C":"10億筆資料的規模遠超Excel可處理的資料列上限與運算能力，將資料輸出為CSV並用Excel計算在此規模下完全不可行。","D":"正確。使用DataFrame.agg或RDD.aggregate等Spark原生分散式統計方法，讓各Executor就地計算局部統計量後再彙總，是分散式環境下計算整體標準差最正確且有效率的策略。"}},"origin":"past"},{"id":"middle_115-1_s2_q22","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":22,"context":null,"stem":"某連鎖便利商店集團欲建立門市未來14天每日銷售額預測模型（500間門市、3年歷史資料）。資料具有明顯的週期性（週末較高）、年度季節性（暑假與年末高峰）及長期成長趨勢，並包含已知節日與不定期事件（如颱風）。在此情境下，關於資料切分與建模策略，何者最適當？","options":{"A":"採隨機切分（80/20），使用傳統時間序列模型建模，刪除節日資料避免極端值影響，並以均方根誤差（RMSE）評估","B":"依時間順序切分（最後90天為測試集），使用具季節性建模能力的時間序列模型並加入節日資訊，不處理不定期事件，以平均絕對百分比誤差（MAPE）評估","C":"依時間順序切分並採前進式驗證（Walk-Forward Validation），結合時間序列分解與機器學習模型，加入時間特徵、滯後與滾動統計特徵，並納入節日與不定期事件資訊，使用均方根誤差（RMSE）與平均絕對百分比誤差（MAPE）評估","D":"依時間順序切分，直接使用深度學習模型建模，不進行特徵工程，所有門市共用模型，以平均絕對誤差（MAE）評估"},"answer":"C","figures":[],"explanation":{"approach":"此預測情境同時具備週期性、年度季節性、長期趨勢，以及已知節日與不定期事件（颱風）等複雜時間特性，最適當的策略須依時間順序切分（尤其採前進式驗證Walk-Forward Validation，貼近真實預測情境），結合時間序列分解與機器學習模型，加入時間、滯後（lag）與滾動統計等特徵，並納入節日與不定期事件資訊，同時以RMSE與MAPE等多指標綜合評估。","options":{"A":"隨機切分（80/20）會破壞時間序列的時間順序（讓未來資料洩漏進訓練集），且刪除節日資料反而丟失重要的季節性訊號，並不適當。","B":"依時間切分並加入節日資訊的方向正確，但完全不處理颱風等不定期事件會遺漏重要影響因子，相較於能同時處理已知與不定期事件的完整方案（C）並非最適當選擇。","C":"正確。依時間順序切分並採前進式驗證貼近真實預測情境，結合時間序列分解與機器學習模型、豐富的時間/滯後/滾動特徵，並納入節日與不定期事件資訊，同時使用RMSE與MAPE多指標評估，最完整地對應此情境的所有時間特性。","D":"完全不進行特徵工程且500間門市共用單一模型，會忽略不同門市間的獨特銷售模式與各項已知的季節性/事件資訊，難以有效捕捉題目描述的複雜時間特性。"}},"origin":"past"},{"id":"middle_115-1_s2_q23","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":23,"context":null,"stem":"Receiver Operating Characteristic（ROC）曲線係由單一分類模型在不同決策閾值下形成，並以真陽率（True Positive Rate, TPR）為縱軸、假陽率（False Positive Rate, FPR）為橫軸。請問下圖中四條曲線，何者最不可能是ROC曲線？","options":{"A":"水平線A","B":"曲線B","C":"曲線C","D":"斜直線D"},"answer":"C","figures":[{"src":"images/middle_115-1_s2_q23_fig1.png","position":"stem"}],"explanation":{"approach":"ROC曲線的TPR與FPR皆會隨決策閾值單調變化（不遞減），因此有效的ROC曲線必須是從(0,0)到(1,1)呈非遞減（monotonically non-decreasing）走勢。圖中曲線C呈現先上升、中途下降又再上升的波浪狀非單調走勢，違反了ROC曲線應具備的單調非遞減特性，因此最不可能是有效的ROC曲線。","options":{"A":"水平線A雖形狀特殊（趨近理想分類器樣式，快速達到TPR=1後維持平坦至(1,1)），但整體仍維持非遞減走勢，符合ROC曲線的基本特性。","B":"曲線B呈平滑上凸（concave）走勢，是典型表現良好分類器的ROC曲線形狀，符合單調非遞減特性。","C":"正確（本題答案）。曲線C中途出現下降再回升的波浪狀走勢，屬於非單調變化，違反ROC曲線隨閾值變化應TPR、FPR皆非遞減的基本性質，因此最不可能是實際的ROC曲線。","D":"斜直線D為對角線，代表隨機猜測（無鑑別力）分類器的基準ROC曲線，本身仍是單調非遞減的有效ROC曲線型態。"}},"origin":"past"},{"id":"middle_115-1_s2_q24","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":24,"context":null,"stem":"某AI工程師評估客戶滿意度評分（1–5分，含有明顯離群值）與退款率（連續型比例變數）之間的相關性，考慮使用皮爾森（Pearson）、斯皮爾曼（Spearman）或肯德爾（Kendall）相關係數。關於三者的特性比較，下列敘述何者不正確？","options":{"A":"皮爾森衡量兩個連續變數間的線性關係強度；斯皮爾曼與肯德爾基於排名（Rank）計算，對非線性單調關係也適用","B":"斯皮爾曼相關係數的計算公式等價於皮爾森，只是將原始數值替換為其排名後代入計算","C":"與肯德爾相比，斯皮爾曼對離群值的穩健度更強","D":"三者的數值範圍（相關係數區間）皆相同，均在[-1, 1]之間"},"answer":"C","figures":[],"explanation":{"approach":"皮爾森相關係數衡量兩連續變數間的線性關係，斯皮爾曼與肯德爾則基於排名（Rank）計算、可捕捉非線性但單調的關係；斯皮爾曼的公式本質上等同於將原始數值轉為排名後再代入皮爾森公式計算。就對離群值的穩健性而言，一般認為肯德爾（基於一致對/不一致對計算）較斯皮爾曼（基於排名差平方，結構上更接近皮爾森）更為穩健，此為本題「不正確」的敘述所在。","options":{"A":"正確敘述。皮爾森衡量線性關係，斯皮爾曼與肯德爾基於排名，能捕捉非線性但單調的關係，此描述符合三者特性差異。","B":"正確敘述。斯皮爾曼相關係數確實可理解為將資料轉換為排名後，代入皮爾森相關係數公式計算所得的結果。","C":"不正確（本題答案）。一般而言，肯德爾相關係數因基於一致對/不一致對的計算方式，對離群值的穩健性通常優於斯皮爾曼（斯皮爾曼結構上接近對排名值做皮爾森計算），此敘述將兩者穩健度高低說反了。","D":"正確敘述。皮爾森、斯皮爾曼、肯德爾三者的相關係數數值範圍皆介於[-1, 1]之間。"}},"origin":"past"},{"id":"middle_115-1_s2_q25","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":25,"context":null,"stem":"某金融機構導入AI模型進行信用卡詐欺偵測，由於詐欺交易極為稀少（約佔全部交易0.3%），因此模型在測試階段得到99.6%準確率（Accuracy），被初步認定為「高效模型」。然而在實際上線後，風控部門發現模型幾乎無法攔截詐欺交易，且大量誤判正常交易。經進一步檢查，發現資料極度不平衡，但模型仍以Accuracy作為主要優化與評估指標。在此情境下，下列何者最適當的改善方向？","options":{"A":"持續優化Accuracy指標以提升整體分類正確率","B":"改用精確率（Precision）作為主要評估指標以降低誤報","C":"引入Class Weight或Cost-sensitive Learning調整損失函數","D":"移除少數類資料以提升模型穩定性與收斂速度"},"answer":"C","figures":[],"explanation":{"approach":"在詐欺交易僅佔0.3%的極度不平衡資料下，模型僅用Accuracy作為主要優化與評估指標會產生「準確率悖論」，導致模型偏向多數類（正常交易）而幾乎無法偵測詐欺。最根本的改善方向是從模型訓練層面著手，導入Class Weight或Cost-sensitive Learning，讓損失函數對少數類（詐欺）錯誤給予更高懲罰權重，促使模型真正學習偵測稀少的詐欺樣本。","options":{"A":"持續優化Accuracy正是導致目前問題的根本原因，繼續以此為主要目標只會延續模型偏向多數類、忽略少數類的缺陷，並非改善方向。","B":"僅改用Precision作為評估指標只是換一個同樣可能被不平衡資料誤導的單一指標（且Precision高不代表Recall/攔截能力足夠），並未實際調整模型訓練方式讓其更有效偵測詐欺，並非最根本的改善作法。","C":"正確。導入Class Weight或Cost-sensitive Learning可直接在模型訓練的損失函數層面加重少數類（詐欺）樣本的權重，從根本上改善模型對極度不平衡資料中少數類的學習與偵測能力，是最適當的改善方向。","D":"移除少數類資料只會讓已經稀少的詐欺樣本更加不足，模型將更難學習偵測詐欺特徵，是與改善目標背道而馳的作法。"}},"origin":"past"},{"id":"middle_115-1_s2_q26","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":26,"context":null,"stem":"某電商推薦系統的資料工程師在建構模型特徵時，將使用者的訂單UNIX時間戳記（連續數值）轉換為「早晨（6–12時）、下午（12–18時）、夜晚（18–6時）」三個區間類別，以讓推薦模型更容易學習消費時段規律。在資料前處理中，這種將連續數值轉換為有序類別的操作最精確的名稱為何？","options":{"A":"特徵離散化（Feature Discretization）","B":"特徵縮放（Feature Scaling）","C":"數據降維（Dimensionality Reduction）","D":"One-Hot編碼（One-Hot Encoding）"},"answer":"A","figures":[],"explanation":{"approach":"將連續的UNIX時間戳記依時間區間切分為「早晨／下午／夜晚」等具順序意義的類別區間，這種把連續數值依規則切分成類別區間的操作，最精確的名稱是特徵離散化（Feature Discretization／Binning）。","options":{"A":"正確。將連續數值依區間規則切分為有限個類別（區間）的操作，即為特徵離散化（Feature Discretization），符合題目描述的轉換方式。","B":"特徵縮放是調整連續數值的尺度範圍（如標準化、正規化），並非將連續值切分為類別區間，與題目描述的操作不符。","C":"數據降維是減少特徵維度（如PCA），並非將單一連續特徵切分為類別區間，與題目描述的操作性質不同。","D":"One-Hot編碼是將既有的類別變數轉換為二元虛擬變數的後續處理步驟，題目所描述「將連續數值轉換為有序類別」的核心動作是離散化本身，而非One-Hot編碼。"}},"origin":"past"},{"id":"middle_115-1_s2_q27","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":27,"context":null,"stem":"某AI產品的商業分析師在準備月度報告時，需要在單一頁面上同時呈現1,000位使用者的留存率、活躍程度與付費轉換率三項指標，以讓決策層快速掌握整體趨勢。若依據Edward Tufte的資料視覺化原則中資料密度（Data Density）的概念，下列何者最符合此原則的設計方向？","options":{"A":"將1,000筆資料分散至多張圖表（每張顯示約100筆），避免單一圖表資訊過載","B":"移除所有圖例、軸標籤與輔助線等非資料墨水（Non-data Ink），使版面最簡潔","C":"在圖表中加入大量裝飾性元素（如色塊、陰影、3D效果），使視覺效果更豐富","D":"在有限頁面空間中呈現盡可能多的有效資料資訊，同時維持可讀性與清楚的視覺層次"},"answer":"D","figures":[],"explanation":{"approach":"Edward Tufte的「資料密度（Data Density）」原則強調應在有限的頁面空間中盡可能呈現更多有效的資料資訊，同時仍須維持圖表的可讀性與清晰的視覺層次，而非一味追求簡化或分散資訊，這與另一相關但不同的「資料墨水比（Data-Ink Ratio）」原則（去除非必要裝飾）有所區別。","options":{"A":"將資料分散至多張圖表反而降低了單一視覺呈現的資訊密度，並非資料密度原則所強調的「在有限空間內呈現盡可能多的有效資訊」。","B":"移除圖例、軸標籤等輔助元素涉及的是「資料墨水比」（Data-Ink Ratio，去除非資料墨水）的概念，並非「資料密度」原則的核心訴求，且過度移除必要標示反而可能損害可讀性。","C":"加入大量裝飾性元素（色塊、陰影、3D效果）屬於Tufte所批評的「圖表垃圾（Chart Junk）」，會降低資訊傳達效率，與資料密度原則背道而馳。","D":"正確。在有限頁面空間中呈現盡可能多的有效資料資訊，同時兼顧可讀性與清楚的視覺層次，正是Tufte資料密度原則的核心精神。"}},"origin":"past"},{"id":"middle_115-1_s2_q28","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":28,"context":null,"stem":"行銷團隊比較三種廣告投放管道（A／B／C）的轉換率差異，原始數據如下，A：3.2%、B：3.8%、C：4.0%。若設計圖表時將y軸刻意截斷（不從0開始），造成視覺差異放大。此做法最可能產生的問題為何？","options":{"A":"提升資料解析效率並減少認知負擔","B":"增強小幅差異的可視化辨識能力","C":"造成視覺誤導並放大實際差異感","D":"提升圖表計算準確性與數據正確性"},"answer":"C","figures":[],"explanation":{"approach":"將y軸刻意截斷、不從0開始，會使原本微小的數值差異（如3.2%、3.8%、4.0%）在視覺上被不成比例地放大，造成觀看者誤判差異程度，是常見的資料視覺化誤導手法，違反誠實呈現資料的原則。","options":{"A":"截斷y軸並非為了提升資料解析效率，其效果是扭曲視覺比例造成誤導，而非合理減少認知負擔。","B":"此描述以正面詞彙包裝，但實質上「增強差異辨識」正是透過不成比例放大差異所產生的視覺誤導效果，並非中性或有益的呈現方式。","C":"正確。將y軸截斷會使實際差異在視覺上被不成比例放大，造成觀看者誤判各管道間轉換率差異的真實程度，屬於典型的視覺誤導手法。","D":"截斷y軸只是改變視覺呈現比例，並不會提升圖表運算或數據本身的準確性，兩者無關。"}},"origin":"past"},{"id":"middle_115-1_s2_q29","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":29,"context":null,"stem":"某AI系統的維運工程師需要在儀表板上呈現「模型推論延遲（ms）隨時間的變化趨勢」，以便即時監控服務水準協議（Service Level Agreement, SLA）是否達標（P99<200ms）。在資料視覺化的圖表類型選擇上，下列哪種圖表最適合呈現連續數值隨時間變化的趨勢？","options":{"A":"面積圖（Area Chart）","B":"散佈圖（Scatter Plot）","C":"長條圖（Bar Chart）","D":"折線圖（Line Plot）"},"answer":"D","figures":[],"explanation":{"approach":"要呈現「連續數值（推論延遲）隨時間變化的趨勢」以便監控SLA是否達標，折線圖（Line Plot）是最適合呈現連續時間序列資料變化趨勢的圖表類型，能清楚展現數值隨時間推移的走勢與波動。","options":{"A":"面積圖較常用於強調數量的累積或量體大小，對於單純呈現延遲隨時間變化的趨勢而言不如折線圖直觀簡潔。","B":"散佈圖主要用於呈現兩變數間的分布關係或相關性，缺乏連接線條難以清楚呈現隨時間演進的連續趨勢走向。","C":"長條圖較適合呈現離散類別間的數值比較，並非呈現連續時間序列變化趨勢的最佳選擇。","D":"正確。折線圖以連續線條連接各時間點的數值，最能清楚呈現連續數值（如推論延遲）隨時間變化的趨勢，適合用於SLA即時監控情境。"}},"origin":"past"},{"id":"middle_115-1_s2_q30","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":30,"context":null,"stem":"訓練資料共5,000萬筆，工程師比較Batch Size=32與Batch Size = 4096的訓練表現，發現大批次（Large Batch）雖然訓練較快，但模型泛化能力較差。從最佳化理論角度，下列何者為此現象最合理的解釋？","options":{"A":"大批次（Large Batch）計算量過大，GPU無法有效處理","B":"大批次（Large Batch）梯度估計更穩定，但容易收斂至局部極小值（Local Minima），導致泛化能力較差","C":"小批次（Small Batch）因隨機性高，更容易發生梯度爆炸（Gradient Explosion）","D":"批次大小（Batch Size）與泛化能力無關，問題出在學習率（Learning Rate）設定"},"answer":"B","figures":[],"explanation":{"approach":"從最佳化理論角度，大批次（Large Batch）訓練時每次更新所用的梯度估計因取樣樣本數較多而更穩定（雜訊較小），但這也使得優化過程較難跳脫尖銳的局部極小值（Sharp Minima），容易收斂在對訓練資料過度貼合、但泛化能力較差的解；相對地，小批次帶來的梯度雜訊有助於跳出尖銳極小值，找到較平坦（Flat Minima）、泛化能力較佳的解，這是文獻中常見用來解釋大批次訓練泛化落差現象的理論觀點。","options":{"A":"現代GPU完全能有效處理Batch Size=4096規模的計算量，計算能力並非造成泛化能力下降的原因。","B":"正確。大批次梯度估計較穩定（雜訊小），但也因此更容易收斂至尖銳的局部極小值，導致模型對訓練資料過度貼合、在新資料上的泛化能力較差，是解釋此現象的合理理論觀點。","C":"小批次因隨機性較高，一般與梯度爆炸（通常源於網路深度、權重初始化或學習率過大等因素）並無直接關聯，此為不相關的推論。","D":"大量實證與理論研究已顯示Batch Size與模型泛化能力確實存在關聯，並非與泛化能力無關、單純只是學習率設定問題。"}},"origin":"past"},{"id":"middle_115-1_s2_q31","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":31,"context":null,"stem":"某公司中，A團隊負責信用評分模型，B團隊負責詐欺偵測模型，兩團隊皆需要「使用者過去30天交易行為」資料，但各自會進行特徵工程與後續工作。以公司整體管理角度，下列何者為導入統一管理與共用特徵的主要目的？","options":{"A":"模型推論延遲過高，導致線上服務回應時間不符合系統即時性需求與使用體驗要求","B":"降低跨團隊重複開發的維護成本","C":"訓練資料儲存空間不足，造成歷史資料保存與批次訓練流程效率下降問題","D":"模型版本管理混亂，導致不同模型部署與回溯分析困難並增加維運複雜度"},"answer":"B","figures":[],"explanation":{"approach":"A、B兩團隊皆需要相同的「使用者過去30天交易行為」資料並各自進行特徵工程，若缺乏統一管理，容易導致相同或相似特徵在不同團隊間被重複開發與維護。從公司整體管理角度，導入統一的特徵管理（Feature Store）與共用機制，主要目的即在於降低這種跨團隊重複開發所造成的維護成本。","options":{"A":"題目情境著重於「兩團隊各自重複進行特徵工程」的資源浪費問題，並未特別提及模型推論延遲過高或即時性不符需求的問題，此非統一管理共用特徵的主要目的。","B":"正確。兩團隊使用相同基礎資料卻各自重複進行特徵工程，統一管理與共用特徵可避免重複勞動與版本分歧，主要目的即在於降低跨團隊重複開發所造成的維護成本。","C":"題目情境的核心問題並非儲存空間不足，而是特徵工程重複開發造成的維護負擔，此非導入統一管理的主要目的。","D":"題目情境聚焦於特徵開發的重複性問題，而非模型版本管理混亂或部署回溯困難的議題，此非本題所述情境導入共用特徵管理的主要目的。"}},"origin":"past"},{"id":"middle_115-1_s2_q32","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":32,"context":null,"stem":"某銀行建置貸款違約預測模型，資料共50,000筆，其中違約樣本僅800筆（佔1.6%）。在模型建置流程中，先對整體資料使用SMOTE對少數類進行過採樣，之後再進行訓練／測試切分，並訓練輕量梯度提升機（LightGBM）模型，並以AUC-ROC評估模型表現。模型在測試集的AUC-ROC達到0.91，團隊認為模型表現良好，準備上線部署。在模型審查過程中，下列何者為使測試集評估結果失真的主要原因？","options":{"A":"SMOTE不適合用於金融違約預測場景，此類高風險業務應一律採用class_weight調整損失函數，而非對資料本身進行過採樣","B":"SMOTE的過採樣操作在訓練/測試切分之前即對全體資料執行，導致合成樣本資訊洩漏至測試集，使AUC-ROC 0.91虛高而不可信","C":"AUC-ROC在1.6%的不平衡場景下過度樂觀，應改用PR-AUC作為評估指標，其餘流程均正確","D":"LightGBM本身已內建處理不平衡的機制，與SMOTE同時使用會造成少數類過度補償，導致過多誤判"},"answer":"B","figures":[],"explanation":{"approach":"此流程的關鍵錯誤在於SMOTE過採樣是在「訓練/測試切分之前」對全體資料執行，使得部分基於少數類樣本合成出的新樣本，其資訊可能滲透進入之後劃分出的測試集中，造成資料洩漏，使測試集的AUC-ROC 0.91產生虛高、不可信的評估結果，並非模型真實的泛化表現。","options":{"A":"SMOTE並非「不適合」用於金融違約預測場景而必須一律改用class_weight，SMOTE本身是合理常用的技術，問題出在其執行的時機（切分前 vs 切分後），而非該技術本身不適用。","B":"正確。SMOTE的過採樣操作在訓練/測試切分之前即對全體資料執行，使合成樣本資訊有機會滲入之後劃分出的測試集中，造成資料洩漏，導致AUC-ROC 0.91的評估結果虛高、失去可信度。","C":"在1.6%極度不平衡下改用PR-AUC確實是較合適的評估指標調整方向，但這並非本題「測試集評估結果失真」的『主要』原因，主要原因在於SMOTE於切分前執行所造成的資料洩漏，而非僅止於評估指標選擇不當，且題目說「其餘流程均正確」與實際情形不符。","D":"LightGBM本身並不會自動處理類別不平衡（除非額外設定如scale_pos_weight等參數），與SMOTE同時使用「造成少數類過度補償」並非此情境測試集結果失真的根本原因，根本原因在於資料洩漏。"}},"origin":"past"},{"id":"middle_115-1_s2_q33","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":33,"context":null,"stem":"某線上書店希望建立一個多類別書籍推薦模型，根據讀者的「年齡、性別、過去購書類別偏好評分」等特徵，預測讀者下次最可能購買的書籍主題（共8類）。資料已完整標註，且資料量達數十萬筆。在模型選型上，除了預測準確率外，也需考量模型訓練效率、可擴充性，並需支援快速訓練與線上部署。請問下列哪種方法最適合此情境？","options":{"A":"多類別羅吉斯迴歸（Multinomial Logistic Regression）","B":"支援向量機（SVM）搭配One-vs-One","C":"K-means分群後將群集標籤作為分類結果","D":"主成分分析（PCA）後再以最大主成分作為分類依據"},"answer":"A","figures":[],"explanation":{"approach":"此情境需要對大規模已標註資料進行8類別的監督式分類預測，同時兼顧準確率、訓練效率、可擴充性及支援快速訓練與線上部署。多類別羅吉斯迴歸（Multinomial Logistic Regression）原生支援多類別分類、模型結構簡單、訓練與推論速度快、易於擴充與部署，最符合此情境的整體需求。","options":{"A":"正確。多類別羅吉斯迴歸原生支援多類別分類問題，模型輕量、訓練效率高、易擴充也易於快速部署，最符合題目對效率、可擴充性與線上部署的多重要求。","B":"SVM搭配One-vs-One在8個類別下需訓練C(8,2)=28個成對分類器，訓練與部署的計算複雜度明顯較高，相較之下擴充性與訓練效率不如多類別羅吉斯迴歸。","C":"K-means是非監督式分群方法，其分群結果不必然對應到實際已標註的購書主題類別，並非設計用來進行監督式的多類別預測任務。","D":"PCA是降維技術，「以最大主成分作為分類依據」本身並非一套有效的監督式分類方法，無法直接對應到實際的標註類別進行預測。"}},"origin":"past"},{"id":"middle_115-1_s2_q34","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":34,"context":null,"stem":"某電商平台希望建立二元分類模型，根據商品的「價格區間、品牌、顏色、材質」等特徵，將商品分類為「高銷量（1）」或「低銷量（0）」。同時希望模型輸出具備可解釋的機率（如P=0.73表示73%機率為高銷量）。請問下列哪種方法最適合？","options":{"A":"K-means分群（K-means Clustering）","B":"決策樹迴歸（Decision Tree Regression）","C":"羅吉斯迴歸（Logistic Regression）","D":"線性迴歸（Linear Regression）"},"answer":"C","figures":[],"explanation":{"approach":"此情境需要二元分類（高銷量/低銷量），同時要求模型輸出具可解釋意義的機率值（如P=0.73代表73%機率為高銷量）。羅吉斯迴歸（Logistic Regression）透過Sigmoid函數將線性組合轉換為[0,1]區間的機率輸出，天生即適合二元分類且具備機率可解釋性，最符合此情境需求。","options":{"A":"K-means為非監督式分群演算法，並不使用「高銷量／低銷量」的標籤進行監督式學習，也不會輸出屬於某類別的機率值。","B":"決策樹迴歸屬於迴歸方法，輸出為連續數值，並非專為二元分類任務設計，也不天然輸出符合機率意義（0至1、加總為1）的分類機率。","C":"正確。羅吉斯迴歸透過Sigmoid函數將預測結果轉換為[0,1]區間的機率，天生適用於二元分類並具備可解釋的機率輸出，完全符合題目「二元分類且需輸出可解釋機率」的要求。","D":"線性迴歸輸出為不受限的連續數值（可能小於0或大於1），並不適合直接作為二元分類的機率或類別預測，不符合此情境需求。"}},"origin":"past"},{"id":"middle_115-1_s2_q35","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":35,"context":null,"stem":"某工程師在開發一個以Transformer為基礎的文本分類模型時，發現模型對於詞語順序的變化不夠敏感，影響語意判斷效果。請問在Transformer架構中，位置編碼（PositionalEncoding）的主要作用為何？","options":{"A":"在詞嵌入（Embedding）中加入隨機擾動，以提升模型對輸入變化的泛化能力","B":"在注意力機制中加入遮罩（Mask），限制模型只能關注部分詞語","C":"將輸入序列轉換為可同時運算的向量表示，以提升計算效率","D":"在詞的向量表示中加入位置資訊，使模型能區分序列中不同位置的詞語"},"answer":"D","figures":[],"explanation":{"approach":"Transformer的自注意力機制（Self-Attention）本身對輸入序列中詞語的排列順序不具備天生的敏感性（具有排列不變性），因此需要額外加入位置編碼（Positional Encoding），將位置資訊注入詞嵌入向量中，使模型能夠區分序列中不同位置的詞語，進而正確理解語序所隱含的語意。","options":{"A":"位置編碼並非在詞嵌入中加入隨機擾動以提升泛化能力，而是有規律地（如正餘弦函數）注入固定的位置資訊，兩者目的與作法皆不同。","B":"在注意力機制中加入遮罩（Mask，如因果遮罩）限制模型只能關注部分詞語，這是遮罩機制的作用，並非位置編碼的功能。","C":"將輸入序列轉換為可平行運算的向量表示是Self-Attention機制本身（相對於RNN序列化計算）帶來的效率優勢，並非位置編碼的主要作用。","D":"正確。位置編碼將位置資訊加入詞的向量表示中，使原本對順序不敏感的注意力機制得以區分序列中不同位置的詞語，進而提升模型對語序的判斷能力，正是其設計目的。"}},"origin":"past"},{"id":"middle_115-1_s2_q36","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":36,"context":null,"stem":"某AI系統架構師正在為一個電子商務資料湖（Data Lake）設計系統。該資料湖儲存數百億筆使用者點擊紀錄，並作為企業主要的分析資料來源。系統需讓非技術背景的行銷人員能以自然語言查詢數據洞察（如：上個月台北市購買3C產品的女性轉換率為何？），同時滿足高精確性、可擴展性，支援資料庫層級的權限控管與查詢審計，並確保查詢結果可由資料庫引擎精確執行。在此情境下，下列何者為最適合的系統架構？","options":{"A":"協同過濾（Collaborative Filtering）：根據歷史查詢推薦相似問題的答案，無法執行新問題的即時計算","B":"檢索增強生成（RAG）：讓LLM檢索相關資料後生成回答，但無法可靠執行大規模數值聚合與精確統計查詢","C":"生成對抗網路（GAN）：用於生成合成資料或模擬數據分佈，可用於資料擴增，但不適合即時查詢與資料庫聚合運算","D":"Text-to-SQL Agent：由LLM將自然語言轉換為SQL查詢，交由分散式資料庫執行，兼顧自然語言彈性與資料查詢精確性"},"answer":"D","figures":[],"explanation":{"approach":"此情境需要讓非技術人員以自然語言查詢資料，同時要求高精確性、可擴展性、支援資料庫層級的權限控管與查詢審計，並確保結果能被資料庫引擎精確執行。Text-to-SQL Agent讓LLM負責將自然語言轉換為結構化SQL查詢，再交由分散式資料庫引擎精確執行，兼顧了自然語言的彈性與資料庫查詢應有的精確性、權限控管與可審計性，是最適合的架構。","options":{"A":"協同過濾是推薦系統技術，用於根據歷史行為推薦相似項目，並非設計用來處理即時自然語言查詢與精確數值聚合運算的架構。","B":"RAG讓LLM檢索相關文字資料後生成回答，雖能處理自然語言問答，但難以可靠地執行大規模、精確的數值聚合與統計查詢，無法保證資料庫級的精確性。","C":"GAN是生成對抗網路，主要用於生成合成資料或模擬資料分佈，與即時自然語言查詢及精確資料庫聚合運算的需求完全無關。","D":"正確。Text-to-SQL Agent由LLM將自然語言轉換為SQL查詢，並交由分散式資料庫引擎精確執行，能同時兼顧自然語言查詢的彈性與資料庫層級的精確性、權限控管及查詢審計需求，最符合此情境。"}},"origin":"past"},{"id":"middle_115-1_s2_q37","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":37,"context":null,"stem":"某金融機構將訓練好的信用評分模型開放API供合作夥伴查詢。資安團隊警告此設計可能遭受成員推斷攻擊（Membership Inference Attack）。下列何者最準確說明攻擊原理與對應防禦？","options":{"A":"利用模型對訓練樣本的高信心輸出判斷其是否屬於訓練集；以差分隱私或降低輸出信心防禦","B":"利用查詢次數與回應頻率差異判斷資料是否在訓練集中；以限制查詢次數防禦","C":"透過模型輸出推測輸入的敏感特徵；以限制輸出資訊防禦","D":"透過大量查詢建立替代模型模擬目標模型；以限制模型存取防禦"},"answer":"A","figures":[],"explanation":{"approach":"成員推斷攻擊（Membership Inference Attack）的原理是攻擊者利用模型對「曾用於訓練」的樣本，通常會輸出較高信心度（或較低損失）的特性，來推斷某筆特定資料是否曾出現在訓練集中；常見的防禦方式包括採用差分隱私（Differential Privacy）訓練，或降低模型輸出信心資訊的細緻程度（如僅回傳類別而非完整機率分布），以縮小攻擊者可利用的資訊差異。","options":{"A":"正確。攻擊者利用模型對訓練樣本輸出信心度較高的特性來判斷該樣本是否屬於訓練集，這正是成員推斷攻擊的核心原理；以差分隱私訓練或降低輸出信心資訊的細緻度，是公認有效的防禦方式。","B":"以查詢次數與回應頻率差異來判斷資料是否在訓練集中，並非成員推斷攻擊的標準定義與原理，且限制查詢次數並非其對應的核心防禦手段。","C":"透過模型輸出推測輸入的敏感特徵，描述的是模型反演攻擊（Model Inversion Attack）的原理，並非成員推斷攻擊。","D":"透過大量查詢建立替代模型模擬目標模型，描述的是模型萃取／竊取攻擊（Model Extraction Attack）的原理，並非成員推斷攻擊。"}},"origin":"past"},{"id":"middle_115-1_s2_q38","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":38,"context":null,"stem":"某AI平台的資料治理工程師正在評估三種去識別化技術的適用場景與強度：K匿名（K-anonymity）、差分隱私合成資料（Differential Privacy Synthetic Data）、亂數回應機制（Randomized Response）。下列敘述何者不正確？","options":{"A":"K匿名主要應用於表格型資料，確保每筆記錄在準識別符（Quasi-identifier）組合上至少與K-1筆其他記錄相同，防止個體被唯一識別","B":"差分隱私合成資料是在發布統計查詢結果或訓練模型時直接對原始資料加入雜訊，以確保單一個體的加入或移除不會顯著改變輸出","C":"亂數回應機制讓受訪者以機率性方式回答敏感問題（如：您是否曾逃稅？），賦予個人對答案的可否認性（Plausible Deniability）","D":"三種技術中，只有差分隱私提供可組合且可量化的隱私保證，而K匿名與亂數回應在面對背景知識攻擊或多次查詢時保護能力有限"},"answer":"B","figures":[],"explanation":{"approach":"差分隱私（Differential Privacy）技術通常是在發布統計查詢結果時對「查詢輸出」加入校準過的雜訊，或在模型訓練過程中對梯度加入雜訊（如DP-SGD），藉此確保任一個體資料的加入或移除都不會顯著改變輸出結果；並非直接對原始資料本身加雜訊來產生合成資料，此描述混淆了差分隱私機制實際作用的對象（輸出/梯度）與原始資料本身。","options":{"A":"正確敘述。K匿名要求每筆記錄在準識別符組合上至少與K-1筆其他記錄相同，藉此防止個體被唯一識別，此為K匿名的標準定義。","B":"不正確（本題答案）。差分隱私機制通常是對「統計查詢結果的輸出」或「模型訓練過程中的梯度」加入校準雜訊，而非直接對原始資料本身加雜訊產生合成資料，此敘述混淆了雜訊實際加入的對象。","C":"正確敘述。亂數回應機制讓受訪者以機率性方式作答，使任一單一回答都具備「合理可否認性」，這是其保護敏感問題受訪者隱私的核心設計。","D":"正確敘述。相較於K匿名與亂數回應在面對背景知識攻擊或多次查詢時保護能力有限，差分隱私提供可組合（composable）且可量化（quantifiable）的隱私保證，是三者中理論保證最嚴謹的技術。"}},"origin":"past"},{"id":"middle_115-1_s2_q39","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":39,"context":null,"stem":"在建構自動化資料清洗管線時，工程師撰寫一個用於補齊缺失欄位的Python函式，如下圖所示。當此函式連續處理兩筆獨立的資料（row1與row2）後，請問第二筆資料row2['tags']的內容會為何？","options":{"A":"[\"checked\", \"tags\"]","B":"[]","C":"[\"checked\", \"checked\"]","D":"拋出KeyError錯誤，因為字典中沒有tags鍵值"},"answer":"C","figures":[{"src":"images/middle_115-1_s2_q39_fig1.png","position":"stem"}],"explanation":{"approach":"此為Python常見的「可變預設引數（Mutable Default Argument）」陷阱：函式定義中tags=[]的預設空列表在函式定義時僅建立一次，之後每次呼叫若未傳入tags參數，都會共用同一個列表物件。row1呼叫時該共用列表被append為[\"checked\"]；row2呼叫時仍沿用同一個已被修改過的共用列表，再append一次\"checked\"，故最終row2['tags']變為[\"checked\", \"checked\"]。","options":{"A":"此結果並非可變預設引數陷阱下實際會產生的內容，與程式實際執行邏輯不符。","B":"由於預設列表在函式定義時只建立一次並在多次呼叫間共用，row2呼叫時的tags並非重新初始化的空列表，此選項忽略了可變預設引數會累積修改的特性。","C":"正確。tags=[]的預設列表在函式定義時只建立一次，row1呼叫後該共用列表已變為[\"checked\"]；row2再次呼叫沿用同一物件並再append一次\"checked\"，最終結果為[\"checked\", \"checked\"]。","D":"record['tags'] = tags這行程式碼是以指定（assignment）方式為字典建立/覆寫'tags'鍵值，即使原本字典中沒有該鍵也不會拋出KeyError（KeyError通常發生在讀取不存在的鍵時，而非賦值時）。"}},"origin":"past"},{"id":"middle_115-1_s2_q40","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":40,"context":null,"stem":"下圖為一段分類演算法的pseudocode，請問最可能對應下列哪一種演算法？","options":{"A":"K-近鄰（K-Nearest Neighbors, KNN）","B":"K-means分群（K-means Clustering）","C":"支援向量機（Support Vector Machine, SVM）","D":"隨機森林分類器（Random Forest Classifier）"},"answer":"A","figures":[{"src":"images/middle_115-1_s2_q40_fig1.png","position":"stem"}],"explanation":{"approach":"圖中pseudocode描述的流程為：計算測試點與每個訓練樣本的距離、依距離排序、取前X個最近的樣本標籤、以多數決方式決定預測標籤，此流程正是K-近鄰（KNN）演算法的標準運作方式（利用距離找出最近的K個鄰居並多數決分類）。","options":{"A":"正確。pseudocode逐步計算測試點與所有訓練樣本的距離、排序、取前X個最近鄰居並以多數決標籤作為預測結果，完全對應K-近鄰（KNN）演算法的運作邏輯。","B":"K-means是非監督式分群演算法，透過反覆更新群集中心（centroid）將樣本分派到最近的群集，並不使用「訓練資料標籤」與「測試點多數決分類」的流程，與pseudocode描述不符。","C":"支援向量機（SVM）是透過尋找最大間隔的分隔超平面（可能搭配核函數）進行分類，其運作機制與pseudocode所描述的「計算距離、排序、取K個最近鄰多數決」完全不同。","D":"隨機森林分類器是由多棵決策樹依特徵切分並集成投票組成，其運作方式（樹狀特徵分裂＋多樹投票）與pseudocode描述的距離排序、近鄰多數決機制不同。"}},"origin":"past"},{"id":"middle_115-1_s2_q41","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":41,"context":{"text":"某全球共享乘車平台的資料科學團隊，正針對2025年第四季度進行營收優化與防弊分析專案。團隊希望透過資料分析達成兩項目標：一是預測司機未來收入表現，以支援營運策略與獎勵機制調整；二是希望透過分析裝置與定位回傳資料，辨識潛在異常行為，以降低補貼濫用風險。\n為此，團隊整理出一份司機每日營運資料檔（driver_daily_stats.csv），其中每筆資料代表某位司機於某一天的營運表現與系統回傳摘要資訊。資料欄位如下：\n● driver_id：司機編號\n● daily_earnings：日總收入（單位：美元）\n● region：註冊營運區域（以字串A、B、C表示）\n● app_version：使用的司機端App版本（如v1.0、v2.0）\n● gps_ping_rate：每分鐘回傳GPS訊號的次數\n請根據此資料情境回答第41~44題。","figures":[]},"stem":"資料分析師使用Python檢視daily_earnings欄位的基本統計量，執行以下程式碼（Pandas2以上版本）：輸出結果如下：● mean：223.411306● 50%：128.552462● max：4500.000000若團隊進一步發現daily_earnings欄位約有5%的遺失值，且目前規劃先建立線性迴歸（Linear Regression）模型來預測未來收入。為盡可能保留該欄位原有分布特性，並降低因補值造成的偏差，請問下列哪一種處理方式最為合理？","options":{"A":"df['daily_earnings'].fillna(df['daily_earnings'].mean(), inplace=True)","B":"df['daily_earnings'].fillna(df['daily_earnings'].median(), inplace=True)","C":"df['daily_earnings'].fillna(df['daily_earnings'].max(), inplace=True)","D":"直接刪除所有遺失資料，因數值型欄位不適合進行補值處理"},"answer":"B","figures":[{"src":"images/middle_115-1_s2_q41_fig1.png","position":"stem"}],"explanation":{"approach":"由describe()輸出可見平均數（mean≈223.4）明顯大於中位數（50%≈128.6），且最大值高達4500，顯示daily_earnings欄位存在明顯右偏分布與極端值。在此情況下，若以平均數填補遺失值，會受極端值拉抬而偏離大多數資料的真實水準；改用中位數填補則較能抵抗極端值影響、更貼近資料的典型集中趨勢，是較合理的補值方式。","options":{"A":"在資料明顯右偏、存在極端值（max=4500）的情況下，平均數本身已受極端值影響而偏高，用平均數補值會把這種偏誤帶入所有遺失值，扭曲原本的分布特性。","B":"正確。資料呈右偏分布且平均數受極端值影響明顯偏高，中位數不易受極端值干擾、更能反映資料的典型集中趨勢，以中位數補值可較好地保留原有分布特性並降低偏差。","C":"以最大值（4500，本身即為極端值）填補所有遺失值，會嚴重扭曲資料分布、放大偏誤，是最不合理的補值方式之一。","D":"直接刪除所有遺失資料在僅約5%遺失比例且有更合理補值方法可用的情況下，會不必要地損失資料，並非在此情境下最合理的處理方式。"}},"origin":"past"},{"id":"middle_115-1_s2_q42","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":42,"context":{"text":"某全球共享乘車平台的資料科學團隊，正針對2025年第四季度進行營收優化與防弊分析專案。團隊希望透過資料分析達成兩項目標：一是預測司機未來收入表現，以支援營運策略與獎勵機制調整；二是希望透過分析裝置與定位回傳資料，辨識潛在異常行為，以降低補貼濫用風險。\n為此，團隊整理出一份司機每日營運資料檔（driver_daily_stats.csv），其中每筆資料代表某位司機於某一天的營運表現與系統回傳摘要資訊。資料欄位如下：\n● driver_id：司機編號\n● daily_earnings：日總收入（單位：美元）\n● region：註冊營運區域（以字串A、B、C表示）\n● app_version：使用的司機端App版本（如v1.0、v2.0）\n● gps_ping_rate：每分鐘回傳GPS訊號的次數\n請根據此資料情境回答第41~44題。","figures":[]},"stem":"承上題，團隊在建立預測模型前，先將region（A、B、C區）轉換為整數1、2、3，即採用標籤編碼（Label Encoding）。模型上線測試後發現，線性迴歸模型對於C區（編碼為3）的預測收入出現明顯高估，顯示模型可能將編碼值誤解為具有線性大小關係。若主管要求不得修改原有的特徵編碼方式，必須維持1、2、3的整數表示，但希望從演算法層面降低此類誤解風險，則下列何者最適合作為替代模型？","options":{"A":"羅吉斯迴歸（Logistic Regression）","B":"Ridge迴歸（Ridge Regression）","C":"支援向量機（Support Vector Machine, SVM）搭配線性核函數","D":"隨機森林（Random Forest）"},"answer":"D","figures":[],"explanation":{"approach":"「居住縣市」以標籤編碼（1、2、3）表示ABC三個無序類別，但線性迴歸模型會將此數值視為具有連續且線性大小關係的變數，導致模型誤解C區（編碼3）與收入間存在不成立的線性放大關係，造成明顯高估。在不得更改既有整數編碼的前提下，應改用不依賴特徵間線性假設、能透過閾值切分處理類別型數值的樹狀模型（如隨機森林），以降低此類誤解風險。","options":{"A":"羅吉斯迴歸是分類模型，用於預測類別（如是/否），並非用於預測連續數值型的收入，任務型態本身就與此迴歸預測需求不符。","B":"Ridge迴歸仍是線性模型（僅多了L2正則化），本質上依然會將1、2、3視為具有線性大小關係的數值，無法從演算法層面解決本題所描述的誤解問題。","C":"線性核函數的SVM本質上仍屬於線性模型，同樣會將標籤編碼的整數值視為具有線性關係，無法解決題目所描述的編碼誤解問題。","D":"正確。隨機森林是樹狀集成模型，透過對特徵值進行閾值切分來建立決策規則，不需假設特徵與目標間存在線性關係，能在維持1、2、3整數編碼不變的前提下，從演算法層面降低將編碼值誤解為線性大小關係的風險。"}},"origin":"past"},{"id":"middle_115-1_s2_q43","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":43,"context":{"text":"某全球共享乘車平台的資料科學團隊，正針對2025年第四季度進行營收優化與防弊分析專案。團隊希望透過資料分析達成兩項目標：一是預測司機未來收入表現，以支援營運策略與獎勵機制調整；二是希望透過分析裝置與定位回傳資料，辨識潛在異常行為，以降低補貼濫用風險。\n為此，團隊整理出一份司機每日營運資料檔（driver_daily_stats.csv），其中每筆資料代表某位司機於某一天的營運表現與系統回傳摘要資訊。資料欄位如下：\n● driver_id：司機編號\n● daily_earnings：日總收入（單位：美元）\n● region：註冊營運區域（以字串A、B、C表示）\n● app_version：使用的司機端App版本（如v1.0、v2.0）\n● gps_ping_rate：每分鐘回傳GPS訊號的次數\n請根據此資料情境回答第41~44題。","figures":[]},"stem":"平台安全部門發現，僅有極少數司機（約占總體0.05%）會利用外掛程式竄改gps_ping_rate，以騙取里程補貼。某新進資料科學家訓練了一個二元分類模型，並在報告中指出：「模型整體準確率（Accuracy）高達99.95%，因此可直接上線攔截可疑帳號。」然而，資深工程師檢視後認為，僅憑上述結果（如圖）仍不足以支持模型直接上線。下列何者不是其提出質疑的合理理由？","options":{"A":"在此類極度不平衡的資料中，即使模型永遠預測所有司機皆為正常，整體準確率仍可能高達99.95%","B":"報告中未呈現召回率（Recall），因此模型可能無法有效辨識真正的外掛司機","C":"異常偵測問題不可使用分類模型處理，僅能使用分群或離群值方法","D":"對於少數類比例極低的問題，若僅觀察Accuracy，可能忽略模型對異常樣本的實際偵測能力"},"answer":"C","figures":[{"src":"images/middle_115-1_s2_q43_fig1.png","position":"stem"}],"explanation":{"approach":"此題要找出「並非」資深工程師合理質疑理由的選項。在外掛司機僅佔0.05%的極度不平衡資料下，即使模型永遠預測所有司機正常，Accuracy仍可能高達99.95%，因此僅憑高Accuracy（甚至圖中完美的precision/recall/f1）不足以確認模型真能有效偵測異常，應審慎檢視是否有Recall不足、過度樂觀等問題；但「異常偵測問題不可使用分類模型處理」這個說法本身在方法論上就是錯誤的，分類模型（含監督式方法）本來就是異常/詐欺偵測領域常見且有效的方法之一，並不成立，因此並非合理的質疑理由。","options":{"A":"此為合理的質疑理由。在此類極度不平衡資料中，一個永遠預測「正常」的無效模型也能達到99.95%的高Accuracy，凸顯Accuracy本身可能失去判別意義。","B":"此為合理的質疑理由。若報告未完整揭露Recall等能反映異常偵測能力的指標，僅憑Accuracy難以判斷模型是否真的能有效抓出外掛司機。","C":"不合理（本題答案）。此敘述本身在方法論上是錯誤的：異常/詐欺偵測問題完全可以使用（監督式）分類模型處理，並非僅能使用分群或離群值方法，因此這並非資深工程師應提出的合理質疑理由。","D":"此為合理的質疑理由。對於少數類比例極低的問題，僅觀察Accuracy容易忽略模型對稀少異常樣本的實際偵測能力，是常見且合理的統計質疑點。"}},"origin":"past"},{"id":"middle_115-1_s2_q44","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":44,"context":{"text":"某全球共享乘車平台的資料科學團隊，正針對2025年第四季度進行營收優化與防弊分析專案。團隊希望透過資料分析達成兩項目標：一是預測司機未來收入表現，以支援營運策略與獎勵機制調整；二是希望透過分析裝置與定位回傳資料，辨識潛在異常行為，以降低補貼濫用風險。\n為此，團隊整理出一份司機每日營運資料檔（driver_daily_stats.csv），其中每筆資料代表某位司機於某一天的營運表現與系統回傳摘要資訊。資料欄位如下：\n● driver_id：司機編號\n● daily_earnings：日總收入（單位：美元）\n● region：註冊營運區域（以字串A、B、C表示）\n● app_version：使用的司機端App版本（如v1.0、v2.0）\n● gps_ping_rate：每分鐘回傳GPS訊號的次數\n請根據此資料情境回答第41~44題。","figures":[]},"stem":"針對上述外掛偵測模型，營運長下達最終的商業決策目標如下：「對於作弊行為零容忍。即使誤凍結部分正常司機帳號，後續仍可交由人工覆核；但不能放過任何一個真正的外掛司機。」根據上述目標，團隊在調整模型輸出的決策機率門檻（Threshold，預設為0.5）時，應採取下列何種策略最為合理？","options":{"A":"選擇使模型對作弊者的召回率（Recall）最大化的門檻，通常代表應降低Threshold","B":"選擇使模型精確率（Precision）最大化的門檻，通常代表應提高Threshold","C":"固定使用Threshold=0.5作為預設值，因為調整門檻將破壞演算法原有的訓練平衡","D":"選擇使模型特異度（Specificity）達到100%的門檻，以確保正常司機不會被誤判"},"answer":"A","figures":[],"explanation":{"approach":"營運長設定的商業目標是「零容忍，寧可誤判正常司機也不能放過任何一個真正的外掛司機」，此目標對應到希望盡可能不漏掉任何真正的正例（外掛司機），即要最大化召回率（Recall）。要提升對正例的召回率，通常需要降低判定為「異常」所需的機率門檻（Threshold），讓模型更容易將可疑樣本判為異常（即使因此增加誤判正常司機的風險，但可交由人工覆核處理）。","options":{"A":"正確。營運長要求「不能放過任何一個真正的外掛司機」，對應到應最大化對作弊者的召回率（Recall），通常透過降低Threshold讓模型更容易將可疑樣本判為異常來達成此目標。","B":"最大化精確率（Precision）的作法通常需要提高Threshold，這會讓模型判定異常更保守、更容易漏掉真正的外掛司機（降低Recall），與「零容忍、不放過任何外掛司機」的目標方向相反。","C":"固定使用預設Threshold=0.5並非必要規則，門檻本應依實際商業目標（此處為極大化Recall）調整，「調整門檻會破壞演算法原有訓練平衡」的說法並不成立。","D":"追求特異度（Specificity）達到100%意味著完全不誤判正常司機，這會讓模型判定異常變得極度保守，容易導致許多真正的外掛司機被放過，與題目「不能放過任何一個外掛司機」的優先目標互相矛盾。"}},"origin":"past"},{"id":"middle_115-1_s2_q45","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":45,"context":{"text":"請依照以下情境回答第45~47題。\n資料分析師載入一份電商交易紀錄的Pandas DataFrame df，其欄位包含：OrderID（訂\n單編號）、CustomerID（客戶編號）、Category（商品分類）、Revenue（該筆營收）。此\n外，另有一份客戶資料表customers，包含CustomerID（客戶編號）與Region（所在地\n區）欄位。","figures":[]},"stem":"若分析師想找出「總貢獻營收最高的前3名客戶」，下列Pandas程式碼何者最為精確且高效？","options":{"A":"df.sort_values('Revenue', ascending=False).head(3)['CustomerID']","B":"df.groupby('CustomerID')['Revenue'].max().head(3)","C":"df.groupby('CustomerID')['Revenue'].sum().nlargest(3)","D":"df.value_counts('CustomerID').head(3)"},"answer":"C","figures":[],"explanation":{"approach":"要找出「總貢獻營收最高的前3名客戶」，須先依CustomerID分組並加總（sum）各客戶的Revenue以得到每位客戶的總貢獻營收，再取前3大（nlargest）。df.groupby('CustomerID')['Revenue'].sum().nlargest(3)正確地完成了「先加總、再取前3大」的邏輯，且nlargest的效率通常優於先排序整個Series再取head。","options":{"A":"sort_values('Revenue')是對「原始逐筆訂單」的Revenue排序後取前3筆，僅得到單筆金額最高的3筆訂單，並非依CustomerID加總後的總貢獻營收排名，語意不符題意。","B":"使用.max()取得的是各客戶「單筆最高的一筆訂單金額」，而非該客戶所有訂單加總後的「總貢獻營收」；且未排序即接.head(3)也無法保證取到的是數值最大的前3名。","C":"正確。先以groupby('CustomerID')對Revenue做sum()加總得到各客戶總貢獻營收，再以nlargest(3)取出總營收最高的前3名客戶，精確且相較「排序全部再取頭」通常更有效率。","D":"value_counts()計算的是各CustomerID出現的「筆數（訂單次數）」，並非Revenue金額的加總，與「總貢獻營收最高」的題意完全不符。"}},"origin":"past"},{"id":"middle_115-1_s2_q46","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":46,"context":{"text":"請依照以下情境回答第45~47題。\n資料分析師載入一份電商交易紀錄的Pandas DataFrame df，其欄位包含：OrderID（訂\n單編號）、CustomerID（客戶編號）、Category（商品分類）、Revenue（該筆營收）。此\n外，另有一份客戶資料表customers，包含CustomerID（客戶編號）與Region（所在地\n區）欄位。","figures":[]},"stem":"若分析師只想計算「Electronics（電子產品）」這個特定分類的平均營收，下列何者為最佳的語法？","options":{"A":"df[df['Category'] == 'Electronics']['Revenue'].mean()","B":"df['Category' == 'Electronics']['Revenue'].mean()","C":"df.loc['Electronics', 'Revenue'].mean()","D":"df.filter(items=['Electronics'])['Revenue'].mean()"},"answer":"A","figures":[],"explanation":{"approach":"要篩選出Category為特定值（'Electronics'）的資料列，正確作法是先用布林索引 df['Category'] == 'Electronics' 產生布林遮罩，再以df[遮罩]篩選出對應的資料列，最後取其Revenue欄位計算平均值：df[df['Category'] == 'Electronics']['Revenue'].mean()。","options":{"A":"正確。先以df['Category'] == 'Electronics'產生布林遮罩篩選出符合條件的資料列，再取Revenue欄位計算平均值，是Pandas中篩選特定條件並計算彙總統計的標準且正確寫法。","B":"df['Category' == 'Electronics']會先計算括號內字串比較（'Category'=='Electronics'恆為False），並非對DataFrame欄位值進行條件篩選，此為誤用語法、邏輯錯誤。","C":".loc['Electronics', 'Revenue']是嘗試以'Electronics'作為「索引標籤（列索引）」查找，而非依Category欄位「值」篩選資料列，除非索引本身即為Category（本題並非如此），否則無法正確篩選或會出錯。","D":".filter(items=[...])預設用於依「欄位名稱或索引標籤」篩選欄或列，並非用來依欄位「值」篩選符合條件的資料列，此用法無法正確篩選出Category為Electronics的資料。"}},"origin":"past"},{"id":"middle_115-1_s2_q47","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":47,"context":{"text":"請依照以下情境回答第45~47題。\n資料分析師載入一份電商交易紀錄的Pandas DataFrame df，其欄位包含：OrderID（訂\n單編號）、CustomerID（客戶編號）、Category（商品分類）、Revenue（該筆營收）。此\n外，另有一份客戶資料表customers，包含CustomerID（客戶編號）與Region（所在地\n區）欄位。","figures":[]},"stem":"分析師想將customers表中的Region欄位加入到df交易紀錄中，且「只保留那些在customers表中有對應資料的交易紀錄」。下列哪一種合併方式最正確？","options":{"A":"pd.concat([df, customers], axis=1)","B":"pd.merge(df, customers, on='CustomerID', how='outer')","C":"pd.merge(df, customers, on='CustomerID', how='inner')","D":"df.join(customers, on='CustomerID')"},"answer":"C","figures":[],"explanation":{"approach":"要將customers表的Region欄位加入df，且「只保留在customers表中有對應資料的交易紀錄」，須以CustomerID為鍵進行內部合併（Inner Join），只有內部合併（how='inner'）才會僅保留兩表皆存在對應鍵值的紀錄，符合題目要求。","options":{"A":"pd.concat(axis=1)是依「位置或索引」單純橫向拼接兩個DataFrame，並未依CustomerID這個鍵值進行對應合併，容易造成資料錯位或不正確的合併結果。","B":"how='outer'會保留兩表所有紀錄（含沒有對應資料的列，以NaN填補），並不符合題目「只保留在customers表中有對應資料」的要求。","C":"正確。pd.merge(df, customers, on='CustomerID', how='inner')以CustomerID為鍵進行內部合併，只保留兩表都存在對應資料的交易紀錄，完全符合題目需求。","D":"df.join()預設是依照DataFrame的索引（index）進行合併，而非依照'CustomerID'這個欄位的值進行合併，除非事先將索引設為CustomerID，否則此寫法無法正確依鍵值合併兩表。"}},"origin":"past"},{"id":"middle_115-1_s2_q48","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":48,"context":{"text":"請根據下方資訊回答第48~50題。","figures":["images/middle_115-1_s2_ctx4_fig1.png"]},"stem":"在進行機器學習建模前，資料分析師需對特徵變數X進行標準化處理，以消除不同量尺所造成的影響。已知使用StandardScaler進行資料轉換，程式碼如下：scaler =StandardScaler()。請問下列哪一種寫法可以正確完成資料標準化？","options":{"A":"X_norm = scaler.transform(X)","B":"X_norm = scaler.fit(X)","C":"X_norm = scaler.fit_transform(X)","D":"X_norm = fit_transform(scaler)"},"answer":"C","figures":[],"explanation":{"approach":"StandardScaler需要先透過fit()根據資料學習出平均數與標準差等參數，再透過transform()套用該參數將資料轉換為標準化後的結果；fit_transform()則是將這兩個步驟合併為一次呼叫，直接完成學習參數並回傳標準化後的資料，是最常見且正確的一步到位寫法。","options":{"A":"尚未呼叫fit()學習參數之前直接呼叫transform(X)，scaler因未被擬合（fit）過而缺乏平均數/標準差等必要參數，實務上會拋出NotFittedError。","B":"fit(X)僅會讓scaler學習（計算）出平均數與標準差等參數，並不會回傳轉換後的標準化資料，X_norm得到的會是已擬合的scaler物件本身，而非標準化後的資料。","C":"正確。fit_transform(X)一次完成「學習標準化參數」與「套用轉換」兩個步驟，直接回傳標準化後的資料，是完成資料標準化最正確的寫法。","D":"fit_transform是scaler物件的方法，應以scaler.fit_transform(X)呼叫；寫成fit_transform(scaler)是把scaler當作參數傳入一個不存在的獨立函式，語法用法錯誤。"}},"origin":"past"},{"id":"middle_115-1_s2_q49","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":49,"context":{"text":"請根據下方資訊回答第48~50題。","figures":["images/middle_115-1_s2_ctx4_fig1.png"]},"stem":"在進行機器學習建模前，資料分析師已完成資料前處理（包含遺漏值處理與特徵標準化），並準備建立分類模型。已知資料流程如下：1. 將資料區分為訓練集與測試集2. 建立羅吉斯迴歸（Logistic Regression）模型3. 使用訓練資料進行模型擬合（fit）請問下列哪一組Pandas / Scikit-learn程式碼流程最為正確？","options":{"A":"","B":"","C":"","D":""},"answer":"B","figures":[{"src":"images/middle_115-1_s2_q49_fig1.png","position":"option:D"},{"src":"images/middle_115-1_s2_q49_fig2.png","position":"option:A"},{"src":"images/middle_115-1_s2_q49_fig3.png","position":"option:B"},{"src":"images/middle_115-1_s2_q49_fig4.png","position":"option:C"}],"explanation":{"approach":"此為建立訓練/測試切分並訓練羅吉斯迴歸模型的標準流程，train_test_split()的正確參數順序應為(X, y, ...)（特徵在前、標籤在後）；此外，iris資料集為3類別（setosa、versicolor、virginica）的多分類問題，liblinear求解器僅能以One-vs-Rest方式間接處理多類別、不支援真正的multinomial（多項式）損失，而lbfgs是scikit-learn目前預設且原生支援multinomial多類別羅吉斯迴歸的求解器，更適合此3分類情境。","options":{"A":"train_test_split參數順序正確（X_norm在前、y在後），但採用solver=\"liblinear\"僅支援以One-vs-Rest方式處理多類別問題，並非針對此3類別（iris）情境最適合、支援原生multinomial的求解器選擇。","B":"正確。train_test_split(X_norm, y, ...)參數順序正確（特徵在前、標籤在後），且solver=\"lbfgs\"為scikit-learn預設、原生支援multinomial多類別邏輯迴歸的求解器，最適合iris這種3類別分類情境，整體流程最為正確。","C":"train_test_split(y, X_norm, ...)將特徵與標籤的參數順序顛倒，會導致X_train、y_train實際對應到錯誤的資料內容（標籤被當特徵、特徵被當標籤），流程邏輯錯誤。","D":"同樣將train_test_split的參數順序寫反（y在前、X_norm在後），即使solver使用較合適的lbfgs，也無法彌補特徵與標籤對應錯誤所造成的根本性邏輯問題。"}},"origin":"past"},{"id":"middle_115-1_s2_q50","level":"middle","session":"115-1","subject":2,"subject_name":"大數據處理分析與應用","number":50,"context":{"text":"請根據下方資訊回答第48~50題。","figures":["images/middle_115-1_s2_ctx4_fig1.png"]},"stem":"參考下圖程式碼，下列描述何者正確？","options":{"A":"cm表示混淆矩陣，橫列表測試集的預測值","B":"混淆矩陣對角線數值皆大於非對角線數值表示模型過度擬合","C":"f1_score參數average=\"weighted\"表示計算平均f1_score","D":"f1_score計算時採用各類別精確率（Precision）與召回率（Recall）的調和平均，並加權考量類別不平衡性"},"answer":"D","figures":[{"src":"images/middle_115-1_s2_q50_fig1.png","position":"stem"}],"explanation":{"approach":"圖中程式碼以confusion_matrix(y_test, y_pred)產生混淆矩陣（列為實際值y_test、欄為預測值y_pred），並以f1_score(y_test, y_pred, average=\"weighted\")計算加權F1分數。F1分數本質上是精確率（Precision）與召回率（Recall）的調和平均，而average=\"weighted\"則是依各類別實際樣本數（support）加權平均各類別F1分數，能兼顧類別不平衡的情況，這也與圖中classification_report所示的weighted avg欄位相呼應。","options":{"A":"sklearn中confusion_matrix(y_true, y_pred)的慣例是「橫列（row）代表實際值（y_test/真實類別）、直欄（column）代表預測值」，此選項將橫列誤說成代表預測值，方向說反了。","B":"混淆矩陣對角線數值遠大於非對角線，一般代表模型在該資料集上的分類表現良好（準確度高），而非過度擬合；過擬合須比較訓練集與測試集（或驗證集）表現的落差才能判斷，僅憑單一（測試集）混淆矩陣無法直接推論是否過擬合。","C":"average=\"weighted\"並非單純「計算平均f1_score」這麼簡略，其精確意義是依各類別的實際樣本數（support）加權平均各類別的F1分數，藉此反映類別不平衡的影響，此選項描述過於籠統、未點出加權的關鍵意涵。","D":"正確。F1分數的計算本質上是精確率與召回率的調和平均，而average=\"weighted\"則進一步依各類別樣本數加權平均，考量了類別不平衡的情況，此為對f1_score(..., average=\"weighted\")最精確完整的描述。"}},"origin":"past"},{"id":"middle_115-1_s3_q01","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":1,"context":null,"stem":"某量化投資團隊需估算某投資組合未來30日的風險值。由於衍生性金融商品的定價模型過於複雜，無法以解析解直接求得，工程師因此採用隨機模擬方式，產生大量市場情境模擬並估計損失分布。此方法屬於下列哪一種技術框架？","options":{"A":"馬可夫鏈（Markov Chain）：以狀態轉移機率描述系統演變的隨機過程","B":"梯度下降最佳化（Gradient Descent）：透過迭代更新參數以最小化損失函數","C":"蒙地卡羅方法（Monte Carlo Method）：透過大量隨機抽樣近似機率分布或數值結果","D":"貝氏推論（Bayesian Inference）：結合先驗分布與資料更新後驗機率"},"answer":"C","figures":[],"explanation":{"approach":"題目描述「模型過於複雜無法解析求解，改以大量隨機模擬市場情境估計損失分布」，這正是蒙地卡羅方法的定義：以大量隨機抽樣近似機率分布或數值結果，常用於風險值（VaR）估算。判斷關鍵字在於「隨機模擬」＋「大量情境」＋「估計分布」。","options":{"A":"馬可夫鏈描述的是狀態間的轉移機率過程，重點在「狀態轉移」而非大量隨機抽樣求分布，與題意不符。","B":"梯度下降是最佳化參數的迭代演算法，用於訓練模型參數，與風險模擬求分布無關。","C":"正確。蒙地卡羅方法透過大量隨機抽樣模擬市場情境，以估計損失分布，完全符合題目描述的技術框架。","D":"貝氏推論著重先驗與後驗機率的更新，與「大量隨機模擬求數值分布」的做法不同，屬於不同技術框架。"}},"origin":"past"},{"id":"middle_115-1_s3_q02","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":2,"context":null,"stem":"某工程師在建立房價預測模型時，訓練資料中存在少數豪宅（成交價超過一般物件10倍以上）。若工程師希望模型對這些極端高價物件的預測誤差更敏感，並在訓練時產生較大的梯度更新影響，應優先選擇下列哪種損失函數？","options":{"A":"平均絕對誤差（MAE）：對誤差進行線性懲罰，對離群值較不敏感，梯度近似固定","B":"Huber損失（Huber Loss）：小誤差採平方懲罰，大誤差轉為線性懲罰，以降低離群值影響","C":"均方誤差（MSE）：對誤差進行平方處理，使大誤差產生更大的懲罰與梯度","D":"交叉熵損失（Cross-Entropy Loss）：用於分類問題的機率分布差異衡量"},"answer":"C","figures":[],"explanation":{"approach":"題目要求對極端高價物件（離群值）產生「更敏感、更大梯度」的懲罰，這正是MSE的特性：誤差平方放大大誤差的懲罰與梯度，使模型更關注離群樣本。因此答案為MSE。","options":{"A":"MAE對誤差線性懲罰、梯度近似固定，對離群值不敏感，與題目要求「更敏感」相反。","B":"Huber損失刻意在大誤差時轉為線性懲罰，目的正是降低離群值影響，與題目要求相反。","C":"正確。MSE對誤差平方處理，離群值（大誤差）會產生更大的懲罰與梯度，使模型訓練時更敏感地修正這些樣本。","D":"交叉熵損失是用於分類問題的機率分布差異衡量，房價預測屬於迴歸問題，並不適用。"}},"origin":"past"},{"id":"middle_115-1_s3_q03","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":3,"context":null,"stem":"某工程師在撰寫Transformer的Attention層時，需手動驗證矩陣維度是否相容。輸入矩陣Q已攤平成形狀為(1, 10)，Query投影權重矩陣W形狀為(10, 64)。執Q行Q x W後輸出的形狀為何？Q","options":{"A":"(1, 64)","B":"(10, 10)","C":"(64, 1)","D":"維度不相容，無法相乘"},"answer":"A","figures":[],"explanation":{"approach":"矩陣乘法規則：(m, n) x (n, p) = (m, p)。Q形狀為(1, 10)，W形狀為(10, 64)，內側維度10相符可相乘，輸出形狀為(1, 64)。","options":{"A":"正確。依矩陣乘法規則，(1,10)x(10,64)的內側維度10相同可相乘，輸出形狀為(1,64)。","B":"(10,10)並非正確的矩陣乘法結果，此為誤把兩矩陣的內側維度直接組合，未正確套用乘法規則。","C":"(64,1)為輸出形狀的錯誤轉置，正確乘法順序Q x W不會產生此形狀，屬於張冠李戴。","D":"Q的第二維(10)與W的第一維(10)相同，維度是相容可相乘的，此選項判斷錯誤。"}},"origin":"past"},{"id":"middle_115-1_s3_q04","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":4,"context":null,"stem":"某AI團隊同時開發多個影像辨識系統，並在訓練流程中統一加入資料擴增策略（包含隨機水平翻轉）以提升模型泛化能力。實驗後發現，部分任務的測試表現明顯下降。下列哪一項任務最可能因該資料擴增策略引入語意錯誤（SemanticInconsistency），使同一樣本在翻轉後對應不同類別標籤，進而影響模型學習？","options":{"A":"寵物監控中的貓狗分類","B":"車輛辨識中的車型分類","C":"手寫數字辨識","D":"道路場景中的行人偵測"},"answer":"C","figures":[],"explanation":{"approach":"水平翻轉增強最容易在「翻轉後樣本本身失去原有語意（甚至變成另一個不存在的符號）」的任務中造成問題。手寫數字若做水平翻轉，翻轉後的圖形通常不再是任何合理的數字外觀，等同破壞了樣本與標籤的對應關係，屬於語意不一致；而貓狗、車型、行人偵測的物件類別在水平翻轉後仍維持原本類別語意，不受影響。","options":{"A":"貓、狗經水平翻轉後仍是同一隻貓或狗，類別語意不變，翻轉增強對此任務通常有益無害。","B":"車輛外觀左右翻轉後仍屬於同一車型，類別標籤不會改變，不會造成語意錯誤。","C":"正確。手寫數字經水平翻轉後，筆畫形狀通常不再對應任何合理數字，使樣本外觀與原標籤產生語意不一致，破壞學習效果。","D":"行人在影像中翻轉後仍是行人，偵測任務的類別語意不受水平翻轉影響。"}},"origin":"past"},{"id":"middle_115-1_s3_q05","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":5,"context":null,"stem":"某工程師完成多元線性迴歸模型後，繪製殘差圖（Residual Plot），發現殘差隨預測值增大而呈現擴散現象（右側明顯比左側分散）。此現象最可能代表什麼問題？","options":{"A":"殘差之間存在關聯","B":"特徵之間高度相關","C":"殘差變異數不一致","D":"殘差不符合常態分布"},"answer":"C","figures":[],"explanation":{"approach":"殘差圖中殘差隨預測值增大而擴散（漏斗形），是典型的「異質變異數」（Heteroscedasticity）現象，代表殘差變異數並非常數，違反線性迴歸的同質變異數假設。","options":{"A":"殘差之間存在關聯（自相關）通常在時間序列資料的殘差圖中呈現規律的波動或趨勢型態，而非隨預測值擴散的漏斗形。","B":"特徵間高度相關（多重共線性）主要影響係數估計的穩定性，不會在殘差對預測值圖中呈現擴散型態。","C":"正確。殘差隨預測值增大而分散程度增加，正是殘差變異數不一致（異質變異數）的典型圖形特徵。","D":"殘差是否符合常態分布通常以Q-Q圖或直方圖檢視，而非殘差對預測值的擴散型態，兩者判斷方式不同。"}},"origin":"past"},{"id":"middle_115-1_s3_q06","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":6,"context":null,"stem":"某資料科學家欲對512維詞嵌入向量（共10萬筆）進行視覺化以探索群集結構，同時另一工程師需將200個製程特徵降維後作為XGBoost的輸入特徵。關於t-SNE與PCA選型，下列敘述何者最正確？","options":{"A":"t-SNE保留全局線性結構，適合作為XGBoost的降維前處理","B":"t-SNE保留局部鄰域結構，適合視覺化；但不保留全局結構，不適合作為模型輸入特徵","C":"PCA為非線性降維方法，能保留複雜流形結構","D":"t-SNE與PCA皆可直接對新資料進行線性外推"},"answer":"B","figures":[],"explanation":{"approach":"t-SNE著重保留局部鄰域結構，適合高維資料視覺化探索群集，但不保留全局距離關係、也無法對新資料做線性外推，故不適合作為模型輸入特徵；PCA則是線性降維方法，可保留全局變異結構並能套用到新資料，適合作為XGBoost的前處理特徵。","options":{"A":"t-SNE並不保留全局線性結構，且無法對新資料一致地轉換，並不適合作為監督式模型的降維前處理。","B":"正確。t-SNE專注保留局部鄰域關係，適合視覺化群集分布；但犧牲全局結構且無法泛化到新樣本，不適合作為模型特徵輸入。","C":"PCA是線性降維方法，透過線性投影找主成分，並非非線性方法，也無法保留複雜流形結構。","D":"t-SNE屬於非線性、非參數式方法，並不能對新資料做線性外推，只有PCA可以透過已學得的線性投影套用到新資料。"}},"origin":"past"},{"id":"middle_115-1_s3_q07","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":7,"context":null,"stem":"某金融團隊建立信貸風險模型，特徵工程後共產生200個變數，其中「月收入」、「年收入」、「季收入」三者高度相關。模型上線後業務單位反映：每次重新訓練後，模型輸出的重要特徵清單在這些高度相關特徵間反覆變動，難以向審查單位解釋。請問下列何者為造成此現象最可能的原因？","options":{"A":"模型使用L2正則化，導致所有特徵係數被壓縮至接近零，重要性難以區分","B":"模型使用L1正則化，面對高度相關特徵時隨機保留其中之一，導致每次訓練保留的特徵不穩定","C":"模型未使用任何正則化，過擬合導致係數每次收斂至不同極值","D":"特徵數量過多導致梯度消失，應優先進行PCA降維再套用正則化"},"answer":"B","figures":[],"explanation":{"approach":"月收入、年收入、季收入三者高度共線，L1正則化（Lasso）的稀疏化特性會在共線特徵之間傾向保留其中之一並將其他係數壓為零，且因訓練隨機性（如資料切分、初始化）不同次訓練保留的特徵可能不同，造成重要特徵清單反覆變動、難以穩定解釋。","options":{"A":"L2正則化是將所有相關係數同時等比例縮小，而非壓成零，也不會造成特徵清單在不同次訓練間「反覆變動」的不穩定現象，與題目描述不符。","B":"正確。L1正則化面對高度共線特徵時，容易隨機保留其中之一並將其餘壓為零，導致每次重新訓練保留的重要特徵不穩定、清單反覆變動。","C":"題目並未描述過擬合的徵兆（如訓練與驗證表現落差），且未使用正則化不會特別導致「特徵清單在相關特徵間變動」的現象，因果推論不符。","D":"200個特徵並不算導致梯度消失的規模，梯度消失是深層網路反向傳播的問題，與此處線性模型特徵重要性不穩定的現象無關，屬於概念混淆。"}},"origin":"past"},{"id":"middle_115-1_s3_q08","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":8,"context":null,"stem":"某深度學習工程師訓練ResNet時，發現模型在前幾個Epoch驗證損失快速下降，但從第15個Epoch起驗證損失開始上升，而訓練損失持續下降。工程師將學習率調高後，訓練損失反而開始明顯震盪。學習率過大最直接導致下列哪種現象？","options":{"A":"梯度消失（Gradient Vanishing）：梯度在反向傳播中逐層縮小趨近於零，底層無法學習","B":"損失函數震盪或發散（Oscillation / Divergence）：每次更新步伐過大，參數在最優點兩側反覆跳越，無法穩定收斂","C":"過擬合（Overfitting）：模型記憶訓練資料的雜訊，泛化能力下降","D":"死亡ReLU（Dying ReLU）：大量神經元輸出永久為零，停止參與梯度更新"},"answer":"B","figures":[],"explanation":{"approach":"學習率過大時，每次參數更新的步伐過大，會使參數在最優點附近來回跳越而無法穩定收斂，表現為訓練損失震盪甚至發散，這與題目「調高學習率後訓練損失明顯震盪」的觀察直接對應。","options":{"A":"梯度消失是深層網路反向傳播時梯度逐層縮小趨近零的現象，通常導致訓練「停滯」而非「震盪」，與調高學習率的效果相反。","B":"正確。學習率過大使每次更新步伐過大，參數在最優點兩側反覆跳越，導致損失函數震盪或發散，無法穩定收斂。","C":"過擬合是模型記憶訓練雜訊、驗證表現下降但訓練損失通常持續平穩下降的現象，與調高學習率後訓練損失本身震盪的描述不同。","D":"死亡ReLU是神經元輸出恆為零、停止學習的現象，通常與過大的負向梯度更新有關，並非學習率過大最直接、典型的後果。"}},"origin":"past"},{"id":"middle_115-1_s3_q09","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":9,"context":null,"stem":"某工程師訓練深度神經網路時發現損失函數震盪嚴重且收斂速度慢，改用Adam優化器後訓練變得穩定且收斂更快。下列何者為Adam能改善此問題的主要原因？","options":{"A":"同時結合一階動量（Momentum）與自適應學習率（Adaptive Learning Rate），為每個參數調整更新步長","B":"強制所有參數使用相同學習率（Learning Rate），避免梯度差異造成不穩定","C":"透過批次正規化（Batch Normalization）重新分布輸入資料","D":"將梯度裁剪為固定範圍以避免梯度爆炸（Gradient Explosion）"},"answer":"A","figures":[],"explanation":{"approach":"Adam優化器同時結合了Momentum（一階動量，利用歷史梯度方向平滑更新）與RMSProp式的自適應學習率（依每個參數梯度的二階動量調整步長），使各參數能有各自合適的更新步伐，因而較傳統SGD更穩定且收斂更快。","options":{"A":"正確。Adam結合一階動量與自適應學習率，為每個參數量身調整更新步長，兼顧收斂穩定性與速度。","B":"Adam並非強制所有參數使用相同學習率，恰好相反，其核心特色就是為「每個參數」自適應調整不同的學習率。","C":"批次正規化是獨立於優化器的網路層技術，用於重新分布中間層輸入，並非Adam優化器本身的機制。","D":"梯度裁剪是另一種獨立技術，用於限制梯度範數避免梯度爆炸，並非Adam優化器改善收斂穩定性的主要原因。"}},"origin":"past"},{"id":"middle_115-1_s3_q10","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":10,"context":null,"stem":"某工程師同時開發兩個模型：一個預測使用者「隔日App使用時長（分鐘）」，另一個預測使用者「隔日是否流失（是/否）」。關於上述兩個任務，他應分別選擇哪種適當的損失函數？","options":{"A":"使用時長預測：均方誤差（MSE）；流失預測：二元交叉熵（Binary Cross-Entropy）","B":"使用時長預測：交叉熵損失（Cross-Entropy）；流失預測：均方誤差（MSE）","C":"使用時長預測：Hinge損失（Hinge Loss）；流失預測：MAE（平均絕對誤差）","D":"兩個任務均使用交叉熵損失，因為兩者的輸出都有不確定性"},"answer":"A","figures":[],"explanation":{"approach":"「App使用時長」為連續數值的迴歸任務，適合用MSE衡量預測值與真實值的平方誤差；「是否流失」為二元分類任務，適合用二元交叉熵衡量預測機率與真實類別的差距。","options":{"A":"正確。連續數值的迴歸任務對應MSE，二元分類任務對應Binary Cross-Entropy，分別對應兩個任務的正確損失函數。","B":"此選項將兩個任務的損失函數對調：交叉熵應用於分類（流失預測），MSE應用於迴歸（使用時長），敘述相反。","C":"Hinge損失主要用於SVM等最大間隔分類器，並非典型的迴歸損失；MAE雖可用於迴歸但通常不用於二元分類任務，兩者搭配與任務性質不符。","D":"使用時長預測是連續數值迴歸問題，並非機率分布問題，交叉熵損失並不適用，此選項混淆了迴歸與分類任務的本質差異。"}},"origin":"past"},{"id":"middle_115-1_s3_q11","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":11,"context":null,"stem":"某工程師在A100 GPU叢集上訓練大型語言模型，觀察到以下現象：全批次梯度下降時GPU利用率達100%，但每次更新耗時45秒；隨機梯度下降（SGD）每次更新僅需0.01秒，但梯度極不穩定、訓練曲線震盪劇烈。為兼顧梯度穩定性與GPU吞吐量（Throughput），應採用下列哪種策略？","options":{"A":"全批次梯度下降（Full-batch GD）：使用完整資料集計算梯度，更新穩定但每次更新耗時長","B":"隨機梯度下降（SGD）：每次只用一個樣本，速度快但梯度雜訊大，收斂不穩定","C":"第二階梯度法（Newton's Method）：利用Hessian矩陣精確估計曲率，大幅減少更新次數","D":"小批次梯度下降（Mini-batch GD）：以適當批次大小（如256-2048）平衡梯度估計穩定性與GPU平行效率，是深度學習的業界標準"},"answer":"D","figures":[],"explanation":{"approach":"全批次GD穩定但每次更新耗時長，SGD快但梯度雜訊大不穩定，兩者為極端。小批次梯度下降（如256-2048筆）在梯度估計穩定性與GPU平行運算效率間取得平衡，是深度學習實務上的業界標準做法。","options":{"A":"全批次梯度下降雖更新穩定，但每次更新耗時長（45秒），無法有效利用GPU平行吞吐量，不符合兼顧兩者的需求。","B":"SGD速度快但梯度雜訊大、訓練曲線震盪劇烈，犧牲了梯度穩定性，不符合題目「兼顧穩定性」的要求。","C":"牛頓法需計算並求逆Hessian矩陣，在大型語言模型的龐大參數量下計算成本極高，實務上不可行，並非兼顧效率的解法。","D":"正確。小批次梯度下降以適當批次大小平衡梯度估計的穩定性與GPU平行運算效率，是深度學習訓練的業界標準策略。"}},"origin":"past"},{"id":"middle_115-1_s3_q12","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":12,"context":null,"stem":"某醫院導入肺癌篩檢模型，資料集中正常病例佔99%、肺癌陽性僅佔1%。模型上線後，系統報告整體準確率（Accuracy）為99.1%。醫師對此數字感到疑慮，認為不足以評估臨床價值，在漏診風險上可能存在重大問題。請問在此情境下，僅以Accuracy作為評估指標最嚴重的缺陷為何？","options":{"A":"Accuracy對類別不平衡不敏感，可能無法反映模型對肺癌陽性的偵測能力","B":"Accuracy的計算不包含模型對邊界樣本的分類結果，容易遺漏困難樣本","C":"Accuracy無法處理多分類問題，在二元分類下需改用AUC","D":"Accuracy無法揭示模型的收斂速度，因此不適合用來選擇最終模型"},"answer":"A","figures":[],"explanation":{"approach":"正常病例佔99%，若模型全部預測為正常也能有99%左右的Accuracy，因此Accuracy在極度類別不平衡下無法反映模型對少數類別（肺癌陽性）的偵測能力，容易掩蓋高漏診率的問題，需改用Precision、Recall、F1或AUC等指標評估。","options":{"A":"正確。Accuracy對類別不平衡不敏感，在99%為正常病例的資料下，即使模型幾乎偵測不到肺癌陽性，整體Accuracy仍可能很高，無法反映臨床上關鍵的偵測能力。","B":"Accuracy的計算是以全體樣本的預測正確與否統計而成，本身涵蓋所有樣本（含邊界樣本），並非「不包含邊界樣本」的問題，此描述不正確。","C":"Accuracy本身就可用於二元分類，AUC是另一種評估工具而非因為Accuracy「無法處理多分類」才需要，此因果關係與題目情境（類別極度不平衡）無關，屬於張冠李戴。","D":"Accuracy是評估分類效果的指標，與模型訓練過程中的「收斂速度」無關，兩者屬於不同面向的評估內容。"}},"origin":"past"},{"id":"middle_115-1_s3_q13","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":13,"context":null,"stem":"某工程師訓練文本情感分類模型，訓練集F1=0.96、驗證集F1=0.71，落差明顯，顯示模型出現過擬合。下列哪一種策略能最直接從降低模型複雜度的角度緩解過擬合？","options":{"A":"增加訓練Epoch數至200，讓模型充分學習訓練資料的所有細節","B":"引入更多原始文本特徵（包括原始URL、HTML標籤），增加特徵多樣性","C":"對Embedding層與全連結層加入L2權重衰減（Weight Decay），懲罰參數值","D":"移除驗證集並將其併入訓練集，以增加模型可見的訓練樣本數"},"answer":"C","figures":[],"explanation":{"approach":"訓練與驗證F1落差大屬於過擬合，題目要求「從降低模型複雜度」角度緩解，L2權重衰減（Weight Decay）會懲罰過大的參數值，抑制模型複雜度、降低對訓練資料雜訊的過度擬合，是直接從模型複雜度切入的正則化手段。","options":{"A":"增加訓練Epoch數至200會讓模型更充分記憶訓練資料細節，反而加劇過擬合，與緩解過擬合的目標相反。","B":"引入更多原始文本特徵（含雜訊如URL、HTML標籤）會增加模型可利用的雜訊資訊，容易加劇過擬合，而非降低複雜度。","C":"正確。L2權重衰減透過懲罰參數值大小，限制模型權重的自由度，直接從降低模型複雜度的角度緩解過擬合。","D":"移除驗證集並入訓練集只是拿掉了監控過擬合的依據，並未實際降低模型複雜度，無法真正緩解過擬合問題。"}},"origin":"past"},{"id":"middle_115-1_s3_q14","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":14,"context":null,"stem":"某電商平台使用樸素貝氏分類器（Naive Bayes Classifier）建立垃圾郵件過濾模型。訓練集準確率（Accuracy）達92%，但上線後發現，包含「限時優惠、立即下單享折扣」等關鍵字的正常促銷郵件，常被誤判為垃圾信。經分析發現，這些詞彙在訓練資料中多出現在垃圾郵件中，導致其類別條件機率偏高。請問造成此現象的最主要原因與較適當的改善方式為何？","options":{"A":"應禁用Naive Bayes，改用其他更先進演算法","B":"模型過擬合於訓練資料，應增加Epoch數以提升泛化能力","C":"類別條件機率受訓練資料分布影響，導致促銷關鍵字被視為垃圾信特徵，應重新平衡資料或調整先驗機率","D":"模型未進行特徵標準化（Feature Scaling），導致分類邊界偏移，應先進行正規化處理"},"answer":"C","figures":[],"explanation":{"approach":"Naive Bayes的類別條件機率P(詞|類別)是直接由訓練資料的詞頻統計而得，若「限時優惠」等詞彙在訓練資料中多出現於垃圾郵件，模型便會學到偏高的垃圾機率，這是訓練資料分布偏誤所致，應透過重新平衡資料或調整先驗機率來改善，而非模型演算法本身的缺陷。","options":{"A":"問題根源在於訓練資料分布偏誤，而非Naive Bayes演算法本身不適用，直接棄用整個演算法並非對症下藥的做法。","B":"訓練準確率92%並非明顯過擬合的證據，且增加Epoch數是神經網路的訓練概念，Naive Bayes是以統計方式一次性估計機率，並無「增加Epoch」的訓練程序，此選項概念混淆。","C":"正確。類別條件機率由訓練資料統計而得，促銷詞彙因訓練集中多出現於垃圾郵件而被誤學為垃圾信特徵，應透過重新平衡資料或調整先驗機率改善此偏誤。","D":"Naive Bayes是以詞頻或出現與否為特徵進行機率估計，並非依賴數值尺度計算距離的模型，「特徵標準化」並非此問題的根本原因或解法。"}},"origin":"past"},{"id":"middle_115-1_s3_q15","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":15,"context":null,"stem":"某資料科學家將客戶資料進行分群，使用K-means（K=5）後發現部分群集呈現半月形（非凸）結構，且資料中存在少數離群值（Outliers）。他同時觀察到每次執行結果略有不同。下列敘述何者最完整且準確地反映K-means在此情境中的已知限制？","options":{"A":"K-means無法處理維度超過10的資料，在高維空間中距離計算失效","B":"K-means假設群集為高斯分佈，無法處理任何非球形群集","C":"K-means對K值敏感，但初始化不影響最終結果（演算法保證全局最優）","D":"K-means需預先指定K；以歐氏距離為基礎，難以處理非凸群集；對初始化與離群值敏感"},"answer":"D","figures":[],"explanation":{"approach":"K-means的已知限制包括：需事先指定K值、以歐氏距離為基礎衡量相似度、因此難以正確辨識非凸（如半月形）群集、且對初始中心點選擇與離群值皆敏感（不同初始化可能得到不同收斂結果），這些正好對應題目觀察到的現象。","options":{"A":"K-means並非因維度超過10就完全失效，維度過高主要帶來距離度量效果變差（維度詛咒）等問題，並非「無法處理」的絕對限制，敘述過於誇大。","B":"K-means假設群集近似球形（可視為各向同性），並非嚴格假設高斯分佈，且並非「無法處理任何」非球形群集，只是效果不佳，敘述過於絕對。","C":"K-means確實對K值敏感，但後半段「初始化不影響最終結果、演算法保證全局最優」明顯錯誤，K-means易收斂至局部最優，這也是題目中「每次執行結果略有不同」的原因。","D":"正確。K-means需預先指定K值、以歐氏距離衡量相似度導致難以處理非凸群集、且對初始中心點與離群值皆敏感，完整且準確地反映題目情境中的已知限制。"}},"origin":"past"},{"id":"middle_115-1_s3_q16","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":16,"context":null,"stem":"某資料科學家在信用評分任務中使用XGBoost建立模型，發現模型在訓練集表現良好但驗證集出現過擬合跡象。他檢視其模型設計，發現XGBoost在目標函數（Objective Function）中引入額外的正則化機制以控制模型複雜度。相較於傳統梯度提升決策樹（GBDT），XGBoost在其核心目標函數中加入了下列哪一種關鍵設計，使其具備更強的防過擬合能力？","options":{"A":"加入樹的複雜度懲罰項（包含深度、葉節點數量與葉節點權重的L2正則化）","B":"加入動態學習率（Dynamic Learning Rate）的強制衰減機制","C":"加入卷積運算（Convolution）以萃取特徵間的空間關係","D":"強制所有決策樹深度為1（Decision Stumps）"},"answer":"A","figures":[],"explanation":{"approach":"XGBoost相較傳統GBDT，在目標函數中明確加入正則化項，涵蓋樹的複雜度懲罰（包含樹的深度、葉節點數量以及葉節點權重的L2正則化），藉此直接控制樹模型的複雜度，是其相對GBDT具備更強防過擬合能力的核心設計。","options":{"A":"正確。XGBoost在目標函數中加入樹複雜度懲罰項，包含葉節點數量與葉節點權重的L2正則化，直接控制模型複雜度以降低過擬合風險，是其相對傳統GBDT的核心創新。","B":"動態學習率衰減機制並非XGBoost目標函數中的正則化設計，學習率（如eta參數）是超參數設定問題，與目標函數的正則化項無關。","C":"卷積運算是CNN處理影像等空間資料的技術，XGBoost是基於樹的集成模型，並不涉及卷積運算。","D":"強制樹深度為1（決策樹樁）並非XGBoost目標函數本身的正則化機制，而是超參數設定的極端案例，且並非XGBoost防過擬合的核心設計。"}},"origin":"past"},{"id":"middle_115-1_s3_q17","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":17,"context":null,"stem":"某醫療新創團隊將原有3層CNN升級為16層架構以提升CT影像腫瘤偵測率，但發現訓練損失反而高於3層版本且收斂困難。工程師懷疑是網路深度造成的訓練問題，下列診斷與對策何者最正確？","options":{"A":"網路層數增加導致參數量過多，應減少每層卷積濾波器（Filters）數量以降低模型複雜度","B":"深層網路可能出現梯度消失問題，導致淺層權重難以更新；應採用ResNet的殘差連接（Skip Connection）以改善梯度傳遞","C":"16層模型對CT影像而言仍過淺，應進一步增加網路深度以學習更高階特徵","D":"問題可能來自激活函數（Activation Function），將ReLU改為Sigmoid可改善梯度傳遞問題"},"answer":"B","figures":[],"explanation":{"approach":"加深網路後訓練損失反而更高、收斂更困難，是深層網路常見的梯度消失問題所致：反向傳播時梯度經過多層連乘逐漸縮小，使淺層權重難以有效更新。解法是採用ResNet的殘差連接（Skip Connection），讓梯度能直接跨層傳遞，改善深層網路的訓練困難。","options":{"A":"參數量過多主要影響計算成本與過擬合風險，而非導致「訓練損失反而更高、收斂困難」，並非此現象最直接的診斷。","B":"正確。深層網路容易出現梯度消失，使淺層權重難以更新，導致訓練損失不降反升；採用ResNet的殘差連接可讓梯度跨層直接傳遞，有效改善此問題。","C":"16層對CT影像而言並非過淺，題目描述的是加深後訓練反而變差（梯度消失徵兆），此時應優先解決梯度傳遞問題，而非繼續增加深度。","D":"Sigmoid的導數範圍更小（最大僅0.25），反而比ReLU更容易加劇梯度消失問題，將ReLU改為Sigmoid是錯誤方向。"}},"origin":"past"},{"id":"middle_115-1_s3_q18","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":18,"context":null,"stem":"某工程師設計用於醫療X光影像分類的CNN，發現卷積層後直接接全連結層導致參數量高達5,000萬，訓練速度極慢。為降低模型參數量與計算成本，他在卷積層後加入池化層（Pooling Layer）。下列何者為池化層在此設計中最主要解決的問題？","options":{"A":"降低特徵圖空間維度，減少參數與計算量","B":"提供非線性表達能力，以提升模型學習複雜度","C":"改善梯度消失問題，以強化反向傳播穩定性","D":"提升模型泛化能力而不影響特徵維度"},"answer":"A","figures":[],"explanation":{"approach":"卷積層輸出的特徵圖若直接接全連結層，龐大的空間維度會導致參數量爆炸。池化層透過降採樣（如Max Pooling）縮小特徵圖的空間尺寸，直接減少後續全連結層的輸入維度與參數量，同時降低計算成本，這正是題目描述問題的核心解法。","options":{"A":"正確。池化層降低特徵圖的空間維度，使後續全連結層輸入的神經元數量大幅減少，直接減少參數量與計算量，解決題目中5000萬參數過多的問題。","B":"池化層本身是降採樣運算（如取最大值），並非用來提供非線性表達能力，非線性主要來自激活函數（如ReLU），此選項張冠李戴。","C":"池化層與梯度消失問題的改善並無直接關聯，梯度消失主要透過殘差連接、適當的激活函數或正規化技術處理，非池化層的主要作用。","D":"池化層降低特徵維度是其主要效果之一，此選項卻聲稱「不影響特徵維度」，與池化層的實際作用矛盾。"}},"origin":"past"},{"id":"middle_115-1_s3_q19","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":19,"context":null,"stem":"某團隊開發合約文件審查系統，需比對合約首頁的定義條款與第20頁的責任條款是否一致。工程師初版採用雙向長短期記憶（Bidirectional LSTM），但發現長文件的跨段落語義關聯捕捉效果不佳，且訓練時間隨文件長度明顯增加。改用Transformer架構後問題獲得改善，下列何者為最主要的原因？","options":{"A":"Transformer參數量比LSTM少，因此訓練速度更快、不易過擬合","B":"Transformer內建位置編碼，使模型天生理解文件的章節結構與段落順序","C":"LSTM無法處理超過512個token的輸入，Transformer無此硬性限制","D":"Transformer的Self-Attention可讓任意token直接建立關聯，不受距離限制，且運算可平行化"},"answer":"D","figures":[],"explanation":{"approach":"LSTM需依序處理序列，長距離的跨段落關聯需經過多個時間步才能傳遞，容易衰減且難以平行化，訓練時間隨長度增加。Transformer的Self-Attention機制讓任意兩個token可以直接建立關聯，不受距離限制，且各token的運算可平行處理，因此能有效捕捉長文件中相隔甚遠段落（如首頁定義與第20頁條款）的語義關聯，同時加快訓練速度。","options":{"A":"Transformer的參數量通常並不比LSTM少（尤其含多頭注意力與前饋層），「參數量較少」並非其改善長距離關聯的主要原因，此敘述不正確。","B":"位置編碼的作用是讓模型獲得token的順序資訊，並非「天生理解章節結構」這種高層語意結構，此敘述過度誇大位置編碼的功能。","C":"LSTM並非有512 token的「硬性限制」，其序列長度理論上不受限，只是隨長度增加會有梯度衰減與計算效率的問題，此敘述描述有誤。","D":"正確。Self-Attention讓任意token能直接互相建立關聯而不受序列距離限制，同時允許平行運算，是Transformer能有效處理長文件跨段落關聯且訓練較快的最主要原因。"}},"origin":"past"},{"id":"middle_115-1_s3_q20","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":20,"context":null,"stem":"工程師在PyTorch中建構貓、狗、鳥三分類CNN，並使用交叉熵損失函數（CrossEntropyLoss）作為訓練目標。由於此損失函數在內部已包含Softmax計算，輸出層的設計需特別注意。請問輸出層的激活函數（Activation Function）與輸出維度應如何設定？","options":{"A":"使用ReLU作為激活函數，輸出維度設為1，直接輸出單一數值作為預測結果","B":"使用Sigmoid作為激活函數，輸出維度設為3，使每個類別獨立輸出0到1的機率","C":"不使用任何激活函數，直接輸出未經正規化的logits，輸出維度設為3對應三個類別","D":"使用Softmax作為激活函數，輸出維度設為3，輸出為已正規化的機率分布"},"answer":"C","figures":[],"explanation":{"approach":"PyTorch的nn.CrossEntropyLoss()內部已經整合了Softmax與負對數概似運算，因此模型的輸出層不應再額外套用Softmax（否則等於做了兩次），應直接輸出未正規化的原始分數（logits），且輸出維度需對應類別數（3類即設為3）。","options":{"A":"ReLU會將負值截斷為0，且輸出維度僅設為1無法表示三個類別的分類結果，不適用於三分類任務。","B":"Sigmoid各自獨立輸出0到1機率是多標籤分類（Multi-label）的做法，並非搭配CrossEntropyLoss的單標籤多分類任務所需設計。","C":"正確。CrossEntropyLoss內部已包含Softmax計算，輸出層應直接輸出未正規化的logits（不加激活函數），且輸出維度設為3以對應三個類別。","D":"若輸出層已使用Softmax，再搭配內部已含Softmax的CrossEntropyLoss會等於做了兩次Softmax運算，使機率分布被過度平滑，是常見的錯誤用法。"}},"origin":"past"},{"id":"middle_115-1_s3_q21","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":21,"context":null,"stem":"某工程師將一個大型預訓練模型部署至資源受限的行動裝置，發現模型體積過大且推論效率不足。為降低模型大小並提升推論速度，他將原本32-bit浮點數權重轉換為8-bit整數。在不重新訓練模型的前提下，請問此過程稱為何？","options":{"A":"知識蒸餾（Knowledge Distillation）","B":"權重剪枝（Pruning）","C":"張量分解（Tensor Decomposition）","D":"模型量化（Quantization）"},"answer":"D","figures":[],"explanation":{"approach":"將模型權重從32-bit浮點數轉換為8-bit整數，且不需重新訓練，正是「模型量化」（Quantization）的定義，可有效縮小模型體積並加快推論速度，適合部署於資源受限的行動裝置。","options":{"A":"知識蒸餾是訓練一個較小的學生模型模仿大型教師模型的行為，需要額外的訓練過程，與題目「不重新訓練、直接轉換數值精度」的做法不同。","B":"權重剪枝是移除不重要的權重連結或神經元以縮減模型規模，並非改變數值的表示精度（bit數），與題目描述的操作不同。","C":"張量分解是將權重矩陣分解為多個較小矩陣的乘積以降低參數量，並非改變數值精度，與題目描述不符。","D":"正確。將32-bit浮點數權重轉換為8-bit整數、且不重新訓練，正是模型量化的標準定義，可降低模型大小並提升推論效率。"}},"origin":"past"},{"id":"middle_115-1_s3_q22","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":22,"context":null,"stem":"某工程師建置企業內部知識問答的RAG系統，上線後發現部分問題檢索結果與查詢語意不符。分析後確認問題出在向量搜尋的語意匹配不準確。於檢索階段，採取下列哪種方法最能直接改善此問題？","options":{"A":"將切片大小（Chunk Size）由512tokens縮小至128tokens，以提升檢索精細度","B":"調整向量相似度閾值（Similarity Threshold），以過濾低相關檢索結果","C":"採用混合搜尋（Hybrid Search）：結合語意向量搜尋與關鍵字搜尋（BM25），並以RRF（Reciprocal Rank Fusion）融合排序","D":"將檢索結果隨機洗牌（Shuffle）後回傳給LLM，避免位置偏誤（Position Bias）"},"answer":"C","figures":[],"explanation":{"approach":"題目明確指出問題出在「向量搜尋的語意匹配不準確」，混合搜尋（Hybrid Search）結合語意向量搜尋與關鍵字搜尋（BM25），並以RRF融合排序結果，能截長補短：向量搜尋掌握語意相似度、BM25掌握精確關鍵字匹配，直接針對檢索階段的語意匹配問題進行改善。","options":{"A":"縮小Chunk Size雖可能提升檢索的細緻度，但無法直接解決「語意匹配不準確」的根本問題，屬於切片策略調整而非檢索方法本身的改善。","B":"調整相似度閾值只是過濾掉分數較低的結果，並不能提升向量搜尋本身語意匹配的準確度，無法解決題目描述的根本問題。","C":"正確。混合搜尋結合語意向量與關鍵字搜尋（BM25），並以RRF融合排序，能同時兼顧語意相似度與精確詞彙匹配，直接改善向量搜尋語意匹配不準確的問題。","D":"隨機洗牌檢索結果是用於降低LLM對輸入順序的位置偏誤，與檢索階段「語意匹配不準確」的問題無關，無法改善檢索品質。"}},"origin":"past"},{"id":"middle_115-1_s3_q23","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":23,"context":null,"stem":"某團隊開發法律文件生成系統，需根據合約前半段內容自動生成後半段條款。工程師分別使用BERT與GPT-2進行微調，但發現BERT的生成效果明顯較差，且即使增加訓練資料也無法改善。下列何者為最主要原因？","options":{"A":"BERT缺乏法律領域知識，因此生成能力較差","B":"BERT的分詞方式影響語意理解，導致生成效果不佳","C":"BERT模型規模較小，因此生成能力不足","D":"BERT無法根據前文逐步生成後續文字，較不適合此類任務"},"answer":"D","figures":[],"explanation":{"approach":"BERT是雙向編碼器（Encoder），訓練目標為克漏字（Masked Language Model），設計上並非用來逐步、自迴歸地生成後續文字；GPT-2則是自迴歸解碼器（Decoder），天生適合根據前文逐步預測生成下一個詞。這是架構層面的根本差異，並非資料量或領域知識的問題，因此增加訓練資料也無法改善BERT的生成能力。","options":{"A":"題目情境是通用的合約文件生成任務比較，缺乏領域知識並非BERT生成效果差的根本原因，且此問題也非用增加資料就能解決的知識缺口。","B":"分詞方式並非BERT與GPT-2在生成任務上表現差異的關鍵原因，兩者常使用相近的子詞分詞技術，此非核心因素。","C":"模型規模並非決定生成能力的關鍵因素，題目也指出「即使增加訓練資料也無法改善」，顯示問題並非規模大小可解決的。","D":"正確。BERT是雙向編碼器，設計上不具備自迴歸逐步生成文字的能力，而GPT-2是解碼器架構，天生適合根據前文逐步生成後續內容，此為架構本質差異，非資料量能彌補。"}},"origin":"past"},{"id":"middle_115-1_s3_q24","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":24,"context":null,"stem":"某推薦系統工程師處理商品類別特徵，該特徵包含約3,000個不同商品項目，每一種商品或其規格皆視為一個獨立類別。請問在高基數（High Cardinality）的情境下，下列哪一種編碼方式最容易造成維度爆炸問題？","options":{"A":"目標編碼（Target Encoding）","B":"標籤編碼（Label Encoding）","C":"Embedding層（Categorical Embedding）","D":"One-Hot編碼（One-Hot Encoding）"},"answer":"D","figures":[],"explanation":{"approach":"One-Hot編碼會為每個類別建立一個獨立的二元欄位，當類別基數高達3,000個時，會產生3,000維的稀疏向量，造成特徵維度急遽膨脹（維度爆炸），相較之下標籤編碼、目標編碼或Embedding層都能將高基數類別壓縮至較低維度。","options":{"A":"目標編碼是將類別轉換為單一數值（如目標平均值），不會隨類別數增加而擴張維度，不會造成維度爆炸。","B":"標籤編碼是將每個類別對應一個整數，僅佔用一個欄位，不會因類別數量增加而擴張維度。","C":"Embedding層將類別映射至固定且較低維度的稠密向量（如32或64維），即使類別數上千也不會造成維度隨類別數線性膨脹。","D":"正確。One-Hot編碼會為每個類別建立一個獨立欄位，3,000個類別即產生3,000維的稀疏向量，是高基數情境下最容易造成維度爆炸的編碼方式。"}},"origin":"past"},{"id":"middle_115-1_s3_q25","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":25,"context":null,"stem":"某工程師建立房價預測模型，輸入特徵包含屋齡與距捷運站距離（公尺）。他發現距捷運站距離分布嚴重右偏，經對數（Log）轉換後模型表現明顯改善；但將同樣轉換套用於屋齡後，模型表現反而下降。下列何者為最可能的原因？","options":{"A":"屋齡與房價若呈線性關係，Log轉換反而破壞此結構","B":"Log轉換會壓縮所有特徵的變異數，導致模型失去鑑別能力","C":"Log轉換不適用於有單位的連續變數，應改用Box-Cox","D":"兩特徵須套用相同轉換，否則尺度不一致導致梯度不穩定"},"answer":"A","figures":[],"explanation":{"approach":"Log轉換適合處理右偏（分布不對稱、有長尾）的變數，能壓縮極端值、使分布更接近常態，因此對右偏的距捷運站距離有效。但若屋齡與房價原本已呈近似線性關係，套用Log轉換會把原本線性的關係扭曲成非線性，反而破壞模型可利用的線性結構，導致表現下降。","options":{"A":"正確。若屋齡與房價本身已呈線性關係，Log轉換會將此線性關係扭曲為非線性，反而破壞了模型原本能有效利用的結構，導致表現變差。","B":"Log轉換確實會壓縮數值尺度與變異數，但這是對右偏變數的合理處理方式，並非「所有特徵」都會因此喪失鑑別能力，此為過度推論。","C":"Log轉換本來就常用於有單位的連續變數（如距離、金額）以處理偏態，並非「不適用」，且題目中對距離套用Log轉換即有效，此敘述與題目觀察矛盾。","D":"不同特徵可依各自分布特性選擇是否轉換，並非所有特徵都「必須」套用相同轉換，尺度不一致可透過標準化等方式處理，並非強制統一轉換的理由。"}},"origin":"past"},{"id":"middle_115-1_s3_q26","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":26,"context":null,"stem":"在時間序列資料的特徵工程中，工程師常使用滑動窗口（Sliding Window）方法，將過去多個時間點的觀測值組合為模型輸入。下列何者為此方法的主要目的？","options":{"A":"資料增強","B":"去除資料雜訊","C":"降低特徵維度","D":"建立滯後特徵"},"answer":"D","figures":[],"explanation":{"approach":"滑動窗口方法將過去多個時間點的觀測值（如t-1, t-2, ..., t-n）組合為模型在時間點t的輸入特徵，這些過去時間點的數值即為「滯後特徵」（Lag Features），目的是讓模型能利用歷史資訊預測未來。","options":{"A":"資料增強通常指透過變換（如翻轉、加噪）產生更多訓練樣本，滑動窗口的目的是組織既有歷史資料為特徵，並非產生新樣本，非其主要目的。","B":"滑動窗口本身並不具備去除雜訊的功能，僅是將過去觀測值重新組合為特徵，雜訊仍存在於這些觀測值中，需另外的平滑或濾波技術處理。","C":"滑動窗口組合多個時間點的觀測值通常反而會增加特徵數量（維度），並非用於降低特徵維度，此敘述方向相反。","D":"正確。滑動窗口將過去多個時間點的觀測值組合為當前時間點的輸入特徵，這些過去的數值即構成滯後特徵，是時間序列特徵工程的核心目的。"}},"origin":"past"},{"id":"middle_115-1_s3_q27","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":27,"context":null,"stem":"某工程師建立零售商品銷量預測模型，初期以第1至52週資料作為訓練集、第53週作為測試集（固定時間切分）。半年後重新評估，發現模型對最新資料（如第80週）的預測明顯衰退，推測為時間演進導致行為模式改變。若重新設計驗證策略，應採用下列哪種方法，使每次訓練皆基於最新時間區間資料？","options":{"A":"K-fold交叉驗證（K-fold Cross-Validation）","B":"分層K-fold（Stratified K-fold）","C":"滾動窗口驗證（Rolling Window Validation / Time Series Split）","D":"留一驗證法（Leave-One-Out Cross-Validation）"},"answer":"C","figures":[],"explanation":{"approach":"題目情境是時間演進導致行為模式改變（概念漂移），需要驗證方法能持續反映最新資料的時間特性。滾動窗口驗證（Rolling Window / Time Series Split）依時間順序切分，每次訓練都基於較新的時間區間資料進行訓練與驗證，能定期評估模型對最新趨勢的適應能力，符合題目需求。","options":{"A":"標準K-fold是隨機切分資料，未考慮時間先後順序，可能讓未來資料混入訓練集造成資料洩漏，不適合時間序列且不符合「基於最新時間區間」的要求。","B":"分層K-fold是為了維持類別比例一致而設計，同樣未考慮時間順序，並不符合時間序列資料需依時間切分驗證的需求。","C":"正確。滾動窗口驗證按時間順序切分訓練與測試集，且能隨時間推進持續使用最新區間資料訓練與驗證，符合題目「每次訓練皆基於最新時間區間資料」的需求。","D":"留一驗證法是每次僅留一筆樣本作驗證、其餘全部訓練，同樣未考慮時間先後順序，且在大量樣本下計算成本極高，不適合此情境。"}},"origin":"past"},{"id":"middle_115-1_s3_q28","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":28,"context":null,"stem":"某房仲平台要預測物件成交價，資料集含50個特徵，其中部分特徵與房價呈非線性關係，且業務單位要求模型須能提供整體特徵重要性以供稽核。下列哪一種模型選擇策略最符合需求？","options":{"A":"使用羅吉斯迴歸（Logistic Regression），透過線性係數解釋特徵影響，但無法有效建模非線性關係","B":"使用隨機森林迴歸（Random Forest Regression），可處理非線性關係，並提供整體特徵重要性（Feature Importance）作為解釋依據","C":"用K-means分群（K-means Clustering）後分別建立迴歸模型，以提升預測準確度並間接提升可解釋性","D":"使用支持向量迴歸（Support Vector Regression, SVR），透過核函數（KernelFunction）捕捉非線性關係，並以支持向量解釋模型決策"},"answer":"B","figures":[],"explanation":{"approach":"題目需求包含：能處理特徵與房價的非線性關係，且須提供整體特徵重要性以供業務稽核使用。隨機森林迴歸作為集成樹模型，天生能捕捉非線性關係，且能透過各特徵在樹分裂中的貢獻計算出整體特徵重要性（Feature Importance），直接同時滿足這兩項需求。","options":{"A":"邏輯迴歸適用於分類問題而非房價這種連續數值的迴歸預測，且僅能透過線性係數解釋，題目也明確指出無法有效處理非線性關係。","B":"正確。隨機森林迴歸可處理特徵與目標間的非線性關係，同時能提供整體特徵重要性作為稽核解釋依據，符合題目的兩項核心需求。","C":"先用K-means分群再分別建模的做法主要用於處理群體異質性，並非提供「整體特徵重要性」的標準做法，也未直接說明如何滿足稽核解釋的需求。","D":"SVR雖可透過核函數處理非線性關係，但其決策由支持向量與核函數共同決定，難以直接轉換為業務單位可理解的整體特徵重要性，可解釋性較差。"}},"origin":"past"},{"id":"middle_115-1_s3_q29","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":29,"context":null,"stem":"某工廠設備監測系統需偵測馬達軸承的異常振動，但過去僅記錄了大量正常運作的振動時序資料，缺乏任何已確認故障的標註樣本。請問下列何種任務範疇最符合此情境下的異常偵測需求？","options":{"A":"監督式二元分類（Supervised Binary Classification）","B":"非監督或半監督異常偵測（Unsupervised / Semi-supervised Anomaly Detection）","C":"強化學習（Reinforcement Learning）","D":"自監督學習（Self-supervised Learning）"},"answer":"B","figures":[],"explanation":{"approach":"訓練資料僅有大量正常樣本、完全缺乏已標註的故障（異常）樣本，無法採用需要正負樣本標籤的監督式學習。此情境應採用非監督或半監督異常偵測方法：僅以正常資料建立正常運作的模式或分布，再將明顯偏離此模式的樣本判定為異常。","options":{"A":"監督式二元分類需要正常與異常兩類皆有標註樣本才能訓練，題目明確指出缺乏任何已確認故障的標註樣本，無法採用此方法。","B":"正確。僅有正常樣本、缺乏異常標籤的情境，正是非監督或半監督異常偵測的典型應用場景，透過學習正常資料的分布來判斷異常。","C":"強化學習透過與環境互動並依獎勵訊號學習策略，並非用於此類基於歷史資料判斷異常的偵測任務，任務性質不符。","D":"自監督學習通常是設計代理任務從資料本身產生監督訊號來學習表徵，並非此情境下用於異常偵測任務範疇最直接對應的方法。"}},"origin":"past"},{"id":"middle_115-1_s3_q30","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":30,"context":null,"stem":"某信用風險模型：訓練AUC=0.97、驗證AUC=0.72、少數違約樣本預測波動極大及不同K-fold切分結果差異明顯。下列何者為最可能的問題？","options":{"A":"高偏差","B":"高變異","C":"過擬合","D":"資料漂移"},"answer":"B","figures":[],"explanation":{"approach":"訓練AUC與驗證AUC落差極大、且不同K-fold切分結果差異明顯，代表模型對訓練資料的擬合結果高度依賴所使用的特定訓練樣本，樣本稍有變動（不同fold）預測結果就大幅波動，這是模型複雜度過高、對資料變動敏感的「高變異」（High Variance）現象。","options":{"A":"高偏差是指模型在訓練集本身就表現不佳（欠擬合），但題目中訓練AUC高達0.97，並非欠擬合的現象，與高偏差不符。","B":"正確。訓練與驗證表現落差大、不同資料切分結果差異明顯，正是模型對訓練樣本變動過度敏感的高變異現象，反映模型複雜度過高、泛化能力不足。","C":"過擬合是描述此現象的整體結果性稱呼，而題目要求指出訓練/驗證落差與不同切分結果不穩定所對應的偏差-變異分解概念，「高變異」是更精確對應此症狀的專有名詞。","D":"資料漂移是指部署後資料分布隨時間改變導致效能下降，題目描述的是同一批資料下不同fold切分的表現落差，屬於模型本身泛化能力問題，並非資料隨時間變化的漂移現象。"},"note":"選項C(過擬合)與B(高變異)描述的其實是同一現象的兩種說法——訓練 AUC 0.97 對驗證 0.72 正是過擬合的教科書定義,而過擬合在偏差-變異框架下就稱為高變異。本題的判別線索在「不同 K-fold 切分結果差異明顯」與「少數樣本預測波動極大」:這是在描述模型對資料切分的敏感度,也就是變異(variance)本身,故官方答案取B。口訣:看到「切分結果差異大/預測不穩定」選高變異,只看到「訓練好、測試差」選過擬合。"},"origin":"past"},{"id":"middle_115-1_s3_q31","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":31,"context":null,"stem":"某倉儲自動化公司以強化學習（Reinforcement Learning, RL）訓練機器手臂進行揀貨，獎勵函數設計為「每成功抓取一個貨品得+1分」。部署後發現機器手臂學會反覆放開再抓取同一物品，以累積分數，但實際完成任務的效率極低。請問此現象的核心問題為何？應如何修正獎勵設計？","options":{"A":"獎勵塑形（Reward Shaping）：將獎勵改為「成功完成一次揀貨任務」而非單次抓取行為","B":"策略退化（Policy Degradation）：降低學習率以穩定訓練","C":"信用分配問題（Credit Assignment Problem）：引入優勢函數（AdvantageFunction）","D":"災難性遺忘（Catastrophic Forgetting）：加入經驗回放（Replay Buffer）"},"answer":"A","figures":[],"explanation":{"approach":"獎勵函數只針對「每次抓取」給分，導致機器手臂學會鑽漏洞：反覆放開再抓取同一物品以刷分，而非真正完成揀貨任務，這是典型的獎勵設計缺陷（Reward Hacking）。修正方式是進行獎勵塑形，改為針對「成功完成一次揀貨任務」給予獎勵，讓獎勵訊號真正對齊任務目標。","options":{"A":"正確。此為獎勵塑形問題：原獎勵函數獎勵了「抓取動作」而非「任務完成」，使代理人找到刷分捷徑；修正方式是將獎勵改為對齊「成功完成一次揀貨任務」，使獎勵訊號與真實目標一致。","B":"題目描述的核心問題是獎勵訊號設計不當導致代理人鑽漏洞，並非策略本身退化或訓練不穩定，降低學習率無法解決獎勵函數誤導代理人的根本問題。","C":"信用分配問題是指難以判斷序列決策中哪些動作對最終結果有貢獻，而題目情境是獎勵本身設計錯誤導致代理人刷分，並非分不清動作貢獻度的問題，診斷方向不符。","D":"災難性遺忘是指模型在學習新任務時忘記舊任務的知識，與題目中「反覆抓取刷分」的獎勵設計缺陷無關，經驗回放也非針對此問題的解法。"}},"origin":"past"},{"id":"middle_115-1_s3_q32","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":32,"context":null,"stem":"某詐欺偵測模型需同時具備高精確率（Precision），以避免誤凍結正常帳號，並維持高召回率（Recall）表現，以確保不放過任何詐欺行為。然而工程師發現兩者之間存在取捨關係（Precision-Recall Tradeoff）。在此情境下，F1-score最能反映何種特性？","options":{"A":"F1-score = (Precision + Recall) / 2，為算術平均","B":"F1-score為Precision的加權平均","C":"F1-score僅適用於類別平衡資料","D":"F1-score = 2 × (Precision×Recall)/(Precision+Recall)，為調和平均，對較小值敏感"},"answer":"D","figures":[],"explanation":{"approach":"F1-score的公式為2×(Precision×Recall)/(Precision+Recall)，屬於調和平均數。調和平均的特性是對數值中較小者更為敏感（會被較低的一方拉低），因此當Precision與Recall有所取捨、其中一項偏低時，F1-score會明顯下降，能有效反映兩者失衡的情況，適合用來衡量此類存在Trade-off的任務表現。","options":{"A":"F1-score並非Precision與Recall的算術平均（(P+R)/2），算術平均對兩者一視同仁、不會特別受較小值拉低，無法反映F1真正的調和平均特性。","B":"F1-score是Precision與Recall兩者的調和平均，而非僅對Precision本身做加權平均，此敘述描述錯誤。","C":"F1-score並非僅適用於類別平衡資料，事實上F1-score常被用於類別不平衡情境（如詐欺偵測）以彌補Accuracy的不足，此敘述錯誤。","D":"正確。F1-score = 2×(Precision×Recall)/(Precision+Recall)為調和平均，其特性是對Precision與Recall中較小的一方特別敏感，能有效反映兩者的取捨關係。"}},"origin":"past"},{"id":"middle_115-1_s3_q33","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":33,"context":null,"stem":"某工程師的多元線性迴歸模型包含150個特徵，其中許多特徵高度相關（如「建坪」與「總面積」）。他同時希望控制過擬合且保留所有特徵的解釋能力，不讓任何特徵係數歸零，下列哪一項正則化方案最適當？","options":{"A":"Lasso迴歸（L1正則化）：透過絕對值懲罰使部分係數歸零，具有特徵選擇效果","B":"Ridge迴歸（L2正則化）：透過平方懲罰縮小所有係數，在共線性下穩定估計且不歸零","C":"Elastic Net（L1+L2）：結合稀疏性與穩定性，但部分係數仍可能被壓為0","D":"無正則化的OLS迴歸：不控制過擬合，在共線性下係數估計不穩定"},"answer":"B","figures":[],"explanation":{"approach":"題目要求控制過擬合、同時保留所有特徵的解釋力（不讓任何係數歸零），且特徵間存在共線性（建坪與總面積高度相關）。Ridge迴歸（L2正則化）以平方懲罰縮小所有係數但不會將係數壓至零，能在共線性下提供穩定的估計，同時保留每個特徵的解釋能力，完全符合題目需求。","options":{"A":"Lasso（L1正則化）具有特徵選擇效果，會將部分係數壓至零，這與題目「不讓任何特徵係數歸零」的要求直接矛盾。","B":"正確。Ridge迴歸透過平方懲罰縮小所有係數但不會使其歸零，在高度共線性下能提供穩定的參數估計，同時保留全部特徵的解釋能力，符合題目需求。","C":"Elastic Net雖結合L1與L2，但因保留了L1成分，部分係數仍可能被壓為0，同樣不完全符合「不讓任何特徵係數歸零」的要求。","D":"無正則化的OLS迴歸完全沒有機制控制過擬合，且在特徵高度共線時係數估計會非常不穩定，不符合題目控制過擬合的需求。"}},"origin":"past"},{"id":"middle_115-1_s3_q34","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":34,"context":null,"stem":"某工程師使用XGBoost模型進行調參，需對以下超參數進行網格搜尋（GridSearch）：learning_rate（3個候選值）、max_depth（4個）、n_estimators（5個）、subsample（3個）、colsample_bytree（3個）。每組參數組合皆需完整進行5-Fold交叉驗證。請問總共需要訓練幾個模型？","options":{"A":"3 + 4 + 5 + 3 + 3 = 18個","B":"5 × 5 = 25個","C":"max(3,4,5,3,3) × 5 = 25個","D":"3 × 4 × 5 × 3 × 3 × 5 = 2,700個"},"answer":"D","figures":[],"explanation":{"approach":"網格搜尋（Grid Search）需窮舉所有超參數候選值的「笛卡兒積」組合數，即3×4×5×3×3 = 540組參數組合；每組參數組合皆需完整進行5-Fold交叉驗證（即各訓練5個模型），因此總訓練模型數為540×5 = 2,700個。","options":{"A":"此選項將各超參數的候選值個數直接相加（3+4+5+3+3=18），但Grid Search是窮舉所有參數「組合」（笛卡兒積相乘），並非相加，計算方式錯誤。","B":"此選項僅以5×5=25計算，既未反映所有超參數候選值應相乘的組合數，也未正確納入5-Fold交叉驗證的意義，計算方式錯誤。","C":"此選項僅取各超參數候選值中的最大值（5）再乘以5-Fold，忽略了Grid Search需窮舉「所有」候選值組合（相乘）的定義，明顯低估總數。","D":"正確。5個超參數的候選值應相乘得出所有參數組合數（3×4×5×3×3=540），每組再進行5-Fold交叉驗證（各訓練5個模型），總數為540×5=2,700個模型。"}},"origin":"past"},{"id":"middle_115-1_s3_q35","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":35,"context":null,"stem":"某團隊使用LoRA微調大型語言模型進行法律摘要任務，發現模型在複雜條款的摘要上常出現內容遺漏，但GPU顯存已接近上限。下列哪種調整方式最能在不明顯增加記憶體使用的前提下改善模型表現？","options":{"A":"提高LoRA rank以增強模型表達能力","B":"改用完整微調（Full Fine-tuning）以學習更多細節","C":"降低LoRA rank以釋放記憶體並增加Batch Size","D":"降低LoRA rank但套用到更多層，保持trainable總參數不變"},"answer":"D","figures":[],"explanation":{"approach":"LoRA的可訓練參數量主要由rank與套用的層數共同決定。在GPU顯存已接近上限、不希望明顯增加記憶體使用的前提下，將LoRA套用到更多層、同時降低每層的rank，可以在維持總可訓練參數量大致不變（因此記憶體用量相近）的情況下，讓更多層都能學習任務相關的調整，進而改善模型在複雜條款上的表現。","options":{"A":"提高LoRA rank會直接增加可訓練參數量與所需記憶體，與題目「不明顯增加記憶體使用」的限制條件相違背。","B":"完整微調需要更新模型全部參數，記憶體需求遠高於LoRA，在GPU顯存已接近上限的情況下明顯不可行。","C":"降低LoRA rank雖可釋放記憶體，但同時也降低了模型的表達能力，且再用來增加Batch Size並無法直接改善「內容遺漏」這類模型表達能力不足的問題。","D":"正確。降低單層LoRA rank但套用到更多層，可在維持總可訓練參數量（進而維持記憶體用量）大致不變的前提下，讓更多層參與任務調整，提升模型表達能力以改善內容遺漏問題。"}},"origin":"past"},{"id":"middle_115-1_s3_q36","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":36,"context":null,"stem":"某金融機構的AI信用評分模型需上傳至第三方雲端服務商進行推論。法務部門要求：在不解密資料的前提下，由單一雲端服務商直接對加密資料進行模型運算。下列哪種隱私保護技術最符合此需求？","options":{"A":"聯邦學習（Federated Learning）","B":"同態加密（Homomorphic Encryption）","C":"差分隱私（Differential Privacy）","D":"安全多方計算（Secure Multi-Party Computation, MPC）"},"answer":"B","figures":[],"explanation":{"approach":"題目要求「不解密資料的前提下，由單一雲端服務商直接對加密資料進行模型運算」，這正是同態加密（Homomorphic Encryption）的定義：允許在密文（加密狀態）上直接進行運算，運算結果解密後等同於對明文運算的結果，且僅需單一運算方即可完成，無需多方協作或明文交換。","options":{"A":"聯邦學習是讓資料留在各參與方本地、僅交換模型參數或梯度以共同訓練模型，並非「單一雲端服務商對加密資料直接運算」的模式，架構本質不同。","B":"正確。同態加密允許雲端服務商在不解密的情況下，直接對加密資料進行運算，運算結果解密後與對明文運算結果一致，完全符合題目「單一服務商對加密資料直接運算」的需求。","C":"差分隱私是透過在資料或查詢結果中加入雜訊以保護個體隱私，並非讓服務商能對加密資料直接進行模型運算的技術。","D":"安全多方計算（MPC）是讓「多個」參與方在不揭露各自資料的情況下共同計算，需要多方協作，而非題目要求的「單一」雲端服務商即可完成的模式。"}},"origin":"past"},{"id":"middle_115-1_s3_q37","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":37,"context":null,"stem":"某銀行導入AI貸款審核系統，監管要求每筆被拒絕的申請須提供可理解的拒絕原因。技術主管評估以下方案，哪一種最能實現個別預測的局部可解釋性（LocalExplainability）？","options":{"A":"SHAP（SHapley Additive exPlanations）值：計算每個特徵對單筆預測的貢獻","B":"全域特徵重要性（Global Feature Importance）：說明整體特徵影響，無法解釋單一個案","C":"Grad-CAM（Gradient-weighted Class Activation Mapping）：以熱力圖解釋影像模型","D":"混淆矩陣（Confusion Matrix）：呈現整體分類表現"},"answer":"A","figures":[],"explanation":{"approach":"題目要求「每筆」被拒絕申請都要有可理解的拒絕原因，這是針對單一個案（局部）的解釋需求。SHAP值能計算每個特徵對「單筆」預測結果的具體貢獻程度，屬於局部可解釋性（Local Explainability）方法，能針對個別被拒絕的申請提供其專屬的特徵貢獻說明。","options":{"A":"正確。SHAP值計算每個特徵對單筆預測的貢獻，能針對個別被拒絕的申請提供專屬的解釋，符合局部可解釋性的需求。","B":"全域特徵重要性說明的是整體模型層面的特徵影響力排序，選項本身也點明「無法解釋單一個案」，與題目要求的個別預測解釋需求相反。","C":"Grad-CAM是以熱力圖解釋影像分類模型關注的區域，適用於影像任務，與銀行貸款審核這類表格資料的分類任務不符。","D":"混淆矩陣呈現的是模型在整體資料集上的分類表現統計（如真陽性、偽陽性數量），屬於整體評估工具，無法解釋單一個案的拒絕原因。"}},"origin":"past"},{"id":"middle_115-1_s3_q38","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":38,"context":null,"stem":"某公司導入AI履歷篩選系統，用於自動決定是否進入面試。模型對男性應徵者的面試通過率為55%，對女性應徵者為30%。在其他條件不變的情況下，工程師需評估模型是否符合統計均等（Statistical Parity）的公平性定義。下列何者最正確？","options":{"A":"符合統計均等，因為模型未使用性別作為輸入特徵","B":"符合統計均等，因為兩個族群皆有部分應徵者被錄取","C":"不符合統計均等，因為不同群體的正向決策比例（通過率）存在明顯差異","D":"不符合統計均等，因為女性族群的預測準確率較低"},"answer":"C","figures":[],"explanation":{"approach":"統計均等（Statistical Parity）要求不同群體獲得正向決策（如通過面試）的比例應大致相等。題目中男性通過率55%、女性僅30%，兩群體的正向決策比例存在明顯差異，因此不符合統計均等的定義，即使模型未直接使用性別作為輸入特徵，仍可能透過其他相關特徵間接產生此落差。","options":{"A":"統計均等關注的是決策結果（通過率）在不同群體間是否一致，即使模型未使用性別作為輸入特徵，仍可能因其他相關特徵導致結果落差，「未使用性別特徵」不能保證符合統計均等。","B":"統計均等要求的是「比例」相近而非「兩群體皆有部分人被錄取」這種寬鬆條件，55%與30%的通過率比例差異明顯，並不符合統計均等的定義。","C":"正確。統計均等的核心是比較不同群體獲得正向決策的比例，男性55%與女性30%的通過率存在明顯差異，因此不符合統計均等的公平性定義。","D":"統計均等關注的是「正向決策比例」的差異，而非「預測準確率」，此選項雖然結論相同（不符合），但給出的理由（準確率較低）與統計均等的定義不符，屬於概念混淆。"}},"origin":"past"},{"id":"middle_115-1_s3_q39","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":39,"context":null,"stem":"某銀行信貸模型上線後稽核發現，女性申請者中「實際具有還款能力卻被模型拒絕」的比例顯著高於男性，但法務限制不允許在推論階段使用性別欄位調整輸出。下列去偏策略何者在此限制下仍可執行？","options":{"A":"訓練中（In-processing）：在損失函數加入公平性懲罰項，降低不同群體的錯誤拒絕比例差異","B":"前處理（Pre-processing）：僅於訓練資料進行重新採樣，無法直接修正既有模型在推論階段的偏誤","C":"後處理（Post-processing）：依性別分組調整決策門檻，使不同群體的錯誤拒絕比例一致","D":"改用人口統計均等指標（Demographic Parity），錯誤拒絕比例差異將自動消失"},"answer":"A","figures":[],"explanation":{"approach":"法務限制「不允許在推論階段使用性別欄位」，因此任何需要在推論時依性別做調整的方法皆不可行。訓練中（In-processing）去偏是在訓練階段的損失函數中加入公平性懲罰項，讓模型學習到更公平的決策邊界，訓練完成後推論階段不需要再使用性別欄位，因此在此限制下仍可執行。","options":{"A":"正確。訓練中去偏是在「訓練階段」的損失函數中加入公平性懲罰項來調整模型學習過程，訓練完成後於推論階段不需要再使用性別欄位，符合法務限制。","B":"前處理策略本身即如選項所述，僅能透過重新採樣訓練資料間接影響模型，無法直接修正「既有已上線模型」在推論階段的偏誤，不符合題目「銀行模型上線後」需要修正的情境。","C":"後處理策略需要在「推論階段」依性別分組調整決策門檻，這正是需要在推論時使用性別欄位的做法，直接違反法務「不允許在推論階段使用性別欄位」的限制。","D":"更換公平性指標的定義（如人口統計均等）僅是改變評估或約束的目標，並不會讓既有模型的錯誤拒絕比例差異「自動消失」，仍需實際的去偏方法才能改善。"}},"origin":"past"},{"id":"middle_115-1_s3_q40","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":40,"context":null,"stem":"分析師準備建立一個能將手寫數字圖片（28x28像素展平為784維度）分為0~9共10個類別的多層感知機（MLP），且標籤已轉為One-Hot編碼（One-Hot Encoding）。為符合10個類別的單標籤分類需求，下圖中的程式碼中(A)與(B)的函數應填入何者？","options":{"A":"sigmoid，mean_squared_error","B":"softmax，categorical_crossentropy","C":"relu，binary_crossentropy","D":"tanh，sparse_categorical_crossentropy"},"answer":"B","figures":[{"src":"images/middle_115-1_s3_q40_fig1.png","position":"stem"}],"explanation":{"approach":"題目情境為10類別的單標籤分類、且標籤已轉為One-Hot編碼。單標籤多分類的標準組合是：輸出層使用Softmax（使10個輸出值總和為1、形成機率分布），搭配categorical_crossentropy作為損失函數（因標籤為One-Hot格式，需與Softmax機率分布逐一比對）。程式碼中(A)為輸出層activation，(B)為compile的loss，依此組合應分別填入softmax與categorical_crossentropy。","options":{"A":"Sigmoid用於獨立的多標籤或二元分類，各輸出彼此獨立不形成機率分布；MSE是迴歸常用損失，皆不適合此10類別單標籤分類任務。","B":"正確。10個類別的單標籤分類搭配One-Hot標籤，標準做法是輸出層用Softmax產生機率分布，並用categorical_crossentropy計算與One-Hot標籤的交叉熵損失。","C":"ReLU通常用於隱藏層而非輸出層的機率轉換，且binary_crossentropy是用於二元分類（或多標籤），與此10類別單標籤分類任務不符。","D":"tanh輸出範圍為-1至1，並非機率分布，不適合作輸出層；sparse_categorical_crossentropy是搭配「整數標籤」使用，而非題目中已轉為One-Hot的標籤格式，兩者不匹配。"}},"origin":"past"},{"id":"middle_115-1_s3_q41","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":41,"context":null,"stem":"工程師使用PyTorch建立OCR訓練pipeline，並對手寫字母資料集套用下圖程式進行資料增強（Transform）。模型在訓練過程中顯示驗證損失（Validation Loss）持續下降，但實際部署後，系統在辨識「b/d/p/q」類字母錯誤率異常偏高。下列何者為最可能的根本原因？","options":{"A":"RandomRotation(15)角度過大導致特徵變形，應降至5度以內","B":"RandomHorizontalFlip破壞字母方向語義，使模型以50%機率學到鏡像錯誤標籤","C":"ColorJitter改變筆畫灰階，導致邊緣偵測特徵失真","D":"ToTensor( )應放在所有幾何變換之前才能保持座標對應正確"},"answer":"B","figures":[{"src":"images/middle_115-1_s3_q41_fig1.png","position":"stem"}],"explanation":{"approach":"程式碼中對OCR手寫字母套用了RandomHorizontalFlip(p=0.5)。字母b、d、p、q彼此互為左右鏡像關係（b翻轉後變成d、p翻轉後變成q），水平翻轉會以50%機率把原本是b的樣本翻轉成外觀像d的圖像，卻仍標記原始標籤b，導致模型學到錯誤的視覺-標籤對應，這正是驗證損失下降但實際部署時b/d/p/q辨識錯誤率異常偏高的根本原因。","options":{"A":"RandomRotation(15)角度中等，主要造成輕微形變，並非b/d/p/q這類「鏡像混淆」錯誤的主要來源，與觀察到的特定錯誤型態不符。","B":"正確。水平翻轉會使b與d、p與q的字型外觀彼此對調，但標籤仍維持原樣，等於以50%機率讓模型學到鏡像錯誤的標籤對應，正是b/d/p/q辨識率異常偏高的根本原因。","C":"ColorJitter僅調整亮度等色彩相關屬性，不會改變字母的左右形狀結構，與b/d/p/q這類方向性混淆問題無直接關聯。","D":"ToTensor()僅將影像轉換為張量格式，並不涉及座標幾何變換，其在Compose中的順序並非造成b/d/p/q辨識錯誤率偏高的根本原因。"}},"origin":"past"},{"id":"middle_115-1_s3_q42","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":42,"context":{"text":"下圖為使用ResNet進行遷移學習（Transfer Learning）的Python程式片段。請回答\n第42~43題。","figures":["images/middle_115-1_s3_ctx1_fig1.png"]},"stem":"觀察程式中行(A)將所有既有權重的梯度計算關閉，這在遷移學習中屬於哪一種標準策略？","options":{"A":"全面微調（Full Fine-Tuning）","B":"零樣本學習（Zero-shot Learning）","C":"特徵萃取（Feature Extraction）","D":"知識蒸餾（Knowledge Distillation）"},"answer":"C","figures":[],"explanation":{"approach":"情境程式碼中，for迴圈將預訓練ResNet50所有既有參數的requires_grad設為False（行A），代表這些層在訓練過程中完全不會被更新，僅有後續新增的model.fc（全連結分類層）會被訓練。此做法是把預訓練模型當作固定的特徵抽取器使用，屬於「特徵萃取」（Feature Extraction）策略。","options":{"A":"全面微調是指讓所有（或大部分）預訓練層的梯度皆開啟並隨新任務資料更新，與程式碼中把所有既有權重梯度關閉（False）的做法相反。","B":"零樣本學習是指模型未經任何該任務樣本訓練即可直接進行預測，與程式碼中仍會用資料訓練新的全連結層（fc）的流程不同。","C":"正確。將所有既有預訓練權重的requires_grad設為False，代表凍結這些層不參與訓練，僅利用其輸出特徵、只訓練新增的分類層，這正是特徵萃取的標準做法。","D":"知識蒸餾是讓一個較小的學生模型學習模仿教師模型的輸出行為，需要教師與學生兩個模型間的知識傳遞過程，與程式碼中凍結既有權重的單一模型微調流程不同。"}},"origin":"past"},{"id":"middle_115-1_s3_q43","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":43,"context":{"text":"下圖為使用ResNet進行遷移學習（Transfer Learning）的Python程式片段。請回答\n第42~43題。","figures":["images/middle_115-1_s3_ctx1_fig1.png"]},"stem":"在進行遷移學習微調（Fine-Tuning）時，通常會將優化器的學習率（Learning Rate）設得非常小（如1e-4），下列何者為主要的原因？","options":{"A":"為了避免記憶體耗盡（OOM）","B":"為了加速模型整體的收斂時間","C":"為了讓損失函數強制歸零","D":"為了避免更新步伐過大，破壞預訓練模型原本已學好的良好特徵表示"},"answer":"D","figures":[],"explanation":{"approach":"遷移學習微調時，預訓練模型的權重已經在大量資料上學到良好的通用特徵表示。若使用過大的學習率，更新步伐過大容易劇烈改動這些已經學好的權重，等於破壞了預訓練帶來的優勢；因此通常設定極小的學習率（如1e-4），讓模型在保留原有良好特徵的基礎上，緩慢地微調以適應新任務。","options":{"A":"小學習率與避免記憶體耗盡（OOM）無關，OOM通常與批次大小、模型規模等記憶體占用因素有關，並非學習率大小的問題。","B":"小學習率通常會使收斂速度「變慢」而非加速，此選項與小學習率的實際效果相反。","C":"學習率大小與損失函數是否能「強制歸零」無關，損失函數收斂程度取決於資料與模型擬合狀況，並非單純靠調小學習率可強制達成。","D":"正確。使用極小的學習率是為了避免更新步伐過大，破壞預訓練模型原本已經學到的良好特徵表示，讓微調過程能穩定地在既有基礎上小幅調整以適應新任務。"}},"origin":"past"},{"id":"middle_115-1_s3_q44","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":44,"context":{"text":"請依據下方資訊回答第44~45題。\nIris是UCI Dataset上的一組經典資料集，常被用來教學與測試分類模型。\n這份資料包含三種類型的鳶尾花（Iris setosa、Iris versicolor、Iris virginica），每個類\n別各有50筆資料。\n每筆資料包含四個特徵：花萼長度、花萼寬度、花瓣長度、花瓣寬度。\n研究人員希望透過機器學習模型，根據花朵的形態特徵，自動判斷該花屬於哪一種\n類型。在本次任務中，研究人員希望比較不同分類模型的表現。他們首先嘗試用線\n性判別分析（LDA）進行降維，接著使用K最近鄰（KNN）分類器來做分類預測，\n並使用交叉驗證（Cross Validation）評估模型的準確率。","figures":["images/middle_115-1_s3_ctx3_fig1.png"]},"stem":"研究人員撰寫的程式中（下圖），先用整體資料進行LDA（Linear DiscriminantAnalysis）降維，接著再用KNN（K-Nearest Neighbors）進行分類，並用交叉驗證來評估準確率。請問下列敘述何者正確？","options":{"A":"此寫法完全正確，因為先以整體資料進行LDA降維，再以交叉驗證測試KNN，是標準流程","B":"此寫法存在資料洩漏（Data Leakage）問題，應將LDA納入交叉驗證流程中一併進行","C":"雖然流程不夠嚴謹，但結果仍然能夠代表模型真實的泛化能力","D":"如果只想驗證KNN的分類效果，可以直接跳過LDA步驟，以簡化流程"},"answer":"B","figures":[{"src":"images/middle_115-1_s3_q44_fig1.png","position":"stem"}],"explanation":{"approach":"程式碼是先對「整體資料」（包含後續會被劃入測試折的樣本）進行LDA降維，之後才用交叉驗證評估KNN。由於LDA降維本身是一種監督式轉換（會利用類別標籤資訊學習投影方向），若在交叉驗證「之前」就對整體資料做LDA，等於讓測試折的資訊提前參與了降維轉換的學習過程，屬於資料洩漏，會導致交叉驗證評估出的準確率被高估、無法反映模型真實的泛化能力。正確做法應將LDA一併納入交叉驗證流程（如置於Pipeline中），確保每一折的降維僅以該折的訓練資料學習。","options":{"A":"此寫法並非標準流程，而是存在資料洩漏問題：LDA在交叉驗證之前先以整體資料（含測試折）進行降維學習，使測試資料的資訊間接影響了降維轉換，此為常見錯誤而非正確做法。","B":"正確。LDA是監督式降維方法，若在交叉驗證前先以整體資料（含測試折）進行降維學習，會讓測試資料的類別資訊提前滲入降維過程，屬於資料洩漏，應將LDA納入交叉驗證流程中，確保每折僅用該折訓練資料學習LDA轉換。","C":"資料洩漏會導致交叉驗證評估出的準確率被高估，並不能代表模型真實的泛化能力，此敘述與資料洩漏的影響相反。","D":"跳過LDA步驟並非解決資料洩漏問題的方法，且題目研究人員本意即是比較「LDA+KNN」的流程效果，直接跳過LDA無法解決程式碼中資料洩漏的核心問題。"}},"origin":"past"},{"id":"middle_115-1_s3_q45","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":45,"context":{"text":"請依據下方資訊回答第44~45題。\nIris是UCI Dataset上的一組經典資料集，常被用來教學與測試分類模型。\n這份資料包含三種類型的鳶尾花（Iris setosa、Iris versicolor、Iris virginica），每個類\n別各有50筆資料。\n每筆資料包含四個特徵：花萼長度、花萼寬度、花瓣長度、花瓣寬度。\n研究人員希望透過機器學習模型，根據花朵的形態特徵，自動判斷該花屬於哪一種\n類型。在本次任務中，研究人員希望比較不同分類模型的表現。他們首先嘗試用線\n性判別分析（LDA）進行降維，接著使用K最近鄰（KNN）分類器來做分類預測，\n並使用交叉驗證（Cross Validation）評估模型的準確率。","figures":["images/middle_115-1_s3_ctx3_fig1.png"]},"stem":"研究人員在程式（下圖）中使用cross_val_score進行交叉驗證，但目前尚未設定cv參數。他們希望確保在每次資料分割時，訓練集與測試集的類別比例與原始資料一致，以免影響模型的準確率估計。目前有以下幾段候選程式碼可供選擇。請問為了確保在交叉驗證時每個分割中的類別比例與原始資料一致，上面哪幾段程式碼插入在原始程式中[#填入程式碼]的部分比較合適？","options":{"A":"程式碼B、程式碼C、程式碼D","B":"程式碼A、程式碼C","C":"程式碼A、程式碼B、程式碼D","D":"程式碼C、程式碼D"},"answer":"A","figures":[{"src":"images/middle_115-1_s3_q45_fig1.png","position":"stem"},{"src":"images/middle_115-1_s3_q45_fig2.png","position":"stem"}],"explanation":{"approach":"題目要求交叉驗證時每個分割中的類別比例都與原始資料一致，這正是「分層抽樣」（Stratified）交叉驗證的目的。程式碼B（StratifiedKFold）與程式碼D（RepeatedStratifiedKFold）皆明確使用分層抽樣，能確保各折類別比例與原始資料一致；程式碼C（cv=5，即傳入整數）在sklearn中，若估計器（如KNeighborsClassifier）為分類器，cross_val_score預設即會自動採用StratifiedKFold進行切分，因此同樣能達到分層效果；只有程式碼A使用一般的KFold（僅隨機打散、不保證類別比例），無法確保類別比例一致。","options":{"A":"正確。程式碼B（StratifiedKFold）與D（RepeatedStratifiedKFold）明確採用分層抽樣；程式碼C（cv=5，整數）在分類器情境下，cross_val_score預設會自動採用StratifiedKFold，因此B、C、D皆能確保各折類別比例與原始資料一致。","B":"程式碼A（KFold，僅設定shuffle=True）僅隨機打散樣本、並未依類別比例分層切分，無法保證各折的類別比例與原始資料一致，不應被選入。","C":"此選項納入了程式碼A，但KFold不具備分層抽樣功能，即使shuffle=True仍可能造成各折類別比例失衡，不符合題目「類別比例與原始資料一致」的要求。","D":"此選項排除了程式碼C，但由於分類器搭配整數cv時，cross_val_score預設即會自動使用StratifiedKFold達到分層效果，因此程式碼C亦應被視為合適選項之一，此組合並不完整。"}},"origin":"past"},{"id":"middle_115-1_s3_q46","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":46,"context":{"text":"請依據下方資訊回答第46~48題。\n使用CIFAR-10資料集以建立卷積神經網路（CNN），進行彩色影像之分類與辨識\n分析。CIFAR-10為一常用之影像分類基準資料集，內容包含10個類別，共計60000\n張彩色影像，其中訓練集含50000張影像，測試集則含10000張影像。每張影像解\n析度為32 × 32像素，並具有三個通道（channel），分別對應紅、綠、藍三原色。\n以下程式碼片段示範資料載入與處理流程。\n下圖顯示資料集的第1筆部分資料。","figures":["images/middle_115-1_s3_ctx5_fig1.png","images/middle_115-1_s3_ctx5_fig2.png"]},"stem":"參考下圖資料處理，下列哪一項描述組合正確？","options":{"A":"描述A、描述C、描述F","B":"描述B、描述D、描述E、描述F","C":"描述B、描述C、描述E、描述F","D":"描述A、描述B、描述D、描述E、描述F"},"answer":"B","figures":[{"src":"images/middle_115-1_s3_q46_fig1.png","position":"stem"}],"explanation":{"approach":"圖中六段描述須逐一判斷真偽：描述A稱像素壓縮到「0~31」範圍，但x_train/255.0實際結果為0~1，數值錯誤；描述C稱此轉換相當於z-score標準化，但除以255只是線性的min-max縮放、並未用到平均值與標準差，亦錯誤。描述B（有助泛化）、D（正規化避免梯度爆炸或消失）、E（to_categorical即One-hot編碼）、F（One-hot標籤適合搭配Softmax輸出層）皆為正確敘述。因此正確組合恰為「描述B、描述D、描述E、描述F」，對應選項B。","options":{"A":"組合為「描述A、描述C、描述F」，但描述A（誤稱範圍為0~31）與描述C（誤稱相當於z-score標準化）皆為錯誤敘述，混入錯誤描述使此組合不成立。","B":"正確。組合「描述B、描述D、描述E、描述F」恰好對應四項皆為正確的描述：有助泛化、避免梯度爆炸或消失、轉為One-hot編碼、適合搭配Softmax輸出層，完整且無誤地涵蓋所有正確敘述。","C":"組合為「描述B、描述C、描述E、描述F」，其中描述C（誤稱除以255相當於z-score標準化）為錯誤敘述，混入此錯誤描述使整體組合不正確。","D":"組合為「描述A、描述B、描述D、描述E、描述F」，其中描述A（誤稱範圍為0~31）為錯誤敘述，多納入此錯誤描述使整體組合不正確。"}},"origin":"past"},{"id":"middle_115-1_s3_q47","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":47,"context":{"text":"請依據下方資訊回答第46~48題。\n使用CIFAR-10資料集以建立卷積神經網路（CNN），進行彩色影像之分類與辨識\n分析。CIFAR-10為一常用之影像分類基準資料集，內容包含10個類別，共計60000\n張彩色影像，其中訓練集含50000張影像，測試集則含10000張影像。每張影像解\n析度為32 × 32像素，並具有三個通道（channel），分別對應紅、綠、藍三原色。\n以下程式碼片段示範資料載入與處理流程。\n下圖顯示資料集的第1筆部分資料。","figures":["images/middle_115-1_s3_ctx5_fig1.png","images/middle_115-1_s3_ctx5_fig2.png"]},"stem":"參考下圖建立模型結果，下列哪一項描述組合正確？","options":{"A":"描述A、描述C","B":"描述C、描述E、描述F","C":"描述A、描述D、描述E","D":"描述D、描述E、描述F"},"answer":"B","figures":[{"src":"images/middle_115-1_s3_q47_fig1.png","position":"stem"}],"explanation":{"approach":"圖中六段描述須逐一判斷真偽：描述A稱Input層主要目的是資料標準化，但Input層僅宣告輸入形狀，並不執行標準化，錯誤；描述B稱該層Conv2D(32,...)輸出shape為(32,32,3)，但filters=32、padding=\"same\"時應輸出(32,32,32)，數值錯誤；描述D稱Dropout(0.25)會將25%神經元輸出「設定為1」，但Dropout實際是設為0（丟棄），描述相反，錯誤。描述C（BatchNorm置於Conv2D後可減少梯度消失或爆炸）、E（Dropout可減少過擬合）、F（Flatten將3D特徵圖展平為1D向量）皆為正確敘述。因此正確組合恰為「描述C、描述E、描述F」，對應選項B。","options":{"A":"組合為「描述A、描述C」，其中描述A（誤稱Input層用於資料標準化）為錯誤敘述，混入此錯誤描述使組合不正確。","B":"正確。組合「描述C、描述E、描述F」恰好對應三項皆為正確的描述：BatchNorm置於Conv2D之後有助穩定梯度、Dropout有助降低過擬合、Flatten將3D特徵圖展平為1D向量，完整且無誤地涵蓋所有正確敘述。","C":"組合為「描述A、描述D、描述E」，其中描述A（Input層非用於標準化）與描述D（Dropout應設為0而非1）皆為錯誤敘述，僅描述E正確，此組合不成立。","D":"組合為「描述D、描述E、描述F」，其中描述D（誤稱Dropout將輸出設定為1）為錯誤敘述，混入此錯誤描述使整體組合不正確。"}},"origin":"past"},{"id":"middle_115-1_s3_q48","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":48,"context":{"text":"請依據下方資訊回答第46~48題。\n使用CIFAR-10資料集以建立卷積神經網路（CNN），進行彩色影像之分類與辨識\n分析。CIFAR-10為一常用之影像分類基準資料集，內容包含10個類別，共計60000\n張彩色影像，其中訓練集含50000張影像，測試集則含10000張影像。每張影像解\n析度為32 × 32像素，並具有三個通道（channel），分別對應紅、綠、藍三原色。\n以下程式碼片段示範資料載入與處理流程。\n下圖顯示資料集的第1筆部分資料。","figures":["images/middle_115-1_s3_ctx5_fig1.png","images/middle_115-1_s3_ctx5_fig2.png"]},"stem":"參考下圖繪圖結果，當Epochs=6時，訓練曲線值(0.81)明顯大於驗證曲線值(0.72)，下列何者為最可能的原因？","options":{"A":"學習率（Learning Rate）太低","B":"批次大小（Batch Size）設定太大","C":"模型低度擬合（Underfitting）","D":"模型過擬合（Overfitting）"},"answer":"D","figures":[{"src":"images/middle_115-1_s3_q48_fig1.png","position":"stem"}],"explanation":{"approach":"由訓練曲線圖可見，隨Epochs增加，訓練準確率持續穩定上升並逐漸高於驗證準確率（在Epoch=6時訓練約0.81、驗證約0.72，兩者出現明顯落差，且驗證曲線在後段呈現震盪、未能同步跟上訓練曲線），這是模型在訓練集上學得越來越好、但對未見過的驗證資料泛化能力相對不足的典型過擬合（Overfitting）現象。","options":{"A":"學習率過低通常會使訓練與驗證曲線「同步」緩慢上升、皆難以收斂，而非造成訓練與驗證準確率之間出現明顯落差，與圖中現象不符。","B":"批次大小設定過大主要影響訓練的穩定性與收斂速度，並非典型造成訓練準確率持續高於驗證準確率、兩者出現落差的直接原因。","C":"低度擬合（Underfitting）代表模型連訓練集都學不好，訓練準確率會偏低，但圖中訓練準確率持續上升且明顯高於驗證準確率，並非欠擬合的表現。","D":"正確。訓練準確率持續上升並明顯高於驗證準確率、兩者出現落差，是模型在訓練資料上學習過度、但對驗證資料泛化能力相對不足的典型過擬合現象。"}},"origin":"past"},{"id":"middle_115-1_s3_q49","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":49,"context":{"text":"某人工智慧團隊正在開發一套自動光學檢測（Automated Optical Inspection, AOI）系統，目標是透過機械手臂上的相機，自動辨識晶圓表面是否存在「劃傷（Scratch）」或「污點（Spot）」等瑕疵。目前系統開發面臨以下挑戰：\n● 資料極度不平衡，正常晶圓影像約佔99%，有瑕疵影像僅佔1%。\n● 輸入影像品質不一致，包含不同解析度，且部分影像因機械手臂震動而出現模糊。\n● 在使用深層卷積神經網路（CNN）訓練時，Loss曲線震盪劇烈，甚至偶爾出現數值溢出（NaN）情形。\n請根據上述情境，回答第49~50題。","figures":[]},"stem":"若團隊需要建立一個超過50層的深層神經網路，以捕捉晶圓表面細微的劃傷特徵，但又擔心傳統深層網路常見的梯度消失（Vanishing Gradient）問題，則下列哪一種經典架構最適合優先考慮？","options":{"A":"VGG（Visual Geometry Group）：透過重複堆疊3×3卷積層與池化層來維持梯度穩定","B":"GoogLeNet：透過Inception模塊並行使用不同大小的卷積核，以避免深層網路的梯度問題","C":"ResNet（Residual Network）：透過殘差連接（Residual Connection / SkipConnection），使梯度能跨層傳遞並降低深層訓練困難","D":"Vision Transformer（ViT）：完全捨棄卷積，因此不會出現任何深層模型的訓練問題"},"answer":"C","figures":[],"explanation":{"approach":"題目要求建立超過50層的深層網路、同時解決常見的梯度消失問題。ResNet透過殘差連接（Skip Connection）讓輸入可以跨層直接傳遞至後面的層，使梯度在反向傳播時能透過捷徑直接回傳，大幅降低深層網路訓練困難與梯度消失的問題，是此情境下最經典且對應明確的架構選擇。","options":{"A":"VGG僅是重複堆疊3×3卷積與池化層，並未包含任何緩解梯度消失的特殊機制，層數越深仍會面臨梯度消失問題，無法有效支撐50層以上的訓練。","B":"GoogLeNet的Inception模塊主要目的是在同一層並行使用不同尺寸卷積核以擷取多尺度特徵、提升參數效率，並非其解決深層梯度消失問題的核心設計。","C":"正確。ResNet的殘差連接讓梯度能夠跨層直接傳遞，有效降低深層網路的訓練困難與梯度消失問題，是解決50層以上深層網路訓練問題最經典的架構。","D":"ViT雖然捨棄卷積改用注意力機制，但仍為深層架構，同樣可能面臨深層訓練上的困難，「完全不會出現任何深層模型的訓練問題」的敘述過於絕對，並不正確。"}},"origin":"past"},{"id":"middle_115-1_s3_q50","level":"middle","session":"115-1","subject":3,"subject_name":"機器學習技術與應用","number":50,"context":{"text":"某人工智慧團隊正在開發一套自動光學檢測（Automated Optical Inspection, AOI）系統，目標是透過機械手臂上的相機，自動辨識晶圓表面是否存在「劃傷（Scratch）」或「污點（Spot）」等瑕疵。目前系統開發面臨以下挑戰：\n● 資料極度不平衡，正常晶圓影像約佔99%，有瑕疵影像僅佔1%。\n● 輸入影像品質不一致，包含不同解析度，且部分影像因機械手臂震動而出現模糊。\n● 在使用深層卷積神經網路（CNN）訓練時，Loss曲線震盪劇烈，甚至偶爾出現數值溢出（NaN）情形。\n請根據上述情境，回答第49~50題。","figures":[]},"stem":"為了修復訓練過程中Loss突然變成NaN的問題，工程師考慮在PyTorch訓練迴圈中加入梯度裁剪（Gradient Clipping）機制，例如torch.nn.utils.clip_grad_norm_。若要正確加入梯度裁剪，最適合插入於哪個位置？其主要作用為何？","options":{"A":"插入於位置3與位置4之間；用以限制Loss數值大小，避免梯度消失","B":"插入於位置4與位置5之間；用以限制梯度範數過大，避免更新步幅失控導致數值不穩","C":"插入於位置5之後；用以將更新後的權重強制壓縮回正常範圍","D":"插入於位置1與位置2之間；用以對輸入影像進行批次標準化"},"answer":"B","figures":[{"src":"images/middle_115-1_s3_q50_fig1.png","position":"stem"}],"explanation":{"approach":"梯度裁剪（Gradient Clipping）的作用是限制反向傳播計算出的梯度範數，避免梯度過大導致參數更新步伐失控、產生數值不穩定（如NaN）。程式碼中位置4為loss.backward()（計算梯度完成後），位置5為optimizer.step()（依梯度更新參數），因此梯度裁剪應插入在位置4與位置5之間，即梯度已算出、但尚未用來更新參數之前，先將梯度範數限制在合理範圍內。","options":{"A":"位置3與位置4之間是計算loss之後、尚未執行backward()產生梯度，此時梯度尚未存在，無法在此處對梯度進行裁剪。","B":"正確。位置4（loss.backward()）已完成梯度計算、位置5（optimizer.step()）尚未依梯度更新參數，此時插入梯度裁剪可限制梯度範數過大的情形，避免更新步幅失控導致數值不穩（如Loss變成NaN）。","C":"位置5（optimizer.step()）之後，參數已經完成更新，此時再處理的對象是「更新後的權重」而非「梯度」，無法達到限制梯度範數、避免更新步幅失控的效果。","D":"位置1與位置2之間是optimizer.zero_grad()之後、模型尚未進行前向傳播（model(images)之前），此階段既未產生梯度也非批次標準化的插入時機，與梯度裁剪的作用無關。"}},"origin":"past"},{"id":"guide_middle_s1_c1_q01","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":1,"context":null,"stem":"下列何者為自然語言處理（NLP）中的詞嵌入技術，能將文字轉換為向量以利機器學習處理？","options":{"A":"TF-IDF","B":"Word2Vec","C":"Stop Words","D":"Bag-of-Words"},"answer":"B","figures":[],"explanation":{"approach":"Word2Vec 是一種詞嵌入方法，可將文字轉換為連續向量空間中具語意的表示，有利後續模型學習。","options":{"A":"TF-IDF 是統計詞頻與逆文件頻率的加權方法，用於衡量詞語重要性，並非將文字轉換為具語意向量的詞嵌入技術。","B":"Word2Vec 透過神經網路將詞彙映射到連續向量空間，使語意相近的詞彙在向量空間中距離相近，為典型詞嵌入技術。","C":"Stop Words（停用詞）僅是文字前處理階段用於過濾常見無意義詞彙的概念，不涉及向量化表示。","D":"Bag-of-Words 僅記錄詞彙出現次數或有無出現，不考慮語意與詞序，不屬於詞嵌入技術。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q02","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":2,"context":null,"stem":"在自然語言處理應用中，哪一項任務主要目的是從文字中識別出人名、地名、組織等資訊？","options":{"A":"情感分析","B":"主題建模","C":"命名實體識別","D":"語音辨識"},"answer":"C","figures":[],"explanation":{"approach":"命名實體識別（Named Entity Recognition, NER）用於辨識文本中的具名實體，如人名、地點與組織等。","options":{"A":"情感分析是判斷文字所表達的情緒傾向（正面／負面／中性），並非識別具名實體。","B":"主題建模用於從大量文件中挖掘潛在主題分布，與辨識人名、地名等具名實體無關。","C":"命名實體識別（NER）的任務即為從文字中找出人名、地名、組織等具名資訊，為正確答案。","D":"語音辨識是將聲音訊號轉換為文字，屬於輸入模態轉換，並非文字中的實體辨識任務。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q03","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":3,"context":null,"stem":"語言模型 BERT 的主要特性為何？","options":{"A":"使用遞迴神經網路","B":"無法處理上下文資訊","C":"為單向語言模型","D":"具雙向上下文理解能力"},"answer":"D","figures":[],"explanation":{"approach":"BERT（Bidirectional Encoder Representations from Transformers）可同時考慮上下文中前後的語意，有利於更精準的語言理解。","options":{"A":"BERT 是基於 Transformer 架構的模型，並非使用遞迴神經網路（RNN），此為錯誤描述。","B":"此敘述與 BERT 特性相反，BERT 正是因為能有效處理上下文語意而著稱。","C":"BERT 並非單向語言模型（如 GPT 才是單向），其設計目的即在於克服單向模型的限制。","D":"BERT（Bidirectional Encoder Representations from Transformers）可同時考慮詞彙前後文語意，具雙向上下文理解能力，為正確答案。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q04","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":4,"context":null,"stem":"在電腦視覺中，影像分類（Image Classification）的主要任務是？","options":{"A":"區分影像中不同實體的邊界","B":"產生新的影像內容","C":"為整張圖片指定一個標籤","D":"判斷影像是否含有文字"},"answer":"C","figures":[],"explanation":{"approach":"影像分類是電腦視覺的基本任務之一，其目標是判斷整張影像的主要內容屬於哪一預定義類別，例如將圖片分類為「貓」、「狗」、「汽車」等。選項（A）描述的是語義分割（Semantic Segmentation），（B）屬於生成式任務如風格轉換，（D）則是目標偵測（Object Detection），因此僅有（C）為正確答案。","options":{"A":"區分影像中不同實體邊界屬於語義分割（Semantic Segmentation）的任務，並非影像分類。","B":"產生新的影像內容屬於生成式任務（如影像生成、風格轉換），與判斷影像類別的分類任務不同。","C":"影像分類的目標是為整張影像指定一個所屬類別標籤，例如判斷圖片為「貓」或「狗」，為正確答案。","D":"判斷影像是否含有文字或特定物件較接近目標偵測（Object Detection）的概念，而非影像分類。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q05","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":5,"context":null,"stem":"若需在一張影像中辨識出多個目標並標示其位置，最適合使用何種技術？","options":{"A":"影像增強","B":"影像分類","C":"目標偵測","D":"圖像生成"},"answer":"C","figures":[],"explanation":{"approach":"目標偵測（Object Detection）能辨識圖像中多個實體，並給出邊界框位置資訊。","options":{"A":"影像增強是改善影像品質（如去雜訊、調整對比度）的前處理技術，無法辨識或標示多個目標位置。","B":"影像分類僅能判斷整張影像所屬的單一類別，無法同時辨識多個目標並標示其位置。","C":"目標偵測（Object Detection）能同時辨識影像中的多個實體並以邊界框標示其位置，為正確答案。","D":"圖像生成是產生新的影像內容，並非辨識既有影像中目標的位置。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q06","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":6,"context":null,"stem":"生成對抗網路（GAN）的訓練包含哪兩個核心組件？","options":{"A":"分類器與分群器","B":"產生器與鑑別器","C":"強化器與回饋器","D":"解碼器與編碼器"},"answer":"B","figures":[],"explanation":{"approach":"GAN 由產生器（Generator）負責生成資料，鑑別器（Discriminator）判斷真偽，兩者相互對抗學習。","options":{"A":"分類器與分群器分屬監督式與非監督式學習的常見模型類型，並非 GAN 的組成架構。","B":"GAN 由產生器（Generator）負責生成資料，鑑別器（Discriminator）負責判斷資料真偽，兩者對抗訓練，為正確答案。","C":"「強化器」與「回饋器」並非標準 AI 術語，也不是 GAN 的架構組件。","D":"編碼器與解碼器是 Autoencoder 或 Seq2Seq 等架構的核心組件，並非 GAN 的訓練組件。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q07","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":7,"context":null,"stem":"在以下哪一個任務中，生成式 AI 技術最常被應用？","options":{"A":"詐欺偵測","B":"語音辨識","C":"圖片風格轉換","D":"資料壓縮"},"answer":"C","figures":[],"explanation":{"approach":"圖片風格轉換（如將相片轉為畫風）是生成式 AI 常見應用之一，通常利用 GAN 完成。","options":{"A":"詐欺偵測通常屬於分類或異常偵測任務，並非生成式 AI 的典型應用場景。","B":"語音辨識是將語音轉換為文字的辨識任務，並非以生成新內容為主的生成式 AI 應用。","C":"圖片風格轉換（如將照片轉為特定畫風）是生成式 AI（常見以 GAN 實現）的典型應用之一，為正確答案。","D":"資料壓縮屬於資訊編碼與儲存效率的技術，並非生成式 AI 的主要應用領域。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q08","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":8,"context":null,"stem":"多模態人工智慧的核心目標為何？","options":{"A":"提升硬體運算效能","B":"同時處理並整合來自不同感知類型的資料","C":"專注於純文字輸入的分析","D":"僅適用於影像分類任務"},"answer":"B","figures":[],"explanation":{"approach":"多模態 AI 整合文字、影像、聲音等不同資料來源，提升模型理解與生成能力。","options":{"A":"提升硬體運算效能屬於基礎設施層面的議題，並非多模態 AI 定義的核心目標。","B":"多模態 AI 的核心目標即在於同時處理並整合文字、影像、聲音等不同感知類型的資料，為正確答案。","C":"僅專注於純文字輸入分析屬於單一模態處理，與多模態強調整合多種資料類型的定義相反。","D":"多模態 AI 的應用範圍遠不止影像分類，此描述過度限縮其適用範疇。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q09","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":9,"context":null,"stem":"CLIP 模型結合了哪兩種模態進行訓練？","options":{"A":"聲音與影像","B":"影像與文字","C":"文字與數值","D":"圖形與表格"},"answer":"B","figures":[],"explanation":{"approach":"CLIP 由 OpenAI 所提出，透過大量圖文配對資料進行對比學習，使模型能理解跨模態語意關聯。","options":{"A":"CLIP 並非以聲音與影像配對進行訓練，此為錯誤的模態組合。","B":"CLIP 由 OpenAI 提出，利用大量圖文配對資料進行對比學習，結合影像與文字兩種模態，為正確答案。","C":"文字與數值並非 CLIP 訓練所使用的模態組合。","D":"圖形與表格並非 CLIP 訓練所使用的模態組合。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c1_q10","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":10,"context":null,"stem":"在多模態 AI 應用中，以下哪一情境最能展現其優勢？","options":{"A":"SQL 資料查詢","B":"純圖片壓縮","C":"影片自動生成字幕","D":"單一感測器故障排除"},"answer":"C","figures":[],"explanation":{"approach":"影片字幕生成涉及聲音（語音辨識）、文字（轉錄）、影像（上下文輔助）等多模態資料處理。","options":{"A":"SQL 資料查詢屬於結構化資料的操作，並非整合多種感知模態的應用情境。","B":"純圖片壓縮僅處理單一影像模態，未涉及跨模態資料整合，無法展現多模態優勢。","C":"影片自動生成字幕需整合聲音（語音辨識）、文字（轉錄）與影像（上下文輔助）等多種模態資料，最能展現多模態 AI 優勢，為正確答案。","D":"單一感測器故障排除僅涉及單一資料來源，並非多模態資料整合的應用情境。"},"source":"official","note":"官方解析第一句（影片字幕生成涉及聲音、文字、影像等多模態資料處理）已足以支持答案 C，其後附加的大段文字為該章節（AI 導入評估規劃）的章節簡介，與本題選項內容無直接關聯，研判為資料整理時誤植，逐選項說明未採用該段落。"},"origin":"guide"},{"id":"guide_middle_s1_c2_q01","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":1,"context":null,"stem":"在評估企業 AI 導入可行性時，下列哪一項屬於「商業價值評估」的考量？","options":{"A":"模型參數量大小","B":"開發人員數量","C":"預期效益與回報","D":"演算法選擇難度"},"answer":"C","figures":[],"explanation":{"approach":"商業價值評估主要衡量 AI 專案在解決問題或創造價值上的潛力，例如降低成本、增加收入或提升效率。","options":{"A":"模型參數量大小屬於模型技術規格層面的考量，並非商業價值評估的重點。","B":"開發人員數量屬於專案資源規劃範疇，並非用以衡量商業價值的指標。","C":"預期效益與回報（如降低成本、增加收入、提升效率）正是商業價值評估的核心考量，為正確答案。","D":"演算法選擇難度屬於技術可行性評估範疇，並非商業價值評估的重點。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q02","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":2,"context":null,"stem":"在進行 AI 導入評估時，為確保企業體系具備執行能力，應考量下列哪一項？","options":{"A":"使用者介面風格","B":"技術成熟度與部署資源","C":"品牌識別度","D":"客服滿意度"},"answer":"B","figures":[],"explanation":{"approach":"技術評估是導入前的重要環節，需確認所選技術是否穩定且能在現有架構下順利實作。","options":{"A":"使用者介面風格屬於 UI/UX 設計層面，與企業執行能力（技術與部署資源）的評估無關。","B":"技術成熟度與部署資源決定企業是否具備穩定實作與落地 AI 的能力，為執行能力評估的關鍵考量，為正確答案。","C":"品牌識別度屬於行銷與品牌經營範疇，與企業執行 AI 專案的能力無關。","D":"客服滿意度屬於既有服務品質指標，並非導入可行性中執行能力的評估項目。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q03","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":3,"context":null,"stem":"企業進行 AI 導入前的評估分析，通常第一步應聚焦於？","options":{"A":"演算法選擇","B":"資料標註工具","C":"業務痛點與需求辨識","D":"建立測試模型"},"answer":"C","figures":[],"explanation":{"approach":"AI 導入需以業務需求為出發點，若無明確問題定義，後續模型開發將失焦或無法產生實際效益。","options":{"A":"演算法選擇屬於後續模型開發階段的工作，並非導入評估的第一步。","B":"資料標註工具的選用屬於技術執行細節，應在需求明確之後才會涉及。","C":"企業應先辨識業務痛點與需求，以此為出發點才能確保後續 AI 導入聚焦於實際效益，為正確答案。","D":"建立測試模型須在需求與問題定義明確後才進行，若貿然建模容易失焦，並非第一步。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q04","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":4,"context":null,"stem":"在 AI 導入專案的初期規劃階段，下列哪一項屬於「人員規劃」的重點內容？","options":{"A":"API 規格設計","B":"模型優化參數","C":"AI 專案所需的跨部門協作角色","D":"作業系統版本"},"answer":"C","figures":[],"explanation":{"approach":"AI 專案導入涉及資料、業務、IT 等部門合作，需在規劃階段即明確分工與責任分配。","options":{"A":"API 規格設計屬於技術架構設計工作，並非人員規劃的重點內容。","B":"模型優化參數屬於技術細節範疇，與人員角色分工無關。","C":"AI 專案需要資料、業務、IT 等跨部門協作，明確分工與角色安排正是人員規劃的重點，為正確答案。","D":"作業系統版本屬於 IT 基礎設施議題，並非人員規劃的內容。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q05","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":5,"context":null,"stem":"在 AI 導入規劃過程中，為確保專案順利推進並落實業務需求，下列哪一項規劃內容最能避免部門間溝通斷裂與責任不清的風險？","options":{"A":"確認所採用演算法的最新研究成果","B":"由高階主管全權拍板模型選擇與部署方式","C":"建立跨部門協作機制與角色分工","D":"優先採購效能最佳的 GPU 運算資源"},"answer":"C","figures":[],"explanation":{"approach":"AI 導入需橫跨業務、資料、IT 等多部門，若缺乏明確的溝通與分工安排，容易出現責任模糊或推進不順。建立協作機制可確保需求對齊、資料準備、模型開發與部署流程協同一致，是規劃階段關鍵工作。其他選項則過度聚焦於單點技術或管理決策，無法解決跨部門合作問題。","options":{"A":"確認演算法最新研究成果屬於技術面的考量，無助於解決部門間溝通斷裂與責任不清的問題。","B":"由高階主管全權拍板決策雖然集中權責，但若缺乏協作機制，執行面仍可能因溝通不足而出現落差。","C":"建立跨部門協作機制與角色分工，能確保需求對齊、資料準備、模型開發與部署流程協同一致，直接解決溝通斷裂與責任不清的風險，為正確答案。","D":"優先採購高效能 GPU 資源屬於硬體投資議題，與部門間溝通及責任分工無直接關聯。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q06","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":6,"context":null,"stem":"當 AI 導入規劃需評估系統部署模式時，若考量資料隱私與本地控制需求，應優先考慮？","options":{"A":"第三方雲端部署","B":"地端私有部署","C":"區塊鏈儲存方式","D":"外包給 AI 公司"},"answer":"B","figures":[],"explanation":{"approach":"地端部署可提供更強的資料控制與隱私保障，常見於金融、政府、醫療等敏感領域。","options":{"A":"第三方雲端部署須將資料交付外部業者代管，資料控制程度與隱私保障相對較低。","B":"地端私有部署可將資料保留於企業自有環境中，提供更強的資料控制與隱私保障，為正確答案，常見於金融、政府、醫療等敏感領域。","C":"區塊鏈儲存方式並非典型的系統部署模式選項，與資料隱私控制需求的直接對應性較低。","D":"外包給 AI 公司仍須將資料交付第三方處理，難以滿足本地控制與隱私需求。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q07","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":7,"context":null,"stem":"在 AI 風險評估中，若模型輸出不穩定且缺乏邏輯可解釋性，可能帶來哪一風險？","options":{"A":"模型效率過高","B":"公平性過度提升","C":"決策透明性不足","D":"資料使用效率太高"},"answer":"C","figures":[],"explanation":{"approach":"模型無法解釋其輸出會降低使用者與監管單位的信任，是常見的 AI 風險來源之一。","options":{"A":"模型效率過高與輸出穩定性、可解釋性無關，並非此情境所指出的風險。","B":"公平性並不存在「過度提升」的風險說法，且此描述與模型缺乏可解釋性的情境無關。","C":"模型輸出不穩定且缺乏邏輯可解釋性，會使使用者與監管單位難以信任其決策依據，形成決策透明性不足的風險，為正確答案。","D":"資料使用效率太高與模型輸出穩定性、可解釋性缺乏無關，並非合理的風險描述。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q08","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":8,"context":null,"stem":"以下何者屬於 AI 模型偏誤造成的風險？","options":{"A":"語法錯誤","B":"輸入資料格式錯誤","C":"特定族群預測結果不公平","D":"模型壓縮後效能下降"},"answer":"C","figures":[],"explanation":{"approach":"資料或模型偏誤常導致對少數族群、女性或弱勢族群的不公平結果，是需積極管理的 AI 倫理風險。","options":{"A":"語法錯誤屬於程式撰寫層面的問題，與模型偏誤無關。","B":"輸入資料格式錯誤屬於資料工程或系統整合問題，並非模型偏誤造成的風險。","C":"模型偏誤常導致對特定族群（如少數族群、女性、弱勢群體）的預測結果不公平，是需積極管理的 AI 倫理風險，為正確答案。","D":"模型壓縮後效能下降屬於模型優化技術的取捨問題，與偏誤無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q09","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":9,"context":null,"stem":"為管理 AI 導入過程中的「法律與合規風險」，企業應採取何種措施？","options":{"A":"強化演算法複雜度","B":"減少模型訓練次數","C":"檢視個資使用的合法性","D":"加速模型部署速度"},"answer":"C","figures":[],"explanation":{"approach":"若使用涉及個人資料，須確認是否符合資料保護法（如 GDPR 或個資法）規範。","options":{"A":"強化演算法複雜度屬於技術面的調整，與法律及合規風險管理無關。","B":"減少模型訓練次數屬於訓練資源管理，並不能解決法規合規問題。","C":"若使用涉及個人資料，企業應檢視其使用是否符合資料保護法規（如 GDPR 或個資法），為管理法律與合規風險的正確作法。","D":"加速模型部署速度不僅無助於合規風險管理，反而可能因略過必要審查而增加風險。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c2_q10","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":10,"context":null,"stem":"AI 模型部署後，若長期輸入資料分佈逐漸改變，導致模型效能下降，最適合採取下列哪一項作法進行風險管理？","options":{"A":"定期重啟伺服器以排除效能問題","B":"加入多個冗餘模型以進行同時預測","C":"建置概念漂移監控與觸發模型再訓練流程","D":"縮減模型層數以降低計算成本"},"answer":"C","figures":[],"explanation":{"approach":"概念漂移（Concept Drift）指資料分佈隨時間改變，可能使模型預測確率下降，因此在風險管理架構中，須建置監控機制偵測輸入與輸出異常，並結合模型再訓練策略進行調整。選項（A）（D）與風險無直接關聯，（B）雖具備冗餘設計概念，但不直接針對資料變異處理。","options":{"A":"定期重啟伺服器僅能排除系統運作異常，無法解決因資料分佈改變（概念漂移）造成的預測失準問題。","B":"加入多個冗餘模型屬於系統備援設計概念，並非針對資料分布變化所做的因應措施。","C":"概念漂移（Concept Drift）指資料分佈隨時間改變導致模型效能下降，應建置監控機制偵測異常並觸發模型再訓練，為正確作法。","D":"縮減模型層數是為了降低運算成本，與因應概念漂移的風險管理無關，甚至可能犧牲模型效能。"},"source":"official","note":"官方解析前半段（概念漂移定義與各選項對錯說明）已完整回答本題，其後附加的大段文字為下一章節（AI 技術系統集成與部署）的章節簡介，與本題選項內容無直接關聯，研判為資料整理時誤植，逐選項說明未採用該段落。"},"origin":"guide"},{"id":"guide_middle_s1_c3_q01","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":1,"context":null,"stem":"在進行 AI 建模前，進行「資料標註」的主要目的是？","options":{"A":"減少資料容量","B":"強化系統安全性","C":"讓模型能夠辨識輸入與目標之間的對應關係","D":"提升資料儲存速度"},"answer":"C","figures":[],"explanation":{"approach":"資料標註是監督式學習的關鍵步驟，能讓模型理解每筆資料對應的標籤或結果。","options":{"A":"資料標註並不會減少資料容量，與資料壓縮無關。","B":"資料標註與系統安全性的強化無關，屬於不相關的選項。","C":"資料標註是監督式學習的關鍵步驟，其目的在於讓模型能辨識輸入資料與目標標籤之間的對應關係，為正確答案。","D":"資料標註不涉及資料儲存機制，與提升儲存速度無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q02","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":2,"context":null,"stem":"在特徵工程中，進行特徵標準化（如 Z-score 標準化）的主要目的是？","options":{"A":"增加欄位數量","B":"提升資料壓縮效率","C":"將特徵縮放至相同尺度，利於模型學習","D":"將文字轉換為向量"},"answer":"C","figures":[],"explanation":{"approach":"許多演算法（如 SVM、KNN）對特徵尺度敏感，標準化有助於提升模型表現與穩定性。","options":{"A":"特徵標準化是調整數值尺度，並不會增加欄位數量。","B":"特徵標準化的目的不在於提升資料壓縮效率，兩者屬不同範疇。","C":"許多演算法（如 SVM、KNN）對特徵尺度敏感，標準化可將不同特徵縮放至相同尺度，有助於提升模型學習效果與穩定性，為正確答案。","D":"將文字轉換為向量屬於詞嵌入等文字特徵處理技術，並非數值標準化的目的。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q03","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":3,"context":null,"stem":"若某企業的目標是預測顧客是否會流失，最適合選用下列哪一種模型任務？","options":{"A":"分類任務","B":"迴歸任務","C":"生成任務","D":"分群任務"},"answer":"A","figures":[],"explanation":{"approach":"顧客流失通常為「會/不會」的二元分類問題，適合使用分類模型如Logistic Regression、決策樹等。","options":{"A":"顧客流失通常為「會／不會」的二元結果，屬於分類問題，適合使用 Logistic Regression、決策樹等分類模型，為正確答案。","B":"迴歸任務用於預測連續數值，並非預測會不會流失此類離散結果的合適任務類型。","C":"生成任務用於產生新內容（如文字、影像），與預測顧客是否流失的目標不符。","D":"分群任務屬於非監督式學習，不需事先標籤即可分組，並不適合此類已有明確結果標籤（流失／未流失）的預測問題。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q04","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":4,"context":null,"stem":"關於模型選擇，下列哪一項敘述較為正確？","options":{"A":"模型越複雜越好","B":"模型應優先考慮開發成本與可部署性","C":"只要準確率高就不需考慮其他指標","D":"模型無須考慮資料量大小"},"answer":"B","figures":[],"explanation":{"approach":"選擇模型需考量資料特性、開發時間、計算成本與後續維運難度，不應一味追求複雜度。","options":{"A":"模型並非越複雜越好，過度複雜可能導致過擬合、增加部署與維運困難，此為錯誤觀念。","B":"選擇模型應綜合考量資料特性、開發成本、計算資源與可部署性，而非一味追求複雜或高準確率，為正確答案。","C":"只重視準確率而忽略可解釋性、公平性、運算成本等其他指標，是不周全的模型選擇方式，此敘述有誤。","D":"資料量大小會直接影響模型選型與訓練策略，並非「無須考慮」，此敘述有誤。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q05","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":5,"context":null,"stem":"下列哪一種資料前處理技術主要用來處理缺失值？","options":{"A":"資料增強","B":"標準化","C":"插補法","D":"降維"},"answer":"C","figures":[],"explanation":{"approach":"插補法（Imputation）可用平均數、中位數、眾數或模型預測方式填補缺失欄位，常用於資料清理階段。","options":{"A":"資料增強是用於擴增資料多樣性（如影像旋轉、翻轉）的技術，並非處理缺失值的方法。","B":"標準化是調整數值尺度以利模型學習，並非用來填補缺失欄位。","C":"插補法（Imputation）可用平均數、中位數、眾數或模型預測等方式填補缺失欄位，是處理缺失值的常見資料清理技術，為正確答案。","D":"降維是用於減少特徵維度、降低運算複雜度的技術，並非處理缺失值的方法。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q06","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":6,"context":null,"stem":"在設計 AI 應用系統架構時，使用容器技術（如 Docker）的主要優點為？","options":{"A":"加快資料標註速度","B":"提升 API 回應速度","C":"促進模型跨平台部署與環境一致性","D":"減少模型所需參數量"},"answer":"C","figures":[],"explanation":{"approach":"容器技術可封裝應用與其依賴環境，確保模型從開發到部署保持一致。","options":{"A":"容器技術與加快資料標註速度無關，兩者屬不同範疇的工作。","B":"容器技術的優點不在於提升 API 回應速度，而在於環境封裝與部署一致性。","C":"容器技術（如 Docker）可封裝應用程式與其相依環境，確保模型從開發到部署維持一致，促進跨平台部署，為正確答案。","D":"容器技術與減少模型參數量無關，參數量屬於模型設計與壓縮的範疇。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q07","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":7,"context":null,"stem":"MLOps 的主要目的為何？","options":{"A":"壓縮模型參數","B":"簡化使用者介面設計","C":"實現 AI 模型的自動化開發、部署與持續維運流程","D":"將 AI 模型嵌入硬體晶片"},"answer":"C","figures":[],"explanation":{"approach":"MLOps 結合 DevOps 與機器學習，可實現模型生命週期的持續整合、測試與監控。","options":{"A":"壓縮模型參數屬於模型優化技術，並非 MLOps 的主要目的。","B":"簡化使用者介面設計與 MLOps 的核心目標無關。","C":"MLOps 結合 DevOps 與機器學習理念，旨在實現 AI 模型開發、部署與持續維運的自動化流程，為正確答案。","D":"將 AI 模型嵌入硬體晶片屬於邊緣運算或晶片設計範疇，並非 MLOps 的定義目的。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q08","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":8,"context":null,"stem":"在邊緣運算架構中，AI 模型的推論通常會發生在哪裡？","options":{"A":"雲端 GPU 伺服器","B":"終端裝置本地端","C":"資料標註平台","D":"資料儲存庫"},"answer":"B","figures":[],"explanation":{"approach":"邊緣 AI 將模型部署至如手機、攝影機、感測器等裝置上，提升即時性並減少延遲。","options":{"A":"雲端 GPU 伺服器是雲端運算的部署模式，與邊緣運算強調在終端進行推論的特性相反。","B":"邊緣 AI 將模型部署至手機、攝影機、感測器等終端裝置本地端進行推論，以提升即時性並減少延遲，為正確答案。","C":"資料標註平台是用於資料前處理的工具，與模型推論執行的位置無關。","D":"資料儲存庫僅具備儲存功能，並非模型推論實際執行的場所。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q09","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":9,"context":null,"stem":"持續監控部署後 AI 模型效能的主要目的為何？","options":{"A":"減少資料備份空間","B":"提升 UI 使用效率","C":"偵測模型概念漂移與效能下降","D":"強化模型壓縮效果"},"answer":"C","figures":[],"explanation":{"approach":"模型部署後若輸入資料特性改變，將可能導致預測不準，故需建立監控機制。","options":{"A":"持續監控模型效能的目的與減少資料備份空間無關。","B":"持續監控模型效能的目的並非提升使用者介面（UI）使用效率。","C":"模型部署後若輸入資料特性隨時間改變，可能導致預測不準，因此需持續監控以偵測概念漂移與效能下降，為正確答案。","D":"持續監控模型效能與強化模型壓縮效果無關，兩者屬不同技術範疇。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s1_c3_q10","level":"middle","session":"學習指引","subject":1,"subject_name":"人工智慧技術應用與規劃","number":10,"context":null,"stem":"在 AI 系統整合過程中，為確保模型可與業務流程無縫對接，通常需要哪種角色協作？","options":{"A":"社群經營人員","B":"資料標註員","C":"產品經理與工程人員","D":"硬體維修技術員"},"answer":"C","figures":[],"explanation":{"approach":"產品經理負責需求對齊與驗證場景，工程人員負責將模型封裝並整合至應用流程。","options":{"A":"社群經營人員的工作聚焦於對外社群互動，與模型和業務流程的技術整合無直接關聯。","B":"資料標註員主要負責訓練資料的標註工作，並非負責模型與業務系統整合對接。","C":"產品經理負責釐清需求並驗證應用場景，工程人員負責將模型封裝並整合至業務流程，兩者協作才能確保系統無縫對接，為正確答案。","D":"硬體維修技術員負責硬體設備維護，與模型和業務流程的整合工作無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q01","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":1,"context":null,"stem":"下列何者屬於「敘述統計」的主要目的？","options":{"A":"建立模型預測未來事件","B":"評估樣本是否顯著","C":"概括並整理資料特徵","D":"檢定兩組資料的平均數是否相等"},"answer":"C","figures":[],"explanation":{"approach":"敘述統計（Descriptive Statistics）主要用於整理、彙整與呈現資料特性，不涉及推論或決策。","options":{"A":"建立模型預測未來事件屬於推論或預測性分析的範疇，並非敘述統計的目的。","B":"評估樣本是否顯著是推論統計（假設檢定）的工作，敘述統計不涉及顯著性判斷。","C":"正確，敘述統計旨在整理、彙整並呈現資料的特性，不涉及推論或決策。","D":"檢定兩組資料平均數是否相等屬於推論統計的假設檢定（如t檢定），超出敘述統計範圍。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q02","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":2,"context":null,"stem":"下列何者為常見的離散型機率分佈？","options":{"A":"常態分佈","B":"指數分佈","C":"貝他分佈","D":"二項分佈"},"answer":"D","figures":[],"explanation":{"approach":"二項分佈用於計算多次伯努利試驗中成功的次數，為典型的離散型分佈。","options":{"A":"常態分佈的隨機變數可取連續區間內任意值，屬於連續型分佈。","B":"指數分佈用於描述事件發生間隔時間，變數值連續，屬於連續型分佈。","C":"貝他分佈定義於[0,1]之連續區間，屬於連續型分佈，而非離散型。","D":"正確，二項分佈用於計算多次伯努利試驗中成功的次數，是典型的離散型分佈。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q03","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":3,"context":null,"stem":"在資料集中若極端值眾多，應優先採用哪一項代表集中趨勢？","options":{"A":"平均數","B":"中位數","C":"眾數","D":"標準差"},"answer":"B","figures":[],"explanation":{"approach":"中位數不受極端值影響，適合描述偏態分佈或有離群值的資料。","options":{"A":"平均數會將所有數值納入計算，容易被極端值拉高或拉低，不適合有離群值的資料。","B":"正確，中位數只取中間排序位置的值，不受極端值影響，適合描述有離群值或偏態分佈的資料。","C":"眾數僅反映出現頻率最高的值，無法完整代表資料整體的集中位置，也不是針對極端值問題設計的指標。","D":"標準差是衡量資料離散程度的指標，並非用來代表集中趨勢。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q04","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":4,"context":null,"stem":"標準差的統計意義為何？","options":{"A":"資料中最大與最小值的距離","B":"數據分佈的對稱程度","C":"資料平均偏離中心值的程度","D":"代表資料的平均數"},"answer":"C","figures":[],"explanation":{"approach":"標準差衡量資料與平均值的偏離程度，是最常見的離散程度指標之一。","options":{"A":"資料中最大與最小值的距離是全距（Range）的定義，並非標準差的意義。","B":"數據分佈的對稱程度是偏態（Skewness）所描述的概念，與標準差不同。","C":"正確，標準差衡量的是資料平均偏離中心值（平均數）的程度，是常見的離散程度指標。","D":"代表資料的平均數本身是「平均數（Mean）」的定義，與標準差是不同的統計量。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q05","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":5,"context":null,"stem":"假設檢定中，若 p 值小於顯著水準 0.05，代表什麼意思？","options":{"A":"接受虛無假設","B":"拒絕虛無假設","C":"樣本數不足","D":"結果不顯著"},"answer":"B","figures":[],"explanation":{"approach":"當 p 值小於設定的顯著水準 α，表示樣本資料與虛無假設有顯著差異，故應拒絕虛無假設。","options":{"A":"接受虛無假設與 p 值小於顯著水準的結論相反，此時應拒絕虛無假設。","B":"正確，p 值小於顯著水準 α，代表樣本結果與虛無假設有顯著差異，故拒絕虛無假設。","C":"p 值大小反映的是統計顯著性，與樣本數是否足夠並無直接對應關係。","D":"p 值小於 0.05 代表結果達統計顯著，而非不顯著，此敘述恰好相反。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q06","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":6,"context":null,"stem":"在統計推論中，哪一個值通常用於判斷假設檢定的顯著性？","options":{"A":"z-score","B":"t 值","C":"p 值","D":"標準差"},"answer":"C","figures":[],"explanation":{"approach":"p 值表示在虛無假設成立的情況下，觀察到現有樣本結果的機率，是統計顯著性的核心指標。","options":{"A":"z-score 是標準化後的分數，用於特定情境下的檢定計算，並非判斷顯著性的核心指標。","B":"t 值是檢定統計量，需搭配對應的 p 值或臨界值才能判讀顯著性，本身不是顯著性判斷的直接依據。","C":"正確，p 值表示在虛無假設成立下觀察到現有樣本結果的機率，是判斷統計顯著性的核心指標。","D":"標準差是描述資料離散程度的指標，與假設檢定的顯著性判斷無直接關聯。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q07","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":7,"context":null,"stem":"下列哪一個情況較適合使用單樣本 t 檢定？","options":{"A":"比較兩群獨立樣本平均差異","B":"比較一組樣本與既定平均值的差異","C":"分析兩變數間的線性關係","D":"檢定類別分佈是否一致"},"answer":"B","figures":[],"explanation":{"approach":"單樣本 t 檢定用來評估樣本平均數是否與某個已知值有顯著差異。","options":{"A":"比較兩群獨立樣本平均差異屬於獨立樣本 t 檢定的應用情境，而非單樣本 t 檢定。","B":"正確，單樣本 t 檢定用來評估一組樣本平均數是否與某個已知（既定）平均值有顯著差異。","C":"分析兩變數間的線性關係屬於相關分析或迴歸分析的範疇，非單樣本 t 檢定的用途。","D":"檢定類別分佈是否一致屬於卡方檢定的應用情境，非單樣本 t 檢定的用途。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q08","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":8,"context":null,"stem":"平均數、標準差、最大值等統計量的取得屬於何種統計方法？","options":{"A":"敘述統計","B":"推論統計","C":"機率模型","D":"監督式學習"},"answer":"A","figures":[],"explanation":{"approach":"這些統計量是對資料本身的描述，不涉及推論或預測，屬於敘述統計。","options":{"A":"正確，平均數、標準差、最大值等統計量是對資料本身特性的描述，屬於敘述統計。","B":"推論統計涉及以樣本結果推論母體特性或進行假設檢定，而非單純描述資料本身的統計量。","C":"機率模型用於描述隨機事件發生的可能性分佈，與直接計算資料的描述性統計量不同。","D":"監督式學習是機器學習中的一種訓練方法，與計算平均數、標準差等統計量的目的無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q09","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":9,"context":null,"stem":"關於常態分佈（Normal Distribution）的敘述，下列何者「錯誤」？","options":{"A":"其分佈曲線呈鐘型且對稱於均值","B":"大多數數據點集中於均值附近，隨著偏離均值逐漸減少","C":"任何類型的數據在樣本數足夠大時，都會呈現常態分佈","D":"標準常態分佈的均值為 0，標準差為 1"},"answer":"C","figures":[],"explanation":{"approach":"中央極限定理指出，當樣本數足夠大時，樣本平均數的分佈會趨近常態分佈；然而，原始資料本身的分佈並不會因此變為常態。","options":{"A":"此敘述正確：常態分佈曲線確實呈鐘型且對稱於均值，並非本題要挑出的錯誤選項。","B":"此敘述正確：常態分佈中大多數數據集中於均值附近，隨偏離均值增加而遞減，並非本題要挑出的錯誤選項。","C":"此為錯誤敘述（本題答案）：中央極限定理指的是樣本數夠大時，樣本『平均數』的抽樣分佈會趨近常態分佈，並不代表原始資料本身會變成常態分佈。","D":"此敘述正確：標準常態分佈依定義其均值為 0、標準差為 1，並非本題要挑出的錯誤選項。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c1_q10","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":10,"context":null,"stem":"若資料呈現明顯左偏，最適合使用下列哪一項統計量作為代表集中趨勢的指標？","options":{"A":"平均數","B":"標準差","C":"中位數","D":"變異係數"},"answer":"C","figures":[],"explanation":{"approach":"當資料呈現偏態分佈（如左偏或右偏）時，平均數容易受到極端值影響，導致偏離中心位置。中位數對極端值不敏感，因此在偏態分佈中較能準確代表資料集中趨勢。","options":{"A":"平均數會將所有數值納入計算，在左偏資料中容易被極端小值拉低，偏離資料真正集中的位置。","B":"標準差是衡量資料離散程度的指標，並非用來代表集中趨勢。","C":"正確，中位數不受極端值影響，在偏態（如左偏）分佈中能較準確代表資料的集中趨勢。","D":"變異係數是標準差與平均數的比值，用於比較不同尺度資料的相對離散程度，並非集中趨勢指標。"},"source":"official","note":"官方 official_explanation 除說明中位數適合偏態分佈的正確理由外，其後段混入與本題無關的大數據處理技術章節介紹文字，屬內容拼接錯誤，逐選項說明僅依前段的正確理由撰寫。"},"origin":"guide"},{"id":"guide_middle_s2_c2_q01","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":1,"context":null,"stem":"在大數據收集階段，若資料來源來自感測器與機台設備，最常見的資料特性為？","options":{"A":"批次性、靜態資料","B":"高頻率、串流型資料","C":"人工產生、低變動性資料","D":"固定欄位、標準化格式資料"},"answer":"B","figures":[],"explanation":{"approach":"感測器與機台設備產出的資料具有即時性與高頻率更新特性，屬於典型的串流資料來源。","options":{"A":"批次性、靜態資料與感測器持續、連續產出資料的特性相反，不符合感測器資料的典型樣貌。","B":"正確，感測器與機台設備通常持續產生資料，具有即時性與高頻率更新特性，屬於串流型資料。","C":"感測器資料是由裝置自動、持續產生，並非人工產生，且更新頻繁、變動性高，與此敘述相反。","D":"此類資料的關鍵特性在於高頻即時性，而非欄位固定或格式標準化，選項描述並非其主要特性。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q02","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":2,"context":null,"stem":"在進行資料清理時，下列哪一項操作主要用於處理欄位中存在空值的情況？","options":{"A":"資料標準化","B":"特徵選擇","C":"遺漏值補全（Imputation）","D":"主成分分析"},"answer":"C","figures":[],"explanation":{"approach":"Imputation 是處理缺失值的主要方法，可透過平均數、中位數或模型預測進行補值。","options":{"A":"資料標準化是將數值調整至統一尺度（如z-score）的處理，並非用於補齊空值。","B":"特徵選擇是挑選對預測任務具意義的欄位，與處理欄位空值無關。","C":"正確，遺漏值補全（Imputation）是處理欄位空值的主要方法，可用平均數、中位數或模型預測進行補值。","D":"主成分分析（PCA）用於資料降維，與處理欄位中的空值無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q03","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":3,"context":null,"stem":"哪一種資料儲存系統較適合處理半結構化資料，如 JSON 或 XML？","options":{"A":"關聯式資料庫（RDBMS）","B":"鍵值資料庫","C":"文件型 NoSQL 資料庫","D":"圖形資料庫"},"answer":"C","figures":[],"explanation":{"approach":"文件型資料庫如 MongoDB 可有效儲存結構不固定的 JSON/XML，常用於半結構化資料管理。","options":{"A":"關聯式資料庫需預先定義固定的資料表結構（schema），不適合結構彈性、巢狀的半結構化資料。","B":"鍵值資料庫僅以簡單的 key-value 對應儲存，難以妥善表達 JSON/XML 中的巢狀結構。","C":"正確，文件型 NoSQL 資料庫（如 MongoDB）可有效儲存結構不固定的 JSON/XML，適合半結構化資料管理。","D":"圖形資料庫著重於節點與關係（邊）的儲存與查詢，並非為半結構化文件資料而設計。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q04","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":4,"context":null,"stem":"下列何者為分散式資料儲存架構中的一項核心特徵？","options":{"A":"集中式備份","B":"單點故障容忍度高","C":"跨節點資料切分與冗餘備援","D":"僅支援結構化資料格式"},"answer":"C","figures":[],"explanation":{"approach":"分散式系統可將資料分片儲存並建立冗餘副本，提高可用性與容錯能力。","options":{"A":"集中式備份仍依賴單一儲存點進行備份，與分散式架構強調去中心化的核心概念相反。","B":"此敘述僅描述結果面的效果，並非分散式架構的核心機制；真正的核心特徵在於透過資料切分與備援達成高可用性，如選項C所述。","C":"正確，分散式儲存架構的核心特徵是將資料分片（切分）儲存於多個節點，並建立冗餘副本，藉此提高可用性與容錯能力。","D":"分散式儲存架構可支援結構化、半結構化與非結構化等多樣資料型態，並非僅限結構化格式。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q05","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":5,"context":null,"stem":"若企業希望即時監控交易異常，應選擇下列哪一類數據處理架構？","options":{"A":"批次式資料倉儲","B":"離線式資料湖","C":"串流處理系統","D":"冷資料備援架構"},"answer":"C","figures":[],"explanation":{"approach":"串流處理（如 Apache Kafka、Spark Streaming）可即時處理與分析進入系統的資料，適用於異常偵測與即時應用。","options":{"A":"批次式資料倉儲的資料處理具有延遲，無法滿足交易異常的即時監控需求。","B":"離線式資料湖的資料多為延後處理與探索使用，不具即時分析能力。","C":"正確，串流處理系統（如 Apache Kafka、Spark Streaming）可即時處理進入系統的資料，適合即時監控與異常偵測。","D":"冷資料備援架構用於長期封存、低頻存取的資料，存取速度慢，不適合即時監控應用。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q06","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":6,"context":null,"stem":"在進行特徵工程時，特徵衍生（Feature Derivation）的主要目的是什麼？","options":{"A":"增加模型的自由度以擬合更多資料","B":"精簡資料以減少儲存成本","C":"建立對預測任務更具意義或可解釋性的變數","D":"移除不連續的類別型欄位"},"answer":"C","figures":[],"explanation":{"approach":"特徵衍生旨在透過現有資料邏輯建立新特徵，如時間差、組合變數，提升模型可預測性與可解釋性。（A）增加模型自由度可能導致過擬合，並非特徵衍生的核心目的。（B）資料壓縮與儲存效率屬資料處理領域，與特徵衍生無關。（D）移除不連續的類別型欄位屬於特徵選擇或清理行為，並非特徵衍生，其目的為簡化模型或排除不具預測力的欄位。","options":{"A":"增加模型自由度以擬合更多資料可能導致過擬合，並非特徵衍生的核心目的。","B":"精簡資料以減少儲存成本屬於資料處理或壓縮的範疇，與特徵衍生的目的無關。","C":"正確，特徵衍生旨在透過現有資料邏輯建立新特徵（如時間差、組合變數），提升模型的可預測性與可解釋性。","D":"移除不連續的類別型欄位屬於特徵選擇或資料清理的行為，目的在簡化模型或排除不具預測力的欄位，並非特徵衍生。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q07","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":7,"context":null,"stem":"在大數據清理流程中，對文字資料進行大小寫統一、移除特殊符號與空白等動作，最適合歸類為哪一種前處理操作？","options":{"A":"資料轉換","B":"資料驗證","C":"資料正規化（Normalization）","D":"資料標註"},"answer":"A","figures":[],"explanation":{"approach":"此類操作目的在於將文字欄位轉換為一致格式，利於分析，屬於典型的轉換處理，不涉及數值縮放或資料結構規劃。","options":{"A":"正確，大小寫統一、移除特殊符號與空白是將文字欄位轉換為一致格式，屬於典型的資料轉換處理。","B":"資料驗證是檢查資料格式與邏輯是否正確的動作，而非對文字執行轉換處理，性質不同。","C":"資料正規化通常指將數值縮放至特定範圍（如 0 到 1），而非針對文字格式的統一化處理。","D":"資料標註是為資料附加標籤（如分類標籤）供模型學習使用，與統一文字格式無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q08","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":8,"context":null,"stem":"在處理由 IoT 裝置產生的大規模即時資料時，系統架構應優先考量下列哪一項需求？","options":{"A":"高解析圖像處理能力","B":"即時串流處理與低延遲反應能力","C":"複雜圖形關係查詢能力","D":"靜態資料的批次整合能力"},"answer":"B","figures":[],"explanation":{"approach":"IoT 裝置資料具有高頻、連續與即時性等特徵，需使用能支援實時資料接收、處理與響應的架構（Kafka、Spark Streaming）來確保即時決策與效能穩定性。","options":{"A":"高解析圖像處理能力與 IoT 裝置產生的高頻連續資料特性無直接關聯，非優先考量。","B":"正確，IoT 裝置資料具有高頻、連續、即時等特性，系統需優先具備即時串流處理與低延遲反應能力，以支援即時決策。","C":"複雜圖形關係查詢能力屬於圖形資料庫的應用情境，非 IoT 即時資料架構的首要考量。","D":"靜態資料的批次整合能力與 IoT 資料連續、即時產生的特性相反，不符合此情境需求。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q09","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":9,"context":null,"stem":"在大數據架構中，資料湖（Data Lake）與傳統資料倉儲最大的差異為何？","options":{"A":"資料湖僅支援結構化資料","B":"資料湖支援多樣資料型態且不需預先定義結構","C":"資料倉儲無法查詢資料","D":"資料湖適用於即時交易分析"},"answer":"B","figures":[],"explanation":{"approach":"資料湖可儲存原始格式的結構化、半結構化與非結構化資料，支援彈性探索與延後建模。","options":{"A":"資料湖恰好相反，可支援結構化、半結構化與非結構化等多樣資料型態，不僅限結構化資料。","B":"正確，資料湖可儲存原始格式的多樣資料型態，且不需預先定義結構，支援彈性探索與延後建模。","C":"資料倉儲本身即為支援查詢與分析而設計，此敘述明顯與事實不符。","D":"資料湖多用於原始資料的彈性儲存與探索分析，並非特別針對即時交易處理設計。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c2_q10","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":10,"context":null,"stem":"資料驗證（Data Validation）的主要目的為何？","options":{"A":"將資料轉為結構化表格","B":"過濾掉資料中所有離群值","C":"檢查資料格式與邏輯是否正確","D":"壓縮資料以節省儲存空間"},"answer":"C","figures":[],"explanation":{"approach":"資料驗證確保資料符合預期格式與邏輯規則，是資料品質管理的重要步驟。","options":{"A":"將資料轉為結構化表格屬於資料轉換或 ETL 的工作內容，並非資料驗證的目的。","B":"資料驗證並非要過濾掉所有離群值，離群值的判斷與處理屬於資料清理範疇，且需視情境保留或處理，而非一律過濾。","C":"正確，資料驗證的主要目的是檢查資料是否符合預期的格式與邏輯規則，是資料品質管理的重要步驟。","D":"壓縮資料以節省儲存空間是資料壓縮技術的目的，與檢驗資料正確性的資料驗證無關。"},"source":"official","note":"官方 official_explanation 在說明資料驗證定義後，混入與本題無關的大數據分析方法章節介紹文字，屬內容拼接錯誤，逐選項說明僅依前段的正確定義撰寫。"},"origin":"guide"},{"id":"guide_middle_s2_c3_q01","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":1,"context":null,"stem":"在大數據的描述性分析中，最常用來呈現類別變數分佈的圖形是？","options":{"A":"折線圖","B":"箱型圖","C":"長條圖","D":"散佈圖"},"answer":"C","figures":[],"explanation":{"approach":"長條圖（BarChart）可清楚顯示類別型變數的數量分佈，是描述性分析中的基礎視覺工具。","options":{"A":"折線圖適合呈現隨時間變動的連續趨勢，並非用於呈現類別變數的分佈。","B":"箱型圖用於呈現數值資料的分布狀況與離群值，並非用於呈現類別變數的計數分佈。","C":"正確，長條圖可清楚顯示各類別的數量或頻率分佈，是描述性分析中呈現類別變數的基礎視覺工具。","D":"散佈圖用於呈現兩個連續變數之間的關係，並非用於呈現單一類別變數的分佈。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q02","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":2,"context":null,"stem":"若要分析網站每日訪客數量的趨勢變化，最適合使用下列哪一種視覺化工具？","options":{"A":"熱力圖","B":"折線圖","C":"圓餅圖","D":"直方圖"},"answer":"B","figures":[],"explanation":{"approach":"折線圖適合表現隨時間變動的連續數據，如日、週、月的趨勢觀察。","options":{"A":"熱力圖適合呈現二維資料的密度或強度分布，並非用於呈現隨時間變化的趨勢。","B":"正確，折線圖適合表現隨時間變動的連續數據，能清楚呈現日、週、月的趨勢變化。","C":"圓餅圖用於呈現各類別在整體中的佔比，並非用於呈現隨時間變化的趨勢。","D":"直方圖用於呈現數值資料的分布情形（如次數分配），並非用於呈現時間序列的趨勢變化。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q03","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":3,"context":null,"stem":"在大數據中進行關聯分析時，最常用來量化兩變數線性關係的指標為何？","options":{"A":"變異數","B":"t 值","C":"相關係數","D":"z 分數"},"answer":"C","figures":[],"explanation":{"approach":"相關係數（如 Pearsonr）用於衡量兩變數間的線性關聯程度，常見於探索性分析。","options":{"A":"變異數衡量的是單一變數本身的離散程度，並非兩變數間的線性關係。","B":"t 值是假設檢定中使用的檢定統計量，並非用於量化兩變數線性關係的指標。","C":"正確，相關係數（如 Pearson 相關係數）用於衡量兩變數間線性關聯的強弱與方向，常見於探索性分析。","D":"z 分數是將數值標準化後的分數，用於衡量單一數值相對平均數的位置，並非兩變數關係的量化指標。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q04","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":4,"context":null,"stem":"為了分析社群網路使用者之間的互動結構，應使用下列哪種分析方法？","options":{"A":"文字探勘","B":"主成分分析","C":"圖論分析","D":"分群分析"},"answer":"C","figures":[],"explanation":{"approach":"圖論分析可用於建構節點與邊的關係網路，適用於社群關係、推薦系統等情境。","options":{"A":"文字探勘聚焦於文字內容本身的分析，並非用於描述使用者之間的互動結構。","B":"主成分分析用於將高維資料降維，並非用來分析節點間的關係網路。","C":"正確，圖論分析可建構節點與邊的關係網路，適合分析社群使用者間的互動結構，也常用於推薦系統。","D":"分群分析用於將相似樣本歸類分組，並非用來描述節點之間的連結關係。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q05","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":5,"context":null,"stem":"在文字分析中，使用 TF-IDF 技術的主要目的是？","options":{"A":"去除標點符號","B":"將詞彙轉換為向量","C":"辨識常出現的關鍵詞並排除常見詞","D":"標示詞性與語法角色"},"answer":"C","figures":[],"explanation":{"approach":"TF-IDF（詞頻-逆文檔頻率）可強化具有辨識性的詞彙，抑制文檔中普遍存在但不具代表性的詞語。","options":{"A":"去除標點符號屬於文字前處理的清理步驟，並非 TF-IDF 技術本身的目的。","B":"將詞彙轉換為向量是詞向量化（如 one-hot、word embedding）的功能，TF-IDF 的核心目的在於凸顯關鍵詞的重要性，而非單純的向量化轉換。","C":"正確，TF-IDF（詞頻-逆文檔頻率）可強化具有辨識性的詞彙，並抑制文檔中普遍存在但不具代表性的常見詞。","D":"標示詞性與語法角色是詞性標註（POS tagging）的功能，與 TF-IDF 的目的無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q06","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":6,"context":null,"stem":"下列哪一項屬於異常偵測技術常見的應用情境？","options":{"A":"定期報表自動生成","B":"用戶行為分群","C":"信用卡詐騙識別","D":"影片推薦排序"},"answer":"C","figures":[],"explanation":{"approach":"異常偵測可用於發現違常模式，像是信用卡交易中異常消費、系統入侵等風險情境。","options":{"A":"定期報表自動生成屬於報表自動化流程的應用，並非異常偵測的典型情境。","B":"用戶行為分群屬於分群分析的應用，目的在歸類相似使用者，並非偵測異常。","C":"正確，異常偵測常用於發現違常模式，例如信用卡交易中的異常消費、系統入侵等風險情境。","D":"影片推薦排序屬於推薦系統的應用，並非異常偵測的典型情境。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q07","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":7,"context":null,"stem":"若要從大量原始變數中萃取低維的代表性特徵，最常使用哪一種降維技術？","options":{"A":"K-means","B":"PCA（主成分分析）","C":"t 檢定","D":"SMOTE"},"answer":"B","figures":[],"explanation":{"approach":"PCA 是常見的線性降維方法，將原始特徵投影到新的主成分空間中，以保留資料最大變異。","options":{"A":"K-means 是分群演算法，用於將樣本分組，並非用於降維。","B":"正確，PCA（主成分分析）是常見的線性降維方法，將原始特徵投影到新的主成分空間，以保留資料的最大變異。","C":"t 檢定是假設檢定的統計方法，用於比較平均數差異，並非降維技術。","D":"SMOTE 是處理類別不平衡問題的過採樣技術，並非降維方法。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q08","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":8,"context":null,"stem":"在大數據分析中，哪一種資料探勘技術可用於找出客戶購買行為中常見的組合規則？","options":{"A":"關聯規則分析","B":"分類分析","C":"時間序列分析","D":"迴歸分析"},"answer":"A","figures":[],"explanation":{"approach":"關聯規則分析（如 Apriori 演算法）可找出項目間常見組合，例如「買牛奶常搭配買麵包」。","options":{"A":"正確，關聯規則分析（如 Apriori 演算法）可找出項目間常見的組合關係，例如「買牛奶常搭配買麵包」。","B":"分類分析用於預測樣本所屬的類別，並非用來找出項目之間的組合規則。","C":"時間序列分析用於分析隨時間變化的資料模式，並非用於挖掘商品間的組合關聯。","D":"迴歸分析用於預測連續數值型結果，並非用於找出項目間的組合規則。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q09","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":9,"context":null,"stem":"箱型圖（Box Plot）如何呈現異常值？","options":{"A":"以箱體內部大小表示","B":"以特殊符號（如點或星號）單獨標記","C":"自動刪除異常值","D":"以中位數代表異常值"},"answer":"B","figures":[],"explanation":{"approach":"箱型圖透過特殊符號（如點、星號）單獨標記異常值，使使用者易於辨識數據中的異常資料點。","options":{"A":"箱體內部大小代表的是四分位距（IQR）的範圍，並非用來呈現異常值。","B":"正確，箱型圖會以特殊符號（如點或星號）將超出上下界的異常值單獨標記出來，方便辨識。","C":"箱型圖是視覺化呈現工具，僅標示異常值供使用者參考，並不會自動刪除資料中的異常值。","D":"中位數是箱型圖中呈現資料集中趨勢的線（箱體中線），與標記異常值的方式無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c3_q10","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":10,"context":null,"stem":"若企業需自動比對商品評論中出現的品牌名稱，建議使用哪一種處理流程？","options":{"A":"結構化資料匹配","B":"命名實體識別（NER）","C":"群集分析","D":"影像分類"},"answer":"B","figures":[],"explanation":{"approach":"NER 屬於自然語言處理技術，可自動從文字中辨識出品牌、人名、地點等實體資訊。","options":{"A":"商品評論屬於非結構化文字資料，難以直接以結構化資料匹配的方式進行比對。","B":"正確，命名實體識別（NER）屬於自然語言處理技術，可自動從文字中辨識出品牌、人名、地點等實體資訊。","C":"群集分析用於將相似樣本分組，並非用於識別文字中特定的實體名稱。","D":"影像分類適用於圖像資料的辨識，與文字評論中品牌名稱的辨識無關。"},"source":"official","note":"官方 official_explanation 在說明 NER 的正確理由後，混入與本題無關的大數據於人工智慧應用章節介紹文字，屬內容拼接錯誤，逐選項說明僅依前段的正確理由撰寫。"},"origin":"guide"},{"id":"guide_middle_s2_c4_q01","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":1,"context":null,"stem":"鑑別式 AI 模型的主要特性為何？","options":{"A":"可產生新內容樣本","B":"僅適用於無監督學習任務","C":"專注於資料分類與預測決策邊界","D":"無法使用結構化資料進行訓練"},"answer":"C","figures":[],"explanation":{"approach":"鑑別式 AI 模型（如邏輯迴歸、SVM）學習資料間的判別界線，廣泛應用於預測任務。","options":{"A":"可產生新內容樣本是生成式 AI 的特性，並非鑑別式 AI 模型的主要特性。","B":"鑑別式 AI 廣泛應用於監督式學習的分類與預測任務，並不僅限於無監督學習任務，此敘述錯誤。","C":"正確，鑑別式 AI 模型（如邏輯迴歸、SVM）著重學習資料間的判別界線，專注於分類與預測決策邊界。","D":"鑑別式 AI 模型（如邏輯迴歸、SVM）經常使用結構化資料進行訓練，此敘述與事實相反。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q02","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":2,"context":null,"stem":"為了加速大數據環境下的 AI 模型訓練，以下哪一項為常見技術？","options":{"A":"早期停止（Early Stopping）","B":"批次分群（Mini-batching）","C":"混合精度訓練（Mixed Precision Training）","D":"主成分分析（PCA）"},"answer":"C","figures":[],"explanation":{"approach":"混合使用 16-bit 與 32-bit 浮點運算可減少訓練時間與記憶體使用量，提升效能。","options":{"A":"早期停止（Early Stopping）主要用於防止模型過擬合，並非用於加速訓練效率的技術。","B":"批次分群（Mini-batching）是訓練過程中的基本作法，有助於穩定訓練與記憶體管理，但並非本題所指的加速訓練關鍵技術。","C":"正確，混合精度訓練（Mixed Precision Training）混合使用 16-bit 與 32-bit 浮點運算，可減少訓練時間與記憶體使用量，提升訓練效能。","D":"主成分分析（PCA）是資料降維的前處理技術，並非用於加速模型訓練的技術。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q03","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":3,"context":null,"stem":"在生成式 AI 中，若輸入為結構化資料並希望產出自然語言敘述，最適合使用下列哪類模型？","options":{"A":"決策樹","B":"強化學習模型","C":"語言生成模型","D":"圖論模型"},"answer":"C","figures":[],"explanation":{"approach":"生成式 AI 可根據結構化或非結構化輸入生成文字、圖像等內容，GPT是典型文字生成架構。","options":{"A":"決策樹屬於鑑別式模型，用於分類或迴歸預測，並非用來生成自然語言敘述。","B":"強化學習模型著重於透過獎勵機制學習決策策略，並非專門用於根據結構化資料生成自然語言敘述。","C":"正確，生成式 AI 中的語言生成模型（如 GPT）可根據結構化或非結構化輸入生成文字內容，屬於典型的文字生成架構。","D":"圖論模型用於分析節點與關係網路結構，並非用來生成文字內容。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q04","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":4,"context":null,"stem":"大數據對生成式 AI 內容品質的影響關鍵在於？","options":{"A":"GPU 數量多寡","B":"訓練樣本是否具多樣性與語境一致性","C":"API 回應速度","D":"是否使用 Python 編寫模型"},"answer":"B","figures":[],"explanation":{"approach":"生成式模型的品質極度依賴訓練資料的多樣性與語境品質，關係到語言流暢性與真實性。","options":{"A":"GPU 數量多寡主要影響訓練速度與運算效能，並非決定生成內容品質的關鍵因素。","B":"正確，生成式模型的內容品質高度依賴訓練樣本是否具多樣性與語境一致性，直接關係到語言流暢性與真實性。","C":"API 回應速度屬於系統效能指標，與生成內容本身的品質無關。","D":"使用何種程式語言（如 Python）編寫模型，與生成內容的品質沒有直接關係。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q05","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":5,"context":null,"stem":"在 AI 模型訓練過程中，為避免使用含有個資的敏感欄位，常用哪一種資料處理方法？","options":{"A":"資料標註","B":"資料蒐集","C":"資料匿名化","D":"資料分群"},"answer":"C","figures":[],"explanation":{"approach":"資料匿名化處理如移除姓名、轉換欄位等，可降低個資風險並符合法規要求。","options":{"A":"資料標註是為資料加上標籤以利模型學習的步驟，並非用來避免使用含個資的敏感欄位。","B":"資料蒐集是取得資料的階段，並未針對敏感個資欄位進行處理，無法避免個資風險。","C":"正確，資料匿名化處理（如移除姓名、轉換欄位）可降低個資外洩風險，並符合法規要求，是常用的處理方法。","D":"資料分群是將相似樣本歸類的技術，與避免使用含個資的敏感欄位無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q06","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":6,"context":null,"stem":"下列哪一項技術可強化 AI 模型對使用者資料的隱私保護？","options":{"A":"特徵擴增（Feature Augmentation）","B":"差分隱私（Differential Privacy）","C":"貝氏分類器","D":"強化學習"},"answer":"B","figures":[],"explanation":{"approach":"差分隱私透過加噪機制保護個別資料不被逆推出，即使在公開模型中也難以重建原始資料。","options":{"A":"特徵擴增（Feature Augmentation）用於增加特徵數量以提升模型表現，並非隱私保護技術。","B":"正確，差分隱私（Differential Privacy）透過加噪機制保護個別資料不被逆推出，即使在公開模型中也難以重建原始資料，能強化隱私保護。","C":"貝氏分類器是一種分類演算法，用於預測任務，與隱私保護無關。","D":"強化學習是一種透過獎勵機制學習決策策略的學習範式，與隱私保護無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q07","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":7,"context":null,"stem":"若企業欲將醫療資料用於訓練 AI 模型，下列哪一項最符合合法合規原則？","options":{"A":"將所有資料匿名處理後存於海外伺服器","B":"取得合法授權與病患同意，並執行隱私強化","C":"僅標註患者年齡即可訓練","D":"合併不同院所資料以擴大樣本量，不需其他處理"},"answer":"B","figures":[],"explanation":{"approach":"處理含敏感資訊之醫療資料時，必須符合隱私法規與倫理原則，包括告知、同意與匿名化處理。","options":{"A":"僅將資料匿名處理後存於海外伺服器，仍可能涉及跨境傳輸合規與病患同意等問題，並非完整合規的做法。","B":"正確，處理含敏感資訊的醫療資料時，必須取得合法授權與病患同意，並執行隱私強化措施，才符合隱私法規與倫理原則。","C":"僅標註患者年齡並不足以保障病患隱私與符合合規要求，仍須取得同意並採取其他隱私強化措施。","D":"合併不同院所資料以擴大樣本量會涉及更高的隱私風險，絕非「不需其他處理」即可進行，此敘述明顯不符合規原則。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q08","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":8,"context":null,"stem":"為確保 AI 系統合規性與可追溯性，應建立哪一種制度？","options":{"A":"模型評分制度","B":"模型自動訓練流程","C":"資料版本管理與操作紀錄制度","D":"開源資料集快速上線制度"},"answer":"C","figures":[],"explanation":{"approach":"版本管理可確保資料來源、處理歷程清楚記錄，對稽核與合規性追蹤至關重要。","options":{"A":"模型評分制度用於評估模型表現優劣，並非用來確保資料來源與處理歷程的可追溯性。","B":"模型自動訓練流程聚焦於訓練效率與自動化，與合規性及可追溯性的建立無關。","C":"正確，資料版本管理與操作紀錄制度可確保資料來源、處理歷程清楚記錄，對稽核與合規性追蹤至關重要。","D":"開源資料集快速上線制度著重加速資料取得與導入，並未涉及合規性與可追溯性的機制建立。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q09","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":9,"context":null,"stem":"在企業內部推動 AI 模型落地時，哪一種治理措施最能確保模型部署後持續符合法規與道德標準？","options":{"A":"部署後由 IT 團隊定期觀察效能","B":"設定固定訓練資料更新週期","C":"導入 AI 治理框架與跨部門監管流程","D":"採購更多模型訓練設備以強化能力"},"answer":"C","figures":[],"explanation":{"approach":"AI 治理需結合技術、法務、業務等部門共同制定監督機制，確保風險控制與合規落實。","options":{"A":"部署後由 IT 團隊定期觀察效能僅關注技術層面的表現，未涵蓋法規與道德標準的跨部門監督機制。","B":"設定固定訓練資料更新週期僅為資料維運的作法，無法確保模型部署後在治理層面持續符合法規與道德標準。","C":"正確，導入 AI 治理框架與跨部門監管流程，能結合技術、法務、業務等部門共同制定監督機制，確保風險控制與合規落實。","D":"採購更多模型訓練設備僅提升硬體運算能力，與確保法規及道德標準的持續遵循無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s2_c4_q10","level":"middle","session":"學習指引","subject":2,"subject_name":"大數據處理分析與應用","number":10,"context":null,"stem":"若欲在大數據環境中有效訓練深度學習模型，以下哪一項策略最常用於解決資料與運算資源不對稱的問題？","options":{"A":"將所有資料轉存為影像格式以提升讀取效率","B":"將模型拆解為多個子模型並分別部署於本機","C":"採用分散式訓練與硬體加速架構","D":"改以監督式學習取代非監督式學習以降低負載"},"answer":"C","figures":[],"explanation":{"approach":"在面對龐大資料量與高計算需求時，常採用 GPU/TPU 加速與分散式訓練架構（如 Horovod、SageMaker、PyTorch Distributed）以縮短訓練時間並提升效能，為目前主流解法。","options":{"A":"將所有資料轉存為影像格式並非提升運算資源對稱性的通用有效方法，對非影像類資料未必適用，也無法解決資源不對稱的根本問題。","B":"將模型拆解為多個子模型卻僅部署於本機，缺乏分散式協同運算的核心機制，無法有效解決大規模資料與運算資源不足的問題。","C":"正確，面對龐大資料量與高計算需求時，常採用 GPU/TPU 硬體加速與分散式訓練架構（如 Horovod、SageMaker、PyTorch Distributed）以縮短訓練時間並提升效能，是目前主流解法。","D":"學習方式（監督式或非監督式）的選擇取決於任務需求與資料標註情況，並非用於解決運算資源不對稱問題的策略。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q01","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":1,"context":null,"stem":"若欲描述隨機變數在連續範圍內取值的機率分佈，最適合使用下列哪一種函數？","options":{"A":"機率質量函數（PMF）","B":"條件機率","C":"機率密度函數（PDF）","D":"累積分佈函數（CDF）"},"answer":"C","figures":[],"explanation":{"approach":"機率密度函數（PDF）用於描述連續型隨機變數於某個取值範圍內的機率分佈。與離散型隨機變數不同，連續變數在單一點的機率為零，PDF 通常透過積分計算區間內的機率，而 PMF 則用於離散型變數。累積分佈函數（CDF）則是累計機率的工具，而非直接描述機率密度。","options":{"A":"PMF（機率質量函數）用於描述離散型隨機變數的機率分佈，並非用於連續範圍取值的變數。","B":"條件機率是描述在已知某事件發生下另一事件發生的機率，性質上並非用來描述隨機變數在連續範圍內的分佈函數。","C":"正確。PDF 專門用於描述連續型隨機變數的機率分佈，透過對區間積分求得該範圍內的機率。","D":"CDF 描述的是累積機率（小於等於某值的機率），是累計工具而非直接描述機率密度，與題目所問性質不同。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q02","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":2,"context":null,"stem":"若一個隨機變數服從伯努利分佈（Bernoulli Distribution），則該變數可能取值為下列哪一組？","options":{"A":"任何實數","B":"0 或 1","C":"正整數","D":"任意整數"},"answer":"B","figures":[],"explanation":{"approach":"伯努利分佈是典型的二元分佈，僅有兩種可能結果，通常以 0 和 1 表示，例如成功與失敗、點擊與未點擊。此分佈是多數二元分類模型（如邏輯迴歸）的理論基礎。","options":{"A":"任何實數涵蓋範圍過大，不符合伯努利分佈僅有兩種結果的特性。","B":"正確。伯努利分佈是二元分佈，僅有 0 與 1 兩種可能結果，代表成功/失敗、點擊/未點擊等二分類事件。","C":"正整數為多值且無上限的範圍，不符合伯努利分佈僅二元取值的定義。","D":"任意整數範圍過大且包含負數，不符合伯努利分佈僅 0 或 1 的特性。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q03","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":3,"context":null,"stem":"在主成分分析（PCA）中，常使用哪一種矩陣分解技術來找出資料的主軸方向？","options":{"A":"矩陣求逆","B":"矩陣轉置","C":"特徵值分解","D":"條件機率分解"},"answer":"C","figures":[],"explanation":{"approach":"PCA 透過對協方差矩陣進行特徵值分解，找出最大變異方向，並以此降低維度並保留最重要的資訊。這能讓資料投影到較少的維度上，同時盡可能維持原始資料的變異。","options":{"A":"矩陣求逆用於求解線性方程組等問題，並非 PCA 找出主軸方向所使用的核心技術。","B":"矩陣轉置僅是調換矩陣的列與欄，不具備找出資料變異方向的能力。","C":"正確。PCA 透過對協方差矩陣進行特徵值分解，找出資料變異最大的方向（主成分）。","D":"條件機率分解並非矩陣分解技術，與 PCA 找主軸方向的方法無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q04","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":4,"context":null,"stem":"若想將高維資料映射至較低維度空間，同時保留資料的主要變異，常用下列哪一種方法？","options":{"A":"邊際機率估計","B":"矩陣轉置","C":"主成分分析","D":"累積機率計算"},"answer":"C","figures":[],"explanation":{"approach":"PCA 是常用的維度簡化工具，透過線性變換找出資料中變異最大的方向，將原始高維度資料投影到較少維度上，達到資料壓縮與特徵提取的效果。","options":{"A":"邊際機率估計是機率論中的概念，並非用於降維、保留主要變異的技術。","B":"矩陣轉置僅調換矩陣的列與欄，不具備降維或保留資料變異的功能。","C":"正確。PCA 能將高維資料以線性變換投影至低維空間，同時盡量保留原始資料的主要變異。","D":"累積機率計算屬於統計機率範疇，並非降維方法。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q05","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":5,"context":null,"stem":"在梯度下降（Gradient Descent）中，「梯度」代表下列哪一項？","options":{"A":"資料點個數","B":"模型精確度","C":"損失函數對參數的偏微分","D":"模型計算速度"},"answer":"C","figures":[],"explanation":{"approach":"梯度是損失函數相對於模型參數的導數，能指引參數應往哪個方向調整以減少損失。梯度越大，表示調整幅度應越大，以快速降低誤差。","options":{"A":"資料點個數是樣本規模的描述，與梯度的定義無關。","B":"模型精確度是評估模型表現的指標，並非梯度所代表的意義。","C":"正確。梯度是損失函數對模型參數的偏微分，指出參數應調整的方向與幅度。","D":"模型計算速度屬於運算效能範疇，與梯度的定義無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q06","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":6,"context":null,"stem":"在進行假設檢定時，顯著水準（α）表示什麼？","options":{"A":"平均值的大小","B":"模型運算速度","C":"拒絕虛無假設時所容許的型一錯誤機率","D":"資料筆數多少"},"answer":"C","figures":[],"explanation":{"approach":"顯著水準（α）是研究者事先設定的風險上限，代表當虛無假設為真時，錯誤拒絕該假設的容忍機率。常見設定為 0.05，意即容許 5%的型一錯誤。","options":{"A":"平均值的大小是描述資料集中趨勢的統計量，與顯著水準的定義無關。","B":"模型運算速度屬於效能範疇，與假設檢定中顯著水準的統計意義無關。","C":"正確。顯著水準（α）是拒絕虛無假設時，容許犯下型一錯誤（誤判）的機率上限，常見設定為 0.05。","D":"資料筆數多少屬於樣本數概念，並非顯著水準所代表的意義。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q07","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":7,"context":null,"stem":"若資料集中存在極端值，以下哪一種集中趨勢指標較不受影響？","options":{"A":"平均數","B":"變異數","C":"標準差","D":"中位數"},"answer":"D","figures":[],"explanation":{"approach":"平均數會受極端值拉動而偏離中心位置。中位數則是將資料排序後取中間值，不會受到少數極端值的嚴重影響，因此在偏態分佈或極端值存在時，常用中位數描述資料集中趨勢。","options":{"A":"平均數會被極端值拉動而偏離資料真實的集中位置，容易受極端值影響。","B":"變異數是離散程度指標而非集中趨勢指標，其計算方式（平方）反而會放大極端值的影響。","C":"標準差同樣是離散程度指標而非集中趨勢指標，也會因極端值而放大。","D":"正確。中位數為排序後的中間值，不受少數極端值大小的影響，適合描述偏態分佈或含極端值資料的集中趨勢。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q08","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":8,"context":null,"stem":"以下哪一種優化方法會累積每個參數的歷史梯度大小，以調整學習率？","options":{"A":"Momentum","B":"Adagrad","C":"SGD","D":"Batch Normalization"},"answer":"B","figures":[],"explanation":{"approach":"Adagrad 根據各參數歷史梯度平方和，調整每個參數的學習率。對變動較少的參數保留較高學習率，而對變動大的參數降低學習率，特別適合處理稀疏特徵資料。","options":{"A":"Momentum 是利用過去梯度方向的動量加速收斂，並非依歷史梯度大小調整學習率。","B":"正確。Adagrad 會累積每個參數的歷史梯度平方和，並依此調整（縮小）各參數的學習率。","C":"SGD（隨機梯度下降）通常使用固定學習率更新參數，不會依歷史梯度調整學習率。","D":"Batch Normalization 是用來穩定各層輸入分佈的技術，與依歷史梯度調整學習率無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q09","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":9,"context":null,"stem":"當深度學習模型在訓練時出現梯度爆炸現象，應優先採用哪種技術加以處理？","options":{"A":"增大學習率","B":"梯度裁剪（Gradient Clipping）","C":"減少資料量","D":"刪除輸入特徵"},"answer":"B","figures":[],"explanation":{"approach":"梯度爆炸會導致權重變動過大甚至溢出，影響模型穩定性。梯度裁剪能限制梯度的最大值，防止數值爆炸，特別適用於深度神經網路或 RNN 訓練。","options":{"A":"增大學習率反而會加劇梯度爆炸時參數更新過大的問題，並非正確處理方式。","B":"正確。梯度裁剪能限制梯度的最大範圍，避免梯度數值過大造成不穩定或溢位。","C":"減少資料量無法解決梯度爆炸的根本原因（通常與網路架構、初始化或學習率有關）。","D":"刪除輸入特徵並不能針對性解決梯度爆炸問題，且可能損失重要資訊。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c1_q10","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":10,"context":null,"stem":"邏輯迴歸（Logistic Regression）模型在處理二元分類問題時，通常假設目標變數服從哪種分佈？","options":{"A":"常態分佈","B":"均勻分佈","C":"伯努利分佈","D":"泊松分佈"},"answer":"C","figures":[],"explanation":{"approach":"邏輯迴歸假設目標變數為二元型態（如 0 或 1），服從伯努利分佈，並透過 sigmoid 函數將預測值映射至機率區間[0, 1]，以完成二元分類。","options":{"A":"常態分佈用於連續型變數，不符合二元分類目標變數僅有兩種結果的假設。","B":"均勻分佈假設各結果發生機率相等，並非邏輯迴歸對二元目標變數所做的假設。","C":"正確。邏輯迴歸假設目標變數（0 或 1）服從伯努利分佈，並以 sigmoid 函數將預測值映射為屬於某類別的機率。","D":"泊松分佈用於描述單位時間或空間內事件發生的次數，並非二元分類目標變數的分佈假設。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q01","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":1,"context":null,"stem":"機器學習（Machine Learning）中，若輸入資料沒有標註，欲探索潛在的群組或模式，應屬於哪種學習類型？","options":{"A":"監督式學習（Supervised Learning）","B":"半監督式學習（Semi-supervised Learning）","C":"非監督式學習（Unsupervised Learning）","D":"強化式學習（Reinforcement Learning）"},"answer":"C","figures":[],"explanation":{"approach":"非監督式學習（Unsupervised Learning）不依賴標註資料，主要目的是從資料中發現潛在結構、模式或分佈，例如分群（Clustering）、降維（Dimensionality Reduction）等技術，是探索性資料分析的重要工具。","options":{"A":"監督式學習需要標註資料以學習輸入與輸出的對應關係，與題目「沒有標註」的情境不符。","B":"半監督式學習同時使用少量標註與大量未標註資料，並非完全沒有標註資料的情境。","C":"正確。非監督式學習不依賴標註資料，目的即在於從資料中探索潛在群組或模式，如分群、降維。","D":"強化式學習透過與環境互動、以獎勵回饋學習策略，並非用於探索未標註資料中的群組或模式。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q02","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":2,"context":null,"stem":"在監督式學習中，當模型要預測一個連續數值時，這種任務稱為什麼？","options":{"A":"分類（Classification）","B":"迴歸（Regression）","C":"聚類（Clustering）","D":"降維（Dimensionality Reduction）"},"answer":"B","figures":[],"explanation":{"approach":"迴歸（Regression）是預測連續數值的任務，如房價預測、氣溫預測等，與分類不同，分類是用來預測離散類別結果。","options":{"A":"分類是預測離散類別結果（如是/否），並非預測連續數值。","B":"正確。迴歸是預測連續數值的任務，如房價預測、氣溫預測等。","C":"聚類是依相似性將資料分群，屬於非監督式學習，並非預測連續數值。","D":"降維是將高維資料轉換為低維表示，並非預測連續數值的任務。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q03","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":3,"context":null,"stem":"在深度學習中，用於學習資料中局部特徵的網路架構通常是什麼？","options":{"A":"循環神經網路（Recurrent Neural Network, RNN）","B":"決策樹（Decision Tree）","C":"卷積神經網路（Convolutional Neural Network, CNN）","D":"隨機森林（Random Forest）"},"answer":"C","figures":[],"explanation":{"approach":"卷積神經網路（CNN）透過卷積層偵測局部特徵，尤其擅長處理影像、語音等有空間或時間結構的資料，是深度學習中重要的基礎架構之一。","options":{"A":"RNN 擅長處理具序列（時間）相依性的資料，而非局部空間特徵的擷取。","B":"決策樹是以規則分裂資料進行預測的傳統機器學習模型，並非深度學習中用於擷取局部特徵的網路架構。","C":"正確。CNN 透過卷積層偵測影像等資料的局部特徵，是深度學習中處理空間結構資料的核心架構。","D":"隨機森林是由多棵決策樹組成的集成學習方法，並非深度學習網路架構。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q04","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":4,"context":null,"stem":"支援向量機（Support Vector Machine, SVM）若用於迴歸問題，稱為什麼？","options":{"A":"Logistic Regression","B":"Decision Tree Regression","C":"Random Forest","D":"Support Vector Regression"},"answer":"D","figures":[],"explanation":{"approach":"當支援向量機（SVM）應用於連續數值的預測問題時，稱為支援向量迴歸（Support Vector Regression, SVR）。SVR 與傳統 SVM 不同，目標是尋找一條最佳超平面，使大多數資料點落在預設的誤差範圍內。","options":{"A":"Logistic Regression 用於分類問題（輸出機率並分類），並非 SVM 應用於迴歸問題時的名稱。","B":"Decision Tree Regression 是決策樹用於迴歸任務時的稱呼，並非 SVM 的迴歸版本。","C":"Random Forest 是決策樹的集成方法，並非 SVM 應用於迴歸問題的名稱。","D":"正確。SVM 用於迴歸問題時稱為 Support Vector Regression（SVR），目標是讓多數資料點落在容忍誤差範圍內的超平面。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q05","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":5,"context":null,"stem":"機器學習模型若過度學習訓練資料中的雜訊，導致泛化能力下降，此現象稱為什麼？","options":{"A":"欠擬合（Underfitting）","B":"過擬合（Overfitting）","C":"特徵縮放（Feature Scaling）","D":"梯度爆炸（Gradient Explosion）"},"answer":"B","figures":[],"explanation":{"approach":"過擬合（Overfitting）是指模型在訓練資料上表現極好，卻無法在未知新資料上維持預測效能，通常是因為模型過於複雜，學習到不具代表性的噪聲。","options":{"A":"欠擬合是模型過於簡單、連訓練資料都無法學好，與題目描述「過度學習雜訊」的情形相反。","B":"正確。過擬合是模型過度學習訓練資料中的雜訊與細節，導致在新資料上的泛化能力下降。","C":"特徵縮放是將特徵數值範圍標準化的前處理技術，與過度學習雜訊無關。","D":"梯度爆炸是訓練過程中梯度數值過大導致訓練不穩定的現象，並非泛化能力下降的原因描述。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q06","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":6,"context":null,"stem":"在深度學習中，哪一個是為了引入非線性，使神經網路能學習複雜模式的元件？","options":{"A":"損失函數（Loss Function）","B":"激活函數（Activation Function）","C":"隱藏層（Hidden Layer）","D":"梯度下降（Gradient Descent）"},"answer":"B","figures":[],"explanation":{"approach":"激活函數（Activation Function）如 ReLU、Sigmoid 等，為神經網路帶來非線性能力，若沒有激活函數，多層網路仍只是線性變換，無法表現複雜的關係。","options":{"A":"損失函數是用來衡量預測誤差的指標，並非引入非線性的元件。","B":"正確。激活函數（如 ReLU、Sigmoid）為神經網路引入非線性，使模型能學習複雜的非線性關係。","C":"隱藏層是神經網路中間的運算層，但若無激活函數，多層堆疊仍只是線性變換，隱藏層本身不負責引入非線性。","D":"梯度下降是用於更新模型參數的優化演算法，並非引入非線性的元件。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q07","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":7,"context":null,"stem":"若想在機器學習中降低模型過度擬合風險，可採用哪種方法？","options":{"A":"提高學習率","B":"減少資料量","C":"正則化（Regularization）","D":"隨機刪除特徵"},"answer":"C","figures":[],"explanation":{"approach":"正則化（Regularization）透過在損失函數中加入 L1 或 L2 懲罰項，限制模型權重的大小，減少模型過度擬合訓練資料，提升泛化能力。","options":{"A":"提高學習率可能導致訓練不穩定甚至無法收斂，並非降低過擬合的方法。","B":"減少資料量通常會使樣本代表性下降、模型更容易過擬合，而非降低過擬合風險。","C":"正確。正則化透過在損失函數中加入 L1 或 L2 懲罰項，限制模型權重大小，降低模型複雜度以減少過擬合。","D":"隨機刪除特徵可能導致重要資訊流失，並非系統性降低過擬合的標準方法。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q08","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":8,"context":null,"stem":"在深度學習模型的訓練過程中，計算模型輸出與實際值差距的函數稱為什麼？","options":{"A":"激活函數（Activation Function）","B":"池化函數（Pooling Function）","C":"損失函數（Loss Function）","D":"梯度函數（Gradient Function）"},"answer":"C","figures":[],"explanation":{"approach":"損失函數（Loss Function）用來衡量模型預測值與實際值的差距，是指引優化器調整參數方向的重要依據。常見如均方誤差（MSE）、交叉熵損失（Cross-Entropy Loss）等。","options":{"A":"激活函數用於引入非線性，並非計算預測值與實際值差距的函數。","B":"池化函數用於降低特徵圖維度、保留重要特徵，與計算預測誤差無關。","C":"正確。損失函數用來計算模型輸出與實際值的差距，作為優化器調整參數方向的依據，如 MSE、交叉熵損失。","D":"梯度函數並非標準術語；梯度是損失函數對參數的偏微分結果，而非獨立衡量誤差的函數。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q09","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":9,"context":null,"stem":"Transformer 模型中用來捕捉輸入序列不同位置間依賴關係的核心機制是什麼？","options":{"A":"池化機制（Pooling）","B":"注意力機制（Attention）","C":"決策樹分支","D":"激活函數（Activation Function）"},"answer":"B","figures":[],"explanation":{"approach":"Transformer 模型核心在於注意力機制（Attention），透過計算序列中各元素間的關聯權重，捕捉長距離依賴，徹底取代傳統 RNN 的循環架構，大幅提升計算效率與表現。","options":{"A":"池化機制用於降低特徵維度，並非 Transformer 捕捉序列位置依賴關係的核心機制。","B":"正確。注意力機制透過計算序列中各元素間的關聯權重，捕捉不同位置間的依賴關係，是 Transformer 的核心。","C":"決策樹分支是傳統機器學習模型的判斷結構，與 Transformer 架構無關。","D":"激活函數用於引入非線性，並非捕捉序列位置依賴關係的機制。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c2_q10","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":10,"context":null,"stem":"在決策樹模型中，用於判斷分裂效果好壞的指標，常見的是下列哪一種？","options":{"A":"機率密度函數（Probability Density Function）","B":"均方根誤差（Root Mean Squared Error）","C":"基尼不純度（Gini Impurity）","D":"卷積核大小（Kernel Size）"},"answer":"C","figures":[],"explanation":{"approach":"基尼不純度（Gini Impurity）衡量節點內樣本的不純度，數值越低表示節點內樣本越集中於單一類別，是決策樹演算法常用的分裂判斷依據，尤其在分類任務中扮演重要角色。","options":{"A":"機率密度函數用於描述連續隨機變數的機率分佈，並非決策樹分裂效果的判斷指標。","B":"均方根誤差是迴歸任務中常用的誤差評估指標，並非決策樹分類分裂常用的不純度指標。","C":"正確。基尼不純度衡量節點內樣本的不純度，數值越低表示樣本越集中於單一類別，是決策樹常用的分裂判斷依據。","D":"卷積核大小是 CNN 架構的參數，與決策樹分裂效果的判斷指標無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q01","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":1,"context":null,"stem":"針對缺失值（Missing Value）的處理，下列哪種方法屬於利用模型進行補值的方式？","options":{"A":"刪除法（Deletion）","B":"均值填補（Mean Imputation）","C":"預測模型填補（Predictive Imputation）","D":"缺失指標編碼（Missing Indicator）"},"answer":"C","figures":[],"explanation":{"approach":"預測模型填補是利用其他特徵變數訓練模型，如迴歸或分類器，預測缺失值的位置或值，特別適用於特徵之間關聯性高的情況。相對於簡單的刪除或均值填補，模型補值能更好地捕捉數據內在關聯性，降低資訊流失。","options":{"A":"刪除法是直接捨棄含缺失值的樣本或欄位，並未利用模型進行補值。","B":"均值填補是以該欄位平均值填補缺失，屬於簡單統計方法，並非模型預測。","C":"正確。預測模型填補是利用其他特徵變數訓練迴歸或分類模型，來預測缺失值，屬於模型導向的補值方式。","D":"缺失指標編碼是新增欄位標記該值是否缺失，並未實際預測或填補缺失的數值。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q02","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":2,"context":null,"stem":"在進行異常值（Outlier）偵測時，哪種方法是利用統計特徵分佈來判斷離群點？","options":{"A":"KNN 補值","B":"四分位距法（IQR）","C":"Isolation Forest","D":"One-hot Encoding"},"answer":"B","figures":[],"explanation":{"approach":"四分位距法是常見的統計方法，透過計算資料的第一與第三四分位數（Q1 與 Q3），並判定距離超過 IQR（四分位距）1.5 倍以上的數據點為異常。這種方法直觀且適用於大多數數值型資料的初步檢查。","options":{"A":"KNN 補值是利用鄰近樣本的數值來填補缺失值，並非用於異常值偵測的統計分佈方法。","B":"正確。四分位距法（IQR）利用 Q1、Q3 計算範圍，將超出 1.5 倍 IQR 的資料點判定為異常值，屬於統計分佈判斷方法。","C":"Isolation Forest 是基於樹狀結構隔離樣本的機器學習演算法，並非單純利用統計特徵分佈判斷。","D":"One-hot Encoding 是類別變數的編碼方法，與異常值偵測無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q03","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":3,"context":null,"stem":"下列哪一種特徵選擇方法會直接在模型訓練過程中進行特徵挑選？","options":{"A":"Filter 方法","B":"Wrapper 方法","C":"Embedded 方法","D":"One-hot Encoding"},"answer":"C","figures":[],"explanation":{"approach":"Embedded 方法會在模型訓練過程中同步進行特徵挑選。例如決策樹模型會產生特徵重要性（Feature Importance），或像 Lasso、Ridge 透過正則化直接控制特徵權重，實現同時建模與特徵選擇的目標。","options":{"A":"Filter 方法是在模型訓練前，依統計指標（如相關係數）獨立篩選特徵，並非在訓練過程中挑選。","B":"Wrapper 方法透過反覆訓練不同特徵組合的模型來評估效果，特徵選擇屬於外部搜尋流程，而非模型訓練本身內建的機制。","C":"正確。Embedded 方法在模型訓練過程中同步進行特徵挑選，如決策樹的特徵重要性或 Lasso、Ridge 的正則化。","D":"One-hot Encoding 是類別變數的編碼方式，並非特徵選擇方法。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q04","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":4,"context":null,"stem":"在進行特徵轉換時，若資料存在極端偏高的右偏分佈，常用哪種轉換以降低偏態？","options":{"A":"平方根轉換（Square Root Transform）","B":"對數轉換（Log Transform）","C":"Label Encoding","D":"缺失指標編碼"},"answer":"B","figures":[],"explanation":{"approach":"對數轉換可有效降低右偏分佈的極端值影響，使資料分佈更接近常態。常用於收入、銷售額等具極端高值的變數。平方根轉換則較適用於中度偏態資料。","options":{"A":"平方根轉換適用於中度偏態資料，對於極端偏高的右偏分佈，降低偏態的效果不如對數轉換明顯。","B":"正確。對數轉換能有效壓縮極端高值，降低右偏分佈的偏態程度，常用於收入、銷售額等具極端高值的變數。","C":"Label Encoding 是將類別轉換為數值標籤的編碼方式，並非用於處理偏態分佈。","D":"缺失指標編碼是標記資料是否缺失的方法，與偏態轉換無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q05","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":5,"context":null,"stem":"在模型訓練過程中，若模型在訓練集表現良好，但測試集效能不佳，可能是發生了什麼問題？","options":{"A":"欠擬合","B":"特徵縮放失敗","C":"過擬合","D":"批次大小過小"},"answer":"C","figures":[],"explanation":{"approach":"過擬合發生在模型學習了太多訓練集的細節與雜訊，導致在未見過的測試資料上表現不佳。常見解決方案包括使用正則化、降低模型複雜度或早停策略（Early Stopping）。","options":{"A":"欠擬合是模型連訓練集都表現不佳，與題目描述「訓練集表現良好」的情況相反。","B":"特徵縮放失敗通常會導致訓練難以收斂、訓練集表現也不佳，與題目所述訓練集表現良好不符。","C":"正確。過擬合是模型過度學習訓練集的細節與雜訊，導致訓練表現好但在未見過的測試資料上效能不佳。","D":"批次大小過小主要影響訓練穩定性與收斂速度，並非造成訓練與測試表現落差的典型原因。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q06","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":6,"context":null,"stem":"交叉驗證中，哪一種方法在每次驗證中只留下一筆樣本作為驗證集，其餘皆用於訓練？","options":{"A":"K-fold","B":"Stratified K-fold","C":"LOOCV","D":"Repeated K-fold"},"answer":"C","figures":[],"explanation":{"approach":"LOOCV（Leave-One-Out Cross-Validation）是 K-fold 的極端形式，當 K等於樣本數 n 時，每次只留一筆做驗證。此方法能最大化資料利用，但計算成本極高，不適用於大樣本情境。","options":{"A":"K-fold 是將資料分成 K 份，每次以其中一份作驗證、其餘做訓練，並非每次僅留一筆樣本。","B":"Stratified K-fold 是在 K-fold 基礎上依類別比例分層抽樣，同樣並非每次僅留一筆樣本驗證。","C":"正確。LOOCV 是 K-fold 的極端形式（K 等於樣本數 n），每次僅留一筆樣本做驗證，其餘全用於訓練。","D":"Repeated K-fold 是重複執行多次 K-fold 交叉驗證以提升穩定性，並非每次僅留一筆樣本。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q07","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":7,"context":null,"stem":"在訓練深度學習模型時，隨機將部分神經元暫時關閉以減少過擬合的技術是什麼？","options":{"A":"Early Stopping","B":"Dropout","C":"Batch Normalization","D":"Quantization"},"answer":"B","figures":[],"explanation":{"approach":"Dropout 透過隨機將神經元暫時設為零，迫使模型在每次訓練都以不同的「子網路」進行學習，有效降低模型對特定神經元的過度依賴，減少過擬合風險。","options":{"A":"Early Stopping 是在驗證效能不再提升時提前停止訓練，並非隨機關閉神經元的技術。","B":"正確。Dropout 隨機將部分神經元暫時關閉（設為零），迫使模型不依賴特定神經元，以降低過擬合風險。","C":"Batch Normalization 是對每層輸入進行標準化以穩定訓練，並非隨機關閉神經元。","D":"Quantization 是將模型參數以較低精度表示以壓縮模型，並非隨機關閉神經元的技術。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q08","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":8,"context":null,"stem":"在模型壓縮技術中，知識蒸餾（Knowledge Distillation）的主要目的是什麼？","options":{"A":"減少資料維度","B":"降低參數數量使模型更小","C":"將大型模型的知識轉移至小型模型","D":"增強資料平衡"},"answer":"C","figures":[],"explanation":{"approach":"Knowledge Distillation 是利用大型、高性能的教師模型，將其知識以軟標籤（soft labels）的形式傳遞給小型學生模型，讓學生模型在參數較少的情況下，仍維持接近的預測能力。","options":{"A":"減少資料維度是特徵工程或降維的目的，並非知識蒸餾的主要目的。","B":"降低參數數量使模型更小是模型壓縮常見的結果之一，但知識蒸餾的核心在於知識轉移，而非單純減少參數。","C":"正確。知識蒸餾的主要目的是將大型教師模型的知識，透過軟標籤等方式轉移給小型學生模型，使其維持接近的預測能力。","D":"增強資料平衡屬於資料層面的處理（如 SMOTE），與知識蒸餾在模型間轉移知識的概念無關。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q09","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":9,"context":null,"stem":"在優化器中，哪一個方法會自動調整每個參數的學習率，特別適用於稀疏資料？","options":{"A":"Momentum","B":"Adagrad","C":"Adam","D":"SGD"},"answer":"B","figures":[],"explanation":{"approach":"Adagrad 能針對每個參數調整不同的學習率，累積梯度平方和後，自動減小常被更新參數的學習步伐。適合處理特徵稀疏的場景，如文字分析，但學習率會不斷衰減至極小值，需留意訓練是否停滯。","options":{"A":"Momentum 是利用過去梯度方向的動量加速收斂，並非自動依歷史梯度調整各參數學習率的方法。","B":"正確。Adagrad 依各參數的歷史梯度平方和自動調整（縮小）學習率，特別適合處理稀疏資料，如文字特徵。","C":"Adam 雖然也具備自適應學習率的特性，但其設計是結合動量與 RMSProp，並非題目所指「累積歷史梯度平方和、特別適合稀疏資料」這項 Adagrad 的典型特徵。","D":"SGD 通常使用固定學習率更新所有參數，並不會自動依參數調整學習率。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c3_q10","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":10,"context":null,"stem":"One-hot Encoding 在什麼情況下可能造成模型的運算負擔加重？","options":{"A":"缺失值多的資料","B":"資料集中某類別種類 10 種","C":"類別變數具有高基數（High Cardinality）","D":"資料集中無重複樣本"},"answer":"C","figures":[],"explanation":{"approach":"One-hot Encoding 會為每個不同類別產生獨立欄位，若類別數過多，會導致特徵維度爆炸，增加記憶體使用與模型訓練的負擔，尤其在資料量大時更明顯。","options":{"A":"缺失值多的資料是資料品質問題，與 One-hot Encoding 增加運算負擔的原因無關。","B":"類別種類僅 10 種時，One-hot Encoding 產生的欄位數有限，通常不會造成明顯的運算負擔。","C":"正確。當類別變數具有高基數（類別數量很多）時，One-hot Encoding 會產生大量欄位，造成特徵維度爆炸與運算負擔增加。","D":"資料集中無重複樣本與 One-hot Encoding 產生的欄位數量無關，不會因此加重運算負擔。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q01","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":1,"context":null,"stem":"在個人資料保護法規的框架下，下列哪一組資訊單獨使用時，最明確地被歸類為「直接識別個人身份資訊（Directly Identifiable Information, PII）」？","options":{"A":"出生日期、郵遞區號、職業","B":"網站 Cookie ID、設備 IP 位址、地理定位資訊","C":"姓名、電子郵件地址、身分證字號","D":"網路行為模式、匿名化統計數據、加密後的密碼雜湊值"},"answer":"C","figures":[],"explanation":{"approach":"「直接識別個人身份資訊（PII）」是指無需透過其他資訊輔助，單獨即可明確辨識出特定個人的資料。（A）出生日期、郵遞區號和職業等資訊單獨無法直接識別特定個人，通常需要結合其他資訊才能達到識別效果，屬於準識別資訊（Quasi-Identifiers）。（B）網站 Cookie ID、IP 位址和地理定位資訊雖然屬於識別符號，且在特定情境下可被追溯或結合其他資訊後具有識別性，但其本身通常不被視為單獨可直接指向特定個人的 PII。通常被歸類為間接識別資訊。（C）姓名、電子郵件地址和身分證字號是典型的直接識別資訊，這些資訊單獨就能指向一個特定且唯一的人。（D）網路行為模式、匿名化統計數據和加密後的密碼雜湊值均屬於非直接識別資訊。匿名化數據已去除識別性，加密雜湊值雖然源於個人密碼但已不可逆地處理，網路行為模式本身也不直接指向個人。","options":{"A":"出生日期、郵遞區號、職業單獨無法直接指向特定個人，須結合其他資訊才能達到識別效果，屬於準識別資訊。","B":"網站 Cookie ID、IP 位址、地理定位資訊屬於間接識別資訊，通常需結合其他資料才能追溯至特定個人，並非單獨可直接識別。","C":"正確。姓名、電子郵件地址、身分證字號等資訊，單獨即可明確指向特定且唯一的個人，屬於直接識別個人身份資訊（PII）。","D":"網路行為模式、匿名化統計數據及加密後的密碼雜湊值皆已去除或不具直接識別性，屬於非直接識別資訊。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q02","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":2,"context":null,"stem":"以下哪一種資料處理方式屬於「隨機擾動（Noise Injection）」？","options":{"A":"把姓名改成代號","B":"將薪資加入隨機誤差","C":"將地址改成縣市級別","D":"以星號遮蔽身分證號"},"answer":"B","figures":[],"explanation":{"approach":"即便進行匿名化，外部資料比對仍可能造成再識別風險，因此須強化匿名化措施或限制資料使用情境，才能降低風險。","options":{"A":"把姓名改成代號屬於以代號取代識別欄位的「代碼化／去識別化（Pseudonymization）」，並非在數值中加入隨機誤差。","B":"正確。將薪資加入隨機誤差是在原始數值上疊加隨機雜訊，屬於典型的隨機擾動（Noise Injection）技術。","C":"將地址改成縣市級別是把資料精細度降低至較粗略的類別，屬於「泛化（Generalization）」技術，並非隨機擾動。","D":"以星號遮蔽身分證號是將部分欄位內容以符號取代隱藏，屬於「遮蔽（Masking）」技術，並非隨機擾動。"},"source":"official","note":"官方解析內容為「即便匿名化，外部資料比對仍可能造成再識別風險，須強化匿名化措施」，談的是匿名化後的再識別風險，並未針對本題四個選項（代碼化、隨機擾動、泛化、遮蔽）逐一說明，與題幹「哪一種屬於隨機擾動」的問法未直接對應。上列逐選項說明改依標準去識別化技術定義撰寫，供參考，未與官方解析牴觸。"},"origin":"guide"},{"id":"guide_middle_s3_c4_q03","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":3,"context":null,"stem":"在 AI 偏見治理中，對不同群體調整模型預測閾值，屬於哪一種偏見修正方法？","options":{"A":"資料泛化","B":"結果門檻調整","C":"模型剪枝","D":"資料增強"},"answer":"B","figures":[],"explanation":{"approach":"結果門檻調整（Threshold Adjustment）屬於模型後處理方式，透過改變不同群體的決策門檻，以平衡模型在不同群體間的預測公平性。","options":{"A":"資料泛化是將資料精細度降低（如年齡分組），屬於資料層面的去識別化技術，並非調整預測閾值的方法。","B":"正確。結果門檻調整是針對不同群體設定不同的預測閾值，屬於模型後處理的偏見修正方法。","C":"模型剪枝是刪減神經網路中不重要的連結或參數以精簡模型，與調整預測閾值無關。","D":"資料增強是透過生成或轉換資料增加訓練樣本，屬於資料層面的方法，並非調整預測閾值。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q04","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":4,"context":null,"stem":"若企業想確保 AI 模型在不同群體間「真正該被選擇者」皆有同等機會被正確預測，應採用哪一個公平性指標？","options":{"A":"Equal Opportunity","B":"Demographic Parity","C":"K-Anonymity","D":"T-Closeness"},"answer":"A","figures":[],"explanation":{"approach":"Equal Opportunity 著重在實際應獲得正向結果的個案，在不同群體間應具有相同的被正確預測機率，尤其適用於醫療、社會福利等情境。","options":{"A":"正確。Equal Opportunity 著重於「真正該被選擇者（實際為正類）」在不同群體間，應有相同的被正確預測機率。","B":"Demographic Parity 要求不同群體獲得正向預測結果的比例相同，並未特別聚焦於真正該被選擇者是否被正確預測。","C":"K-Anonymity 是隱私保護技術，確保每筆資料至少與 K-1 筆其他資料無法區分，並非公平性指標。","D":"T-Closeness 是隱私保護技術，要求群組內敏感屬性分佈與整體資料集相近，並非公平性指標。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q05","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":5,"context":null,"stem":"若企業欲在 AI 專案中降低敏感特徵（如性別）的影響，可以採取哪種模型內部處理方式？","options":{"A":"對抗式去偏模型","B":"模型蒸餾","C":"雜湊處理","D":"結果門檻調整"},"answer":"A","figures":[],"explanation":{"approach":"對抗式去偏透過訓練一個對抗網路，迫使主模型無法預測敏感屬性，從而降低模型對敏感特徵的依賴，是常見的公平性處理技術。","options":{"A":"正確。對抗式去偏模型透過訓練一個對抗網路，使主模型無法預測敏感屬性，從模型內部降低對敏感特徵的依賴。","B":"模型蒸餾是將大型模型的知識轉移至小型模型以壓縮模型，並非降低敏感特徵影響的公平性技術。","C":"雜湊處理是將資料轉換為不可逆的雜湊值，屬於資料保護技術，並非模型內部降低敏感特徵影響的方法。","D":"結果門檻調整是在模型輸出後調整不同群體的決策門檻，屬於後處理方法，並非模型內部處理。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q06","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":6,"context":null,"stem":"若資料集中存在群體樣本數不均，造成模型偏向多數群體，適合採用哪種技術？","options":{"A":"權重初始化","B":"權重衰減","C":"類別重加權","D":"全量訓練"},"answer":"C","figures":[],"explanation":{"approach":"類別重加權能在模型訓練時賦予少數類別更高權重，提升模型對少數群體的辨識能力，是處理不平衡資料常見的方法。","options":{"A":"權重初始化是設定神經網路訓練起始參數值的方法，與處理群體樣本數不均無關。","B":"權重衰減是一種正則化技術，用於限制模型權重過大以防止過擬合，並非針對樣本不均問題設計。","C":"正確。類別重加權在訓練時賦予少數類別更高權重，提升模型對少數群體的辨識能力，改善樣本不均造成的偏向問題。","D":"全量訓練僅是指使用全部資料進行訓練，並未針對樣本數不均的問題做特別處理。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q07","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":7,"context":null,"stem":"T-接近性（T-Closeness）技術主要是為了降低什麼風險？","options":{"A":"機率分佈差異造成的識別風險","B":"資料重複風險","C":"訓練時間過長","D":"演算法震盪問題"},"answer":"A","figures":[],"explanation":{"approach":"T-Closeness 要求群組內敏感屬性的分佈，需與全體資料集分佈相近，以防止透過分佈偏差推測個人特徵，是進階的隱私保護技術。","options":{"A":"正確。T-接近性要求群組內敏感屬性的分佈需與整體資料集分佈相近，以降低因分佈差異被推測出個人特徵的識別風險。","B":"資料重複風險與 T-Closeness 技術所強調的敏感屬性分佈相似性並無直接關聯。","C":"訓練時間過長屬於模型訓練效率的問題，與 T-Closeness 著重的隱私識別風險無關。","D":"演算法震盪問題通常與優化器或學習率設定有關，並非 T-Closeness 技術要解決的隱私識別風險。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q08","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":8,"context":null,"stem":"在 AI 公平性治理中，企業應建立什麼跨部門組織，確保公平性納入日常決策流程？","options":{"A":"模型剪枝委員會","B":"AI 蒸餾中心","C":"公平性審查委員會","D":"隨機抽樣團隊"},"answer":"C","figures":[],"explanation":{"approach":"公平性審查委員會匯集法務、技術、產品與倫理等部門，負責評估 AI系統的偏見風險，是企業治理 AI 公平性的重要機制。","options":{"A":"模型剪枝委員會並非用於公平性治理的組織名稱；剪枝是刪減模型參數的壓縮技術，與公平性治理無關。","B":"AI 蒸餾中心並非用於公平性治理的組織；知識蒸餾是模型壓縮技術術語，與公平性審查無關。","C":"正確。公平性審查委員會匯集法務、技術、產品與倫理等跨部門人員，負責評估 AI 系統的偏見風險，確保公平性納入日常決策流程。","D":"隨機抽樣團隊通常負責資料抽樣相關工作，並非專責 AI 公平性治理的跨部門組織。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q09","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":9,"context":null,"stem":"若企業欲降低 AI 模型因少數群體樣本過少而造成的過擬合風險，可以採用哪種資料增強方法？","options":{"A":"SMOTE","B":"Softmax","C":"Momentum","D":"Dropout"},"answer":"A","figures":[],"explanation":{"approach":"SMOTE（Synthetic Minority Over-sampling Technique）透過合成新樣本，擴增少數類別資料，有助於平衡類別分佈，降低過擬合及模型偏誤風險。","options":{"A":"正確。SMOTE 透過合成新樣本擴增少數類別資料，平衡類別分佈，降低模型因少數群體樣本過少導致的過擬合風險。","B":"Softmax 是將模型輸出轉換為機率分佈的函數，常用於多分類輸出層，並非資料增強方法。","C":"Momentum 是優化器中用於加速收斂的技術，並非用於擴增少數類別樣本的資料增強方法。","D":"Dropout 是訓練時隨機關閉神經元以降低過擬合的正則化技術，並非擴增少數類別樣本的資料增強方法。"},"source":"official"},"origin":"guide"},{"id":"guide_middle_s3_c4_q10","level":"middle","session":"學習指引","subject":3,"subject_name":"機器學習技術與應用","number":10,"context":null,"stem":"下列哪一項不是常見的隱私保護基礎技術？","options":{"A":"遮蔽（Masking）","B":"泛化（Generalization）","C":"知識蒸餾（Knowledge Distillation）","D":"分桶（Bucketing）"},"answer":"C","figures":[],"explanation":{"approach":"知識蒸餾是用於模型壓縮與加速的技術，並非基礎隱私保護技術。隱私保護常用技術包括遮蔽、泛化及分桶，用來降低個資識別風險。","options":{"A":"遮蔽是常見的隱私保護基礎技術，透過符號遮蓋敏感資料達到去識別化效果，因此不是本題答案。","B":"泛化是常見的隱私保護基礎技術，透過降低資料精細度（如年齡分組）減少識別風險，因此不是本題答案。","C":"正確。知識蒸餾是模型壓縮與加速的技術（將大型模型的知識轉移至小型模型），並非隱私保護基礎技術，故為本題答案。","D":"分桶是常見的隱私保護基礎技術，將連續數值分組為區間以降低識別精細度，因此不是本題答案。"},"source":"official"},"origin":"guide"}];
